function getPlayerPartial(name)
    if not name or name == "" then return nil end
    name = name:lower()
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= player and (p.Name:lower():sub(1, #name) == name or (p.DisplayName and p.DisplayName:lower():sub(1, #name) == name)) then
            return p
        end
    end
    return nil
end

local lastPotatoUpdate = 0
trackConnection("potatoDescendantAdded", workspace.DescendantAdded:Connect(function(v)
    if not Settings.PotatoMode then return end
    
    -- Safe Check: Don't touch Camera or Game specific weather effects that crash if missing
    if v:IsDescendantOf(workspace.Camera) then return end

    if v:IsA("Model") and v.Name:find("Bush") then
        for _, part in ipairs(v:GetDescendants()) do
            if part:IsA("BasePart") then
                part.Material = Enum.Material.SmoothPlastic
                part.CastShadow = false
            elseif part:IsA("Decal") or part:IsA("Texture") then
                part.Transparency = 1
            elseif part:IsA("ParticleEmitter") or part:IsA("Beam") or part:IsA("Trail") then
                part.Enabled = false
            end
        end
        return
    end
    
    if v:IsA("BasePart") then
        v.Material = Enum.Material.SmoothPlastic
        v.CastShadow = false
        v.Reflectance = 0
    elseif v:IsA("Decal") or v:IsA("Texture") or v:IsA("ParticleEmitter") or v:IsA("Trail") then
        task.delay(0.1, function() 
            if v and v.Parent then 
                -- Instead of destroying, just disable to prevent game script errors
                if v:IsA("ParticleEmitter") or v:IsA("Trail") or v:IsA("Beam") then
                    v.Enabled = false
                elseif v:IsA("Decal") or v:IsA("Texture") then
                    v.Transparency = 1
                end
            end 
        end)
    end
end))



