local validHarvestablesCache = {
    "Bloodfruit", "Bluefruit", "Lemon", "Coconut", "Jelly", "Banana", "Orange", 
    "Oddberry", "Berry", "Strangefruit", "Strawberry", "Sunfruit", "Pumpkin", 
    "Prickly Pear", "Pear Cacti", "Apple", "Barley", "Cloudberry", "Carrot", "Corn", "Blossom",
    "Watermelon", "Mango", "Frostfruit"
}
local validHarvestablesSet = {}
for _, name in ipairs(validHarvestablesCache) do
    validHarvestablesSet[name] = true
end

local _nonHarvestableNames = {}
local _harvestOverlapParams = OverlapParams.new()
_harvestOverlapParams.FilterType = Enum.RaycastFilterType.Include

function getHarvestFolders()
    local folders = {}
    local crops = getWorkspaceCrops()
    if crops then table.insert(folders, crops) end
    local resources = getWorkspaceResources()
    local deployables = getWorkspaceDeployables()
    if resources then table.insert(folders, resources) end
    if deployables then table.insert(folders, deployables) end
    return folders
end

function getHarvestEntityId(model)
    if not model then return nil end
    local keys = { "EntityID", "NetworkId", "networkId", "NetworkID", "ID", "Id", "Eid", "EntityId" }
    for _, key in ipairs(keys) do
        local v = model:GetAttribute(key)
        if v ~= nil then
            local n = math.floor(tonumber(v) or 0)
            if n > 0 then return n end
        end
    end
    return nil
end

local function harvestNameMatches(modelName, fruitFilter)
    if not modelName or modelName == "" then return false end
    if _nonHarvestableNames[modelName] then return false end
    if fruitFilter then
        local lowerName = string.lower(modelName)
        for fname in pairs(fruitFilter) do
            if lowerName:find(fname, 1, true) then
                return true
            end
        end
        return false
    end
    if validHarvestablesSet[modelName] then return true end
    for setName in pairs(validHarvestablesSet) do
        if modelName:find(setName, 1, true) then
            validHarvestablesSet[modelName] = true
            return true
        end
    end
    _nonHarvestableNames[modelName] = true
    return false
end

-- Harvest pickup: live Crops radius around you (do not walk the whole folder).
local function collectHarvestNear(originPos, range, fruitFilter, cropsMode)
    local found = {}
    local seenEIDs = {}
    if not originPos then return found end
    range = math.clamp(tonumber(range) or 30, 5, 150)
    local rangeSq = range * range
    local crops = getWorkspaceCrops()
    if not crops then return found end
    local maxFound = 64
    _harvestOverlapParams.FilterDescendantsInstances = {crops}
    local parts = workspace:GetPartBoundsInBox(
        CFrame.new(originPos),
        Vector3.new(range * 2, math.max(24, range * 2), range * 2),
        _harvestOverlapParams
    )
    local nParts = #parts
    if nParts > 180 then nParts = 180 end

    for i = 1, nParts do
        if #found >= maxFound then break end
        local part = parts[i]
        if not part then continue end
        local model = part:IsA("Model") and part or part.Parent
        if not (model and model:IsA("Model")) then
            model = part:FindFirstAncestorOfClass("Model")
        end
        if not model then continue end
        local okName = true
        if fruitFilter then
            okName = false
            local lowerName = string.lower(model.Name)
            for fname in pairs(fruitFilter) do
                if lowerName:find(fname, 1, true) then
                    okName = true
                    break
                end
            end
        elseif not cropsMode then
            okName = harvestNameMatches(model.Name, fruitFilter)
        end
        if not okName then continue end
        local pp = (part:IsA("BasePart") and part) or model.PrimaryPart
        if not pp then continue end
        local pos = pp.Position
        local dx = pos.X - originPos.X
        local dy = pos.Y - originPos.Y
        local dz = pos.Z - originPos.Z
        local distSq = dx * dx + dy * dy + dz * dz
        if distSq > rangeSq then continue end
        local eid = getHarvestEntityId(model)
        local seenKey = eid or model
        if seenEIDs[seenKey] then continue end
        seenEIDs[seenKey] = true
        found[#found + 1] = {
            entityid = eid,
            distSq = distSq,
            model = model,
            part = pp,
        }
    end

    if #found > 1 then
        table.sort(found, function(a, b)
            return (a.distSq or math.huge) < (b.distSq or math.huge)
        end)
    end
    return found
end

-- Pickup (captured): [0][Pickup][u32 eid]  -- 6 bytes (no item id)
function fireByteNetPickup(eid)
    if not ByteNetReliable then return false end
    local pickupId = getPacketId("Pickup")
    local id = math.floor(tonumber(eid) or 0)
    if not pickupId or id <= 0 then return false end
    local b = buffer.create(6)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, pickupId)
    buffer.writeu32(b, 2, id)
    ByteNetReliable:FireServer(b)
    return true
end

function getHarvestables(range, fruitName)
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return {} end

    local fruitFilter = nil
    if fruitName and fruitName ~= "" and fruitName ~= "All" then
        fruitFilter = { [string.lower(tostring(fruitName))] = true }
    else
        fruitFilter = {}
        local fruits = getActivePlantFruits()
        if type(fruits) == "table" then
            for _, name in ipairs(fruits) do
                fruitFilter[string.lower(tostring(name))] = true
            end
        end
        if not next(fruitFilter) then fruitFilter = nil end
    end
    return collectHarvestNear(hrp.Position, range or 30, fruitFilter, true)
end

local _harvestableOverlapParams = OverlapParams.new()
_harvestableOverlapParams.FilterType = Enum.RaycastFilterType.Include
local _harvestNearCache = {
    at = 0,
    center = nil,
    range = nil,
    fruitSig = nil,
    results = {},
}

function getHarvestablesNear(centerPos, range, fruitNames, skipCache)
    local found = {}
    if not centerPos then return found end

    range = math.min(range or 30, 500)
    local rangeSq = range * range
    local fruitSig = ""
    if fruitNames and #fruitNames > 0 then
        fruitSig = table.concat(fruitNames, "|")
    end
    local cacheCenter = _harvestNearCache.center
    if not skipCache
        and _harvestNearCache.range == range
        and _harvestNearCache.fruitSig == fruitSig
        and _harvestNearCache.at > 0
        and (tick() - _harvestNearCache.at) <= 0.2
        and cacheCenter
        and (centerPos - cacheCenter).Magnitude <= 8 then
        return _harvestNearCache.results
    end

    local crops = getWorkspaceCrops()
    if not crops then return found end
    _harvestableOverlapParams.FilterDescendantsInstances = {crops}

    local seenEIDs = {}
    local maxFound = 32
    if Settings.TweenToBushAndBox or Settings.TweenToBush then
        maxFound = 12
    end
    local fruitFilter = nil
    if fruitNames and #fruitNames > 0 then
        fruitFilter = {}
        for _, name in ipairs(fruitNames) do
            fruitFilter[string.lower(tostring(name))] = true
        end
    end

    local function considerPart(part)
        if not part or #found >= maxFound then return end
        local model = getWorkspaceCropModel(part)
        if not model then return end
        local eid = getHarvestEntityId(model)
        local seenKey = eid or model
        if seenEIDs[seenKey] then return end
        local modelName = model.Name
        if fruitFilter then
            local lowerName = string.lower(modelName)
            local fruitMatch = false
            for fname in pairs(fruitFilter) do
                if lowerName:find(fname, 1, true) then
                    fruitMatch = true
                    break
                end
            end
            if not fruitMatch then return end
        elseif not harvestNameMatches(modelName, nil) then
            return
        end
        local pp = getWorkspaceCropPart(model) or part
        if not pp then return end
        local diff = pp.Position - centerPos
        local distSq = diff:Dot(diff)
        if distSq > rangeSq then return end
        seenEIDs[seenKey] = true
        table.insert(found, {
            entityid = eid,
            distSq = distSq,
            model = model,
            part = pp,
        })
    end

    -- Live radius scan of workspace.Crops around you (do not walk the whole folder).
    local nearR = math.min(range, 80)
    local nearParts = workspace:GetPartBoundsInRadius(centerPos, nearR, _harvestableOverlapParams)
    local nearCap = math.min(#nearParts, 120)
    for idx = 1, nearCap do
        considerPart(nearParts[idx])
        if #found >= maxFound then break end
    end
    if range > nearR and #found < maxFound and not (Settings.TweenToBushAndBox or Settings.TweenToBush) then
        local farParts = workspace:GetPartBoundsInRadius(centerPos, range, _harvestableOverlapParams)
        local farCap = math.min(#farParts, 80)
        for idx = 1, farCap do
            considerPart(farParts[idx])
            if #found >= maxFound then break end
        end
    end

    if #found > 1 then
        table.sort(found, function(a, b) return a.distSq < b.distSq end)
    end
    _harvestNearCache.at = tick()
    _harvestNearCache.center = centerPos
    _harvestNearCache.range = range
    _harvestNearCache.fruitSig = fruitSig
    _harvestNearCache.results = found
    return found
end

