-- SwingTool (captured): u8 0, u8 actionId, 18-byte CFrame, u16 LE hitCount,
-- hitCount * (u8 0 + u32 LE eid), f64 timestamp.
local function trackWebhookResourceBreaks(batch)
    local ws = __ASTER_RUNTIME.webhookStats
    if not ws then return end
    ws.broken = ws.broken or {}
    local eidNames = __ASTER_RUNTIME.webhookResourceEids
    for _, t in ipairs(batch) do
        local name = t.resourceName
        if not name and t.eid and eidNames then
            name = eidNames[t.eid]
        end
        if name and name ~= "" then
            ws.broken[name] = (ws.broken[name] or 0) + 1
        end
    end
end

function fireByteNetSwingTool(targetEntries, hrp, opts)
    opts = opts or {}
    if not targetEntries or #targetEntries == 0 or not ByteNetReliable or not hrp then return end

    local clean = {}
    for _, t in ipairs(targetEntries) do
        local id = math.floor(tonumber(t and t.eid) or 0)
        if id > 0 then
            table.insert(clean, { eid = id, pos = t.pos, resourceName = t.resourceName })
        end
    end
    if #clean == 0 then return end
    targetEntries = clean

    local swingId = getPacketId("SwingTool")
    if not swingId then return end

    local function computeFromPos()
        local fromPos = hrp.Position
        if opts.fromPos then
            fromPos = opts.fromPos
        end
        if not opts.skipLead then
            local vel = hrp.AssemblyLinearVelocity or Vector3.zero
            local horizontalVel = Vector3.new(vel.X, 0, vel.Z)
            local tweening = opts.tweening
            if tweening == nil then
                tweening = (isTweening == true) or (horizontalVel.Magnitude > 18)
            end
            local leadTime = tweening and (opts.leadTime ~= nil and opts.leadTime or 0.12) or (opts.leadTime or 0)
            fromPos = fromPos + (horizontalVel * leadTime)
        end
        return fromPos
    end

    local function cframeForBatch(batch, fromPos)
        if #batch == 1 then
            local tp = batch[1].pos
            if typeof(tp) == "Vector3" and (tp - fromPos).Magnitude > 0.01 then
                return CFrame.lookAt(fromPos, tp)
            end
            return hrp.CFrame
        end
        local sum = Vector3.zero
        local n = 0
        for _, t in ipairs(batch) do
            if typeof(t.pos) == "Vector3" then
                sum = sum + t.pos
                n = n + 1
            end
        end
        if n > 0 then
            local center = sum / n
            if (center - fromPos).Magnitude > 0.01 then
                return CFrame.lookAt(fromPos, center)
            end
        end
        return hrp.CFrame
    end

    local maxPerPacket = math.clamp(opts.maxPerPacket or 32, 1, 64)
    local timeStep = opts.timeStep or 0.01
    local baseTime = opts.baseTime or (time() - timeStep)
    local run = game:GetService("RunService")
    local pktIdx = 0

    for startIdx = 1, #targetEntries, maxPerPacket do
        if pktIdx > 0 then
            run.Heartbeat:Wait()
        end
        pktIdx = pktIdx + 1

        local batch = {}
        for i = startIdx, math.min(startIdx + maxPerPacket - 1, #targetEntries) do
            table.insert(batch, targetEntries[i])
        end
        local n = #batch
        local fromPos = computeFromPos()
        local cf = opts.cframe or cframeForBatch(batch, fromPos)
        -- 2 header + 18 cframe + 2 count + 5*n hits + 8 time
        local b = buffer.create(30 + 5 * n)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, swingId)
        write18ByteCFrame(b, 2, cf)
        buffer.writeu16(b, 20, n)
        local o = 22
        for _, t in ipairs(batch) do
            buffer.writeu8(b, o, 0)
            buffer.writeu32(b, o + 1, math.floor(tonumber(t.eid) or 0))
            o = o + 5
        end
        buffer.writef64(b, o, baseTime + (pktIdx * timeStep))
        trackWebhookResourceBreaks(batch)
        ByteNetReliable:FireServer(b)
    end
end

local _auraLegitSwingAnimTrack = nil
local _auraLegitSwingLastChar = nil
local _auraLegitSwingLastPlay = 0

-- Same local swing feel as Combat SwingHit: ClientSwing + slash anim (+ tool Activate).
function playAuraLegitSwing()
    if not ByteNetReliable then return end
    pcall(function()
        local swingId = getPacketId("ClientSwing")
        if swingId then
            local swingBuf = buffer.create(2)
            buffer.writeu8(swingBuf, 0, 0)
            buffer.writeu8(swingBuf, 1, swingId)
            ByteNetReliable:FireServer(swingBuf)
        end
    end)
    pcall(function()
        if os.clock() - _auraLegitSwingLastPlay < 0.4 then return end
        _auraLegitSwingLastPlay = os.clock()
        local char = plr.Character
        if not char then return end
        if char ~= _auraLegitSwingLastChar then
            _auraLegitSwingLastChar = char
            _auraLegitSwingAnimTrack = nil
        end
        if not _auraLegitSwingAnimTrack then
            local hum = char:FindFirstChildOfClass("Humanoid")
            local animator = hum and (hum:FindFirstChildOfClass("Animator") or hum:FindFirstChild("Animator"))
            if animator then
                local anim = Instance.new("Animation")
                anim.AnimationId = "rbxassetid://10761451679"
                _auraLegitSwingAnimTrack = animator:LoadAnimation(anim)
            end
        end
        if _auraLegitSwingAnimTrack then
            _auraLegitSwingAnimTrack:Play()
        end
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") then
                pcall(function() child:Activate() end)
                break
            end
        end
    end)
end

-- Same current SwingTool wire as fireByteNetSwingTool (kept for older call sites).
function fireByteNetSwingToolPackedMultiHit(targetEntries, hrp, opts)
    opts = opts or {}
    if not targetEntries or #targetEntries == 0 or not hrp then return end

    local seen = {}
    local clean = {}
    local maxN = math.clamp(opts.maxTargets or 9, 1, 9)
    for _, t in ipairs(targetEntries) do
        local id = math.floor(tonumber(t and t.eid) or 0)
        if id > 0 and not seen[id] then
            seen[id] = true
            table.insert(clean, t)
            if #clean >= maxN then break end
        end
    end
    if #clean == 0 then return end

    fireByteNetSwingTool(clean, hrp, {
        maxPerPacket = maxN,
        fromPos = opts.fromPos,
        cframe = opts.cframe,
        skipLead = opts.skipLead,
        tweening = opts.tweening,
        leadTime = opts.leadTime,
        timeStep = opts.timeStep,
        baseTime = opts.baseTime,
    })
end

function getlayout(name)
    if not name or name == "" then return nil end
    local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
    if not mainGui then return nil end
    local right = mainGui:FindFirstChild("RightPanel")
    local inv = right and right:FindFirstChild("Inventory")
    local list = inv and inv:FindFirstChild("List")
    if not list then return nil end
    local lowerTarget = string.lower((tostring(name):match("^%s*(.-)%s*$") or ""))
    if lowerTarget == "" then return nil end
    for _, child in ipairs(list:GetChildren()) do
        if child:IsA("GuiObject") then
            local cn = string.lower((tostring(child.Name):match("^%s*(.-)%s*$") or ""))
            if cn == lowerTarget then
                return child.LayoutOrder
            end
        end
    end
    return nil
end

function drop(itemName)
    local mainGui = game:GetService("Players").LocalPlayer.PlayerGui:FindFirstChild("MainGui")
    local inventory = mainGui and mainGui.RightPanel and mainGui.RightPanel.Inventory and mainGui.RightPanel.Inventory.List
    local slotID = nil
    if inventory then
        -- Use case-insensitive exact match like dynamicDrop for better reliability
        local lowerTarget = itemName:lower():match("^%s*(.-)%s*$")
        if lowerTarget and lowerTarget ~= "" then
            for _, child in ipairs(inventory:GetChildren()) do
                if child:IsA("GuiObject") then
                    local childNameLower = child.Name:lower():match("^%s*(.-)%s*$")
                    if childNameLower == lowerTarget then
                        slotID = child.LayoutOrder
                        break
                    end
                end
            end
        end
    end

    if slotID and ByteNetReliable then
        local dropPacketId = getPacketId("DropBagItem")
        if not dropPacketId then return end
        local b = buffer.create(4)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, dropPacketId)
        buffer.writeu16(b, 2, slotID) -- server expects LayoutOrder slot
        ByteNetReliable:FireServer(b)
    end
end

local _plantBuf = buffer.create(8)
function plant(eid, itemID)
    if not ByteNetReliable then return end
    local interactPacketId = getPacketId("InteractStructure")
    if not interactPacketId then return end
    buffer.writeu8(_plantBuf, 0, 0)
    buffer.writeu8(_plantBuf, 1, interactPacketId)
    buffer.writeu32(_plantBuf, 2, eid)
    buffer.writeu16(_plantBuf, 6, itemID)
    ByteNetReliable:FireServer(_plantBuf)
    plantedboxes[eid] = os.clock()
    local ws = __ASTER_RUNTIME.webhookStats
    if ws then ws.planted = (ws.planted or 0) + 1 end
end


function performRebirth()
    firePacket("Rebirth")
end

-- MOVEMENT & GOLD LOGIC
currentWaypoint = 1
isTweening = false
walkingToWaypoint = false
isWaitingForWaypoint = false -- New: Track if waiting at a waypoint
waypointWaitStartTime = 0 -- New: Track when wait started
alignPosition = nil
alignAttachment0 = nil
alignAttachment1 = nil
restoreCollision = nil
plantAlignPosition = nil
plantAttachment0 = nil
plantAttachment1 = nil
plantIsTweening = false

rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude
function updateRayParams()
    if plr.Character then rayParams.FilterDescendantsInstances = {plr.Character} end
end
plr.CharacterAdded:Connect(updateRayParams)
if plr.Character then updateRayParams() end

WALK_SPEED = 21
NEAR_GOLD_SPEED = 16
SPEED_VARIANCE = 0.05
SPEED_CHANGE_INTERVAL = 0.5
lastSpeedChange = tick()
currentSpeedMultiplier = 1

function getRandomizedSpeed(baseSpeed)
    if tick() - lastSpeedChange > SPEED_CHANGE_INTERVAL then
        if baseSpeed <= 0 then return baseSpeed end
        local minSpeed = baseSpeed - 0.5
        local maxSpeed = baseSpeed
        local chosenSpeed = minSpeed + (math.random() * (maxSpeed - minSpeed))
        currentSpeedMultiplier = chosenSpeed / baseSpeed
        lastSpeedChange = tick()
    end
    return baseSpeed * currentSpeedMultiplier
end

function hasLineOfSight(startPos, endPos)
    local direction = (endPos - startPos)
    local distance = direction.Magnitude
    if distance < 1 then return true end
    local rayResult = workspace:Raycast(startPos + Vector3.new(0, 2, 0), direction, rayParams)
    if rayResult then
        local hitDist = (rayResult.Position - startPos).Magnitude
        if hitDist < (distance * 0.9) then return false end
    end
    return true
end

function wouldTweenHitTerrain(startPos, endPos)
    local sampleCount = 3 
    local direction = (endPos - startPos)
    for i = 0, sampleCount do
        local t = i / sampleCount
        local samplePos = startPos + (direction * t)
        local ray = workspace:Raycast(samplePos, Vector3.new(0, -5, 0), rayParams)
        if not ray then continue end
        if ray and samplePos.Y < ray.Position.Y then return true, samplePos end
    end
    return false
end

function isPathClearToTarget(startPos, endPos)
    local direction = (endPos - startPos)
    local distance = direction.Magnitude
    if distance < 1 then return true end
    direction = direction.Unit
    local rayOrigin = startPos + Vector3.new(0, 2, 0)
    local rayDirection = (endPos + Vector3.new(0, 2, 0)) - rayOrigin
    local ray = workspace:Raycast(rayOrigin, rayDirection, rayParams)
    if ray then
        local hitDistance = (ray.Position - rayOrigin).Magnitude
        local targetDistance = (endPos - startPos).Magnitude
        if hitDistance < (targetDistance * 0.9) then return false, ray.Position end
    end
    return true
end

function hasGroundBeneath(position)
    local ray = workspace:Raycast(position, Vector3.new(0, -100, 0), rayParams)
    if ray then
        local hitPart = ray.Instance
        if hitPart and hitPart:IsA("BasePart") then
            local distance = (position - ray.Position).Magnitude
            return true, distance, ray.Position
        end
    end
    return false, 999, nil
end

function isAboveWater(position)
    if position.Y > 100 then return false end 
    local ray = workspace:Raycast(position, Vector3.new(0, -200, 0), rayParams)
    if ray and ray.Instance and ray.Instance:IsA("Terrain") then
        local region = Region3.new(ray.Position - Vector3.new(4, 4, 4), ray.Position + Vector3.new(4, 4, 4))
        region = region:ExpandToGrid(4)
        local materials, sizes = workspace.Terrain:ReadVoxels(region, 4)
        local size = materials.Size
        for x = 1, size.X do
            for y = 1, size.Y do
                for z = 1, size.Z do
                    if materials[x][y][z] == Enum.Material.Water then return true end
                end
            end
        end
    end
    return false
end

function findNearestAccessibleWaypoint(currentPos)
    if Settings.recordedPositions and #Settings.recordedPositions > 0 then
        local biasCandidates = {}
        table.insert(biasCandidates, currentWaypoint)
        local prev = currentWaypoint - 1
        if prev < 1 then prev = #Settings.recordedPositions end
        if prev ~= currentWaypoint then table.insert(biasCandidates, prev) end

        for _, idx in ipairs(biasCandidates) do
            local pos = Settings.recordedPositions[idx]
            if pos then
                local waypoint = Vector3.new(pos.X, pos.Y, pos.Z)
                local dist = (waypoint - currentPos).Magnitude
                if dist < 60 then
                    local hasLOS = hasLineOfSight(currentPos, waypoint)
                    local wouldHitTerrain = wouldTweenHitTerrain(currentPos, waypoint)
                    if hasLOS and not wouldHitTerrain then
                        return idx, dist, true
                    end
                end
            end
        end
    end

    local closestIndex = currentWaypoint
    local closestDist = math.huge
    local foundAccessible = false
    if not Settings.recordedPositions or #Settings.recordedPositions == 0 then return currentWaypoint, math.huge, false end
    for idx, pos in ipairs(Settings.recordedPositions) do
        if pos and pos.X and pos.Y and pos.Z then
            local waypoint = Vector3.new(pos.X, pos.Y, pos.Z)
            local dist = (waypoint - currentPos).Magnitude
            if dist < closestDist then
                if dist > 150 then continue end
                local hasLOS = hasLineOfSight(currentPos, waypoint)
                local wouldHitTerrain = wouldTweenHitTerrain(currentPos, waypoint)
                if hasLOS and not wouldHitTerrain then
                    closestDist = dist
                    closestIndex = idx
                    foundAccessible = true
                end
            end
        end
    end
    if not foundAccessible then
        closestDist = math.huge
        for idx, pos in ipairs(Settings.recordedPositions) do
            if pos and pos.X and pos.Y and pos.Z then
                local waypoint = Vector3.new(pos.X, pos.Y, pos.Z)
                local dist = (waypoint - currentPos).Magnitude
                if dist < closestDist then closestDist = dist closestIndex = idx end
            end
        end
    end
    return closestIndex, closestDist, foundAccessible
end

function createAlignPosition(hrp)
    if alignPosition then alignPosition:Destroy() end
    if alignAttachment0 then alignAttachment0:Destroy() end
    if alignAttachment1 then alignAttachment1:Destroy() end
    alignAttachment0 = Instance.new("Attachment") alignAttachment0.Parent = hrp
    alignAttachment1 = Instance.new("Attachment") alignAttachment1.Parent = workspace.Terrain
    alignPosition = Instance.new("AlignPosition")
    alignPosition.Attachment0 = alignAttachment0
    alignPosition.Attachment1 = alignAttachment1
    alignPosition.MaxForce = 400000 
    alignPosition.MaxVelocity = 100
    alignPosition.Responsiveness = 200
    alignPosition.ApplyAtCenterOfMass = true
    alignPosition.Parent = hrp
    return alignPosition, alignAttachment1
end

function removeAlignPosition()
    if alignPosition then alignPosition:Destroy() alignPosition = nil end
    if alignAttachment0 then alignAttachment0:Destroy() alignAttachment0 = nil end
    if alignAttachment1 then alignAttachment1:Destroy() alignAttachment1 = nil end
end

function removeBodyVelocity(hrp)
    local bv = hrp:FindFirstChild("CircuitBodyVelocity")
    if bv then bv:Destroy() end
    local bg = hrp:FindFirstChild("CircuitBodyGyro")
    if bg then bg:Destroy() end
end

function tweenToWaypoint(hrp, hum, target, speed)
    removeBodyVelocity(hrp)
    hum:ChangeState(Enum.HumanoidStateType.Freefall) 
    if not alignPosition then createAlignPosition(hrp) end
    alignAttachment1.WorldPosition = target
    alignPosition.MaxVelocity = speed
    isTweening = true
end

function stopAutoPlacementMovement(hrp, hum)
    if isTweening then
        removeAlignPosition()
        isTweening = false
        if hum then hum:ChangeState(Enum.HumanoidStateType.Running) end
        if not Settings.GoldNoclip then restoreCollision() end
    end
    if hrp then
        removeBodyVelocity(hrp)
        hrp.Velocity = Vector3.new(0, 0, 0)
        hrp.RotVelocity = Vector3.new(0, 0, 0)
    end
    waterTweenActive = false
end

function walkToWaypoint(hrp, hum, target, speed)
    local bv = hrp:FindFirstChild("CircuitBodyVelocity")
    local bg = hrp:FindFirstChild("CircuitBodyGyro")
    if not bv then bv = Instance.new("BodyVelocity") bv.Name = "CircuitBodyVelocity" bv.Parent = hrp end
    if not bg then bg = Instance.new("BodyGyro") bg.Name = "CircuitBodyGyro" bg.MaxTorque = Vector3.new(math.huge, math.huge, math.huge) bg.P = 9000 bg.Parent = hrp end
    local direction = (target - hrp.Position)
    local flatDirection = Vector3.new(direction.X, 0, direction.Z)
    if flatDirection.Magnitude > 0 then
        flatDirection = flatDirection.Unit
        bv.MaxForce = Vector3.new(math.huge, 0, math.huge)
        bv.Velocity = flatDirection * speed
        local lookDirection = Vector3.new(direction.X, 0, direction.Z)
        if lookDirection.Magnitude > 0 then
            lookDirection = lookDirection.Unit
            bg.CFrame = CFrame.new(hrp.Position, hrp.Position + lookDirection)
        end
    end
    if tick() % 0.5 < 0.05 then hum:MoveTo(target) end
end

function plantCreateAlign(hrp)
    if plantAlignPosition and plantAlignPosition.Parent then plantAlignPosition:Destroy() end
    if plantAttachment0 and plantAttachment0.Parent then plantAttachment0:Destroy() end
    if plantAttachment1 and plantAttachment1.Parent then plantAttachment1:Destroy() end
    plantAttachment0 = Instance.new("Attachment")
    plantAttachment0.Parent = hrp
    plantAttachment1 = Instance.new("Attachment")
    plantAttachment1.Parent = workspace.Terrain
    plantAlignPosition = Instance.new("AlignPosition")
    plantAlignPosition.Attachment0 = plantAttachment0
    plantAlignPosition.Attachment1 = plantAttachment1
    plantAlignPosition.ForceLimitMode = Enum.ForceLimitMode.Magnitude
    -- High force so Tween doesn't lose to collision and fall back to looking like a walk.
    plantAlignPosition.MaxForce = 4000000
    plantAlignPosition.MaxVelocity = 100
    plantAlignPosition.Responsiveness = 200
    plantAlignPosition.ApplyAtCenterOfMass = true
    plantAlignPosition.Parent = hrp
    return plantAlignPosition, plantAttachment1
end

function plantRemoveAlign()
    if plantAlignPosition then
        plantAlignPosition.Enabled = false
    end
end

_plantBV = nil
_plantBG = nil

function plantRemoveBodyVelocity(hrp)
    if _plantBV and _plantBV.Parent then _plantBV:Destroy() end
    if _plantBG and _plantBG.Parent then _plantBG:Destroy() end
    _plantBV = nil
    _plantBG = nil
end

function plantTweenToTarget(hrp, hum, target, speed)
    plantRemoveBodyVelocity(hrp)
    if not plantAlignPosition or not plantAlignPosition.Parent then
        plantAlignPosition, plantAttachment1 = plantCreateAlign(hrp)
        plantAlignPosition.ForceLimitMode = Enum.ForceLimitMode.Magnitude
    end
    plantAlignPosition.Enabled = true
    plantAttachment1.WorldPosition = target
    plantAlignPosition.MaxVelocity = speed
    hum:ChangeState(Enum.HumanoidStateType.Physics)
    plantIsTweening = true
end

function plantUpdateTarget(hrp, hum, target, speed)
    if not plantAlignPosition or not plantAttachment1 then
        plantTweenToTarget(hrp, hum, target, speed)
        return
    end
    plantAttachment1.WorldPosition = target
    if plantAlignPosition.MaxVelocity ~= speed then
        plantAlignPosition.MaxVelocity = speed
    end
    if not plantAlignPosition.Enabled then
        plantAlignPosition.Enabled = true
    end
    if hum:GetState() ~= Enum.HumanoidStateType.Physics then
        hum:ChangeState(Enum.HumanoidStateType.Physics)
    end
    plantIsTweening = true
end

local _walkMaxForce = Vector3.new(math.huge, 0, math.huge)
local _walkMaxTorque = Vector3.new(math.huge, math.huge, math.huge)

function smoothWalkToTarget(hrp, hum, target, speed)
    if not _plantBV or not _plantBV.Parent then
        _plantBV = Instance.new("BodyVelocity")
        _plantBV.Name = "PlantBodyVelocity"
        _plantBV.MaxForce = _walkMaxForce
        _plantBV.Parent = hrp
    end
    if not _plantBG or not _plantBG.Parent then
        _plantBG = Instance.new("BodyGyro")
        _plantBG.Name = "PlantBodyGyro"
        _plantBG.MaxTorque = _walkMaxTorque
        _plantBG.P = 9000
        _plantBG.Parent = hrp
    end
    local dx = target.X - hrp.Position.X
    local dz = target.Z - hrp.Position.Z
    local mag = math.sqrt(dx * dx + dz * dz)
    if mag > 1.5 then
        local ux, uz = dx / mag, dz / mag
        _plantBV.Velocity = Vector3.new(ux * speed, 0, uz * speed)
        _plantBG.CFrame = CFrame.new(hrp.Position, hrp.Position + Vector3.new(ux, 0, uz))
    else
        _plantBV.Velocity = Vector3.new(0, 0, 0)
    end
    if tick() % 0.5 < 0.05 then hum:MoveTo(target) end
    plantIsTweening = true
end

_plantPrevWalkSpeed = nil
_walkMoveToTarget = nil
_walkMoveToAt = 0

function plantingRestoreWalkSpeed(hum)
    _walkMoveToTarget = nil
    _walkMoveToAt = 0
    if _plantPrevWalkSpeed and hum then
        hum.WalkSpeed = _plantPrevWalkSpeed
    end
    _plantPrevWalkSpeed = nil
end

-- Real Humanoid walk (Tween Select "Walk"). No BodyVelocity — that's SmoothWalk.
function walkToTarget(hrp, hum, target, speed)
    plantRemoveAlign()
    plantRemoveBodyVelocity(hrp)
    if hum:GetState() == Enum.HumanoidStateType.Physics then
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Running) end)
    end
    local walkSpeed = math.clamp(tonumber(speed) or 16, 1, 21)
    if not _plantPrevWalkSpeed then
        _plantPrevWalkSpeed = hum.WalkSpeed
    end
    if math.abs(hum.WalkSpeed - walkSpeed) > 0.05 then
        hum.WalkSpeed = walkSpeed
    end
    local now = tick()
    local far = (hrp.Position - target).Magnitude > 4
    local cancelled = hum.MoveDirection.Magnitude < 0.15 and far
    local farming = Settings.TweenToBushAndBox or Settings.TweenToBush or Settings.TweenToPlantBox
    if farming and (cancelled or not _walkMoveToTarget or (_walkMoveToTarget - target).Magnitude > 1.5 or (now - _walkMoveToAt) > 0.08) then
        pcall(function() hum:MoveTo(target) end)
        _walkMoveToTarget = target
        _walkMoveToAt = now
    elseif not farming and (not _walkMoveToTarget or (_walkMoveToTarget - target).Magnitude > 1.5 or (now - _walkMoveToAt) > 0.2) then
        pcall(function() hum:MoveTo(target) end)
        _walkMoveToTarget = target
        _walkMoveToAt = now
    end
    plantIsTweening = true
end

local _zeroVec = Vector3.new(0, 0, 0)

function plantStopMovement()
    if Settings.TweenToBushAndBox or Settings.TweenToBush or Settings.TweenToPlantBox then
        return
    end
    if not plantIsTweening and not waterTweenActive then return end
    local char = plr.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if hrp then
        plantRemoveBodyVelocity(hrp)
        hrp.Velocity = _zeroVec
        hrp.RotVelocity = _zeroVec
    end
    plantRemoveAlign()
    plantIsTweening = false
    waterTweenActive = false
    stuckCheckWaypoint = nil
    stuckCheckStartDistance = nil
    stuckCheckTimer = 0
    local hum = char:FindFirstChild("Humanoid")
    if hum then
        hum:ChangeState(Enum.HumanoidStateType.Running)
        plantingRestoreWalkSpeed(hum)
    else
        plantingRestoreWalkSpeed(nil)
    end
    if not Settings.GoldNoclip then restoreCollision() end
end

antiFlipGyro = nil
function enableAntiFlip(hrp)
    if not antiFlipGyro then
        antiFlipGyro = Instance.new("BodyGyro")
        antiFlipGyro.Name = "AntiFlipGyro"
        antiFlipGyro.MaxTorque = Vector3.new(math.huge, 0, math.huge)
        antiFlipGyro.P = 9000
        antiFlipGyro.CFrame = CFrame.new()
        antiFlipGyro.Parent = hrp
    end
end
function disableAntiFlip() if antiFlipGyro then antiFlipGyro:Destroy() antiFlipGyro = nil end end

restoreCollision = function()
    if plr.Character then
        local character = plr.Character
        local hum = character:FindFirstChild("Humanoid")
        local hrp = character:FindFirstChild("HumanoidRootPart")
        for _, part in pairs(character:GetDescendants()) do
            if part:IsA("BasePart") then
                local wanted = originalCollision[part]
                if wanted ~= nil then part.CanCollide = wanted end
            end
        end
        if hum then hum:ChangeState(Enum.HumanoidStateType.Running) hum.PlatformStand = false hum.Sit = false hum.AutoRotate = true end
        if hrp then hrp.Velocity = Vector3.new(0, 0, 0) hrp.RotVelocity = Vector3.new(0, 0, 0) end
    end
end

movementConnection = nil
walkAttemptTimer = 0
maxWalkAttemptTime = 3
stuckCheckWaypoint = nil
stuckCheckStartDistance = nil
stuckCheckTimer = 0
STUCK_CHECK_INTERVAL = 3
MINIMUM_PROGRESS = 2
waterTweenActive = false
positionHistory = {}
maxHistorySize = 5

noclipTimer = 0
end -- AsterGameCore

do -- AsterGameCoreMovement
local noclipWorldParts = {}
local noclipDepOverlap = OverlapParams.new()
noclipDepOverlap.FilterType = Enum.RaycastFilterType.Include

function disableWorldCollision(part)
    if not part or not part:IsA("BasePart") then return end
    if noclipWorldParts[part] ~= nil then return end
    noclipWorldParts[part] = part.CanCollide
    part.CanCollide = false
end

function restoreWorldNoclip()
    for part, wanted in pairs(noclipWorldParts) do
        if part and part.Parent then
            part.CanCollide = wanted
        end
    end
    noclipWorldParts = {}
end

function noclip()
    if not Settings.GoldNoclip and not isTweening then return end
    local waitTime = 0.15
    if Settings.GoldNoclip and UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled then
        waitTime = 0.3
    end
    if tick() - noclipTimer < waitTime then return end
    noclipTimer = tick()
    if plr.Character then
        local hrp = plr.Character:FindFirstChild("HumanoidRootPart")
        for _, part in pairs(plr.Character:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                if isTweening then
                    part.CanCollide = false
                else
                    if not (part.Name:find("Leg") or part.Name:find("Foot")) then
                        part.CanCollide = false
                    end
                end
            end
        end
        if Settings.GoldNoclip and hrp and not (Settings.TweenToBushAndBox or Settings.TweenToPlantBox or Settings.TweenToBush) then
            pcall(function()
                local hrpPos = hrp.Position
                local radiusSq = 55 * 55
                local resources = getWorkspaceResources()
                if resources then
                    for _, model in ipairs(resources:GetChildren()) do
                        if model.Name == "Old Boards" then
                            local union = model:FindFirstChild("Union")
                            if union and union:IsA("BasePart") then
                                local d = union.Position - hrpPos
                                if d.X * d.X + d.Y * d.Y + d.Z * d.Z <= radiusSq then
                                    disableWorldCollision(union)
                                end
                            end
                        end
                    end
                end
                local deployables = getWorkspaceDeployables()
                if deployables then
                    noclipDepOverlap.FilterDescendantsInstances = {deployables}
                    local nearby = workspace:GetPartBoundsInRadius(hrpPos, 40, noclipDepOverlap)
                    local cap = math.min(#nearby, 64)
                    for i = 1, cap do
                        disableWorldCollision(nearby[i])
                    end
                end
            end)
        end
    end
end

function startWalkSpeedEnforcer()
    registerFrameUpdate("walkSpeed", function(deltaTime)
        local needsFreeCam = Settings.FreeCam == true
        local needsWalk = Settings.WalkSpeedEnabled == true and not Settings.GoldCircuitEnabled
        local needsHip = Settings.HipHeightEnabled == true
        if not needsFreeCam and not needsWalk and not needsHip then return end

        if needsFreeCam and not (UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled) then
            local camera = workspace.CurrentCamera
            if not camera then return end
            local baseSpeed = (Settings.FreeCamSpeed or 3)
            local speedMultiplier = 1

            if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) or UserInputService:IsKeyDown(Enum.KeyCode.RightShift) then
                speedMultiplier = 4
            end

            local speed = baseSpeed * speedMultiplier * 60 * deltaTime
            local moveVector = Vector3.new(0, 0, 0)

            if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveVector = moveVector + camera.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveVector = moveVector - camera.CFrame.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveVector = moveVector - camera.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveVector = moveVector + camera.CFrame.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.E) then moveVector = moveVector + Vector3.new(0, 1, 0) end
            if UserInputService:IsKeyDown(Enum.KeyCode.Q) then moveVector = moveVector - Vector3.new(0, 1, 0) end

            if moveVector.Magnitude > 0 then
                camera.CFrame = camera.CFrame + moveVector.Unit * speed
            end

            if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
                local mouseDelta = UserInputService:GetMouseDelta()
                local rotationSpeed = 0.2

                Settings.FreeCamYaw = (Settings.FreeCamYaw or 0) - mouseDelta.X * rotationSpeed
                Settings.FreeCamPitch = (Settings.FreeCamPitch or 0) - mouseDelta.Y * rotationSpeed
                Settings.FreeCamPitch = math.clamp(Settings.FreeCamPitch, -89, 89)

                camera.CFrame = CFrame.new(camera.CFrame.Position) * CFrame.fromEulerAnglesYXZ(
                    math.rad(Settings.FreeCamPitch),
                    math.rad(Settings.FreeCamYaw),
                    0
                )
            else
                UserInputService.MouseBehavior = Enum.MouseBehavior.Default
            end
        end

        if needsWalk or needsHip then
            local character = plr.Character
            if not character then return end
            local hum = character:FindFirstChild("Humanoid")
            if not hum then return end
            if needsWalk then
                local wantedSpeed = Settings.WalkSpeed or 16
                if hum.WalkSpeed ~= wantedSpeed then
                    hum.WalkSpeed = wantedSpeed
                end
            end
            if needsHip then
                local wantedHeight = Settings.HipHeight or 2
                if math.abs(hum.HipHeight - wantedHeight) > 0.01 then
                    hum.HipHeight = wantedHeight
                end
            end
        end
    end)
    ensureMasterFrameLoop()
end

function startMovementEngine()
    if movementConnection then return end
    positionHistory = {}
    local lastFramePos = nil
    local isWaitingForDelay = false
    local delayStartTime = 0
    local lastDecisionTick = 0
    local cachedShouldTween = false
    local cachedTweenReason = ""
    local cachedWalkSpeed = 20
    movementConnection = runs.Heartbeat:Connect(function(deltaTime)
        if not Settings.GoldCircuitEnabled then
            if movementConnection then movementConnection:Disconnect() movementConnection = nil end
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then removeBodyVelocity(hrp) end
            if hrp and not isTweening then table.insert(positionHistory, hrp.Position) if #positionHistory > maxHistorySize then table.remove(positionHistory, 1) end end
            restoreCollision()
            isTweening = false walkingToWaypoint = false walkAttemptTimer = 0 stuckCheckWaypoint = nil stuckCheckStartDistance = nil stuckCheckTimer = 0 isWaitingForWaypoint = false
            isWaitingForDelay = false delayStartTime = 0
            lastFramePos = nil
            return
        end
        
        if #Settings.recordedPositions == 0 then return end
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
        if not hrp or not hum then return end
        
        local currentPos = hrp.Position
        if lastFramePos then
            local distMoved = (currentPos - lastFramePos).Magnitude
            if distMoved > 10 then 
                local closestIndex, closestDist = findNearestAccessibleWaypoint(currentPos)
                if closestIndex then
                    currentWaypoint = closestIndex
                    walkingToWaypoint = false
                    isTweening = false
                    if alignPosition then removeAlignPosition() end
                    if hum then hum:ChangeState(Enum.HumanoidStateType.Running) end
                    walkAttemptTimer = 0
                end
            end
        end
        lastFramePos = currentPos

        enableAntiFlip(hrp)
        if (hum.PlatformStand or hum.Sit or hum:GetState() == Enum.HumanoidStateType.FallingDown or hum:GetState() == Enum.HumanoidStateType.Ragdoll) and not isTweening then 
            hum.PlatformStand = false hum.Sit = false hum:ChangeState(Enum.HumanoidStateType.Running) 
        end
        if currentWaypoint > #Settings.recordedPositions then currentWaypoint = 1 walkingToWaypoint = false walkAttemptTimer = 0 removeBodyVelocity(hrp) removeAlignPosition() isTweening = false if hum then hum:ChangeState(Enum.HumanoidStateType.Running) hum.PlatformStand = false end stuckCheckWaypoint = nil stuckCheckStartDistance = nil stuckCheckTimer = 0 isWaitingForWaypoint = false return end
        local targetPos = Settings.recordedPositions[currentWaypoint]
        if not targetPos then currentWaypoint = 1 return end
        local target = Vector3.new(targetPos.X, targetPos.Y, targetPos.Z)
        local currentPos = hrp.Position
        local direction = (target - currentPos)
        local distance = direction.Magnitude
        if walkingToWaypoint and not isTweening then local velocity = hrp.Velocity.Magnitude if velocity < 0.5 and distance > 5 then walkAttemptTimer = walkAttemptTimer + deltaTime if walkAttemptTimer > 1.0 then shouldTween = true walkingToWaypoint = false walkAttemptTimer = 0 end else if velocity > 1 then walkAttemptTimer = 0 end end end
        if not isTweening then
            if stuckCheckWaypoint ~= currentWaypoint then stuckCheckWaypoint = currentWaypoint stuckCheckStartDistance = distance stuckCheckTimer = 0 else
                stuckCheckTimer = stuckCheckTimer + deltaTime
                if stuckCheckTimer >= STUCK_CHECK_INTERVAL then
                    local progressMade = stuckCheckStartDistance - distance
                    if progressMade < MINIMUM_PROGRESS then
                        local closestIndex, closestDist, foundAccessible = findNearestAccessibleWaypoint(hrp.Position)
                        if closestIndex and closestIndex ~= currentWaypoint and foundAccessible then currentWaypoint = closestIndex else currentWaypoint = currentWaypoint + 1 end
                        walkingToWaypoint = false walkAttemptTimer = 0 removeBodyVelocity(hrp) removeAlignPosition() positionHistory = {} stuckCheckWaypoint = nil stuckCheckStartDistance = nil stuckCheckTimer = 0 task.wait(0.5) return
                    else stuckCheckStartDistance = distance stuckCheckTimer = 0 end
                end
            end
        end
        if distance <= 3 then
            -- Waypoint Wait Logic
            local currentWPData = Settings.recordedPositions[currentWaypoint]
            if currentWPData and currentWPData.waitTime and currentWPData.waitTime > 0 then
                if not isWaitingForWaypoint then
                     isWaitingForWaypoint = true
                     waypointWaitStartTime = tick()
                     if isTweening then removeAlignPosition() isTweening = false hum:ChangeState(Enum.HumanoidStateType.Running) if not Settings.GoldNoclip then restoreCollision() end end
                     removeBodyVelocity(hrp)
                     hrp.Velocity = Vector3.new(0,0,0)
                     hum:MoveTo(hrp.Position)
                     return
                else
                     if tick() - waypointWaitStartTime < currentWPData.waitTime then
                         return
                     else
                         isWaitingForWaypoint = false
                     end
                end
            else
                isWaitingForWaypoint = false
            end

            -- Only drop ice at waypoint 1 (start of loop)
            if currentWaypoint == 1 then
                if Settings.AutoIceDropEnabled then
                    local iceToKeep = tonumber(Settings.IceToKeep) or 1
                    local currentIce = getInvCount("Ice Cube")
                    
                    if currentIce > iceToKeep then
                        local amountToDrop = currentIce - iceToKeep
                        -- Drop in small batches to avoid kicks, but handled by new drop() logic anyway
                        for i = 1, amountToDrop do
                            drop("Ice Cube")
                            -- Add a cooldown to prevent spamming the server
            task.wait(tonumber(Settings.HarvestCooldown) or 0.1)
                        end
                    end
                end
            end

            if not isWaitingForDelay then
                local foundGold = false
                local checkParts = workspace:GetPartBoundsInRadius(hrp.Position, 10)
                for _, p in pairs(checkParts) do
                    local nameMatch = p.Name:lower():find("gold node") or (p.Parent and p.Parent.Name:lower():find("gold node"))
                    if nameMatch or (p.Parent and p.Parent:GetAttribute("EntityID") == 422) then foundGold = true break end
                end
                
                if foundGold and Settings.GoldDelay > 0 then
                    isWaitingForDelay = true
                    delayStartTime = tick()
                    if isTweening then removeAlignPosition() isTweening = false hum:ChangeState(Enum.HumanoidStateType.Running) if not Settings.GoldNoclip then restoreCollision() end end
                    removeBodyVelocity(hrp)
                    hrp.Velocity = Vector3.new(0,0,0)
                    return
                end
            else
                if tick() - delayStartTime < Settings.GoldDelay then
                    return
                else
                    isWaitingForDelay = false
                end
            end

            local nextIndex = currentWaypoint + 1
            if nextIndex > #Settings.recordedPositions then nextIndex = 1 end
            local currentAboveWater = Settings.WaterTweenEnabled and (isAboveWater(currentPos) or isAboveWater(target))
            local nextAboveWater = false
            local nextPosData = Settings.recordedPositions[nextIndex]
            if nextPosData then local nextVec = Vector3.new(nextPosData.X, nextPosData.Y, nextPosData.Z) nextAboveWater = Settings.WaterTweenEnabled and isAboveWater(nextVec) end
            currentWaypoint = nextIndex walkingToWaypoint = false walkAttemptTimer = 0 stuckCheckWaypoint = nil stuckCheckStartDistance = nil stuckCheckTimer = 0 isWaitingForWaypoint = false
            if isTweening and nextPosData then local nextTarget = Vector3.new(nextPosData.X, nextPosData.Y, nextPosData.Z) tweenToWaypoint(hrp, hum, nextTarget, getRandomizedSpeed(WALK_SPEED)) waterTweenActive = true else
                if isTweening then removeAlignPosition() isTweening = false hum:ChangeState(Enum.HumanoidStateType.Running) if not Settings.GoldNoclip then restoreCollision() end else removeBodyVelocity(hrp) end waterTweenActive = false
            end
            return
        end
        if #positionHistory >= 3 and not isTweening then local previousPos = positionHistory[#positionHistory - 1] if previousPos then local horizontalPrev = Vector2.new(previousPos.X, previousPos.Z) local horizontalCurrent = Vector2.new(currentPos.X, currentPos.Z) local snapDistance = (horizontalCurrent - horizontalPrev).Magnitude if snapDistance > 10 then local closestIndex, closestDist = findNearestAccessibleWaypoint(hrp.Position) if closestIndex and closestIndex ~= currentWaypoint then currentWaypoint = closestIndex else currentWaypoint = currentWaypoint + 1 end positionHistory = {} walkingToWaypoint = false walkAttemptTimer = 0 removeBodyVelocity(hrp) removeAlignPosition() isTweening = false stuckCheckWaypoint = nil stuckCheckStartDistance = nil stuckCheckTimer = 0 task.wait(0.5) return end end end
        if isTweening then
            noclip()
            waterTweenActive = waterTweenActive or (Settings.WaterTweenEnabled and isAboveWater(currentPos))
            if alignPosition then alignPosition.MaxVelocity = getRandomizedSpeed(WALK_SPEED) end
            if stuckCheckStartDistance == nil then stuckCheckStartDistance = distance stuckCheckTimer = 0 end
            stuckCheckTimer = stuckCheckTimer + deltaTime
            if stuckCheckTimer > 5.0 then local progressMade = stuckCheckStartDistance - distance if progressMade < 1 then isTweening = false hum:ChangeState(Enum.HumanoidStateType.Running) removeAlignPosition() stuckCheckTimer = 0 else stuckCheckStartDistance = distance stuckCheckTimer = 0 end end
            return
        end
        if tick() - lastDecisionTick > 0.15 then
            lastDecisionTick = tick()
            local baseWalkSpeed = Settings.WalkSpeedEnabled and Settings.WalkSpeed or WALK_SPEED
            local walkSpeed = baseWalkSpeed
            local goldFound = false
            local nearbyParts = workspace:GetPartBoundsInRadius(hrp.Position, 2) for _, part in pairs(nearbyParts) do local nameMatch = part.Name:lower():find("gold node") or (part.Parent and part.Parent.Name:lower():find("gold node")) if nameMatch then goldFound = true break end end
            if not goldFound then local targetParts = workspace:GetPartBoundsInRadius(target, 2) for _, part in pairs(targetParts) do local nameMatch = part.Name:lower():find("gold node") or (part.Parent and part.Parent.Name:lower():find("gold node")) if nameMatch then goldFound = true break end end end
            if goldFound then walkSpeed = NEAR_GOLD_SPEED end
            cachedWalkSpeed = getRandomizedSpeed(walkSpeed)

            cachedShouldTween = false
            cachedTweenReason = ""
            
            -- FORCED TWEEN ONLY LOGIC FROM ASTERFarm.lua
            if Settings.TweenOnly then
                cachedShouldTween = true
                cachedTweenReason = "Forced"
            else
                local heightDiff = target.Y - currentPos.Y
                local horizontalDist = math.sqrt((target.X - currentPos.X)^2 + (target.Z - currentPos.Z)^2)
                local wouldHitTerrain, hitPoint = wouldTweenHitTerrain(currentPos, target)
                
                if wouldHitTerrain then cachedShouldTween = false elseif heightDiff < -2 then cachedShouldTween = false else
                    local pathClear, hitPos = isPathClearToTarget(currentPos, target)
                    if not pathClear then cachedShouldTween = true cachedTweenReason = "Path blocked" end
                    if heightDiff > 6 and horizontalDist < 10 then cachedShouldTween = true cachedTweenReason = "Steep climb" end
                    local hasGround, groundDistance = hasGroundBeneath(target)
                    if not hasGround or groundDistance > 15 then cachedShouldTween = true cachedTweenReason = "No ground" end
                    if isAboveWater(target) then cachedShouldTween = true cachedTweenReason = "Water" waterTweenActive = true end
                    local directionToTarget = (target - currentPos).Unit
                    local rayToTarget = workspace:Raycast(currentPos, directionToTarget * distance, rayParams)
                    if rayToTarget and rayToTarget.Instance and not rayToTarget.Instance:IsDescendantOf(plr.Character) then cachedShouldTween = true cachedTweenReason = "Wall" end
                end
            end
        end

        if walkingToWaypoint then 
            walkAttemptTimer = walkAttemptTimer + deltaTime 
            if walkAttemptTimer > maxWalkAttemptTime then 
                local horizontalDist = math.sqrt((target.X - currentPos.X)^2 + (target.Z - currentPos.Z)^2)
                local startDist = (Vector3.new(targetPos.X, currentPos.Y, targetPos.Z) - currentPos).Magnitude 
                if startDist > horizontalDist - 5 then cachedShouldTween = true cachedTweenReason = "Stuck walking" walkAttemptTimer = 0 end 
            end 
        end
        
        hum.WalkSpeed = Settings.WalkSpeed or 16
        
        if cachedShouldTween then
            if cachedTweenReason == "Water" then waterTweenActive = true end
            walkingToWaypoint = false walkAttemptTimer = 0 stuckCheckStartDistance = distance stuckCheckTimer = 0
            tweenToWaypoint(hrp, hum, target, cachedWalkSpeed)
        else
            if not walkingToWaypoint then walkingToWaypoint = true walkAttemptTimer = 0 end
            walkToWaypoint(hrp, hum, target, cachedWalkSpeed)
        end
    end)
end

local goldNoclipActive = false
do
    local old = __ASTER_RUNTIME.connections["goldNoclip"]
    if old and old.Disconnect then
        pcall(function() old:Disconnect() end)
        __ASTER_RUNTIME.connections["goldNoclip"] = nil
    end
end
function startGoldNoclip()
    if goldNoclipActive then return end
    goldNoclipActive = true
    task.spawn(function()
        local RunService = game:GetService("RunService")
        local connection
        connection = RunService.Heartbeat:Connect(function()
            if not Settings.GoldNoclip then
                connection:Disconnect()
                return
            end
            noclip()
        end)
        trackConnection("goldNoclip", connection)
        while Settings.GoldNoclip do
            task.wait(0.5)
        end
        if connection then connection:Disconnect() end
        __ASTER_RUNTIME.connections["goldNoclip"] = nil
        goldNoclipActive = false
        restoreWorldNoclip()
        restoreCollision()
    end)
end

-- [ Shared Equip Logic ] --
function getToolSlot(toolName)
    local GameUtil = nil
    pcall(function() GameUtil = require(game:GetService("ReplicatedStorage").Modules.GameUtil) end)
    if not GameUtil then return nil end
    local toolbar = GameUtil.Data.toolbar
    if not toolbar then return nil end
    for i = 1, 6 do
        if toolbar[i] and toolbar[i].name == toolName then
            return i
        end
    end
    return nil
end

function equipItemPacket(name)
     if ByteNetReliable then
         local slot = getToolSlot(name)
         if slot then
             local equipPacketId = getPacketId("EquipTool")
             if not equipPacketId then return end
             local b = buffer.create(4)
             buffer.writeu8(b, 0, 0)
             buffer.writeu8(b, 1, equipPacketId)
             buffer.writeu16(b, 2, slot)
             ByteNetReliable:FireServer(b)
         else
             if plr.Character then
                 local tool = plr.Backpack:FindFirstChild(name)
                 if tool then plr.Character.Humanoid:EquipTool(tool) end
             end
         end
     else
         if plr.Character then
             local tool = plr.Backpack:FindFirstChild(name)
             if tool then plr.Character.Humanoid:EquipTool(tool) end
         end
     end
end

function isToolEquipped(toolName)
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local plrFolder = playersFolder:FindFirstChild(plr.Name)
        if plrFolder then
            local toolsFolder = plrFolder:FindFirstChild("Tools")
            if toolsFolder and toolsFolder:FindFirstChild(toolName) then
                return true
            end
        end
    end
    if plr.Character and plr.Character:FindFirstChild(toolName) then
        return true
    end
    return false
end

function isAnyToolEquipped()
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local plrFolder = playersFolder:FindFirstChild(plr.Name)
        if plrFolder then
            local toolsFolder = plrFolder:FindFirstChild("Tools")
            if toolsFolder and #toolsFolder:GetChildren() > 0 then
                return true
            end
        end
    end
    if plr.Character and plr.Character:FindFirstChildOfClass("Tool") then
        return true
    end
    return false
end

local healSwingExcludedTools = {"bow", "potion", "sling", "saddle", "fishing rod", "horn", "shovel"}

function hasHealSwingTool()
    local function isSwingableToolName(name)
        if not name or name == "" then return false end
        local lowerName = string.lower(name)
        for _, kw in ipairs(healSwingExcludedTools) do
            if string.find(lowerName, kw, 1, true) then
                return false
            end
        end
        return true
    end

    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local plrFolder = playersFolder:FindFirstChild(plr.Name)
        local toolsFolder = plrFolder and plrFolder:FindFirstChild("Tools")
        if toolsFolder then
            for _, tool in ipairs(toolsFolder:GetChildren()) do
                if isSwingableToolName(tool.Name) then
                    return true
                end
            end
        end
    end

    local char = plr.Character
    if char then
        for _, child in ipairs(char:GetChildren()) do
            if child:IsA("Tool") and isSwingableToolName(child.Name) then
                return true
            end
        end
    end
    return false
end

local goldEquipActive = false

local function findNearbyPlantBox(hrp, range)
    range = range or 25
    if not hrp then return false end
    local rangeSq = range * range
    local hrpPos = hrp.Position
    local boxes = getPlantBoxModelsCached()
    if boxes then
        for i = 1, #boxes do
            local model = boxes[i]
            if model and model.Parent then
                local part = getPlantBoxPartCheap(model)
                if part then
                    local d = hrpPos - part.Position
                    if (d.X * d.X + d.Y * d.Y + d.Z * d.Z) <= rangeSq then
                        return true
                    end
                end
            end
        end
    end
    return false
end

function startGoldEquipManager()
    if goldEquipActive then return end
    if not Settings.GoldAutoEquip then return end
    goldEquipActive = true
    task.spawn(function()
        local HOE_RANGE = 30
        while Settings.GoldAutoEquip and not ScriptKilled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end

                local nearby = findNearbyPlantBox(hrp, HOE_RANGE)
                if nearby then
                    local hoeName = Settings.GoldHoeType or "Wood Hoe"
                    if not isToolEquipped(hoeName) then
                        equipItemPacket(hoeName)
                        task.wait(0.35)
                    end
                else
                    local pickName = "God Pick"
                    if not isToolEquipped(pickName) then
                        equipItemPacket(pickName)
                        task.wait(0.35)
                    end
                end
            end)
            task.wait(0.4)
        end
        goldEquipActive = false
    end)
end

local goldActive = false
function stopGoldCircuit()
    Settings.GoldCircuitEnabled = false
    if movementConnection then
        movementConnection:Disconnect()
        movementConnection = nil
    end
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if hrp then
        removeBodyVelocity(hrp)
        removeAlignPosition()
    end
    if restoreCollision then restoreCollision() end
    isTweening = false
    walkingToWaypoint = false
    goldActive = false
    walkAttemptTimer = 0
    stuckCheckWaypoint = nil
    stuckCheckStartDistance = nil
    stuckCheckTimer = 0
    isWaitingForWaypoint = false
    isWaitingForDelay = false
    delayStartTime = 0
    lastFramePos = nil
end

function startGoldCircuit()
    if goldActive then return end
    goldActive = true
    
    -- Cleanup Old Boards
    local res = getWorkspaceResources()
    if res then
        for _, v in ipairs(res:GetChildren()) do
            if v.Name == "Old Boards" then
                v:Destroy()
            end
        end
    end

    updateRayParams()
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if hrp and Settings.recordedPositions and #Settings.recordedPositions > 0 then
        local closestIndex = 1
        local closestDist = math.huge
        for idx, pos in ipairs(Settings.recordedPositions) do
            local waypoint = Vector3.new(pos.X, pos.Y, pos.Z)
            local dist = (waypoint - hrp.Position).Magnitude
            if dist < closestDist then
                closestDist = dist
                closestIndex = idx
            end
        end
        currentWaypoint = closestIndex
    end
    startMovementEngine()
    
    -- Start Auto Equip Manager separately to keep main loop pure
    if Settings.GoldAutoEquip then
        startGoldEquipManager()
    end
    
    task.spawn(function()
        while Settings.GoldCircuitEnabled do task.wait(0.5) end
        goldActive = false
    end)
end

end -- AsterGameCoreMovement

do -- AsterPathFinder
local PATHFINDER_MAP_SCAN_INTERVAL = 2
local PATHFINDER_STAND_DIST = 2
local PATHFINDER_ROUTE_STEP = 60
local PATHFINDER_ROUTE_GRID = 48
local PATHFINDER_MAX_ROUTE_LEAD = 6
local PATHFINDER_MAX_WAYPOINT_Y_GAP = 7
local PATHFINDER_REACH_PROBE_GOALS = 5
local PATHFINDER_REACH_PROBE_CANDIDATES = 8
local PATHFINDER_UNREACHABLE_BLOCK = 18
local PATHFINDER_NEAR_ORE_RADIUS = 20
local PATHFINDER_UNDERGROUND_Y_GAP = 6
local PATHFINDER_CAVE_GOAL_DIST = 14

local PATHFINDER_ORE_NAMES = {
    "Iron Node",
    "Adurite Node",
    "Gold Node",
    "Stone Node",
    "Coal Node",
    "Crystal Lode",
    "Emerald Lode",
}

PATHFINDER_ITEMS = {}
PATHFINDER_ENTITY_TO_NAME = {}

function getPathFinderWorkspaceFolder(folderName)
    if folderName == "Resources" then return getWorkspaceResources() end
    if folderName == "Deployables" then return getWorkspaceDeployables() end
    if folderName == "Critters" then return getWorkspaceCritters() end
    if folderName == "Crops" then return getWorkspaceCrops() end
    local folder = workspace:FindFirstChild(folderName)
    if folder then return folder end
    for _, top in ipairs(workspace:GetChildren()) do
        local sub = top:FindFirstChild(folderName)
        if sub then return sub end
    end
    return nil
end

function pathFinderGetMatchSubject(item)
    if not item or not item.Parent then return nil end
    if item:IsA("Model") then return item end
    if item:IsA("BasePart") then
        local parent = item.Parent
        if parent and parent:IsA("Model") then
            return parent
        end
        return item
    end
    return nil
end

function pathFinderCollectNames(folder)
    local names = {}
    local seen = {}
    if not folder then return names end
    local function addName(name)
        if name and name ~= "" and not seen[name] then
            seen[name] = true
            table.insert(names, name)
        end
    end
    for _, item in ipairs(folder:GetDescendants()) do
        local subject = pathFinderGetMatchSubject(item)
        if subject then
            addName(subject.Name)
        elseif item:IsA("Folder") then
            addName(item.Name)
        end
    end
    return names
end

function getPathFinderNamesFromWorkspace()
    local seen = {}
    local names = {}
    local function addName(name)
        if name and name ~= "" and not seen[name] then
            seen[name] = true
            table.insert(names, name)
        end
    end
    for _, name in ipairs(PATHFINDER_ORE_NAMES) do
        addName(name)
    end
    for _, name in ipairs(pathFinderCollectNames(getPathFinderWorkspaceFolder("Critters"))) do
        addName(name)
    end
    for _, name in ipairs(pathFinderCollectNames(getPathFinderWorkspaceFolder("Resources"))) do
        addName(name)
    end
    table.sort(names)
    return names
end

function resolvePathFinderItemId(itemName)
    if not itemName or itemName == "" then
        return 0
    end
    local id = (type(autoDiscoverItemID) == "function") and autoDiscoverItemID(itemName) or nil
    if id == nil and type(craftNameToID) == "table" then
        id = craftNameToID[itemName]
    end
    return tonumber(id) or 0
end

function refreshPathFinderItemIds()
    table.clear(PATHFINDER_ITEMS)
    table.clear(PATHFINDER_ENTITY_TO_NAME)
    for _, name in ipairs(getPathFinderNamesFromWorkspace()) do
        local eid = resolvePathFinderItemId(name)
        PATHFINDER_ITEMS[name] = eid
        if eid ~= 0 then
            PATHFINDER_ENTITY_TO_NAME[eid] = name
        end
    end
end

refreshPathFinderItemIds()

function getPathFinderEntityId(item)
    if not item then return nil end
    local eid = item:GetAttribute("EntityID") or item:GetAttribute("ID")
    if type(eid) == "number" then return eid end
    return tonumber(eid)
end

function pathFinderMatchesOre(item, itemName)
    if not item or not itemName or itemName == "" then
        return false
    end
    local subject = pathFinderGetMatchSubject(item)
    if not subject or not subject.Parent then
        return false
    end
    local eid = getPathFinderEntityId(subject) or getPathFinderEntityId(item)
    local wantEid = resolvePathFinderItemId(itemName)
    if wantEid ~= 0 and eid == wantEid then
        return true
    end
    local name = subject.Name
    if name == itemName then
        return true
    end
    local base = itemName:gsub(" Node", ""):gsub(" Lode", "")
    if base ~= itemName and name:find(base, 1, true) then
        return true
    end
    return false
end

function pathFinderGetOrePart(item)
    if not item then return nil end
    local subject = pathFinderGetMatchSubject(item) or item
    local nodePart = subject:FindFirstChild("Node")
    if nodePart and nodePart:IsA("BasePart") then
        return nodePart
    end
    if subject:IsA("Model") then
        return subject.PrimaryPart or subject:FindFirstChildWhichIsA("BasePart", true)
    end
    return subject:IsA("BasePart") and subject or nil
end

function pathFinderGetOreCFrame(item)
    if not item then return nil end
    local subject = pathFinderGetMatchSubject(item) or item
    local nodePart = subject:FindFirstChild("Node")
    if nodePart and nodePart:IsA("BasePart") then
        return nodePart.CFrame
    end
    if subject:IsA("Model") then
        local ok, pivot = pcall(function() return subject:GetPivot() end)
        if ok and pivot then return pivot end
    end
    if subject:IsA("BasePart") then
        return subject.CFrame
    end
    local ppart = subject:FindFirstChildWhichIsA("BasePart", true)
    return ppart and ppart.CFrame or nil
end

function pathFinderIsInTargetFolder(item)
    if not item or not item.Parent then return false, nil end
    local resourcesFolder = getPathFinderWorkspaceFolder("Resources")
    local crittersFolder = getPathFinderWorkspaceFolder("Critters")
    if resourcesFolder and item:IsDescendantOf(resourcesFolder) then
        return true, resourcesFolder
    end
    if crittersFolder and item:IsDescendantOf(crittersFolder) then
        return true, crittersFolder
    end
    return false, nil
end

function pathFinderIsMapTarget(item)
    if not item or not item.Parent then
        return false
    end
    local inFolder = pathFinderIsInTargetFolder(item)
    if not inFolder then
        return false
    end
    local subject = pathFinderGetMatchSubject(item)
    if not subject then
        return false
    end
    return pathFinderGetOreCFrame(subject) ~= nil
end

function isOrePhysicallySpawned(item)
    if not pathFinderIsMapTarget(item) then
        return false
    end
    local subject = pathFinderGetMatchSubject(item) or item
    local part = pathFinderGetOrePart(subject)
    if not part or not part.Parent then
        return false
    end
    if part.Size.Magnitude < 0.01 then
        return false
    end
    return true
end

function pathFinderGetRouteHRP()
    -- Booga Booga Reborn: detection uses workspace.Players.HumanoidRootPart (authoritative route body)
    local playersFolder = workspace:FindFirstChild("Players")
    if not playersFolder then return nil end
    local routePart = playersFolder:FindFirstChild("HumanoidRootPart")
    if routePart and routePart:IsA("BasePart") then
        return routePart
    end
    return nil
end

function pathFinderGetDetectPosition(charHrp)
    local routeHrp = pathFinderGetRouteHRP()
    if routeHrp then
        return routeHrp.Position, routeHrp
    end
    if charHrp then
        return charHrp.Position, nil
    end
    return nil, nil
end

function pathFinderGetRoutePosition(charHrp)
    return pathFinderGetDetectPosition(charHrp)
end

function pathFinderCharLeadXZ(charHrp, routeHrp)
    if not charHrp or not routeHrp then return 0 end
    return (Vector3.new(charHrp.Position.X, 0, charHrp.Position.Z)
        - Vector3.new(routeHrp.Position.X, 0, routeHrp.Position.Z)).Magnitude
end

function pathFinderNearWaypoint(a, b, xzMax, yMax)
    if not a or not b then return false end
    xzMax = xzMax or 5
    yMax = yMax or PATHFINDER_MAX_WAYPOINT_Y_GAP
    local xz = (Vector3.new(a.X, 0, a.Z) - Vector3.new(b.X, 0, b.Z)).Magnitude
    if xz > xzMax then return false end
    if math.abs(a.Y - b.Y) > yMax then return false end
    return true
end

function pathFinderClampTargetToRoute(routeHrp, targetWp, maxLead)
    if not routeHrp or not targetWp then return targetWp end
    maxLead = maxLead or PATHFINDER_MAX_ROUTE_LEAD
    local flat = Vector3.new(targetWp.X - routeHrp.Position.X, 0, targetWp.Z - routeHrp.Position.Z)
    if flat.Magnitude <= maxLead then
        return targetWp
    end
    local clamped = routeHrp.Position + flat.Unit * maxLead
    return Vector3.new(clamped.X, targetWp.Y, clamped.Z)
end

function pathFinderGetSurfaceY(x, z, refY)
    pathFinderUpdateRayParams()
    local startY = (refY or 0) + 320
    local hit = workspace:Raycast(
        Vector3.new(x, startY, z),
        Vector3.new(0, -900, 0),
        rayParams
    )
    return hit and hit.Position.Y or nil
end

function pathFinderIsOreUnderground(orePos, hrpPos)
    if not orePos then return false end
    local refY = math.max(orePos.Y, hrpPos and hrpPos.Y or orePos.Y)
    local surfaceY = pathFinderGetSurfaceY(orePos.X, orePos.Z, refY)
    if not surfaceY then return false end
    return orePos.Y < surfaceY - PATHFINDER_UNDERGROUND_Y_GAP
end

function pathFinderGetOreBelowState(orePos, hrpPos)
    if not orePos or not hrpPos then return false, false end
    local yDiff = orePos.Y - hrpPos.Y
    local belowPlayer = yDiff < -3 or orePos.Y < hrpPos.Y - 2
    local underground = pathFinderIsOreUnderground(orePos, hrpPos)
    return belowPlayer or underground, underground
end

function pathFinderGetCaveStandPosition(orePos, hrpPos, standDist)
    standDist = standDist or PATHFINDER_STAND_DIST
    if not orePos or not hrpPos then return orePos end
    local flat = Vector3.new(hrpPos.X - orePos.X, 0, hrpPos.Z - orePos.Z)
    if flat.Magnitude < 0.05 then
        flat = Vector3.new(1, 0, 0)
    else
        flat = flat.Unit
    end
    return Vector3.new(
        orePos.X + flat.X * standDist,
        orePos.Y + 2.5,
        orePos.Z + flat.Z * standDist
    )
end

function getOreStandPosition(orePos, hrpPos, standDist)
    standDist = standDist or PATHFINDER_STAND_DIST
    if not orePos or not hrpPos then return orePos end
    if pathFinderIsOreUnderground(orePos, hrpPos) then
        return pathFinderGetCaveStandPosition(orePos, hrpPos, standDist)
    end
    pathFinderUpdateRayParams()

    local flat = Vector3.new(hrpPos.X - orePos.X, 0, hrpPos.Z - orePos.Z)
    if flat.Magnitude < 0.05 then
        flat = Vector3.new(1, 0, 0)
    else
        flat = flat.Unit
    end

    local standPos = orePos + flat * standDist
    local bestStand = standPos
    local bestScore = math.huge

    for _, dist in ipairs({ standDist, standDist + 1.5, standDist + 3 }) do
        local candidate = orePos + flat * dist
        for _, startY in ipairs({ orePos.Y + 60, hrpPos.Y + 60, orePos.Y + 15 }) do
            local hit = workspace:Raycast(
                Vector3.new(candidate.X, startY, candidate.Z),
                Vector3.new(0, -300, 0),
                rayParams
            )
            if hit then
                local ground = hit.Position + Vector3.new(0, 2.5, 0)
                local score = (ground - orePos).Magnitude + math.abs(ground.Y - orePos.Y) * 0.5
                if score < bestScore then
                    bestScore = score
                    bestStand = ground
                end
            end
        end
    end
    return bestStand
end

function isDirectPathBlocked(fromPos, toPos)
    if not fromPos or not toPos then return true end
    local dir = toPos - fromPos
    local dist = dir.Magnitude
    if dist < 1 then return false end
    pathFinderUpdateRayParams()
    -- Multi-height rays catch short fences + tall spike walls / base walls
    local heights = { 1.5, 3.0, 5.0 }
    for _, h in ipairs(heights) do
        local hit = workspace:Raycast(fromPos + Vector3.new(0, h, 0), dir, rayParams)
        if hit and (hit.Position - fromPos).Magnitude < dist - 2.5 then
            local inst = hit.Instance
            if inst == workspace.Terrain then
                return true
            end
            if inst and inst:IsA("BasePart") then
                if inst.CanCollide then
                    return true
                end
                -- Some Booga walls/fences are CanCollide false but still solid via query
                local parent = inst.Parent
                local deployables = getWorkspaceDeployables()
                local unbreakable = workspace:FindFirstChild("UnbreakableResources")
                local inDeploy = parent and (
                    (deployables and inst:IsDescendantOf(deployables))
                    or (unbreakable and inst:IsDescendantOf(unbreakable))
                )
                if inDeploy and inst.Transparency < 0.9 then
                    return true
                end
            end
        end
    end
    return false
end

function pathFinderUpdateRayParams()
    if updateRayParams then updateRayParams() end
    local ignore = {}
    if plr.Character then table.insert(ignore, plr.Character) end
    local resources = getWorkspaceResources()
    if resources then table.insert(ignore, resources) end
    if workspace:FindFirstChild("Rubble") then table.insert(ignore, workspace.Rubble) end
    if workspace:FindFirstChild("PathFinderDebug") then table.insert(ignore, workspace.PathFinderDebug) end
    rayParams.FilterDescendantsInstances = ignore
    pcall(function() rayParams.RespectCanCollide = true end)
end

function pathFinderGetGroundPos(x, z, refY)
    pathFinderUpdateRayParams()
    local hit = workspace:Raycast(
        Vector3.new(x, (refY or 0) + 220, z),
        Vector3.new(0, -520, 0),
        rayParams
    )
    if hit then
        return hit.Position + Vector3.new(0, 2.5, 0)
    end
    return nil
end

function pathFinderSegmentThroughTerrain(fromPos, toPos)
    if not fromPos or not toPos then return false end
    local dist = (toPos - fromPos).Magnitude
    if dist < 1 then return false end
    pathFinderUpdateRayParams()
    -- Only reject if a horizontal ray punches straight through a terrain wall.
    local flat = Vector3.new(toPos.X - fromPos.X, 0, toPos.Z - fromPos.Z)
    if flat.Magnitude > 3 then
        local hit = workspace:Raycast(
            fromPos + Vector3.new(0, 2.5, 0),
            flat.Unit * flat.Magnitude,
            rayParams
        )
        if hit and hit.Instance == workspace.Terrain then
            local hitDist = (hit.Position - fromPos).Magnitude
            if hitDist < flat.Magnitude - 4 then
                return true
            end
        end
    end
    return false
end

function pathFinderSegmentBlocked(fromPos, toPos)
    if pathFinderSegmentThroughTerrain(fromPos, toPos) then return true end
    if isDirectPathBlocked(fromPos, toPos) then return true end
    return false
end

function pathFinderFindPathGoals(orePos, hrpPos, oreBelow, standPos)
    local goals = {}
    local seen = {}
    local function add(pos)
        if not pos then return end
        local key = math.floor(pos.X) .. ":" .. math.floor(pos.Y) .. ":" .. math.floor(pos.Z)
        if seen[key] then return end
        seen[key] = true
        table.insert(goals, pos)
    end

    add(standPos or orePos)
    add(orePos)
    pathFinderUpdateRayParams()

    -- Wide rings help route around base walls / spike fences (navmesh ignores Deployables).
    for _, ringDist in ipairs({ PATHFINDER_STAND_DIST + 2, 10, 18, 28, 40 }) do
        for i = 0, 7 do
            local ang = (i / 8) * math.pi * 2
            local sample = (standPos or orePos) + Vector3.new(math.cos(ang) * ringDist, 0, math.sin(ang) * ringDist)
            for _, startY in ipairs({ orePos.Y + 60, hrpPos.Y + 60, orePos.Y + 15 }) do
                local hit = workspace:Raycast(
                    Vector3.new(sample.X, startY, sample.Z),
                    Vector3.new(0, -300, 0),
                    rayParams
                )
                if hit and hit.Normal.Y >= 0.35 then
                    local g = hit.Position + Vector3.new(0, 2.5, 0)
                    -- Prefer stand points that have clear LOS from player side of walls
                    if not isDirectPathBlocked(hrpPos, g) or ringDist >= 18 then
                        add(g)
                    end
                    break
                end
            end
        end
    end

    -- Approach from player direction (helps cave / overhang ores).
    local toOre = orePos - hrpPos
    local flatToOre = Vector3.new(toOre.X, 0, toOre.Z)
    if flatToOre.Magnitude > 1 then
        flatToOre = flatToOre.Unit
        local right = Vector3.new(-flatToOre.Z, 0, flatToOre.X)
        for _, dist in ipairs({ 3, 6, 10, 16, 24, 36 }) do
            for _, side in ipairs({ 0, 1, -1, 2, -2 }) do
                local approach = orePos - flatToOre * dist + right * (side * 10)
                for _, startY in ipairs({ orePos.Y + 60, hrpPos.Y + 60 }) do
                    local hit = workspace:Raycast(
                        Vector3.new(approach.X, startY, approach.Z),
                        Vector3.new(0, -300, 0),
                        rayParams
                    )
                    if hit and hit.Normal.Y >= 0.35 then
                        add(hit.Position + Vector3.new(0, 2.5, 0))
                        break
                    end
                end
            end
        end
    end

    if oreBelow or orePos.Y < hrpPos.Y - 3 then
        add(Vector3.new(orePos.X, orePos.Y + 2.5, orePos.Z))
        for _, dist in ipairs({ 3, 5, 8, 12 }) do
            for _, offset in ipairs({
                Vector3.new(dist, 0, 0),
                Vector3.new(-dist, 0, 0),
                Vector3.new(0, 0, dist),
                Vector3.new(0, 0, -dist),
            }) do
                add(Vector3.new(orePos.X + offset.X, orePos.Y + 2.5, orePos.Z + offset.Z))
            end
        end
        for _, startY in ipairs({ orePos.Y + 60, orePos.Y + 30, orePos.Y + 10, hrpPos.Y + 40 }) do
            local hit = workspace:Raycast(
                Vector3.new(orePos.X, startY, orePos.Z),
                Vector3.new(0, -800, 0),
                rayParams
            )
            if hit then
                add(hit.Position + Vector3.new(0, 2.5, 0))
            end
        end
    else
        local hit = workspace:Raycast(
            Vector3.new(orePos.X, hrpPos.Y + 60, orePos.Z),
            Vector3.new(0, -800, 0),
            rayParams
        )
        if hit then add(hit.Position + Vector3.new(0, 2.5, 0)) end
    end
    return goals
end

function pathFinderScanRouteAnchors(fromPos, goalPos)
    local anchors = {}
    local seen = {}
    local function add(pos)
        if not pos then return end
        local key = math.floor(pos.X / 16) .. ":" .. math.floor(pos.Y / 8) .. ":" .. math.floor(pos.Z / 16)
        if seen[key] then return end
        seen[key] = true
        anchors[#anchors + 1] = pos
    end

    add(fromPos)
    add(goalPos)

    local delta = goalPos - fromPos
    local dist = delta.Magnitude
    if dist < 1 then return anchors end

    local numSteps = math.min(56, math.max(6, math.ceil(dist / PATHFINDER_ROUTE_STEP)))
    local refY = math.max(fromPos.Y, goalPos.Y)

    for i = 1, numSteps - 1 do
        local t = i / numSteps
        local base = fromPos + delta * t
        add(pathFinderGetGroundPos(base.X, base.Z, refY))

        local perp = Vector3.new(-delta.Z, 0, delta.X)
        if perp.Magnitude > 1 then
            perp = perp.Unit
            local spread = math.min(dist * 0.3, 140)
            for _, mul in ipairs({ 0.2, 0.45, 0.7, -0.2, -0.45, -0.7 }) do
                local off = base + perp * spread * mul
                add(pathFinderGetGroundPos(off.X, off.Z, refY))
            end
        end
    end

    local pad = math.min(100, math.max(40, dist * 0.15))
    local minX = math.min(fromPos.X, goalPos.X) - pad
    local maxX = math.max(fromPos.X, goalPos.X) + pad
    local minZ = math.min(fromPos.Z, goalPos.Z) - pad
    local maxZ = math.max(fromPos.Z, goalPos.Z) + pad
    local gridCount = 0
    local gridStep = math.max(24, math.min(PATHFINDER_ROUTE_GRID, dist / 12))
    local gridLimit = math.min(240, math.max(72, math.ceil(dist / gridStep) * 4))
    for x = minX, maxX, gridStep do
        for z = minZ, maxZ, gridStep do
            if gridCount >= gridLimit then break end
            local g = pathFinderGetGroundPos(x, z, refY)
            if g then
                add(g)
                gridCount = gridCount + 1
            end
        end
        if gridCount >= gridLimit then break end
    end

    table.sort(anchors, function(a, b)
        local da = (a - fromPos).Magnitude + (goalPos - a).Magnitude
        local db = (b - fromPos).Magnitude + (goalPos - b).Magnitude
        return da < db
    end)
    return anchors
end

function pathFinderTryComputePath(fromPos, goalPos)
    local PathfindingService = game:GetService("PathfindingService")
    local path = PathfindingService:CreatePath({
        AgentRadius = 2.5,
        AgentHeight = 5,
        AgentCanJump = true,
        AgentCanClimb = false, -- don't invent vertical cliff/fence climbs
        WaypointSpacing = 4,
        Costs = {
            [Enum.Material.Water] = math.huge,
            [Enum.Material.Rock] = 8,
            [Enum.Material.Slate] = 8,
            [Enum.Material.Basalt] = 10,
        },
    })
    local ok = pcall(function() path:ComputeAsync(fromPos, goalPos) end)
    if ok and path.Status == Enum.PathStatus.Success then
        local wps = path:GetWaypoints()
        if wps and #wps > 1 then
            return wps
        end
    end
    return nil
end

function pathFinderValidateWaypointPath(wps)
    if not wps or #wps < 2 then return false end
    for i = 2, #wps do
        local a = wps[i - 1].Position or wps[i - 1]
        local b = wps[i].Position or wps[i]
        -- Reject terrain tunnels AND player walls / spike fences (navmesh ignores Deployables)
        if pathFinderSegmentBlocked(a, b) then
            return false
        end
    end
    return true
end

function pathFinderMergeSegments(merged, segment)
    if not segment or #segment == 0 then return merged end
    local startIdx = (#merged > 0) and 2 or 1
    for i = startIdx, #segment do
        merged[#merged + 1] = segment[i]
    end
    return merged
end

function pathFinderScorePath(wps, goalPos)
    if not wps or #wps < 2 then return math.huge end
    local pathLen = 0
    for i = 2, #wps do
        pathLen = pathLen + ((wps[i].Position or wps[i]) - (wps[i - 1].Position or wps[i - 1])).Magnitude
    end
    local endPos = wps[#wps].Position or wps[#wps]
    local endDist = (endPos - goalPos).Magnitude
    return endDist * 4 + pathLen * 0.12
end

function buildFullMapRouteToOre(fromPos, orePos, oreBelow, standPos)
    local underground = pathFinderIsOreUnderground(orePos, fromPos)
    if underground then
        oreBelow = true
    end
    local goalPos = underground and orePos or (standPos or orePos)
    local goalTolerance = underground and PATHFINDER_CAVE_GOAL_DIST or 22
    local bestWps, bestScore = nil, math.huge
    local fallbackWps = nil
    local fallbackScore = math.huge

    for _, goal in ipairs(pathFinderFindPathGoals(orePos, fromPos, oreBelow, standPos)) do
        local wps = pathFinderTryComputePath(fromPos, goal)
        if wps and #wps > 1 then
            local score = pathFinderScorePath(wps, goalPos)
            if score < fallbackScore then
                fallbackScore = score
                fallbackWps = wps
            end
            if pathFinderValidateWaypointPath(wps) then
                local endPos = wps[#wps].Position or wps[#wps]
                local endToGoal = (endPos - goalPos).Magnitude
                local endToOre = (endPos - orePos).Magnitude
                local endOk
                if underground then
                    endOk = endToOre <= PATHFINDER_CAVE_GOAL_DIST
                else
                    endOk = endToGoal <= goalTolerance
                end
                if endOk then
                    if score < bestScore then
                        bestScore = score
                        bestWps = wps
                    end
                end
            end
        end
    end
    if bestWps then return bestWps end
    -- Never return an unvalidated fallback Ã¢â‚¬â€ that was walking through fences/walls.
    if fallbackWps and pathFinderValidateWaypointPath(fallbackWps) then
        return fallbackWps
    end

    local anchors = pathFinderScanRouteAnchors(fromPos, goalPos)
    local merged = {}
    local current = fromPos

    for _, anchor in ipairs(anchors) do
        if (anchor - current).Magnitude < 14 then
            continue
        end
        if (anchor - goalPos).Magnitude > (current - goalPos).Magnitude + 50 then
            continue
        end
        if pathFinderSegmentBlocked(current, anchor) then
            continue
        end
        local seg = pathFinderTryComputePath(current, anchor)
        if seg and #seg > 1 and pathFinderValidateWaypointPath(seg) then
            pathFinderMergeSegments(merged, seg)
            current = seg[#seg].Position
        end
        if (current - goalPos).Magnitude < 28 then
            break
        end
    end

    local finalSeg = pathFinderTryComputePath(current, goalPos)
    if finalSeg and #finalSeg > 1 and pathFinderValidateWaypointPath(finalSeg) then
        pathFinderMergeSegments(merged, finalSeg)
    end

    if #merged > 1 and pathFinderValidateWaypointPath(merged) then
        return merged
    end

    for _, anchor in ipairs(anchors) do
        if (anchor - fromPos).Magnitude < 14 then continue end
        if pathFinderSegmentBlocked(fromPos, anchor) then continue end
        local seg = pathFinderTryComputePath(fromPos, anchor)
        if not seg or #seg < 2 or not pathFinderValidateWaypointPath(seg) then continue end
        local tail = pathFinderTryComputePath(seg[#seg].Position, goalPos)
        if tail and #tail > 1 and pathFinderValidateWaypointPath(tail) then
            local combo = {}
            pathFinderMergeSegments(combo, seg)
            pathFinderMergeSegments(combo, tail)
            if #combo > 1 and pathFinderValidateWaypointPath(combo) then
                local score = pathFinderScorePath(combo, goalPos)
                if score < bestScore then
                    bestScore = score
                    bestWps = combo
                end
            end
        end
    end

    return bestWps
end

function pathFinderReachPosBucket(fromPos)
    if not fromPos then return "0:0" end
    return math.floor(fromPos.X / 80) .. ":" .. math.floor(fromPos.Z / 80)
end

function pathFinderGetReachCache(st, item, fromPos)
    if not st or not item then return nil end
    local cache = st.reachCache
    if not cache then return nil end
    local entry = cache[item]
    if not entry then return nil end
    if tick() - (entry.at or 0) > PATHFINDER_MAP_SCAN_INTERVAL then
        cache[item] = nil
        return nil
    end
    if entry.fromBucket and entry.fromBucket ~= pathFinderReachPosBucket(fromPos) then
        return nil
    end
    return entry.reachable
end

function pathFinderSetReachCache(st, item, fromPos, reachable)
    if not st or not item then return end
    st.reachCache = st.reachCache or {}
    st.reachCache[item] = {
        reachable = reachable,
        at = tick(),
        fromBucket = pathFinderReachPosBucket(fromPos),
    }
end

function pathFinderQuickReachable(fromPos, orePos, oreBelow, standPos)
    if not fromPos or not orePos then return false end

    local underground = pathFinderIsOreUnderground(orePos, fromPos)
    if underground then
        oreBelow = true
    end
    local goalPos = underground and orePos or (standPos or orePos)
    local reachDist = underground and PATHFINDER_CAVE_GOAL_DIST or 24
    local distToOre = (fromPos - orePos).Magnitude
    if distToOre <= PATHFINDER_STAND_DIST and math.abs(orePos.Y - fromPos.Y) <= 10 then
        return true
    end

    if underground then
        local surfaceY = pathFinderGetSurfaceY(orePos.X, orePos.Z, fromPos.Y)
        if surfaceY and fromPos.Y > surfaceY - 4 and orePos.Y < surfaceY - PATHFINDER_UNDERGROUND_Y_GAP then
            local descentGoals = pathFinderFindPathGoals(orePos, fromPos, true, standPos)
            local extraProbe = math.min(PATHFINDER_REACH_PROBE_CANDIDATES, #descentGoals)
            for i = 1, extraProbe do
                local wps = pathFinderTryComputePath(fromPos, descentGoals[i])
                if wps and #wps > 1 and pathFinderValidateWaypointPath(wps) then
                    local endPos = wps[#wps].Position or wps[#wps]
                    if (endPos - orePos).Magnitude <= PATHFINDER_CAVE_GOAL_DIST then
                        return true
                    end
                end
            end
        end
    end

    local goals = pathFinderFindPathGoals(orePos, fromPos, oreBelow, standPos)
    local probeCount = math.min(PATHFINDER_REACH_PROBE_GOALS, #goals)
    for i = 1, probeCount do
        local wps = pathFinderTryComputePath(fromPos, goals[i])
        if wps and #wps > 1 and pathFinderValidateWaypointPath(wps) then
            local endPos = wps[#wps].Position or wps[#wps]
            local endDist = underground
                and (endPos - orePos).Magnitude
                or (endPos - goalPos).Magnitude
            if endDist <= reachDist then
                return true
            end
        end
    end

    local mid = pathFinderGetGroundPos(
        (fromPos.X + goalPos.X) * 0.5,
        (fromPos.Z + goalPos.Z) * 0.5,
        math.max(fromPos.Y, goalPos.Y)
    )
    if mid then
        local seg1 = pathFinderTryComputePath(fromPos, mid)
        if seg1 and #seg1 > 1 then
            local seg2 = pathFinderTryComputePath(seg1[#seg1].Position, goalPos)
            if seg2 and #seg2 > 1 then
                local endPos = seg2[#seg2].Position or seg2[#seg2]
                local endDist = underground
                    and (endPos - orePos).Magnitude
                    or (endPos - goalPos).Magnitude
                if endDist <= (underground and PATHFINDER_CAVE_GOAL_DIST or 28)
                    and pathFinderValidateWaypointPath(seg2) then
                    return true
                end
            end
        end
    end

    return false
end

function pathFinderIsOreReachable(st, item, fromPos, orePos, oreBelow, standPos)
    if not item or not fromPos or not orePos then return false end

    local cached = pathFinderGetReachCache(st, item, fromPos)
    if cached ~= nil then
        return cached
    end

    local reachable = pathFinderQuickReachable(fromPos, orePos, oreBelow, standPos)
    pathFinderSetReachCache(st, item, fromPos, reachable)
    return reachable
end

__ASTER_RUNTIME.pathFinderState = __ASTER_RUNTIME.pathFinderState or {
    active = false,
    computing = false,
    session = 0,
    blockedNodes = {},
    reachCache = {},
    oreQueue = nil,
    activeOre = nil,
    oreCFrameTable = nil,
    cachedCFrame = nil,
    routeScanFor = nil,
}

function getPathFinderItemOptions()
    local opts = {}
    for name in pairs(PATHFINDER_ITEMS) do
        table.insert(opts, name)
    end
    table.sort(opts)
    return opts
end

function clearPathFinderVisuals()
    local folder = workspace:FindFirstChild("PathFinderDebug")
    if folder then
        folder:Destroy()
    end
end

function clearPathFinderPlannedRoute(st)
    if not st then return end
    st.plannedRoute = nil
    st.plannedRouteJumps = nil
    st.plannedRouteIndex = 1
    st.plannedRouteFor = nil
    st.routeTargetSince = nil
    st.lastRouteIndex = nil
    st.routeStuckDist = nil
end

function resetPathFinderSelection(itemName)
    if itemName and itemName ~= "" then
        Settings.PathFinderItem = itemName
    end
    local st = __ASTER_RUNTIME.pathFinderState
    if not st then return end
    st.cachedName = nil
    st.cachedTarget = nil
    st.activeOre = nil
    st.cachedPos = nil
    st.cachedCFrame = nil
    st.cachedAt = 0
    st.mapScanAt = 0
    st.mapScanItemName = nil
    st.routeScanFor = nil
    st.computing = false
    st.pathFailCount = 0
    st.walkTargetDist = nil
    st.walkTargetSince = nil
    clearPathFinderPlannedRoute(st)
    clearPathFinderVisuals()
end

function stopPathFinder()
    if type(Settings) == "table" then
        Settings.PathFinderEnabled = false
    end
    local st = __ASTER_RUNTIME.pathFinderState
    if not st then return end
    st.active = false
    st.computing = false
    st.cachedTarget = nil
    st.cachedPos = nil
    st.cachedAt = 0
    st.stuckNode = nil
    st.stuckSince = nil
    st.plannedRoute = nil
    st.plannedRouteJumps = nil
    st.plannedRouteIndex = 1
    st.plannedRouteFor = nil
    st.pathFailCount = 0
    st.oreQueue = nil
    st.activeOre = nil
    st.reachCache = nil
    st.mapOreCache = nil
    st.oreCFrameTable = nil
    st.cachedCFrame = nil
    st.routeScanFor = nil
    st.mapScanAt = 0
    st.mapScanItemName = nil
    st.walkTargetDist = nil
    st.walkTargetSince = nil
    clearPathFinderVisuals()
    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if hum and st.prevWalkSpeed then
        hum.WalkSpeed = st.prevWalkSpeed
    end
    st.prevWalkSpeed = nil
    if plantStopMovement then plantStopMovement() end
end

function pathFinderStand(hrp, hum)
    if plantStopMovement then plantStopMovement() end
    if not hrp or not hum then return end
    pcall(function()
        hum:ChangeState(Enum.HumanoidStateType.Running)
        hum:MoveTo(hrp.Position)
    end)
    pcall(function()
        hrp.Velocity = Vector3.new(0, 0, 0)
        hrp.RotVelocity = Vector3.new(0, 0, 0)
    end)
end

function pathWalkToTarget(hrp, hum, target, speed)
    hum.WalkSpeed = speed
    pcall(function()
        hum:ChangeState(Enum.HumanoidStateType.Running)
    end)
    pcall(function()
        hum:MoveTo(target)
    end)
    if smoothWalkToTarget then
        smoothWalkToTarget(hrp, hum, target, speed)
    end
end

function startPathFinder()
    local st = __ASTER_RUNTIME.pathFinderState
    if not st then return end
    if st.active then return end
    refreshPathFinderItemIds()
    st.active = true
    st.session = (st.session or 0) + 1
    local sessionId = st.session
    st.cachedAt = 0
    st.activeOre = nil
    st.oreQueue = nil
    st.mapOreCache = nil
    st.oreCFrameTable = nil
    st.cachedCFrame = nil
    st.routeScanFor = nil
    st.mapScanAt = 0
    st.mapScanItemName = nil
    st.cachedTarget = nil
    st.cachedPos = nil
    st.cachedName = nil
    st.blockedNodes = {}
    st.reachCache = {}
    st.pathFailCount = 0
    st.computing = false
    st.walkTargetDist = nil
    st.walkTargetSince = nil

    if Settings.GoldCircuitEnabled then
        Settings.GoldCircuitEnabled = false
        if Window.ElementRegistry["Gold Circuit"] and Window.ElementRegistry["Gold Circuit"].SetValue then
            Window.ElementRegistry["Gold Circuit"].SetValue(false)
        end
    end


    if not Settings.ResourceAuraEnabled then
        setSelectAuraTypeEnabled("Resource Aura", true)
    end

    task.spawn(function()
        local function getOreCFrame(item)
            return pathFinderGetOreCFrame(item)
        end

        local function getOrePos(item)
            local cf = getOreCFrame(item)
            return cf and cf.Position or nil
        end

        local function rebuildMapOreCache(itemName)
            local cache = {}
            local cframeTable = {}
            local seen = {}
            local foldersToScan = {
                getPathFinderWorkspaceFolder("Resources"),
                getPathFinderWorkspaceFolder("Critters"),
            }
            for _, targetFolder in ipairs(foldersToScan) do
                if targetFolder then
                    for _, item in ipairs(targetFolder:GetDescendants()) do
                        local subject = pathFinderGetMatchSubject(item)
                        if subject and not seen[subject] and pathFinderMatchesOre(subject, itemName) then
                            seen[subject] = true
                            if pathFinderIsMapTarget(subject) then
                                local cf = getOreCFrame(subject)
                                local orePos = cf and cf.Position or nil
                                if orePos then
                                    local entry = { item = subject, pos = orePos, cframe = cf }
                                    cache[#cache + 1] = entry
                                    cframeTable[#cframeTable + 1] = entry
                                end
                            end
                        end
                    end
                end
            end
            st.mapOreCache = cache
            st.oreCFrameTable = cframeTable
            st.mapScanItemName = itemName
            st.mapScanAt = tick()
        end

        local function scanAllOres(itemName, hrpPos, now)
            if st.mapScanItemName ~= itemName
                or (now - (st.mapScanAt or 0)) > PATHFINDER_MAP_SCAN_INTERVAL then
                rebuildMapOreCache(itemName)
            end

            local ores = {}
            for _, entry in ipairs(st.mapOreCache or {}) do
                local item = entry.item
                if item and isOrePhysicallySpawned(item) then
                    if not st.blockedNodes[item] or now >= st.blockedNodes[item] then
                        local cf = getOreCFrame(item) or entry.cframe
                        local orePos = cf and cf.Position or entry.pos
                        if orePos then
                            ores[#ores + 1] = {
                                item = item,
                                pos = orePos,
                                cframe = cf,
                                score = (orePos - hrpPos).Magnitude,
                            }
                        end
                    end
                end
            end
            table.sort(ores, function(a, b)
                return a.score < b.score
            end)
            st.oreCFrameTable = ores
            return ores
        end

        local function pickSelectedRouteTarget(itemName, hrpPos, now)
            local ores = scanAllOres(itemName, hrpPos, now)
            st.oreQueue = ores

            for i = 1, #ores do
                local entry = ores[i]
                if isOrePhysicallySpawned(entry.item)
                    and pathFinderMatchesOre(entry.item, itemName)
                    and (not st.blockedNodes[entry.item] or now >= st.blockedNodes[entry.item]) then
                    local standPos = getOreStandPosition(entry.pos, hrpPos, PATHFINDER_STAND_DIST)
                    local oreBelow, underground = pathFinderGetOreBelowState(entry.pos, hrpPos)
                    if underground then
                        oreBelow = true
                    end
                    if pathFinderIsOreReachable(st, entry.item, hrpPos, entry.pos, oreBelow, standPos) then
                        st.activeOre = entry.item
                        st.cachedTarget = entry.item
                        st.cachedPos = entry.pos
                        st.cachedCFrame = entry.cframe
                        st.cachedAt = now
                        st.cachedName = itemName
                        st.routeScanFor = nil
                        clearPathFinderPlannedRoute(st)
                        return entry.item, entry.pos, entry.cframe
                    end
                    st.blockedNodes[entry.item] = now + PATHFINDER_UNREACHABLE_BLOCK
                end
            end

            st.activeOre = nil
            st.cachedTarget = nil
            st.cachedPos = nil
            st.cachedCFrame = nil
            return nil, nil, nil
        end

        local function assignActiveOre(entry, itemName, now)
            st.activeOre = entry.item
            st.cachedTarget = entry.item
            st.cachedPos = entry.pos
            st.cachedCFrame = entry.cframe
            st.cachedAt = now
            st.cachedName = itemName
            st.routeScanFor = nil
            clearPathFinderPlannedRoute(st)
            return entry.item, entry.pos, entry.cframe
        end

        local function findLocalOre(itemName, hrpPos, now, maxRadius, excludeItem)
            maxRadius = maxRadius or PATHFINDER_NEAR_ORE_RADIUS
            local ores = scanAllOres(itemName, hrpPos, now)
            for _, entry in ipairs(ores) do
                if entry.item ~= excludeItem
                    and isOrePhysicallySpawned(entry.item)
                    and (not st.blockedNodes[entry.item] or now >= st.blockedNodes[entry.item]) then
                    local dist = entry.score or (entry.pos - hrpPos).Magnitude
                    if dist <= maxRadius then
                        return entry
                    end
                    break
                end
            end
            return nil
        end

        local function findCloserNearbyOre(itemName, hrpPos, currentItem, currentDist, now)
            if not currentItem then return nil end
            currentDist = currentDist or math.huge
            local ores = scanAllOres(itemName, hrpPos, now)
            for _, entry in ipairs(ores) do
                if entry.item ~= currentItem
                    and isOrePhysicallySpawned(entry.item)
                    and (not st.blockedNodes[entry.item] or now >= st.blockedNodes[entry.item]) then
                    local dist = entry.score or (entry.pos - hrpPos).Magnitude
                    if dist >= currentDist - 1 then
                        break
                    end
                    if dist <= PATHFINDER_NEAR_ORE_RADIUS then
                        if dist <= PATHFINDER_STAND_DIST * 4 then
                            return entry
                        end
                        local standPos = getOreStandPosition(entry.pos, hrpPos, PATHFINDER_STAND_DIST)
                        local oreBelow, underground = pathFinderGetOreBelowState(entry.pos, hrpPos)
                        if underground then
                            oreBelow = true
                        end
                        if pathFinderIsOreReachable(st, entry.item, hrpPos, entry.pos, oreBelow, standPos) then
                            return entry
                        end
                    end
                end
            end
            return nil
        end

        local pathRequestId = 0

        local function distXZ(a, b)
            return (Vector3.new(a.X, 0, a.Z) - Vector3.new(b.X, 0, b.Z)).Magnitude
        end

        local function clearPlannedRoute()
            clearPathFinderPlannedRoute(st)
        end

        local function advanceRouteIndex(route, routeIndex, routePos)
            while routeIndex <= #route do
                local pos = route[routeIndex]
                if pathFinderNearWaypoint(routePos, pos, 4, PATHFINDER_MAX_WAYPOINT_Y_GAP) then
                    routeIndex = routeIndex + 1
                else
                    break
                end
            end
            return routeIndex
        end

        local function getRouteTarget(route, routeIndex, routePos)
            if not route or routeIndex > #route then
                return nil, routeIndex
            end
            local idx = routeIndex
            -- Need matching height too ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â XZ-only would skip pit nodes while standing on the rim above
            while idx < #route and pathFinderNearWaypoint(routePos, route[idx], 5, PATHFINDER_MAX_WAYPOINT_Y_GAP) do
                idx = idx + 1
            end
            while idx > routeIndex and distXZ(routePos, route[idx]) > PATHFINDER_MAX_ROUTE_LEAD do
                idx = idx - 1
            end
            return route[idx], idx
        end

        local function trimPathWaypoints(wps, goalPos, routePos)
            if not wps or #wps < 2 then return wps end
            -- Only drop waypoints we've already passed; keep the full remaining route to the ore.
            local startIdx = 1
            for i = 1, #wps do
                if pathFinderNearWaypoint(routePos, wps[i].Position, 8, PATHFINDER_MAX_WAYPOINT_Y_GAP + 3) then
                    startIdx = i
                end
            end
            local trimmed = {}
            for i = startIdx, #wps do
                trimmed[#trimmed + 1] = wps[i]
            end
            if #trimmed < 2 then
                return wps
            end
            return trimmed
        end

        local function setPlannedRouteFromPath(wps, routePos, orePos)
            if orePos then
                wps = trimPathWaypoints(wps, orePos, routePos)
            end
            local route = {}
            local jumps = {}
            for i, wp in ipairs(wps) do
                route[i] = wp.Position or wp
                if wp.Action == Enum.PathWaypointAction.Jump then
                    jumps[i] = true
                end
            end
            st.plannedRoute = route
            st.plannedRouteJumps = jumps
            st.plannedRouteIndex = 1
            st.routeTargetSince = tick()
            st.lastRouteIndex = 1
            st.routeStuckDist = nil
            if routePos and #route > 0 then
                st.plannedRouteIndex = advanceRouteIndex(route, 1, routePos)
            end
            if orePos and #route > 0 then
                local last = route[#route]
                if (last - orePos).Magnitude > 1.5 then
                    route[#route + 1] = orePos
                end
            end
        end

        local function resolveWalkTarget(hrp, hum, targetWp, routeHrp)
            if not targetWp then return nil end
            if routeHrp then
                targetWp = pathFinderClampTargetToRoute(routeHrp, targetWp, PATHFINDER_MAX_ROUTE_LEAD)
            end
            hum.MaxSlopeAngle = 89
            local origin = (routeHrp and routeHrp.Position) or hrp.Position
            local flatDir = Vector3.new(targetWp.X - origin.X, 0, targetWp.Z - origin.Z)
            if flatDir.Magnitude <= 0.5 then return targetWp end
            if updateRayParams then updateRayParams() end
            local forwardRay = workspace:Raycast(origin - Vector3.new(0, 1.5, 0), flatDir.Unit * 4, rayParams)
            if forwardRay then
                local topRay = workspace:Raycast(origin + Vector3.new(0, 6, 0), flatDir.Unit * 4, rayParams)
                if not topRay then
                    hum.Jump = true
                end
            end
            return targetWp
        end

        while Settings.PathFinderEnabled and not ScriptKilled and st.session == sessionId do
            local nextWait = 0.15
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                local routeHrp = pathFinderGetRouteHRP()
                local detectPos, _ = pathFinderGetDetectPosition(hrp)
                local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
                if not hrp or not detectPos or not hum or hum.Health <= 0 then return end

                if not st.prevWalkSpeed then
                    st.prevWalkSpeed = hum.WalkSpeed
                end

                local itemName = Settings.PathFinderItem or PATHFINDER_ORE_NAMES[1] or "Iron Node"
                local now = tick()
                local closestPos = st.cachedPos
                local closestItem = st.cachedTarget
                local closestCFrame = st.cachedCFrame
                st.blockedNodes = st.blockedNodes or {}
                for node, untilTime in pairs(st.blockedNodes) do
                    if not node.Parent or now >= untilTime then
                        st.blockedNodes[node] = nil
                    end
                end

                if st.plannedRouteFor and not isOrePhysicallySpawned(st.plannedRouteFor) then
                    st.blockedNodes[st.plannedRouteFor] = now + 3
                    st.activeOre = nil
                    st.cachedTarget = nil
                    st.routeScanFor = nil
                    st.mapScanAt = 0
                    clearPlannedRoute()
                end

                local routeIdx = 1
                local routeLen = 0
                local routeInProgress = false
                if st.plannedRoute and #st.plannedRoute > 0 and st.plannedRouteFor
                    and isOrePhysicallySpawned(st.plannedRouteFor) then
                    routeLen = #st.plannedRoute
                    routeIdx = advanceRouteIndex(st.plannedRoute, st.plannedRouteIndex or 1, detectPos)
                    routeInProgress = routeIdx <= routeLen
                end

                local needPick = (st.cachedName ~= itemName)
                    or not closestItem
                    or not isOrePhysicallySpawned(closestItem)
                    or (st.blockedNodes[closestItem] and now < st.blockedNodes[closestItem])

                if st.activeOre and isOrePhysicallySpawned(st.activeOre)
                    and (not st.blockedNodes[st.activeOre] or now >= st.blockedNodes[st.activeOre]) then
                    needPick = false
                end

                if routeInProgress then
                    closestItem = st.plannedRouteFor
                    closestCFrame = getOreCFrame(closestItem) or st.cachedCFrame
                    closestPos = closestCFrame and closestCFrame.Position or getOrePos(closestItem) or st.cachedPos
                    st.cachedTarget = closestItem
                    st.cachedPos = closestPos
                    st.cachedCFrame = closestCFrame
                    st.activeOre = closestItem
                elseif needPick then
                    closestItem, closestPos, closestCFrame = pickSelectedRouteTarget(itemName, detectPos, now)
                    st.walkTargetDist = nil
                    st.walkTargetSince = nil
                    clearPlannedRoute()
                elseif st.activeOre and isOrePhysicallySpawned(st.activeOre) then
                    closestItem = st.activeOre
                    closestCFrame = getOreCFrame(st.activeOre) or closestCFrame
                    closestPos = closestCFrame and closestCFrame.Position or getOrePos(st.activeOre) or closestPos
                    st.cachedPos = closestPos
                    st.cachedCFrame = closestCFrame
                end

                if not closestItem or not closestPos then
                    nextWait = 0.5
                    pathFinderStand(hrp, hum)
                    task.wait(1)
                    return
                end

                closestCFrame = getOreCFrame(closestItem) or closestCFrame
                closestPos = closestCFrame and closestCFrame.Position or getOrePos(closestItem) or closestPos
                st.cachedPos = closestPos
                st.cachedCFrame = closestCFrame
                st.activeOre = closestItem
                st.cachedTarget = closestItem

                local standPos = getOreStandPosition(closestPos, detectPos, PATHFINDER_STAND_DIST)
                local distToOre = (detectPos - closestPos).Magnitude
                local distToStand = (detectPos - standPos).Magnitude
                local oreBelow, underground = pathFinderGetOreBelowState(closestPos, detectPos)
                if underground then
                    oreBelow = true
                end
                local oreReachDist = PATHFINDER_STAND_DIST
                local atOre = distToOre <= oreReachDist and math.abs(closestPos.Y - detectPos.Y) <= 10

                if st.plannedRouteFor ~= closestItem and not routeInProgress then
                    clearPlannedRoute()
                end

                if not isOrePhysicallySpawned(closestItem) then
                    st.activeOre = nil
                    st.mapScanAt = 0
                    clearPlannedRoute()
                    closestItem, closestPos, closestCFrame = pickSelectedRouteTarget(itemName, detectPos, now)
                    if not closestItem then
                        pathFinderStand(hrp, hum)
                        task.wait(1)
                        return
                    end
                    closestCFrame = getOreCFrame(closestItem) or closestCFrame
                    closestPos = closestCFrame and closestCFrame.Position or getOrePos(closestItem) or closestPos
                    standPos = getOreStandPosition(closestPos, detectPos, PATHFINDER_STAND_DIST)
                    distToOre = (detectPos - closestPos).Magnitude
                    distToStand = (detectPos - standPos).Magnitude
                    oreBelow, underground = pathFinderGetOreBelowState(closestPos, detectPos)
                    if underground then
                        oreBelow = true
                    end
                    atOre = distToOre <= oreReachDist and math.abs(closestPos.Y - detectPos.Y) <= 10
                end

                local speed = math.clamp(Settings.PathFinderSpeed or 18, 1, 21)
                local targetWp = nil
                local targetIdx = 1
                local hasReadyRoute = st.plannedRoute
                    and #st.plannedRoute > 0
                    and st.plannedRouteFor == closestItem
                    and st.routeScanFor == closestItem
                    and not st.computing

                local needPlan = (not st.computing) and (not atOre) and (not routeInProgress)
                    and (
                        st.plannedRouteFor ~= closestItem
                        or not st.plannedRoute
                        or #st.plannedRoute == 0
                        or st.routeScanFor ~= closestItem
                    )

                if needPlan then
                    pathFinderStand(hrp, hum)
                    pathRequestId = pathRequestId + 1
                    local req = pathRequestId
                    st.computing = true
                    st.routeScanFor = closestItem
                    clearPlannedRoute()
                    local fromPos = detectPos
                    local oreItem = closestItem
                    local pathStandPos = underground and closestPos or standPos
                    local pathOrePos = closestPos
                    local pathOreBelow = oreBelow
                    task.spawn(function()
                        local wps = buildFullMapRouteToOre(fromPos, pathOrePos, pathOreBelow, pathStandPos)
                        if req ~= pathRequestId then return end
                        if st.activeOre ~= oreItem then return end
                        if wps and #wps > 1 then
                            pathFinderSetReachCache(st, oreItem, fromPos, true)
                            setPlannedRouteFromPath(wps, fromPos, pathStandPos)
                            st.plannedRouteFor = oreItem
                            st.routeScanFor = oreItem
                            st.pathFailCount = 0
                        else
                            pathFinderSetReachCache(st, oreItem, fromPos, false)
                            st.blockedNodes[oreItem] = tick() + PATHFINDER_UNREACHABLE_BLOCK
                            st.activeOre = nil
                            st.cachedTarget = nil
                            st.cachedName = nil
                            st.pathFailCount = 0
                            st.routeScanFor = nil
                            clearPlannedRoute()
                        end
                        st.computing = false
                    end)
                end

                if atOre then
                    if plantStopMovement then plantStopMovement() end
                    pathFinderStand(hrp, hum)
                    if not isOrePhysicallySpawned(closestItem) then
                        if closestItem then
                            st.blockedNodes[closestItem] = now + 3
                        end
                        st.activeOre = nil
                        st.cachedTarget = nil
                        st.routeScanFor = nil
                        st.mapScanAt = 0
                        clearPlannedRoute()
                        routeInProgress = false
                        closestItem, closestPos, closestCFrame = pickSelectedRouteTarget(itemName, detectPos, now)
                    end
                elseif hasReadyRoute and not st.computing and not needPlan then
                    local route = st.plannedRoute
                    local jumps = st.plannedRouteJumps or {}
                    hum.MaxSlopeAngle = 89
                    local routeIndex = advanceRouteIndex(route, st.plannedRouteIndex or 1, detectPos)
                    st.plannedRouteIndex = routeIndex

                    if routeIndex <= #route then
                        targetIdx = routeIndex
                        targetWp, targetIdx = getRouteTarget(route, routeIndex, detectPos)
                        if targetWp then
                            local charLead = routeHrp and pathFinderCharLeadXZ(hrp, routeHrp) or 0
                            if routeHrp and charLead > PATHFINDER_MAX_ROUTE_LEAD then
                                pathWalkToTarget(hrp, hum, routeHrp.Position, math.min(speed, 14))
                                targetWp = routeHrp.Position
                            else
                                local resolvedWp = resolveWalkTarget(hrp, hum, targetWp, routeHrp)
                                if resolvedWp then
                                    if jumps[targetIdx] or resolvedWp.Y < detectPos.Y - 3 then
                                        hum.Jump = true
                                    end
                                    pathWalkToTarget(hrp, hum, resolvedWp, speed)
                                    targetWp = resolvedWp
                                else
                                    pathFinderStand(hrp, hum)
                                end
                            end
                        else
                            pathFinderStand(hrp, hum)
                        end
                    elseif distToOre <= oreReachDist and math.abs(closestPos.Y - detectPos.Y) <= 10 then
                        pathFinderStand(hrp, hum)
                    else
                        clearPlannedRoute()
                        st.routeScanFor = nil
                        routeInProgress = false
                        pathFinderStand(hrp, hum)
                    end

                    st.walkTargetDist = st.walkTargetDist or distToStand
                    st.walkTargetSince = st.walkTargetSince or now
                    if distToStand < st.walkTargetDist - 2 then
                        st.walkTargetDist = distToStand
                        st.walkTargetSince = now
                    elseif now - (st.walkTargetSince or now) > 14 then
                        st.blockedNodes[closestItem] = now + 15
                        st.activeOre = nil
                        st.cachedTarget = nil
                        st.routeScanFor = nil
                        st.mapScanAt = 0
                        clearPlannedRoute()
                        st.walkTargetDist = nil
                        st.walkTargetSince = nil
                    end
                elseif st.computing or needPlan then
                    nextWait = 0.35
                    pathFinderStand(hrp, hum)
                else
                    pathFinderStand(hrp, hum)
                end
            end)
            task.wait(nextWait)
        end

        if plantStopMovement then plantStopMovement() end
        clearPathFinderVisuals()
        st.active = false
        st.computing = false
    end)
end

end -- AsterPathFinder


do

function getTopOfBoxTarget(part)
    if not part or not part.Size then return part and part.Position or Vector3.new() end
    return part.Position + part.CFrame.UpVector * (part.Size.Y/2 + 3)
end

local PLANT_MOVE_ARRIVAL_DIST = 5

function getPlantBoxTweenTarget(part, nearPos)
    if not part then return Vector3.new() end
    local boxPos = part.Position
    local approach = boxPos
    if nearPos then
        local flat = Vector3.new(nearPos.X - boxPos.X, 0, nearPos.Z - boxPos.Z)
        if flat.Magnitude > 0.5 then
            local half = math.max(part.Size.X, part.Size.Z) * 0.5 + 2.5
            approach = boxPos + flat.Unit * half
            -- Shoreline / ocean-platform: only reject the approach if there is no
            -- walkable part under it (true open water), not merely water terrain below a pier.
            if isAboveWater(approach) then
                local hasGround, groundDist = hasGroundBeneath(approach + Vector3.new(0, 8, 0))
                if not (hasGround and groundDist and groundDist < 25) then
                    return getTopOfBoxTarget(part)
                end
            end
        end
    end
    local rayStart = approach + Vector3.new(0, math.max(part.Size.Y, 8), 0)
    local _, _, groundHit = hasGroundBeneath(rayStart)
    local targetY = groundHit and (groundHit.Y + 3) or (boxPos.Y + 1)
    local target = Vector3.new(approach.X, targetY, approach.Z)
    if isAboveWater(target) then
        local hasGround, groundDist = hasGroundBeneath(target + Vector3.new(0, 8, 0))
        if not (hasGround and groundDist and groundDist < 25) then
            return getTopOfBoxTarget(part)
        end
    end
    return target
end

function plantingMovementTogglesActive()
    return Settings.TweenToPlantBox == true
        or Settings.TweenToBush == true
        or Settings.TweenToBushAndBox == true
        or Settings.CacheWalk == true
end

function plantingUsesHumanoidWalk()
    return Settings.PlantingTweenMode == "Walk"
        and plantingMovementTogglesActive()
end

function plantingUsesSmoothWalk()
    return Settings.PlantingTweenMode == "SmoothWalk"
        and plantingMovementTogglesActive()
end

function plantingUsesWalkMovement()
    return plantingUsesHumanoidWalk() or plantingUsesSmoothWalk()
end

function getPlantMoveArrivalDist()
    if plantingUsesHumanoidWalk() then
        -- Close enough for Auto Harvest to hit bushes while still walking onward.
        local harvestR = tonumber(Settings.HarvestRange) or 25
        return math.clamp(harvestR * 0.45, 8, 14)
    end
    return plantingUsesSmoothWalk() and 6 or PLANT_MOVE_ARRIVAL_DIST
end

function updatePlantMoveProgress(hrp, lastVec, lastDist)
    if not hrp or not lastVec then return lastDist, false end
    local distNow = (hrp.Position - lastVec).Magnitude
    local arrivalDist = getPlantMoveArrivalDist()
    if plantingUsesHumanoidWalk() then
        if lastDist and math.abs(distNow - lastDist) < 0.2 and distNow > arrivalDist + 4 then
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
            if hum then hum.Jump = true end
        end
        -- Don't stop — Walk keeps moving to the next bush/box.
        return distNow, distNow < arrivalDist
    end
    if plantingUsesSmoothWalk() then
        -- Used to abort the whole target on small knockbacks/overshoot, which
        -- made Tween-to-Bush randomly stop. Keep the destination and let the
        -- caller repath/refresh movement instead.
        if lastDist and math.abs(distNow - lastDist) < 0.2 and distNow > arrivalDist + 4 then
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
            if hum then hum.Jump = true end
        end
        if distNow < arrivalDist then
            if not Settings.TweenToBushAndBox then
                plantStopMovement()
            end
            return distNow, true
        end
        return distNow, false
    end
    -- Tween mode: never drop AlignPosition on arrival. Stopping Align + switching
    -- Humanoid to Running is what made Tween "stop tweening and start walking".
    if distNow < arrivalDist then
        local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
        if hum then
            plantRemoveBodyVelocity(hrp)
            plantUpdateTarget(hrp, hum, lastVec, math.min(tonumber(Settings.PlantingTweenSpeed) or 19, 20))
        end
        return distNow, true
    end
    return distNow, false
end

function isInsideCacheArea(pos, cacheCenter, cacheRadiusSq)
    if not pos or not cacheCenter then return false end
    local diff = pos - cacheCenter
    return (diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z) <= cacheRadiusSq
end

function findCachedPlantBoxTopNear(nearPos, cacheCenter, cacheRadiusSq, cachedBoxCount, cachedEids, cachedModels, cachedParts, skipEids)
    local bestTop, bestModel, bestEid, bestSq = nil, nil, nil, math.huge
    for i = 1, cachedBoxCount do
        local eid = cachedEids[i]
        if eid and (not skipEids or not skipEids[eid]) then
            local pp = cachedParts[i]
            local model = cachedModels[i]
            if pp and pp.Parent and model and model.Parent then
                local diffCenter = pp.Position - cacheCenter
                local dCenterSq = diffCenter.X * diffCenter.X + diffCenter.Y * diffCenter.Y + diffCenter.Z * diffCenter.Z
                if dCenterSq <= cacheRadiusSq then
                    local refPos = nearPos or pp.Position
                    local diff = pp.Position - refPos
                    local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                    if dSq < bestSq then
                        bestSq = dSq
                        bestTop = getPlantBoxTweenTarget(pp, nearPos or pp.Position)
                        bestModel = model
                        bestEid = eid
                    end
                end
            end
        end
    end
    return bestTop, bestModel, bestEid, bestSq
end

function normalizeMultiFruitSelection(selTable)
    local fruits = {}
    if type(selTable) ~= "table" then return fruits end
    local isArray = #selTable > 0
    if isArray then
        for _, name in ipairs(selTable) do
            if type(name) == "string" and name ~= "" then
                table.insert(fruits, name)
            end
        end
    else
        for name, sel in pairs(selTable) do
            if sel and type(name) == "string" and name ~= "" then
                table.insert(fruits, name)
            end
        end
    end
    table.sort(fruits)
    return fruits
end

function getActivePlantFruits()
    local fruits = normalizeMultiFruitSelection(Settings.PlantFruit)
    if #fruits > 0 then return fruits end
    if type(Settings.PlantFruit) == "string" and Settings.PlantFruit ~= "" then
        return { Settings.PlantFruit }
    end
    fruits = normalizeMultiFruitSelection(Settings.MultiPlantFruits)
    if #fruits > 0 then return fruits end
    return { "Bloodfruit" }
end

function moveToTargetUsingGoldLogic(targetVec)
    local char = plr.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChild("Humanoid")
    if not hrp or not hum then return end
    waterTweenActive = false
    
    local speed = Settings.PlantingTweenSpeed or 19
    
    if plantingUsesHumanoidWalk() then
        walkToTarget(hrp, hum, targetVec, speed)
    elseif plantingUsesSmoothWalk() then
        plantingRestoreWalkSpeed(hum)
        plantRemoveAlign()
        smoothWalkToTarget(hrp, hum, targetVec, speed)
    else
        plantingRestoreWalkSpeed(hum)
        plantRemoveBodyVelocity(hrp)
        pcall(function() hum:MoveTo(hrp.Position) end)
        plantUpdateTarget(hrp, hum, targetVec, speed)
        if hum:GetState() ~= Enum.HumanoidStateType.Physics then
            hum:ChangeState(Enum.HumanoidStateType.Physics)
        end
    end
end

function farmingReadInGameFps(dt)
    local fps
    pcall(function()
        fps = workspace:GetRealPhysicsFPS()
    end)
    if typeof(fps) ~= "number" or fps < 5 or fps > 1000 then
        fps = nil
    end
    if not fps then
        pcall(function()
            local stats = game:GetService("Stats")
            local ft = stats and stats:FindFirstChild("FrameTime")
            if ft and ft.GetValue then
                local v = ft:GetValue()
                if typeof(v) == "number" and v > 0.0005 then
                    fps = 1 / v
                end
            end
        end)
    end
    if (typeof(fps) ~= "number" or fps < 5) and typeof(dt) == "number" and dt > 0 and dt < 2 then
        fps = 1 / math.max(dt, 0.001)
    end
    return fps
end

function farmingFpsToScanRanges(fps)
    local t = math.clamp(((tonumber(fps) or 60) - 28) / 32, 0, 1)
    t = t * t * (3 - 2 * t)
    local bushCap = math.clamp(tonumber(Settings.TweenRange) or 1000, 250, 1000)
    local bush = math.clamp(250 + 750 * t, 250, bushCap)
    local box = 250 + 250 * t
    return bush, box
end

function farmingFpsScanBudget(fps)
    local fpsN = tonumber(fps) or 60
    if fpsN < 32 then
        return 18, 0.18, false
    elseif fpsN < 42 then
        return 24, 0.14, false
    elseif fpsN < 52 then
        return 36, 0.10, true
    elseif fpsN < 62 then
        return 48, 0.07, true
    end
    return 56, 0.055, true
end

function farmingCheapStandVec(part)
    if not part then return nil end
    local p = part.Position
    return Vector3.new(p.X, p.Y + 1, p.Z)
end

function farmingPruneVisitMap(map, maxAge, cap)
    local now = os.clock()
    local n = 0
    for k, t in pairs(map) do
        if (now - t) > maxAge then
            map[k] = nil
        else
            n = n + 1
        end
    end
    if n > cap then
        table.clear(map)
    end
end

function farmingKeepMoving(lastVec, now)
    if not lastVec then return end
    local char = plr.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChild("Humanoid")
    if not hrp or not hum then return end
    if (hrp.Position - lastVec).Magnitude > 3 then
        local stalled = hum.MoveDirection.Magnitude < 0.12
        if stalled or not _walkMoveToAt or (now - _walkMoveToAt) > 0.22 then
            moveToTargetUsingGoldLogic(lastVec)
        end
    end
end

function farmingCloserEnough(hrp, currentVec, newVec, pad)
    if not hrp or not newVec then return false end
    if not currentVec then return true end
    return (newVec - hrp.Position).Magnitude + (pad or 8) < (currentVec - hrp.Position).Magnitude
end

function farmingClosestOf(hrp, aModel, aBp, aVec, bModel, bBp, bVec)
    if not aModel or not aVec then return bModel, bBp, bVec end
    if not bModel or not bVec then return aModel, aBp, aVec end
    if not hrp then return aModel, aBp, aVec end
    if (aVec - hrp.Position).Magnitude <= (bVec - hrp.Position).Magnitude then
        return aModel, aBp, aVec
    end
    return bModel, bBp, bVec
end

function farmingNearestPlantBoxStand(hrp)
    if not hrp then return nil, nil, nil end
    local boxes = getPlantBoxModelsCached()
    if not boxes then return nil, nil, nil end
    local origin = hrp.Position
    local bestModel, bestPart, bestSq = nil, nil, math.huge
    for i = 1, #boxes do
        local model = boxes[i]
        if model and model.Parent then
            local part = getPlantBoxPartCheap(model)
            if part then
                local p = part.Position
                local dx = p.X - origin.X
                local dy = p.Y - origin.Y
                local dz = p.Z - origin.Z
                local dSq = dx * dx + dy * dy + dz * dz
                if dSq < bestSq then
                    bestSq = dSq
                    bestModel = model
                    bestPart = part
                end
            end
        end
    end
    if not bestPart then return nil, nil, nil end
    return bestModel, bestPart, getTopOfBoxTarget(bestPart)
end

function farmingParkOnPlantBox(hrp, lastModel, lastRef, lastVec, lastKind)
    if lastKind == "park" and lastModel and lastModel.Parent and lastRef and lastRef.Parent and lastVec then
        return lastModel, lastRef, getTopOfBoxTarget(lastRef), "park"
    end
    local model, part, vec = farmingNearestPlantBoxStand(hrp)
    if not model or not vec then
        return lastModel, lastRef, lastVec, lastKind
    end
    return model, part, vec, "park"
end


local plantBoxLoopActive = false
function startTweenPlantBox()
    if plantBoxLoopActive then return end
    plantBoxLoopActive = true
    task.spawn(function()
        local lastRef = nil
        local lastVec = nil
        local lastDist = nil
        local lastModel = nil
        local lastKind = nil
        local skipBoxModel = nil
        local filledBoxes = {}
        local smoothFps = 60
        local boxScanRange = 350
        local scan = {
            boxBp = nil, boxVec = nil, boxModel = nil,
            nextBp = nil, nextVec = nil, nextModel = nil,
            at = 0,
        }

        local function boxIsEmpty(model)
            if not model or not model.Parent or model:FindFirstChild("Seed") then return false end
            local eid = model:GetAttribute("EntityID")
            if eid and plantedboxes[eid] and (os.clock() - plantedboxes[eid]) < 0.45 then return false end
            return true
        end

        local function markBoxDone(model)
            if model then filledBoxes[model] = os.clock() end
        end

        local function boxAlreadyVisited(model)
            local t = filledBoxes[model]
            return t ~= nil and (os.clock() - t) < 10
        end

        task.spawn(function()
            local childIdx = 1
            local lastPrune = 0
            local bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
            local nextSq, nextBp, nextVec, nextModel = math.huge, nil, nil, nil
            while Settings.TweenToPlantBox and plantBoxLoopActive do
                local chunk, waitT = farmingFpsScanBudget(smoothFps)
                pcall(function()
                    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local hrpPos = hrp.Position
                    local nowClock = os.clock()
                    if nowClock - lastPrune > 2 then
                        lastPrune = nowClock
                        farmingPruneVisitMap(filledBoxes, 8, 64)
                    end
                    local boxes = getPlantBoxModelsCached()
                    local rangeSq = boxScanRange * boxScanRange
                    if bestModel and (not boxIsEmpty(bestModel) or bestModel == skipBoxModel or boxAlreadyVisited(bestModel)) then
                        bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
                    end
                    if nextModel and (not boxIsEmpty(nextModel) or nextModel == skipBoxModel or nextModel == bestModel or boxAlreadyVisited(nextModel)) then
                        nextSq, nextBp, nextVec, nextModel = math.huge, nil, nil, nil
                    end
                    if bestBp and bestBp.Parent and bestModel then
                        local d = bestBp.Position - hrpPos
                        local dSq = d.X * d.X + d.Y * d.Y + d.Z * d.Z
                        if dSq > rangeSq then
                            bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
                        else
                            bestSq = dSq
                            bestVec = farmingCheapStandVec(bestBp)
                        end
                    end
                    if boxes then
                        local n = #boxes
                        local processed = 0
                        local wrapped = false
                        while processed < chunk and n > 0 do
                            if childIdx > n then
                                childIdx = 1
                                wrapped = true
                            end
                            local model = boxes[childIdx]
                            childIdx = childIdx + 1
                            processed = processed + 1
                            if boxIsEmpty(model) and model ~= skipBoxModel and not boxAlreadyVisited(model) then
                                local part = getPlantBoxPartCheap(model)
                                if part then
                                    local diff = hrpPos - part.Position
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if distSq <= rangeSq then
                                        if distSq < bestSq then
                                            nextSq, nextBp, nextVec, nextModel = bestSq, bestBp, bestVec, bestModel
                                            bestSq = distSq
                                            bestBp = part
                                            bestModel = model
                                            bestVec = farmingCheapStandVec(part)
                                        elseif model ~= bestModel and distSq < nextSq then
                                            nextSq = distSq
                                            nextBp = part
                                            nextModel = model
                                            nextVec = farmingCheapStandVec(part)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    scan.boxBp, scan.boxVec, scan.boxModel = bestBp, bestVec, bestModel
                    scan.nextBp, scan.nextVec, scan.nextModel = nextBp, nextVec, nextModel
                    scan.at = tick()
                end)
                task.wait(waitT)
            end
        end)

        local lastFpsSample = 0
        local moveConn = runs.Heartbeat:Connect(function(dt)
            if not Settings.TweenToPlantBox or not plantBoxLoopActive then return end
            local now = tick()
            if now - lastFpsSample >= 0.25 then
                lastFpsSample = now
                local instFps = farmingReadInGameFps(dt)
                if typeof(instFps) == "number" then
                    smoothFps = smoothFps * 0.8 + instFps * 0.2
                    local _, nextBox = farmingFpsToScanRanges(smoothFps)
                    boxScanRange = boxScanRange * 0.7 + nextBox * 0.3
                end
            end
            farmingKeepMoving(lastVec, now)
        end)

        while Settings.TweenToPlantBox do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")

            local arrived = false
            if hrp and lastVec then
                lastDist = (hrp.Position - lastVec).Magnitude
                arrived = lastDist < 5
            end

            if lastKind ~= "park" then
                if lastModel and not boxIsEmpty(lastModel) then
                    markBoxDone(lastModel)
                    skipBoxModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                elseif arrived then
                    markBoxDone(lastModel)
                    skipBoxModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                end
            end

            local destVec = nil
            local emptyModel, emptyBp, emptyVec = farmingClosestOf(
                hrp,
                (boxIsEmpty(scan.boxModel) and scan.boxModel ~= skipBoxModel and not boxAlreadyVisited(scan.boxModel)) and scan.boxModel or nil,
                scan.boxBp, scan.boxVec,
                (boxIsEmpty(scan.nextModel) and scan.nextModel ~= skipBoxModel and not boxAlreadyVisited(scan.nextModel)) and scan.nextModel or nil,
                scan.nextBp, scan.nextVec
            )
            local keepBox = lastKind == "box" and lastModel and lastVec
                and boxIsEmpty(lastModel)
                and not boxAlreadyVisited(lastModel)
                and lastModel ~= skipBoxModel
            if keepBox and emptyModel and lastModel ~= emptyModel and farmingCloserEnough(hrp, lastVec, emptyVec, 8) then
                keepBox = false
            end
            if keepBox then
                destVec = lastVec
                if lastRef and lastRef.Parent then
                    destVec = farmingCheapStandVec(lastRef)
                    lastVec = destVec
                end
            elseif emptyModel and emptyBp and emptyVec then
                lastModel, lastRef, lastVec, lastKind = emptyModel, emptyBp, emptyVec, "box"
                destVec = emptyVec
            end

            if hrp and not destVec then
                lastModel, lastRef, lastVec, lastKind = farmingParkOnPlantBox(hrp, lastModel, lastRef, lastVec, lastKind)
                destVec = lastVec
            end

            if destVec and hum and hrp then
                if lastKind == "park" then
                    if (hrp.Position - destVec).Magnitude > 1.5 then
                        moveToTargetUsingGoldLogic(destVec)
                    end
                    lastDist = (hrp.Position - destVec).Magnitude
                elseif (hrp.Position - destVec).Magnitude > 3 then
                    moveToTargetUsingGoldLogic(destVec)
                    lastDist = (hrp.Position - destVec).Magnitude
                end
            end

            task.wait(0.05)
        end
        if moveConn then
            moveConn:Disconnect()
            moveConn = nil
        end
        plantStopMovement()
        plantBoxLoopActive = false
    end)
end

local bushBoxLoopActive = false
function startTweenBushAndBox()
    if bushBoxLoopActive then return end
    bushBoxLoopActive = true
    task.spawn(function()
        local lastRef = nil
        local lastVec = nil
        local lastDist = nil
        local lastModel = nil
        local lastKind = nil
        local skipBushModel = nil
        local skipBoxModel = nil
        local filledBoxes = {}
        local visitedBushes = {}
        local smoothFps = 60
        local bushScanRange = 600
        local boxScanRange = 350
        local scan = {
            bushBp = nil, bushVec = nil, bushModel = nil,
            nextBushBp = nil, nextBushVec = nil, nextBushModel = nil,
            boxBp = nil, boxVec = nil, boxModel = nil,
            nextBp = nil, nextVec = nil, nextModel = nil,
            at = 0,
        }

        local function bushStillValid(model, part)
            return model and model.Parent and part and part.Parent and part:IsDescendantOf(model)
        end

        local function harvestRangeSq()
            local r = tonumber(Settings.HarvestRange) or 30
            return r * r
        end

        local function boxIsEmpty(model)
            return model and model.Parent and not model:FindFirstChild("Seed")
        end

        local function markBoxDone(model)
            if model then
                filledBoxes[model] = os.clock()
            end
        end

        local function boxAlreadyVisited(model)
            local t = filledBoxes[model]
            return t ~= nil and (os.clock() - t) < 10
        end

        local function markBushDone(model)
            if model then
                visitedBushes[model] = os.clock()
            end
        end

        local function bushAlreadyVisited(model)
            local t = visitedBushes[model]
            return t ~= nil and (os.clock() - t) < 8
        end

        local function takeBox(model, bp, vec)
            lastModel, lastRef, lastVec, lastKind = model, bp, vec, "box"
            return vec
        end

        local function takeBush(model, bp, vec)
            lastModel, lastRef, lastVec, lastKind = model, bp, vec, "bush"
            return vec
        end

        task.spawn(function()
            local childIdx = 1
            local cropIdx = 1
            local scanPhase = 0
            local lastPrune = 0
            local lastFruitAt = 0
            local fruitFilter = {}
            local bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
            local nextSq, nextBp, nextVec, nextModel = math.huge, nil, nil, nil
            local bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
            local nextBushSq, nextBushBp, nextBushVec, nextBushModel = math.huge, nil, nil, nil
            while Settings.TweenToBushAndBox and bushBoxLoopActive do
                local chunk, waitT, doBoth = farmingFpsScanBudget(smoothFps)
                pcall(function()
                    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local hrpPos = hrp.Position
                    local nowClock = os.clock()
                    if nowClock - lastPrune > 2 then
                        lastPrune = nowClock
                        farmingPruneVisitMap(filledBoxes, 8, 64)
                        farmingPruneVisitMap(visitedBushes, 8, 64)
                    end
                    if nowClock - lastFruitAt > 1 then
                        lastFruitAt = nowClock
                        table.clear(fruitFilter)
                        local fruits = getActivePlantFruits()
                        for _, name in ipairs(fruits) do
                            fruitFilter[string.lower(tostring(name))] = true
                        end
                    end
                    local bushRangeSq = bushScanRange * bushScanRange
                    local minHarvestSq = harvestRangeSq()
                    local scanBushes = doBoth or (scanPhase % 2 == 0)
                    local scanBoxes = doBoth or (scanPhase % 2 == 1)
                    scanPhase = scanPhase + 1

                    if scanBushes then
                    if bestBushModel and (not bushStillValid(bestBushModel, bestBushBp) or bestBushModel == skipBushModel or bushAlreadyVisited(bestBushModel)) then
                        bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
                    end
                    if nextBushModel and (not bushStillValid(nextBushModel, nextBushBp) or nextBushModel == skipBushModel or nextBushModel == bestBushModel or bushAlreadyVisited(nextBushModel)) then
                        nextBushSq, nextBushBp, nextBushVec, nextBushModel = math.huge, nil, nil, nil
                    end
                    if bestBushBp and bestBushBp.Parent and hrpPos and bestBushModel then
                        local d = bestBushBp.Position - hrpPos
                        local dSq = d.X * d.X + d.Y * d.Y + d.Z * d.Z
                        if dSq <= minHarvestSq or dSq > bushRangeSq then
                            bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
                        else
                            bestBushSq = dSq
                            bestBushVec = farmingCheapStandVec(bestBushBp)
                        end
                    end
                    local fruitCrops = getFruitCropModelsCached(fruitFilter)
                    if fruitCrops then
                        local n = #fruitCrops
                        local processed = 0
                        local wrapped = false
                        while processed < chunk and n > 0 do
                            if cropIdx > n then
                                cropIdx = 1
                                wrapped = true
                            end
                            local model = fruitCrops[cropIdx]
                            cropIdx = cropIdx + 1
                            processed = processed + 1
                            if model and model.Parent and model ~= skipBushModel and not bushAlreadyVisited(model) then
                                local lowerName = string.lower(tostring(model.Name))
                                local fruitMatch = false
                                for fname in pairs(fruitFilter) do
                                    if string.find(lowerName, fname, 1, true) then
                                        fruitMatch = true
                                        break
                                    end
                                end
                                if fruitMatch then
                                local part = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                                if part then
                                    local diff = part.Position - hrpPos
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if distSq <= bushRangeSq and distSq > minHarvestSq then
                                        if distSq < bestBushSq then
                                            nextBushSq, nextBushBp, nextBushVec, nextBushModel = bestBushSq, bestBushBp, bestBushVec, bestBushModel
                                            bestBushSq = distSq
                                            bestBushBp = part
                                            bestBushModel = model
                                            bestBushVec = farmingCheapStandVec(part)
                                        elseif model ~= bestBushModel and distSq < nextBushSq then
                                            nextBushSq = distSq
                                            nextBushBp = part
                                            nextBushModel = model
                                            nextBushVec = farmingCheapStandVec(part)
                                        end
                                    end
                                end
                                end
                            end
                        end
                    end
                    scan.bushBp, scan.bushVec, scan.bushModel = bestBushBp, bestBushVec, bestBushModel
                    scan.nextBushBp, scan.nextBushVec, scan.nextBushModel = nextBushBp, nextBushVec, nextBushModel
                    end

                    if scanBoxes then
                    local boxes = getPlantBoxModelsCached()
                    local rangeSq = boxScanRange * boxScanRange
                    if bestModel and (not boxIsEmpty(bestModel) or bestModel == skipBoxModel or boxAlreadyVisited(bestModel)) then
                        bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
                    end
                    if nextModel and (not boxIsEmpty(nextModel) or nextModel == skipBoxModel or nextModel == bestModel or boxAlreadyVisited(nextModel)) then
                        nextSq, nextBp, nextVec, nextModel = math.huge, nil, nil, nil
                    end
                    if bestBp and bestBp.Parent and hrpPos and bestModel then
                        local d = bestBp.Position - hrpPos
                        local dSq = d.X * d.X + d.Y * d.Y + d.Z * d.Z
                        if dSq > rangeSq then
                            bestSq, bestBp, bestVec, bestModel = math.huge, nil, nil, nil
                        else
                            bestSq = dSq
                            bestVec = farmingCheapStandVec(bestBp)
                        end
                    end
                    if boxes then
                        local n = #boxes
                        local processed = 0
                        local wrapped = false
                        while processed < chunk and n > 0 do
                            if childIdx > n then
                                childIdx = 1
                                wrapped = true
                            end
                            local model = boxes[childIdx]
                            childIdx = childIdx + 1
                            processed = processed + 1
                            if boxIsEmpty(model) and model ~= skipBoxModel and not boxAlreadyVisited(model) then
                                local part = getPlantBoxPartCheap(model)
                                if part then
                                    local diff = hrpPos - part.Position
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if distSq <= rangeSq then
                                        if distSq < bestSq then
                                            nextSq, nextBp, nextVec, nextModel = bestSq, bestBp, bestVec, bestModel
                                            bestSq = distSq
                                            bestBp = part
                                            bestModel = model
                                            bestVec = farmingCheapStandVec(part)
                                        elseif model ~= bestModel and distSq < nextSq then
                                            nextSq = distSq
                                            nextBp = part
                                            nextModel = model
                                            nextVec = farmingCheapStandVec(part)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    scan.boxBp, scan.boxVec, scan.boxModel = bestBp, bestVec, bestModel
                    scan.nextBp, scan.nextVec, scan.nextModel = nextBp, nextVec, nextModel
                    end
                    scan.at = tick()
                end)
                task.wait(waitT)
            end
        end)

        local lastFpsSample = 0
        local moveConn = runs.Heartbeat:Connect(function(dt)
            if not Settings.TweenToBushAndBox or not bushBoxLoopActive then return end
            local now = tick()
            if now - lastFpsSample >= 0.25 then
                lastFpsSample = now
                local instFps = farmingReadInGameFps(dt)
                if typeof(instFps) == "number" then
                    smoothFps = smoothFps * 0.8 + instFps * 0.2
                    local nextBush, nextBox = farmingFpsToScanRanges(smoothFps)
                    bushScanRange = bushScanRange * 0.7 + nextBush * 0.3
                    boxScanRange = boxScanRange * 0.7 + nextBox * 0.3
                end
            end
            if not lastVec then return end
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChild("Humanoid")
            if not hrp or not hum then return end
            if (hrp.Position - lastVec).Magnitude > 3 then
                local stalled = hum.MoveDirection.Magnitude < 0.12
                if stalled or not _walkMoveToAt or (now - _walkMoveToAt) > 0.22 then
                    moveToTargetUsingGoldLogic(lastVec)
                end
            end
        end)

        while Settings.TweenToBushAndBox do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")

            local arrived = false
            if hrp and lastVec then
                if lastKind == "box" then
                    lastDist = (hrp.Position - lastVec).Magnitude
                    arrived = lastDist < 5
                else
                    local distNow, isArrived = updatePlantMoveProgress(hrp, lastVec, lastDist)
                    lastDist = distNow
                    arrived = isArrived == true
                end
            end

            if lastKind ~= "park" then
                if lastKind == "box" and lastModel and not boxIsEmpty(lastModel) then
                    markBoxDone(lastModel)
                    skipBoxModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                elseif lastKind == "bush" and lastModel and not bushStillValid(lastModel, lastRef) then
                    markBushDone(lastModel)
                    skipBushModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                elseif arrived then
                    if lastKind == "bush" then
                        markBushDone(lastModel)
                        skipBushModel = lastModel
                    end
                    if lastKind == "box" then
                        markBoxDone(lastModel)
                        skipBoxModel = lastModel
                    end
                    lastRef, lastModel, lastKind = nil, nil, nil
                end
            end

            local destVec = nil
            local closestBushModel, closestBushBp, closestBushVec = farmingClosestOf(
                hrp,
                (scan.bushModel and scan.bushVec and scan.bushModel ~= skipBushModel and not bushAlreadyVisited(scan.bushModel)) and scan.bushModel or nil,
                scan.bushBp, scan.bushVec,
                (scan.nextBushModel and scan.nextBushVec and scan.nextBushModel ~= skipBushModel and not bushAlreadyVisited(scan.nextBushModel)) and scan.nextBushModel or nil,
                scan.nextBushBp, scan.nextBushVec
            )
            if closestBushModel and closestBushBp and closestBushVec then
                local keepBush = lastKind == "bush" and lastModel and lastVec
                    and bushStillValid(lastModel, lastRef)
                    and not bushAlreadyVisited(lastModel)
                    and lastModel ~= skipBushModel
                if keepBush and lastModel ~= closestBushModel and farmingCloserEnough(hrp, lastVec, closestBushVec, 8) then
                    keepBush = false
                end
                if keepBush then
                    destVec = lastVec
                    if lastRef and lastRef.Parent then
                        destVec = farmingCheapStandVec(lastRef)
                        lastVec = destVec
                    end
                else
                    destVec = takeBush(closestBushModel, closestBushBp, closestBushVec)
                end
            else
                local emptyModel, emptyBp, emptyVec = farmingClosestOf(
                    hrp,
                    (boxIsEmpty(scan.boxModel) and scan.boxModel ~= skipBoxModel and not boxAlreadyVisited(scan.boxModel)) and scan.boxModel or nil,
                    scan.boxBp, scan.boxVec,
                    (boxIsEmpty(scan.nextModel) and scan.nextModel ~= skipBoxModel and not boxAlreadyVisited(scan.nextModel)) and scan.nextModel or nil,
                    scan.nextBp, scan.nextVec
                )
                local keepBox = lastKind == "box" and lastModel and lastVec
                    and boxIsEmpty(lastModel)
                    and not boxAlreadyVisited(lastModel)
                    and lastModel ~= skipBoxModel
                if keepBox and emptyModel and lastModel ~= emptyModel and farmingCloserEnough(hrp, lastVec, emptyVec, 8) then
                    keepBox = false
                end
                if keepBox then
                    destVec = lastVec
                    if lastRef and lastRef.Parent then
                        destVec = farmingCheapStandVec(lastRef)
                        lastVec = destVec
                    end
                elseif emptyModel and emptyBp and emptyVec then
                    destVec = takeBox(emptyModel, emptyBp, emptyVec)
                end
            end

            if hrp and not destVec then
                lastModel, lastRef, lastVec, lastKind = farmingParkOnPlantBox(hrp, lastModel, lastRef, lastVec, lastKind)
                destVec = lastVec
            end

            if destVec and hum and hrp then
                if lastKind == "park" then
                    if (hrp.Position - destVec).Magnitude > 1.5 then
                        moveToTargetUsingGoldLogic(destVec)
                    end
                    lastDist = (hrp.Position - destVec).Magnitude
                elseif (hrp.Position - destVec).Magnitude > 3 then
                    moveToTargetUsingGoldLogic(destVec)
                    lastDist = (hrp.Position - destVec).Magnitude
                end
            end

            task.wait(0.05)
        end
        if moveConn then
            moveConn:Disconnect()
            moveConn = nil
        end
        bushBoxLoopActive = false
        plantStopMovement()
    end)
end

local bushLoopActive = false
function startTweenToBush()
    if bushLoopActive then return end
    bushLoopActive = true
    task.spawn(function()
        local lastRef = nil
        local lastVec = nil
        local lastDist = nil
        local lastModel = nil
        local lastKind = nil
        local skipBushModel = nil
        local visitedBushes = {}
        local smoothFps = 60
        local bushScanRange = 600
        local scan = {
            bushBp = nil, bushVec = nil, bushModel = nil,
            nextBushBp = nil, nextBushVec = nil, nextBushModel = nil,
            at = 0,
        }

        local function bushStillValid(model, part)
            return model and model.Parent and part and part.Parent and part:IsDescendantOf(model)
        end

        local function harvestRangeSq()
            local r = tonumber(Settings.HarvestRange) or 30
            return r * r
        end

        local function markBushDone(model)
            if model then visitedBushes[model] = os.clock() end
        end

        local function bushAlreadyVisited(model)
            local t = visitedBushes[model]
            return t ~= nil and (os.clock() - t) < 8
        end

        task.spawn(function()
            local cropIdx = 1
            local lastPrune = 0
            local lastFruitAt = 0
            local fruitFilter = {}
            local bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
            local nextBushSq, nextBushBp, nextBushVec, nextBushModel = math.huge, nil, nil, nil
            while Settings.TweenToBush and bushLoopActive do
                local chunk, waitT = farmingFpsScanBudget(smoothFps)
                pcall(function()
                    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if not hrp then return end
                    local hrpPos = hrp.Position
                    local nowClock = os.clock()
                    if nowClock - lastPrune > 2 then
                        lastPrune = nowClock
                        farmingPruneVisitMap(visitedBushes, 8, 64)
                    end
                    if nowClock - lastFruitAt > 1 then
                        lastFruitAt = nowClock
                        table.clear(fruitFilter)
                        local fruits = getActivePlantFruits()
                        for _, name in ipairs(fruits) do
                            fruitFilter[string.lower(tostring(name))] = true
                        end
                    end
                    local bushRangeSq = bushScanRange * bushScanRange
                    local minHarvestSq = harvestRangeSq()
                    if bestBushModel and (not bushStillValid(bestBushModel, bestBushBp) or bestBushModel == skipBushModel or bushAlreadyVisited(bestBushModel)) then
                        bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
                    end
                    if nextBushModel and (not bushStillValid(nextBushModel, nextBushBp) or nextBushModel == skipBushModel or nextBushModel == bestBushModel or bushAlreadyVisited(nextBushModel)) then
                        nextBushSq, nextBushBp, nextBushVec, nextBushModel = math.huge, nil, nil, nil
                    end
                    if bestBushBp and bestBushBp.Parent and bestBushModel then
                        local d = bestBushBp.Position - hrpPos
                        local dSq = d.X * d.X + d.Y * d.Y + d.Z * d.Z
                        if dSq <= minHarvestSq or dSq > bushRangeSq then
                            bestBushSq, bestBushBp, bestBushVec, bestBushModel = math.huge, nil, nil, nil
                        else
                            bestBushSq = dSq
                            bestBushVec = farmingCheapStandVec(bestBushBp)
                        end
                    end
                    local fruitCrops = getFruitCropModelsCached(fruitFilter)
                    if fruitCrops then
                        local n = #fruitCrops
                        local processed = 0
                        local wrapped = false
                        while processed < chunk and n > 0 do
                            if cropIdx > n then
                                cropIdx = 1
                                wrapped = true
                            end
                            local model = fruitCrops[cropIdx]
                            cropIdx = cropIdx + 1
                            processed = processed + 1
                            if model and model.Parent and model ~= skipBushModel and not bushAlreadyVisited(model) then
                                local lowerName = string.lower(tostring(model.Name))
                                local fruitMatch = not next(fruitFilter)
                                if not fruitMatch then
                                    for fname in pairs(fruitFilter) do
                                        if string.find(lowerName, fname, 1, true) then
                                            fruitMatch = true
                                            break
                                        end
                                    end
                                end
                                if fruitMatch then
                                    local part = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                                    if part then
                                        local diff = part.Position - hrpPos
                                        local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                        if distSq <= bushRangeSq and distSq > minHarvestSq then
                                            if distSq < bestBushSq then
                                                nextBushSq, nextBushBp, nextBushVec, nextBushModel = bestBushSq, bestBushBp, bestBushVec, bestBushModel
                                                bestBushSq = distSq
                                                bestBushBp = part
                                                bestBushModel = model
                                                bestBushVec = farmingCheapStandVec(part)
                                            elseif model ~= bestBushModel and distSq < nextBushSq then
                                                nextBushSq = distSq
                                                nextBushBp = part
                                                nextBushModel = model
                                                nextBushVec = farmingCheapStandVec(part)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    scan.bushBp, scan.bushVec, scan.bushModel = bestBushBp, bestBushVec, bestBushModel
                    scan.nextBushBp, scan.nextBushVec, scan.nextBushModel = nextBushBp, nextBushVec, nextBushModel
                    scan.at = tick()
                end)
                task.wait(waitT)
            end
        end)

        local lastFpsSample = 0
        local moveConn = runs.Heartbeat:Connect(function(dt)
            if not Settings.TweenToBush or not bushLoopActive then return end
            local now = tick()
            if now - lastFpsSample >= 0.25 then
                lastFpsSample = now
                local instFps = farmingReadInGameFps(dt)
                if typeof(instFps) == "number" then
                    smoothFps = smoothFps * 0.8 + instFps * 0.2
                    local nextBush = farmingFpsToScanRanges(smoothFps)
                    bushScanRange = bushScanRange * 0.7 + nextBush * 0.3
                end
            end
            farmingKeepMoving(lastVec, now)
        end)

        while Settings.TweenToBush do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")

            local arrived = false
            if hrp and lastVec then
                local distNow, isArrived = updatePlantMoveProgress(hrp, lastVec, lastDist)
                lastDist = distNow
                arrived = isArrived == true
            end

            if lastKind ~= "park" then
                if lastModel and not bushStillValid(lastModel, lastRef) then
                    markBushDone(lastModel)
                    skipBushModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                elseif arrived then
                    markBushDone(lastModel)
                    skipBushModel = lastModel
                    lastRef, lastModel, lastKind = nil, nil, nil
                end
            end

            local destVec = nil
            local closestBushModel, closestBushBp, closestBushVec = farmingClosestOf(
                hrp,
                (scan.bushModel and scan.bushVec and scan.bushModel ~= skipBushModel and not bushAlreadyVisited(scan.bushModel)) and scan.bushModel or nil,
                scan.bushBp, scan.bushVec,
                (scan.nextBushModel and scan.nextBushVec and scan.nextBushModel ~= skipBushModel and not bushAlreadyVisited(scan.nextBushModel)) and scan.nextBushModel or nil,
                scan.nextBushBp, scan.nextBushVec
            )
            if closestBushModel and closestBushBp and closestBushVec then
                local keepBush = lastKind == "bush" and lastModel and lastVec
                    and bushStillValid(lastModel, lastRef)
                    and not bushAlreadyVisited(lastModel)
                    and lastModel ~= skipBushModel
                if keepBush and lastModel ~= closestBushModel and farmingCloserEnough(hrp, lastVec, closestBushVec, 8) then
                    keepBush = false
                end
                if keepBush then
                    destVec = lastVec
                    if lastRef and lastRef.Parent then
                        destVec = farmingCheapStandVec(lastRef)
                        lastVec = destVec
                    end
                else
                    lastModel, lastRef, lastVec, lastKind = closestBushModel, closestBushBp, closestBushVec, "bush"
                    destVec = closestBushVec
                end
            end

            if hrp and not destVec then
                lastModel, lastRef, lastVec, lastKind = farmingParkOnPlantBox(hrp, lastModel, lastRef, lastVec, lastKind)
                destVec = lastVec
            end

            if destVec and hum and hrp then
                if lastKind == "park" then
                    if (hrp.Position - destVec).Magnitude > 1.5 then
                        moveToTargetUsingGoldLogic(destVec)
                    end
                    lastDist = (hrp.Position - destVec).Magnitude
                elseif (hrp.Position - destVec).Magnitude > 3 then
                    moveToTargetUsingGoldLogic(destVec)
                    lastDist = (hrp.Position - destVec).Magnitude
                end
            end

            task.wait(0.05)
        end
        if moveConn then
            moveConn:Disconnect()
            moveConn = nil
        end
        plantStopMovement()
        bushLoopActive = false
    end)
end

local TribeDataCache = {}
local TribeRemote = nil

function getTribeRemote()
    if TribeRemote then return TribeRemote ~= false and TribeRemote or nil end

    local rs = game:GetService("ReplicatedStorage")
    local events = rs:FindFirstChild("Events")
    local direct = events and events:FindFirstChild("RequestTribeData")
    if direct and direct:IsA("RemoteFunction") then
        TribeRemote = direct
        return direct
    end

    TribeRemote = false
    return nil
end

local function needsTribeAllyData()
    -- Pinch itself only needs same-Team checks (already done in targeting).
    -- Do NOT start RequestTribeData just for Pinch ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â that remote invoke on
    -- enable was what users reported as "turning Pinch on leaves my tribe".
    return Settings.AutoBoltEnabled
        or Settings.SilentAimbot
        or Settings.AutoShoot
        or Settings.TargetMode == "Auto Target Mode"
        or Settings.TargetMode == "Target GodOnly"
end

-- Background Loop to keep Tribe Data updated
if not __ASTER_RUNTIME.tribeCacheLoopStarted then
    __ASTER_RUNTIME.tribeCacheLoopStarted = true
    local session = CURRENT_SESSION
    task.spawn(function()
        while isRuntimeSessionActive(session) do
            if needsTribeAllyData() then
                -- Use .InvokeServer(remote) (not :InvokeServer) so the call does not
                -- go through hooked __namecall. Yielding inside a namecall metamethod
                -- throws "thread is not yieldable" once silent-aim / event hooks install.
                local remote = getTribeRemote()
                if remote then
                    local invoke = remote.InvokeServer
                    if typeof(invoke) == "function" then
                        local ok, data = pcall(invoke, remote)
                        if ok and type(data) == "table" then
                            TribeDataCache = data
                        end
                    end
                end
                task.wait(12)
            else
                task.wait(30)
            end
        end
    end)
end

function isAlly(player)
    if not player or not player.Team then return false end
    
    local theirTeam = player.Team.Name
    if not theirTeam then return false end
    
    -- EXCEPTION: NoTribe members are never allies (always targetable)
    if theirTeam == "NoTribe" then return false end

    local plr = game:GetService("Players").LocalPlayer
    if not plr or not plr.Team then return false end
    local myTeam = plr.Team.Name
    
    -- If same team, they are teammates (handled by default team check, but good to have)
    if myTeam == theirTeam then 
        -- EXCEPTION: NoTribe members are never allies (always targetable)
        if myTeam == "NoTribe" then return false end
        return true 
    end
    
    -- Check cached tribe data
    if TribeDataCache then
        -- Check if my tribe has them as ally
        local myTribeData = TribeDataCache[myTeam]
        if myTribeData and myTribeData.allies then
            if table.find(myTribeData.allies, theirTeam) then
                return true
            end
        end
        
        -- Check if their tribe has me as ally (Symmetric check)
        local theirTribeData = TribeDataCache[theirTeam]
        if theirTribeData and theirTribeData.allies then
             if table.find(theirTribeData.allies, myTeam) then
                return true
            end
        end
    end
    
    return false
end

-- [REMOVED DUPLICATE ConfigPinch] --

end -- AsterPlantQuery

do -- AsterPinch
-- Continuous dual-place (both walls every tick). Lead distance is ping-based.
local pinchSmoothedVelocity = Vector3.zero
local pinchPrevVelocity = Vector3.zero
local pinchSmoothPingMs = 80
local pinchLastPingSample = 0
local lastPinchTarget = nil
local StatsService = game:GetService("Stats")
local PINCH_BASE_PING_MS = 70

local function resetPinchVelocityTracking()
    pinchSmoothedVelocity = Vector3.zero
    pinchPrevVelocity = Vector3.zero
end

local function readPinchPingMs()
    local pingMs = nil
    pcall(function()
        local network = StatsService:FindFirstChild("Network")
        local serverStats = network and network:FindFirstChild("ServerStatsItem")
        local dataPing = serverStats and serverStats:FindFirstChild("Data Ping")
        if dataPing and dataPing.GetValue then
            pingMs = tonumber(dataPing:GetValue())
        end
    end)
    if not pingMs then
        pcall(function()
            if plr.GetNetworkPing then
                pingMs = plr:GetNetworkPing() * 1000
            end
        end)
    end
    return math.clamp(tonumber(pingMs) or pinchSmoothPingMs or 80, 1, 2000)
end

local function samplePinchPing(now)
    now = now or os.clock()
    if now - pinchLastPingSample < 0.15 then
        return pinchSmoothPingMs
    end
    pinchLastPingSample = now
    pinchSmoothPingMs = pinchSmoothPingMs * 0.65 + readPinchPingMs() * 0.35
    return pinchSmoothPingMs
end

local function updatePinchTargetVelocity(hrp, dt)
    dt = (typeof(dt) == "number" and dt > 0 and dt) or (1 / 60)
    local vel = hrp.AssemblyLinearVelocity
    local horiz = Vector3.new(vel.X, 0, vel.Z)
    pinchPrevVelocity = pinchSmoothedVelocity
    local alpha = math.clamp(dt * 14, 0.1, 0.5)
    pinchSmoothedVelocity = pinchSmoothedVelocity:Lerp(horiz, alpha)
    return pinchSmoothedVelocity, (pinchSmoothedVelocity - pinchPrevVelocity) / math.max(dt, 0.001)
end

-- Returns predictTime, pingMs, pingFactor (1 = baseline 70ms).
local function getPinchPingAdapt()
    local pingMs = samplePinchPing()
    local scale = math.clamp(tonumber(ConfigPinch.PredictTime) or 1, 0.25, 3)
    -- One-way latency lead, slightly boosted so place packet arrives on time.
    local predictTime = math.clamp((pingMs / 1000) * scale * 1.2, 0.04, 0.7)
    local pingFactor = math.clamp((pingMs / PINCH_BASE_PING_MS) * scale, 0.65, 2.6)
    return predictTime, pingMs, pingFactor, scale
end

local function signedPingPad(base, pad)
    if math.abs(base) < 1e-4 then
        return pad
    end
    return base + (base >= 0 and 1 or -1) * pad
end

local pinchStableDir = Vector3.new(0, 0, -1)

local function getStableMoveDir(smoothed, hum, hrp)
    local candidate = nil
    if smoothed and smoothed.Magnitude > 1.25 then
        candidate = Vector3.new(smoothed.X, 0, smoothed.Z)
    elseif hum and hum.MoveDirection.Magnitude > 0.15 then
        candidate = Vector3.new(hum.MoveDirection.X, 0, hum.MoveDirection.Z)
    else
        local lv = hrp.CFrame.LookVector
        candidate = Vector3.new(lv.X, 0, lv.Z)
    end
    if not candidate or candidate.Magnitude < 0.01 then
        return pinchStableDir
    end
    candidate = candidate.Unit
    -- Hysteresis: ignore tiny flips so walls don't swap front/back every tick.
    if pinchStableDir:Dot(candidate) < -0.15 then
        -- Allow reverse only when clearly committed opposite.
        if smoothed and smoothed.Magnitude > 4 then
            pinchStableDir = candidate
        end
    else
        pinchStableDir = pinchStableDir:Lerp(candidate, 0.35)
        if pinchStableDir.Magnitude > 0.01 then
            pinchStableDir = pinchStableDir.Unit
        end
    end
    return pinchStableDir
end

local function computePinchPlacementCFrames(hrp, hum, dt)
    local smoothed, accel = updatePinchTargetVelocity(hrp, dt)
    local predictTime, pingMs, pingFactor, scale = getPinchPingAdapt()
    local moveDir = getStableMoveDir(smoothed, hum, hrp)

    -- Lead only along stable forward â€” never flip behind the target.
    local speed = smoothed.Magnitude
    local forwardSpeed = math.max(0, smoothed:Dot(moveDir))
    local lead = moveDir * (forwardSpeed * predictTime)
    if accel then
        local aAlong = Vector3.new(accel.X, 0, accel.Z):Dot(moveDir)
        if aAlong > 0 then
            lead = lead + moveDir * (aAlong * predictTime * predictTime * 0.45)
        end
    end
    local leadCap = math.clamp(8 + (pingMs / 1000) * 18 * scale, 8, 18)
    if lead.Magnitude > leadCap then
        lead = lead.Unit * leadCap
    end

    local targetBase = hrp.Position + lead

    local xBase = ConfigPinch.X_Offset or 0
    local zBase = ConfigPinch.Z_Offset or 0
    local shiftX = ConfigPinch.Shift_X or 0
    local shiftZ = ConfigPinch.Shift_Z or 0
    local yOff = ConfigPinch.Y_Offset or -3.5

    local stretch = math.clamp(1 + (pingFactor - 1) * 0.5, 0.75, 2.1)
    local absPad = math.max(0, (pingMs - 45) / 1000) * 7 * scale

    local xOff = xBase * stretch
    local zOff = zBase * stretch
    local spacingDominant = math.abs(xBase) >= math.abs(zBase)
    if spacingDominant then
        -- Crystal-style: opposite LEFT/RIGHT only; Distance moves BOTH the same way.
        xOff = signedPingPad(xOff, absPad * 0.45)
    else
        -- Ice-style: opposite FWD/BACK only; Spacing moves BOTH the same way.
        zOff = signedPingPad(zOff, absPad * 0.45)
    end

    -- Mild ping push along forward (both walls together â€” no side flip).
    if forwardSpeed > 1.0 then
        local pushStuds = (pingMs / 1000) * scale * math.clamp(forwardSpeed, 0, 30) * 0.45
        shiftX = shiftX + moveDir.X * pushStuds
        shiftZ = shiftZ + moveDir.Z * pushStuds
    end

    local rot = CFrame.Angles(0, math.rad(90), 0)
    local mid = Vector3.new(targetBase.X + shiftX, targetBase.Y + yOff, targetBase.Z + shiftZ)

    local cf1, cf2
    if spacingDominant then
        -- Â±X (left/right), SAME +Z (distance) for both walls.
        cf1 = CFrame.new(mid.X + xOff, mid.Y, mid.Z + zOff) * rot
        cf2 = CFrame.new(mid.X - xOff, mid.Y, mid.Z + zOff) * rot
    else
        -- Â±Z (fwd/back), SAME +X (spacing) for both walls.
        cf1 = CFrame.new(mid.X + xOff, mid.Y, mid.Z + zOff) * rot
        cf2 = CFrame.new(mid.X + xOff, mid.Y, mid.Z - zOff) * rot
    end
    return cf1, cf2, mid
end

local function sendPinchPlacePacket(cframe, itemName)
    if not ByteNetReliable or not itemName or itemName == "" then return end
    local packetId = getPlaceStructureId()
    if not packetId then return end
    local nameLen = #itemName
    local size = 4 + nameLen + 24
    local b = buffer.create(size)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, packetId)
    buffer.writeu16(b, 2, nameLen)
    for i = 1, nameLen do
        buffer.writeu8(b, 3 + i, string.byte(itemName, i))
    end
    local offset = 4 + nameLen
    local rx, ry, rz = cframe:ToEulerAnglesXYZ()
    buffer.writef32(b, offset, cframe.Position.X)
    buffer.writef32(b, offset + 4, cframe.Position.Y)
    buffer.writef32(b, offset + 8, cframe.Position.Z)
    buffer.writef32(b, offset + 12, rx)
    buffer.writef32(b, offset + 16, ry)
    buffer.writef32(b, offset + 20, rz)
    ByteNetReliable:FireServer(b)
end

ASTER.Options.computePinchPlacementCFrames = computePinchPlacementCFrames

local function firePinchBurst(dt)
    dt = (typeof(dt) == "number" and dt > 0 and dt) or (1 / 60)
    if not ConfigPinch.TargetPlayer or not ConfigPinch.TargetPlayer.Character then
        return
    end

    local char = ConfigPinch.TargetPlayer.Character
    local hrp = char:FindFirstChild("HumanoidRootPart")
    local hum = char:FindFirstChild("Humanoid")
    if not hrp then return end

    if ConfigPinch.TargetPlayer ~= lastPinchTarget then
        lastPinchTarget = ConfigPinch.TargetPlayer
        resetPinchVelocityTracking()
        pinchStableDir = Vector3.new(0, 0, -1)
    end

    -- No delay spam â€” tiny floor only so we don't melt the remote.
    if tick() - (ConfigPinch.LastTrap or 0) < 0.01 then
        return
    end

    local cf1, cf2 = computePinchPlacementCFrames(hrp, hum, dt)
    local itemName = ConfigPinch.ItemName or "Wood Gate"

    -- ALWAYS fire both walls back-to-back.
    sendPinchPlacePacket(cf1, itemName)
    sendPinchPlacePacket(cf2, itemName)

    ConfigPinch.LastTrap = tick()
end

registerHeartbeatUpdate("pinch", function(dt)
    if ConfigPinch.Enabled and ConfigPinch.TargetPlayer then
        firePinchBurst(dt)
    end
end)
ensureMasterHeartbeatLoop()

end -- AsterPinch

do -- AsterAuras
local goldNodeCache = {}
local lastGoldScan = 0

-- [[ OPTIMIZATION: Resource ID Cache ]] --
