do -- AsterAurasSpecialRuntime
local __AuraRuntimeShared = ASTER.Options and ASTER.Options.AuraRuntimeShared or {}
local ResourceIDCache = __AuraRuntimeShared.ResourceIDCache or setmetatable({}, {__mode = "k"})
local CritterIDCache = __AuraRuntimeShared.CritterIDCache or setmetatable({}, {__mode = "k"})
local getAuraConfirmRange = __AuraRuntimeShared.getAuraConfirmRange
local pickAuraTargets = __AuraRuntimeShared.pickAuraTargets
local auraSwingHit = __AuraRuntimeShared.auraSwingHit
local getAuraEntityID = __AuraRuntimeShared.getAuraEntityID
local matchesAuraTypeName = __AuraRuntimeShared.matchesAuraTypeName


local goldNodeAuraActive = false
function startGoldNodeAura()
    if goldNodeAuraActive then return end
    goldNodeAuraActive = true

    local function getEntityID(model)
        if not model or not model:IsA("Model") then return nil end
        if ResourceIDCache[model] then return ResourceIDCache[model] end

        local eid = model:GetAttribute("EntityID") or model:GetAttribute("ID")
        if not eid then
            for _, value in pairs(model:GetAttributes()) do
                if typeof(value) == "number" and value > 1000 then eid = value break end
            end
        end
        if not eid then
            local val = model:FindFirstChildWhichIsA("IntValue", true) or model:FindFirstChildWhichIsA("NumberValue", true)
            if val and val.Value > 1000 then eid = val.Value end
        end

        if eid then ResourceIDCache[model] = eid end
        return eid
    end

    task.spawn(function()
        while Settings.GoldNodeAuraEnabled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local overlapParams = OverlapParams.new()
                overlapParams.FilterDescendantsInstances = {plr.Character}
                overlapParams.FilterType = Enum.RaycastFilterType.Exclude

                local range = 50
                local rangeSq = range * range
                local targetCount = tonumber(Settings.ResourceTargetCount) or 1

                local parts = workspace:GetPartBoundsInRadius(hrp.Position, range, overlapParams)
                local seen = {}
                local targets = {}

                for _, part in ipairs(parts) do
                    local model = part and part.Parent
                    if model and model:IsA("Model") and model.Name == "Gold Node" then
                        local eid = getEntityID(model)
                        if eid and not seen[eid] then
                            seen[eid] = true
                            local ppart = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                            if ppart then
                                local diff = ppart.Position - hrp.Position
                                local distSq = diff:Dot(diff)
                                if distSq <= rangeSq then
                                    table.insert(targets, {eid = eid, distSq = distSq, pos = ppart.Position})
                                end
                            end
                        end
                    end
                end

                if #targets > 0 then
                    table.sort(targets, function(a, b) return a.distSq < b.distSq end)
                    local selected = {}
                    for i = 1, math.min(targetCount, #targets) do
                        table.insert(selected, { eid = targets[i].eid, pos = targets[i].pos })
                    end
                    fireByteNetSwingTool(selected, hrp, { maxPerPacket = math.max(1, #selected) })
                end
            end)

            task.wait(Settings.ResourceCooldown or 0.03)
        end
        goldNodeAuraActive = false
    end)
end

local iceAuraActive = false
function startIceAura()
    if iceAuraActive then return end
    iceAuraActive = true

    local function getEntityID(model)
        if not model or not model:IsA("Model") then return nil end
        if ResourceIDCache[model] then return ResourceIDCache[model] end

        local eid = model:GetAttribute("EntityID") or model:GetAttribute("ID")
        if not eid then
            for _, value in pairs(model:GetAttributes()) do
                if typeof(value) == "number" and value > 1000 then eid = value break end
            end
        end
        if not eid then
            local val = model:FindFirstChildWhichIsA("IntValue", true) or model:FindFirstChildWhichIsA("NumberValue", true)
            if val and val.Value > 1000 then eid = val.Value end
        end

        if eid then ResourceIDCache[model] = eid end
        return eid
    end

    local function hitTargets(rows)
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp or not rows or #rows == 0 then return end
        fireByteNetSwingTool(rows, hrp, { maxPerPacket = math.max(1, #rows) })
    end

    task.spawn(function()
        while Settings.IceAuraEnabled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end

                local overlapParams = OverlapParams.new()
                overlapParams.FilterDescendantsInstances = {plr.Character}
                overlapParams.FilterType = Enum.RaycastFilterType.Exclude

                local range = 50
                local rangeSq = range * range
                local targetCount = tonumber(Settings.ResourceTargetCount) or 1

                local parts = workspace:GetPartBoundsInRadius(hrp.Position, range, overlapParams)
                local seen = {}
                local targets = {}

                for _, part in ipairs(parts) do
                    local model = part and part.Parent
                    if model and model:IsA("Model") then
                        local nameLower = model.Name:lower()
                        if nameLower:find("ice") then
                            local eid = getEntityID(model)
                            if eid and not seen[eid] then
                                seen[eid] = true
                                local ppart = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
                                if ppart then
                                    local diff = ppart.Position - hrp.Position
                                    local distSq = diff:Dot(diff)
                                    if distSq <= rangeSq then
                                        table.insert(targets, {eid = eid, distSq = distSq, pos = ppart.Position})
                                    end
                                end
                            end
                        end
                    end
                end

                if #targets > 0 then
                    table.sort(targets, function(a, b) return a.distSq < b.distSq end)
                    local selected = {}
                    for i = 1, math.min(targetCount, #targets) do
                        table.insert(selected, { eid = targets[i].eid, pos = targets[i].pos or hrp.Position })
                    end
                    hitTargets(selected)
                end
            end)

            task.wait(Settings.ResourceCooldown or 0.03)
        end
        iceAuraActive = false
    end)
end

local behindQueenAntActive = false
local cachedQueenAnt = nil
local QUEEN_ANT_CRITTER_NAME = "Queen Ant"

-- Only the top-level Queen Ant mob under Critters (not "Queen Ant's Servant" or other critters).
function autoDiscoverQueenAntModel()
    local folder = getWorkspaceCritters()
    if not folder then return nil end
    for _, child in ipairs(folder:GetChildren()) do
        if child:IsA("Model") and child.Name == QUEEN_ANT_CRITTER_NAME then
            return child
        end
    end
    return nil
end

function startBehindQueenAntFollow()
    if behindQueenAntActive then return end
    behindQueenAntActive = true
    cachedQueenAnt = nil
    local lastQueenSearch = 0
    local cachedQPart = nil
    local heartbeatConn

    heartbeatConn = game:GetService("RunService").Heartbeat:Connect(function()
        if not Settings.BehindQueenAnt then
            heartbeatConn:Disconnect()
            cachedQueenAnt = nil
            cachedQPart = nil
            behindQueenAntActive = false
            return
        end

        local ok = pcall(function()
            local char = plr.Character
            if not char then return end
            local hum = char:FindFirstChildOfClass("Humanoid")
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if not hum or not hrp or hum.Health <= 0 then return end

            local now = tick()
            if not cachedQueenAnt or not cachedQueenAnt.Parent then
                cachedQPart = nil
                if now - lastQueenSearch < 0.5 then return end
                lastQueenSearch = now
                cachedQueenAnt = autoDiscoverQueenAntModel()
            end
            if not cachedQueenAnt or not cachedQueenAnt.Parent then return end

            if not cachedQPart or not cachedQPart.Parent then
                cachedQPart = cachedQueenAnt.PrimaryPart or cachedQueenAnt:FindFirstChild("HumanoidRootPart") or cachedQueenAnt:FindFirstChildWhichIsA("BasePart")
            end
            if not cachedQPart then return end

            local studs = math.clamp(tonumber(Settings.BehindQueenAntStuds) or 3, 0, 10)

            -- Flattened "behind" direction from the queen's facing.
            local look = cachedQPart.CFrame.LookVector
            local flat = Vector3.new(look.X, 0, look.Z)
            local dir
            if flat.Magnitude > 0.05 then
                dir = flat.Unit
            else
                -- Queen has no usable horizontal facing (spinning/degenerate part).
                -- DON'T fall back to our own facing - that creates a feedback loop where
                -- we chase our own tail (the classic spin/orbit bug). Instead keep our
                -- current bearing relative to the queen and just hold the set distance.
                local toMe = Vector3.new(hrp.Position.X - cachedQPart.Position.X, 0, hrp.Position.Z - cachedQPart.Position.Z)
                dir = toMe.Magnitude > 0.05 and (-toMe.Unit) or Vector3.new(0, 0, 1)
            end

            -- Point `studs` behind the queen, on OUR height plane (using her Y can make
            -- the humanoid try to climb/descend to her, which causes jitter).
            local behind = cachedQPart.Position - dir * studs
            local goal = Vector3.new(behind.X, hrp.Position.Y, behind.Z)

            local dist = (Vector3.new(goal.X - hrp.Position.X, 0, goal.Z - hrp.Position.Z)).Magnitude

            -- Deadzone: once we're basically in position, stop cleanly instead of
            -- re-issuing MoveTo every frame (which causes micro-stutter/orbiting).
            local deadzone = math.max(0.6, studs * 0.15)
            if dist > deadzone then
                hum:MoveTo(goal)
            else
                hum:MoveTo(hrp.Position)
            end
        end)

        if not ok then
            cachedQueenAnt = nil
            cachedQPart = nil
        end
    end)
end


end -- AsterAuras

do -- AsterCombatReach
autoHitLoopActive = false
autoHitRunning = false
autoHitSelection = "SwingHit"
autoHitGui = nil
local autoHitMobileWidget = nil

local reachOriginals = {}
local reachRangeVisual = nil
local reachReachExcluded = {"Bow", "Potion", "Sling", "Saddle", "Fishing Rod", "Horn", "Shovel"}
local lastReachSwing = 0

local function autoHitMobileLabel()
    if autoHitSelection == "NoSwingHit" then
        return "AutoHit"
    end
    return "SwingHit"
end

updateAutoHitGui = function()
    if not Settings or not Settings.MobileAutoHitButton then
        if autoHitMobileWidget then autoHitMobileWidget.destroy() autoHitMobileWidget = nil end
        if autoHitGui then autoHitGui:Destroy() autoHitGui = nil end
        return
    end

    local isOn = Settings.AutoHitStartEnabled
    local label = autoHitMobileLabel()
    if autoHitMobileWidget and autoHitMobileWidget.gui and autoHitMobileWidget.gui.Parent then
        autoHitMobileWidget.setToggleState(isOn, label)
        autoHitGui = autoHitMobileWidget.gui
        return
    end

    if autoHitMobileWidget then autoHitMobileWidget.destroy() autoHitMobileWidget = nil end
    if autoHitGui then autoHitGui:Destroy() autoHitGui = nil end

    pcall(function()
        autoHitMobileWidget = ASTER.CreateMobileWidget({
            guiName = "AsterAutoHitGui",
            label = label,
            position = ASTER.mobileWidgetPosition(2, "right"),
            mode = "toggle",
            initialOn = isOn,
            onClick = function()
                local newState = not Settings.AutoHitStartEnabled
                if Window.ElementRegistry["AutoHitStart"] then
                    Window.ElementRegistry["AutoHitStart"].SetValue(newState)
                else
                    Settings.AutoHitStartEnabled = newState
                    if newState then
                        if autoHitSelection == "NoSwingHit" then
                            startNoSwingAutoHit()
                        else
                            startSwingAutoHit()
                        end
                    else
                        stopAutoHit()
                    end
                end
                autoHitMobileWidget.setToggleState(Settings.AutoHitStartEnabled, autoHitMobileLabel())
            end,
        })
        autoHitGui = autoHitMobileWidget.gui
    end)
end

local function startAutoHitLoop(useSwing)
    if autoHitLoopActive then return end
    autoHitLoopActive = true

    task.spawn(function()
        local targetAnimId = "rbxassetid://10761451679"
        local animTrack, lastAnimPlay, lastHitPlay, lastChar = nil, 0, 0, nil
        local manualAttackLock = false

        if useSwing then
            trackConnection("AutoHitManualLock", UserInputService.InputBegan:Connect(function(input, gameProcessed)
                if gameProcessed then return end
                if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
                manualAttackLock = true
                task.delay(0.2, function() manualAttackLock = false end)
            end))
        end

        local function findNetworkID(object)
            for _, value in pairs(object:GetAttributes()) do
                if typeof(value) == "number" and value > 1000 then return value end
            end
            local val = object:FindFirstChildWhichIsA("IntValue", true) or object:FindFirstChildWhichIsA("NumberValue", true)
            if val and val.Value > 1000 then return val.Value end
            return nil
        end

        local function queueTargets(targetRows)
            if #targetRows == 0 or not ByteNetReliable then return end
            if useSwing then
                local toolsFolder = workspace:FindFirstChild("Players") and workspace.Players:FindFirstChild(plr.Name) and workspace.Players[plr.Name]:FindFirstChild("Tools")
                if not toolsFolder or #toolsFolder:GetChildren() == 0 then return end
                local toolName = toolsFolder:GetChildren()[1].Name:lower()
                for _, kw in ipairs(reachReachExcluded) do
                    if string.find(toolName, kw:lower(), 1, true) then return end
                end
            end

            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then return end

            local entries = {}
            for _, r in ipairs(targetRows) do
                if type(r) == "table" and r.eid then
                    table.insert(entries, { eid = r.eid, pos = r.pos })
                else
                    table.insert(entries, { eid = r })
                end
            end
            if #entries == 0 then return end

            local maxPick = math.clamp(tonumber(Settings.PlayerTargetCount) or 1, 1, 9)
            if Settings.PlayerSwingPackedMultiHit then
                fireByteNetSwingToolPackedMultiHit(entries, hrp, { maxTargets = maxPick })
            else
                fireByteNetSwingTool(entries, hrp, { maxPerPacket = maxPick })
            end

            if useSwing then
                pcall(function()
                    local swingId = getPacketId("ClientSwing")
                    if swingId then
                        local swingBuf = buffer.create(2)
                        buffer.writeu8(swingBuf, 0, 0)
                        buffer.writeu8(swingBuf, 1, swingId)
                        ByteNetReliable:FireServer(swingBuf)
                    end
                end)
                pcall(function()
                    if os.clock() - lastAnimPlay < 0.4 then return end
                    lastAnimPlay = os.clock()
                    local char = plr.Character
                    if char and char ~= lastChar then
                        lastChar = char
                        animTrack = nil
                    end
                    if char and not animTrack then
                        local animator = char:FindFirstChild("Humanoid") and char.Humanoid:FindFirstChild("Animator")
                        if animator then
                            local anim = Instance.new("Animation")
                            anim.AnimationId = targetAnimId
                            animTrack = animator:LoadAnimation(anim)
                        end
                    end
                    if animTrack then animTrack:Play() end
                end)
            end
        end

        while Settings.AutoHitStartEnabled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end

                local range = Settings.PlayerReachRange or 8
                local targets = {}
                local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                local myTeam = plr.Team
                local hrpPos = hrp.Position
                local detectionRange = range + 10
                local rangeSq = range * range
                local detectionRangeSq = detectionRange * detectionRange

                for _, other in ipairs(game:GetService("Players"):GetPlayers()) do
                    if other ~= plr and other.Character then
                        local char = other.Character
                        local eid = findNetworkID(char) or char:GetAttribute("EntityID")
                        local ppart = char:FindFirstChild("HumanoidRootPart")
                        local isTargetable = true
                        if myTeam and myTeam ~= noTribe and other.Team == myTeam then
                            isTargetable = false
                        end
                        if isTargetable and isAlly(other) then
                            isTargetable = false
                        end
                        if isTargetable and eid and ppart then
                            local diff = ppart.Position - hrpPos
                            local distSq = diff:Dot(diff)
                            if distSq <= detectionRangeSq then
                                local flatDiff = Vector3.new(diff.X, 0, diff.Z)
                                local flatDistSq = flatDiff:Dot(flatDiff)
                                if flatDistSq <= detectionRangeSq and math.abs(diff.Y) <= 20 then
                                    table.insert(targets, { eid = eid, distSq = flatDistSq, rangeSq = rangeSq, pos = ppart.Position })
                                end
                            end
                        end
                    end
                end

                if #targets == 0 then return end
                table.sort(targets, function(a, b) return a.distSq < b.distSq end)
                local maxPick = math.clamp(tonumber(Settings.PlayerTargetCount) or 1, 1, 9)
                local selectedRows = {}
                for i = 1, #targets do
                    if #selectedRows >= maxPick then break end
                    if targets[i].distSq <= targets[i].rangeSq then
                        table.insert(selectedRows, { eid = targets[i].eid, pos = targets[i].pos })
                    end
                end
                if #selectedRows == 0 then return end

                if useSwing then
                    if shouldHealSwingControl and shouldHealSwingControl() then return end
                    if isAnyToolEquipped() and not manualAttackLock and os.clock() - lastHitPlay > 0.12 then
                        lastHitPlay = os.clock()
                        queueTargets(selectedRows)
                    end
                else
                    queueTargets(selectedRows)
                end
            end)
            task.wait(Settings.AutoHitCooldown or 0.05)
        end

        autoHitLoopActive = false
    end)
end

startNoSwingAutoHit = function()
    startAutoHitLoop(false)
end

startSwingAutoHit = function()
    startAutoHitLoop(true)
end

stopAutoHit = function()
    autoHitLoopActive = false
    autoHitRunning = false
    pcall(updateAutoHitGui)
end

local function isReachExcludedTool(toolModel)
    local name = toolModel.Name:lower()
    for _, kw in ipairs(reachReachExcluded) do
        if string.find(name, kw:lower(), 1, true) then return true end
    end
    return false
end

local function getEquippedReachTools()
    local tools = {}
    local seen = {}
    local function addTool(tool)
        if tool and not seen[tool] then
            seen[tool] = true
            table.insert(tools, tool)
        end
    end
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local plrFolder = playersFolder:FindFirstChild(plr.Name)
        local toolsFolder = plrFolder and plrFolder:FindFirstChild("Tools")
        if toolsFolder then
            for _, child in ipairs(toolsFolder:GetChildren()) do
                addTool(child)
            end
        end
    end
    local character = plr.Character
    if character then
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Tool") then
                addTool(child)
            end
        end
    end
    return tools
end

local function findReachHandle(toolModel)
    if not toolModel or not toolModel.Parent then return nil end
    if toolModel:IsA("Tool") then
        local handle = toolModel:FindFirstChild("Handle")
        if handle and handle:IsA("BasePart") then return handle end
    end
    local handle = toolModel:FindFirstChild("Handle", true)
    if handle and handle:IsA("BasePart") then return handle end
    return nil
end

local function restoreReachHandle(part)
    if not part or not part.Parent then
        reachOriginals[part] = nil
        return
    end
    local original = reachOriginals[part]
    if not original then return end
    pcall(function()
        part.Size = original.Size
        part.Massless = original.Massless
        if original.CanCollide ~= nil then
            part.CanCollide = original.CanCollide
        end
        local box = part:FindFirstChild("ReachVisualBox")
        if box then box:Destroy() end
    end)
    reachOriginals[part] = nil
end

hideReachRangeVisual = function()
    if reachRangeVisual then
        pcall(function() reachRangeVisual:Destroy() end)
        reachRangeVisual = nil
    end
end

local function restoreAllPlayerReach()
    for part in pairs(reachOriginals) do
        restoreReachHandle(part)
    end
end
getAsterEnv().AsterRestorePlayerReach = function()
    restoreAllPlayerReach()
    hideReachRangeVisual()
end

local function updateReachRangeVisual(hrp, range)
    if not Settings.PlayerReachVisualEnabled then
        hideReachRangeVisual()
        return
    end
    pcall(function()
        if not reachRangeVisual or not reachRangeVisual.Parent then
            hideReachRangeVisual()
            reachRangeVisual = Instance.new("Part")
            reachRangeVisual.Name = "PlayerReachVisual"
            reachRangeVisual.Shape = Enum.PartType.Cylinder
            reachRangeVisual.Material = Enum.Material.Neon
            reachRangeVisual.Color = Color3.fromRGB(170, 80, 255)
            reachRangeVisual.Anchored = true
            reachRangeVisual.CanCollide = false
            reachRangeVisual.CastShadow = false
            reachRangeVisual.Massless = true
            reachRangeVisual.Parent = workspace
        end
        reachRangeVisual.CFrame = hrp.CFrame * CFrame.new(0, -2.9, 0) * CFrame.Angles(0, 0, math.rad(90))
        reachRangeVisual.Size = Vector3.new(0.2, range * 2, range * 2)
        reachRangeVisual.Transparency = 0.6
    end)
end

applyReachVisualOnly = function()
    if not Settings.PlayerReachVisualEnabled then
        hideReachRangeVisual()
        return
    end
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local range = math.clamp(tonumber(Settings.PlayerReachRange) or 8, 1, 8)
    updateReachRangeVisual(hrp, range)
end

applyPlayerReach = function()
    if not Settings.PlayerReachEnabled then
        restoreAllPlayerReach()
        applyReachVisualOnly()
        return
    end
    local range = math.clamp(tonumber(Settings.PlayerReachRange) or 8, 1, 8)
    local activeParts = {}
    for _, tool in ipairs(getEquippedReachTools()) do
        if not isReachExcludedTool(tool) then
            local handle = findReachHandle(tool)
            if handle and handle.Parent then
                activeParts[handle] = true
                if not reachOriginals[handle] then
                    reachOriginals[handle] = {
                        Size = handle.Size,
                        Massless = handle.Massless,
                        CanCollide = handle.CanCollide,
                    }
                end
                pcall(function()
                    handle.Massless = true
                    handle.CanCollide = false
                    handle.Size = Vector3.new(0.5, 0.5, range)
                    local box = handle:FindFirstChild("ReachVisualBox")
                    if box then box:Destroy() end
                end)
            end
        end
    end
    for part in pairs(reachOriginals) do
        if not activeParts[part] then
            restoreReachHandle(part)
        end
    end
    applyReachVisualOnly()
end

local function findReachNetworkID(object)
    for _, value in pairs(object:GetAttributes()) do
        if typeof(value) == "number" and value > 1000 then return value end
    end
    local val = object:FindFirstChildWhichIsA("IntValue", true) or object:FindFirstChildWhichIsA("NumberValue", true)
    if val and val.Value > 1000 then return val.Value end
    return nil
end

local function getReachCharacter(player)
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local customChar = playersFolder:FindFirstChild(player.Name)
        if customChar then return customChar end
    end
    return player.Character
end

local function isReachMeleeEquipped()
    for _, tool in ipairs(getEquippedReachTools()) do
        if not isReachExcludedTool(tool) then
            return true
        end
    end
    return false
end

local function getReachTargetsInRange(hrp, range)
    local targets = {}
    local hrpPos = hrp.Position
    local rangeSq = range * range
    local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
    local myTeam = plr.Team
    for _, other in ipairs(game:GetService("Players"):GetPlayers()) do
        if other ~= plr then
            local isTargetable = true
            if myTeam and myTeam ~= noTribe and other.Team == myTeam then
                isTargetable = false
            end
            if isTargetable and isAlly(other) then
                isTargetable = false
            end
            if isTargetable then
                local char = getReachCharacter(other)
                local ppart = char and char:FindFirstChild("HumanoidRootPart")
                local eid = char and (findReachNetworkID(char) or char:GetAttribute("EntityID"))
                if eid and ppart then
                    local diff = ppart.Position - hrpPos
                    local flatDiff = Vector3.new(diff.X, 0, diff.Z)
                    local flatDistSq = flatDiff:Dot(flatDiff)
                    local yDist = math.abs(diff.Y)
                    if flatDistSq <= rangeSq and yDist <= 20 then
                        table.insert(targets, { eid = eid, distSq = flatDistSq, pos = ppart.Position })
                    end
                end
            end
        end
    end
    table.sort(targets, function(a, b) return a.distSq < b.distSq end)
    return targets
end

local function fireReachHits(hrp, range)
    if not ByteNetReliable or not isReachMeleeEquipped() then return end
    if shouldHealSwingControl and shouldHealSwingControl() then return end
    local targets = getReachTargetsInRange(hrp, range)
    if #targets == 0 then return end
    local maxPick = math.clamp(tonumber(Settings.PlayerTargetCount) or 1, 1, 9)
    local entries = {}
    for i = 1, math.min(#targets, maxPick) do
        table.insert(entries, { eid = targets[i].eid, pos = targets[i].pos })
    end
    if #entries == 0 then return end
    if Settings.PlayerSwingPackedMultiHit then
        fireByteNetSwingToolPackedMultiHit(entries, hrp, { maxTargets = maxPick })
    else
        fireByteNetSwingTool(entries, hrp, { maxPerPacket = maxPick })
    end
    pcall(function()
        local swingId = getPacketId("ClientSwing")
        if swingId then
            local swingBuf = buffer.create(2)
            buffer.writeu8(swingBuf, 0, 0)
            buffer.writeu8(swingBuf, 1, swingId)
            ByteNetReliable:FireServer(swingBuf)
        end
    end)
end

initPlayerReachCombat = function()
    trackConnection("PlayerReachInput", UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or not Settings.PlayerReachEnabled then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
        local now = os.clock()
        if now - lastReachSwing < 0.12 then return end
        lastReachSwing = now
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local range = math.clamp(tonumber(Settings.PlayerReachRange) or 8, 1, 8)
        pcall(fireReachHits, hrp, range)
    end))

    local reachAccum = 0
    registerFrameUpdate("playerReach", function(dt)
        if not Settings.PlayerReachEnabled and not Settings.PlayerReachVisualEnabled then return end
        reachAccum = reachAccum + dt
        if reachAccum < 0.1 then return end
        reachAccum = 0
        if Settings.PlayerReachEnabled then
            pcall(applyPlayerReach)
        else
            pcall(applyReachVisualOnly)
        end
    end)
    ensureMasterFrameLoop()
end
end -- AsterCombatReach

do -- AsterPickup
pickupActive = false
function startAutoPickup()
    if pickupActive then return end
    pickupActive = true
    task.spawn(function()
        local attemptedItems = {}
        
        -- Cached filter states to avoid parsing every tick
        local lastDropString = nil
        local dropFilters = {}
        local lastCustomString = nil
        local customFilters = {}
        local hasCustomText = false

        local pickupOverlap = OverlapParams.new()
        pickupOverlap.FilterType = Enum.RaycastFilterType.Include
        local rawFishOverlap = OverlapParams.new()
        rawFishOverlap.FilterType = Enum.RaycastFilterType.Exclude
        local pickupQueue = {}
        local queueEidSet = {}
        local attemptedEids = {}
        local itemIdCache = {}
        local lastRefillTime = 0
        local lastDeepClean = 0
        local lastRawFishScanTime = 0
        local cachedRawFish = {}
        local MAX_QUEUE = 80
        local MAX_SCAN_CANDIDATES = 60
        local MAX_ATTEMPTED_EIDS = 400
        local REFILL_INTERVAL = 0.12

        local function getPickupNetworkID(item)
            return item:GetAttribute("ID")
                or item:GetAttribute("NetworkID")
                or item:GetAttribute("NetworkId")
                or item:GetAttribute("EntityID")
                or item:GetAttribute("entityId")
        end

        local function getItemWorldPos(item)
            if item:IsA("PVInstance") then
                return item:GetPivot().Position
            end
            if item:IsA("BasePart") then
                return item.Position
            end
            local part = item:FindFirstChildWhichIsA("BasePart", true)
            return part and part.Position
        end
        
        while true do
            if not Settings.AutoPickupEnabled and not Settings.ChestPickupEnabled and not Settings.PickupRawFishEnabled then
                pickupActive = false
                table.clear(pickupQueue)
                table.clear(queueEidSet)
                table.clear(attemptedEids)
                table.clear(attemptedItems)
                break
            end
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local range = tonumber(Settings.PickupRange) or 50
                local batchSize = math.clamp(math.floor(tonumber(Settings.PickupBatchSize) or 150), 1, 500)
                local retryDelay = tonumber(Settings.PickupRetryDelay) or 0.15
                local pickupDelay = math.clamp(tonumber(Settings.PickupDelay) or 0.01, 0, 0.25)
                local perTickRaw = math.clamp(tonumber(Settings.PickupPerTick) or 20, 1, 500)
                -- Cap each-iteration sends for smoother frames; higher batch still raises the cap a bit
                local perTick = math.min(perTickRaw, math.max(14, math.floor(batchSize / 5)), 34)
                local scanCap = math.min(MAX_SCAN_CANDIDATES, math.max(22, math.floor(batchSize * 0.42)))
                local queueCap = math.min(MAX_QUEUE, math.max(44, math.floor(batchSize * 0.52 + 12)))
                local currentTime = tick()
                
                local function isPickupOnCooldown(item, eid)
                    if eid and attemptedEids[eid] and currentTime < attemptedEids[eid] then
                        return true
                    end
                    if item and attemptedItems[item] and currentTime < attemptedItems[item] then
                        return true
                    end
                    return false
                end

                local function markPickupAttempted(item, eid)
                    local untilTime = currentTime + retryDelay
                    if eid then attemptedEids[eid] = untilTime end
                    if item then attemptedItems[item] = untilTime end
                end

                local function prunePickupQueue()
                    local writeIdx = 1
                    for i = 1, #pickupQueue do
                        local cand = pickupQueue[i]
                        local item = cand and cand.item
                        local eid = cand and cand.eid
                        local keep = false
                        if item and eid and item.Parent and not isPickupOnCooldown(item, eid) then
                            keep = true
                            pickupQueue[writeIdx] = cand
                            writeIdx = writeIdx + 1
                        elseif eid then
                            queueEidSet[eid] = nil
                        end
                    end
                    for i = writeIdx, #pickupQueue do
                        pickupQueue[i] = nil
                    end
                end

                -- Cleanup stale cooldowns (dead instances + expired eids)
                for item, attemptTime in pairs(attemptedItems) do
                    if currentTime > attemptTime or not item.Parent then
                        attemptedItems[item] = nil
                    end
                end
                local eidCount = 0
                for eid, attemptTime in pairs(attemptedEids) do
                    eidCount = eidCount + 1
                    if currentTime > attemptTime then
                        attemptedEids[eid] = nil
                        eidCount = eidCount - 1
                    end
                end
                if eidCount > MAX_ATTEMPTED_EIDS or currentTime - lastDeepClean > 8 then
                    lastDeepClean = currentTime
                    table.clear(attemptedEids)
                    table.clear(attemptedItems)
                    table.clear(queueEidSet)
                    prunePickupQueue()
                end

                prunePickupQueue()
                
                -- Update drop filters only if changed
                local currentDropStr = Settings.DropItem or ""
                if lastDropString ~= currentDropStr then
                    lastDropString = currentDropStr
                    table.clear(dropFilters)
                    if currentDropStr ~= "" then
                        for dropWord in string.gmatch(currentDropStr, '([^,]+)') do
                            local cleanDrop = dropWord:match("^%s*(.-)%s*$"):lower()
                            if cleanDrop ~= "" then dropFilters[cleanDrop] = true end
                        end
                    end
                end
                
                -- Update custom filters only if changed
                local currentCustomStr = Settings.CustomPickupFilter or ""
                if lastCustomString ~= currentCustomStr then
                    lastCustomString = currentCustomStr
                    table.clear(customFilters)
                    hasCustomText = currentCustomStr:gsub("%s+", "") ~= ""
                    if hasCustomText then
                        for word in string.gmatch(currentCustomStr, '([^,]+)') do
                            local cleanWord = word:match("^%s*(.-)%s*$"):lower()
                            if cleanWord ~= "" then customFilters[cleanWord] = true end
                        end
                    end
                end

                local function isItemWanted(itemName)
                    if not itemName or itemName == "" then return false end
                    local name = itemName:lower()
                    
                    if hasCustomText then
                        if customFilters[name] then return true end
                        if (name == "coin" or name == "coin2" or name == "coin stack") and customFilters["coin"] then return true end
                        if (name == "essence stack" or name == "essence") and customFilters["essence"] then return true end
                        return false
                    end
                    
                    return true 
                end
                
                 local pickupPacketID = getPacketId("Pickup")
                 
                local function pickupItem(eid, itemName) 
                     fireByteNetPickup(eid)
                 end

                local hrpPos = hrp.Position
                local rangeSq = range * range

                local function enqueuePickup(item, itemName, eid, distSq)
                    if not item or not item.Parent or not eid then return end
                    if isPickupOnCooldown(item, eid) or queueEidSet[eid] then return end
                    if #pickupQueue >= queueCap then return end
                    queueEidSet[eid] = true
                    table.insert(pickupQueue, {
                        item = item,
                        eid = eid,
                        name = itemName or item.Name,
                        distSq = distSq or 0,
                    })
                end

                local function gatherNearbyGroundItems()
                    local candidates = {}
                    local seen = {}
                    local itemsFolder = workspace:FindFirstChild("Items") or workspace:FindFirstChild("DroppedItems")
                    if not itemsFolder then return candidates end

                    local function addCandidate(item)
                        if not item or seen[item] then return end
                        if not (item:IsA("Model") or item:IsA("BasePart")) then return end
                        if not itemsFolder:IsAncestorOf(item) and item.Parent ~= itemsFolder then return end
                        local pos = getItemWorldPos(item)
                        if not pos then return end
                        local diff = pos - hrpPos
                        local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                        if distSq > rangeSq then return end
                        local eid = getPickupNetworkID(item)
                        if not eid or not isItemWanted(item.Name) then return end
                        seen[item] = true
                        table.insert(candidates, { item = item, eid = eid, distSq = distSq, name = item.Name })
                        if #candidates >= scanCap then return end
                    end

                    pickupOverlap.FilterDescendantsInstances = { itemsFolder }
                    local parts = workspace:GetPartBoundsInRadius(hrpPos, range, pickupOverlap)
                    for _, part in ipairs(parts) do
                        local model = part:FindFirstAncestorWhichIsA("Model")
                        if model and itemsFolder:IsAncestorOf(model) then
                            addCandidate(model)
                        elseif part.Parent == itemsFolder then
                            addCandidate(part)
                        end
                        if #candidates >= scanCap then break end
                    end

                    if #candidates < 15 then
                        for _, child in ipairs(itemsFolder:GetChildren()) do
                            addCandidate(child)
                            if #candidates >= scanCap then break end
                        end
                    end

                    table.sort(candidates, function(a, b)
                        return a.distSq < b.distSq
                    end)
                    return candidates
                end

                local function refillPickupQueue()
                    if Settings.AutoPickupEnabled then
                        local candidates = gatherNearbyGroundItems()
                        for _, cand in ipairs(candidates) do
                            enqueuePickup(cand.item, cand.name, cand.eid, cand.distSq)
                            if #pickupQueue >= queueCap then break end
                        end
                    end

                    if Settings.AutoPickupEnabled and #pickupQueue < queueCap then
                        if currentTime - (Settings.LastNilScanTime or 0) > 4 then
                            Settings.LastNilScanTime = currentTime
                            task.spawn(function()
                                local newNilCache = {}
                                local addedCount = 0
                                pcall(function()
                                    local nilInsts = getnilinstances()
                                    for i = 1, #nilInsts do
                                        local v = nilInsts[i]
                                        if typeof(v) == "Instance" and (v:IsA("BasePart") or v:IsA("Model") or v:IsA("UnionOperation")) then
                                            local success, name = pcall(function() return v.Name end)
                                            if success and (name == "Coin Stack" or name == "Essence Stack" or name:find("Drop")) then
                                                table.insert(newNilCache, v)
                                                addedCount = addedCount + 1
                                                if addedCount > 400 then break end
                                            end
                                        end
                                        if i % 4000 == 0 then task.wait() end
                                    end
                                end)
                                Settings.CachedNilItems = newNilCache
                            end)
                        end

                        if Settings.CachedNilItems then
                            for i = 1, math.min(#Settings.CachedNilItems, math.min(40, scanCap)) do
                                local v = Settings.CachedNilItems[i]
                                if v.Parent == nil then
                                    local pos = getItemWorldPos(v)
                                    if pos then
                                        local diff = pos - hrpPos
                                        local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                        if distSq <= rangeSq then
                                            local eid = getPickupNetworkID(v)
                                            if eid and isItemWanted(v.Name) then
                                                enqueuePickup(v, v.Name, eid, distSq)
                                                if #pickupQueue >= queueCap then break end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end

                    if Settings.ChestPickupEnabled and #pickupQueue < queueCap then
                        if currentTime - (Settings.LastChestScanTime or 0) > 1.5 then
                            Settings.LastChestScanTime = currentTime
                            task.spawn(function()
                                local newChestCache = {}
                                local deployables = getWorkspaceDeployables()
                                if deployables then
                                    for _, chest in ipairs(deployables:GetChildren()) do
                                        if (chest.Name:find("Chest") or chest.Name:find("Box")) and not chest.Name:find("Plant Box") then
                                            table.insert(newChestCache, chest)
                                        end
                                    end
                                end
                                Settings.CachedChests = newChestCache
                            end)
                        end

                        if Settings.CachedChests then
                            for _, chest in ipairs(Settings.CachedChests) do
                                if #pickupQueue >= queueCap then break end
                                if not chest.Parent then continue end
                                local pos = chest:IsA("PVInstance") and chest:GetPivot().Position
                                if not pos then continue end
                                local diff = pos - hrpPos
                                if diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z > rangeSq then continue end
                                local contents = chest:FindFirstChild("Contents")
                                if not contents then continue end
                                for _, item in ipairs(contents:GetChildren()) do
                                    local itemPos = getItemWorldPos(item)
                                    local distSq = rangeSq
                                    if itemPos then
                                        local d = itemPos - hrpPos
                                        distSq = d.X * d.X + d.Y * d.Y + d.Z * d.Z
                                    end
                                    local eid = getPickupNetworkID(item)
                                    if eid and isItemWanted(item.Name) then
                                        enqueuePickup(item, item.Name, eid, distSq)
                                        if #pickupQueue >= queueCap then break end
                                    end
                                end
                            end
                        end
                    end

                    if Settings.PickupRawFishEnabled and #pickupQueue < queueCap then
                        if currentTime - lastRawFishScanTime > 1.5 then
                            lastRawFishScanTime = currentTime
                            task.spawn(function()
                                local newRawFish = {}
                                pcall(function()
                                    local rawFishRange = math.clamp(tonumber(Settings.RawFishPickupRange) or 150, 25, 300)
                                    rawFishOverlap.FilterDescendantsInstances = (plr.Character and { plr.Character }) or {}
                                    local seenFish = {}
                                    local parts = workspace:GetPartBoundsInRadius(hrpPos, rawFishRange, rawFishOverlap)
                                    for _, part in ipairs(parts) do
                                        local fish = part.Name == "Raw Fish" and part
                                            or part:FindFirstAncestor("Raw Fish")
                                        if fish and not seenFish[fish]
                                            and (fish:IsA("Model") or fish:IsA("BasePart")) then
                                            seenFish[fish] = true
                                            table.insert(newRawFish, fish)
                                        end
                                    end
                                end)
                                cachedRawFish = newRawFish
                            end)
                        end

                        local rawFishRange = math.clamp(tonumber(Settings.RawFishPickupRange) or 150, 25, 300)
                        local rawFishRangeSq = rawFishRange * rawFishRange
                        for _, fish in ipairs(cachedRawFish) do
                            if #pickupQueue >= queueCap then break end
                            if fish.Parent then
                                local fishPos = getItemWorldPos(fish)
                                if fishPos then
                                    local diff = fishPos - hrpPos
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    local eid = getPickupNetworkID(fish)
                                    if distSq <= rawFishRangeSq and eid and isItemWanted(fish.Name) then
                                        enqueuePickup(fish, fish.Name, eid, distSq)
                                    end
                                end
                            end
                        end
                    end

                    table.sort(pickupQueue, function(a, b)
                        return (a.distSq or 0) < (b.distSq or 0)
                    end)
                end

                if #pickupQueue == 0 or (currentTime - lastRefillTime >= REFILL_INTERVAL and #pickupQueue < math.floor(queueCap * 0.5)) then
                    lastRefillTime = currentTime
                    refillPickupQueue()
                end

                local sent = 0
                while sent < perTick and #pickupQueue > 0 do
                    local cand = pickupQueue[1]
                    if not cand then break end
                    table.remove(pickupQueue, 1)
                    if cand.eid then queueEidSet[cand.eid] = nil end

                    local item = cand.item
                    local eid = cand.eid
                    if item and item.Parent and eid and not isPickupOnCooldown(item, eid) then
                        markPickupAttempted(item, eid)
                        pickupItem(eid, cand.name)
                        sent = sent + 1
                        if pickupDelay > 0 then
                            task.wait(pickupDelay)
                        end
                    end
                end
            end)
            task.wait(math.max(tonumber(Settings.PickupLoopDelay) or 0.05, 0.02))
        end
    end)
end

-- local dropPacket = packets.DropBagItem
function getQuantity(itemFrame)
    local qImage = itemFrame:FindFirstChild("QuantityImage")
    local qText = qImage and qImage:FindFirstChild("QuantityText")
    if qText and qText.Text ~= "" then
        local cleanString = qText.Text:gsub("%D", "")
        return tonumber(cleanString) or 0
    end
    return 0
end
end -- AsterPickup

do -- AsterDrop
local function getDropInventoryCount(targetName)
    local mainGui = game:GetService("Players").LocalPlayer.PlayerGui:FindFirstChild("MainGui")
    local invList = mainGui and mainGui.RightPanel and mainGui.RightPanel.Inventory and mainGui.RightPanel.Inventory.List
    if not invList then return 0 end

    local lowerTarget = tostring(targetName or ""):lower():match("^%s*(.-)%s*$")
    if not lowerTarget or lowerTarget == "" then return 0 end

    for _, child in ipairs(invList:GetChildren()) do
        if child:IsA("GuiObject") then
            local childNameLower = child.Name:lower():match("^%s*(.-)%s*$")
            if childNameLower == lowerTarget then
                local attrCount = child:GetAttribute("Count") or child:GetAttribute("Amount") or child:GetAttribute("Quantity")
                if attrCount then return tonumber(attrCount) or 0 end

                local quantity = getQuantity(child)
                if quantity > 0 then return quantity end
                return 1
            end
        end
    end

    return 0
end

function dynamicDrop(targetName)
    local invList = game:GetService("Players").LocalPlayer.PlayerGui.MainGui.RightPanel.Inventory.List
    
    -- Function to do a case-insensitive exact match to find the item frame
    local function findItemFrame(nameToFind)
        local lowerTarget = nameToFind:lower():match("^%s*(.-)%s*$")
        if not lowerTarget or lowerTarget == "" then return nil end
        
        for _, child in ipairs(invList:GetChildren()) do
            if child:IsA("GuiObject") then
                local childNameLower = child.Name:lower():match("^%s*(.-)%s*$")
                if childNameLower == lowerTarget then
                    return child
                end
            end
        end
        return nil
    end

    local itemFrame = findItemFrame(targetName)
    if itemFrame then
        local quantity = getQuantity(itemFrame)
        if quantity <= 0 then quantity = 1 end
        
        local slotIndex = itemFrame.LayoutOrder
        if slotIndex then
            if ByteNetReliable then
                 local dropId = getPacketId("DropBagItem")
                 if dropId then
                     local b = buffer.create(4)
                     buffer.writeu8(b, 0, 0)
                     buffer.writeu8(b, 1, dropId) 
                     buffer.writeu16(b, 2, slotIndex) -- server expects LayoutOrder slot
                     ByteNetReliable:FireServer(b)
                 end
            end
            -- FASTER DROP RATE: Return 0 (Instant) if > 10, else 0.2 (Slow)
            if quantity <= 10 then
                return 0.2
            else
                return 0 -- Instant drop for bulk
            end
        end
    end
    return 0.5
end

local autoDropCounts = {}
local autoDropStartCounts = {}
local autoDropLastKey = nil

if not __ASTER_RUNTIME.autoDropLoopStarted then
    __ASTER_RUNTIME.autoDropLoopStarted = true
    local session = CURRENT_SESSION
    task.spawn(function()
        while isRuntimeSessionActive(session) do
            local waitTime = 0.5
            if Settings.AutoDropEnabled and Settings.DropItem and Settings.DropItem ~= "" then
             local parsedDropAmount = tonumber(Settings.DropAmount)
             local hasDropLimit = parsedDropAmount ~= nil and parsedDropAmount > 0
             local dropAmount = hasDropLimit and math.floor(parsedDropAmount) or math.huge
             local dropKey = tostring(Settings.DropItem or "") .. "|" .. (hasDropLimit and tostring(dropAmount) or "Infinite")
             if autoDropLastKey ~= dropKey then
                 table.clear(autoDropCounts)
                 table.clear(autoDropStartCounts)
                 autoDropLastKey = dropKey
             end
             local droppedAny = false
             for item in string.gmatch(Settings.DropItem, '([^,]+)') do
                 local cleanItem = item:match("^%s*(.-)%s*$")
                 if cleanItem ~= "" then
                     local itemKey = cleanItem:lower()
                     if hasDropLimit and autoDropStartCounts[itemKey] == nil then
                         autoDropStartCounts[itemKey] = getDropInventoryCount(cleanItem)
                     end

                     local droppedCount = 0
                     if hasDropLimit then
                         local currentCount = getDropInventoryCount(cleanItem)
                         droppedCount = math.max(0, (autoDropStartCounts[itemKey] or currentCount) - currentCount)
                         autoDropCounts[itemKey] = droppedCount
                     end

                     if droppedCount < dropAmount then
                         local delay = dynamicDrop(cleanItem)
                         if delay == 0 then
                             droppedAny = true
                             -- Small yield to prevent crash, but essentially instant
                             if hasDropLimit then task.wait(0.15) else task.wait() end
                         elseif delay == 0.2 then
                             -- Slow mode for low quantity
                             task.wait(0.2)
                         end

                         if hasDropLimit and delay ~= 0.5 then
                             local currentCount = getDropInventoryCount(cleanItem)
                             autoDropCounts[itemKey] = math.max(0, (autoDropStartCounts[itemKey] or currentCount) - currentCount)
                         end
                     end
                 end
             end
             if droppedAny then waitTime = 0 else waitTime = 0.1 end
        else
             if autoDropLastKey ~= nil then
                 table.clear(autoDropCounts)
                 table.clear(autoDropStartCounts)
                 autoDropLastKey = nil
             end
        end
        task.wait(waitTime)
    end
    end)
end
end -- AsterDrop

do -- AsterHeal
local healActive = false
local healConnection = nil
local healGui = nil
local healMobileWidget = nil
local autoChestGui = nil
local autoChestMobileWidget = nil
local healRunning = false
local healGeneration = 0
local healLastTrackedHealth = nil
local healLastDamageTime = 0
local healDamageBurstHits = 0
local healAdaptiveDelay = 0
local healNoGainStreak = 0
local healHealthConn = nil
local healPendingHealthCheck = nil
local healRecentHitTimes = {}

-- CMethod (SmartHeal): wait until HP hits the 60-65% zone, then run
-- heal 7s -> pause 0.30s -> heal 7s -> pause 0.30s... until topped back up.
local SMARTHEAL_TRIGGER_PERCENT = 65
local SMARTHEAL_RECOVER_PERCENT = 98
local SMARTHEAL_CPS = 140
local SMARTHEAL_ACTIVE_SEC = 7
local SMARTHEAL_PAUSE_SEC = 0.30
local healSmartBursting = false
local healSmartCycleStart = 0

-- Ping/FPS adaptive heal: slider = max CPS when connection is healthy.
-- Soft throttle only Ã¢â‚¬â€ never punish normal mid-fight ping/FPS into a death spiral.
local StatsService = game:GetService("Stats")
local RunService = game:GetService("RunService")
local healSmoothFps = 60
local healSmoothPingMs = 80
local healLastPingSample = 0
local healLastHealthChangeClock = 0
local healLastFrameClock = 0
local healLagPauseUntil = 0
local healPerfConn = nil
local healCachedFruitName = nil
local healCachedFruitId = nil
local healCachedSlotId = nil
local healCacheRefreshAt = 0
local healPendingHealthAt = 0


-- Global so Combat UI callbacks outside this block can refresh/clear cache.
function invalidateHealFruitCache()
    healCachedFruitName = nil
    healCachedFruitId = nil
    healCachedSlotId = nil
    healCacheRefreshAt = 0
end

function resetHealAdaptiveState()
    healAdaptiveDelay = 0
    healNoGainStreak = 0
    healDamageBurstHits = 0
    healSmartBursting = false
    healSmartCycleStart = 0
    healLagPauseUntil = 0
    healSmoothFps = 60
    healSmoothPingMs = 80
    table.clear(healRecentHitTimes)
    invalidateHealFruitCache()
end

local function readServerPingMs()
    local pingMs = nil
    pcall(function()
        local network = StatsService:FindFirstChild("Network")
        local serverStats = network and network:FindFirstChild("ServerStatsItem")
        local dataPing = serverStats and serverStats:FindFirstChild("Data Ping")
        if dataPing and dataPing.GetValue then
            pingMs = tonumber(dataPing:GetValue())
        end
    end)
    if not pingMs then
        pcall(function()
            if plr.GetNetworkPing then
                pingMs = plr:GetNetworkPing() * 1000
            end
        end)
    end
    return math.clamp(tonumber(pingMs) or healSmoothPingMs or 80, 1, 2000)
end

local function stopHealPerfSampler()
    if healPerfConn then
        pcall(function() healPerfConn:Disconnect() end)
        healPerfConn = nil
    end
    healLastFrameClock = 0
end

local function startHealPerfSampler()
    if healPerfConn then return end
    healSmoothFps = 60
    healSmoothPingMs = readServerPingMs()
    healLastFrameClock = os.clock()
    healLastPingSample = 0
    healPerfConn = RunService.Heartbeat:Connect(function(dt)
        if not Settings.AutoHealEnabled then return end
        -- Real frame dt only ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â never use heal-loop wait gaps as "FPS".
        if typeof(dt) == "number" and dt > 0 and dt < 2 then
            local instFps = 1 / math.max(dt, 0.001)
            local alpha = (dt >= 0.1) and 0.45 or 0.15
            healSmoothFps = healSmoothFps * (1 - alpha) + instFps * alpha
            if dt >= 0.55 then
                local now = os.clock()
                -- Brief lag pause only Ã¢â‚¬â€ keep SmartHeal burst state so we don't die mid-fight.
                healLagPauseUntil = math.max(healLagPauseUntil, now + math.clamp(dt * 0.25, 0.08, 0.22))
            end
        end
        local now = os.clock()
        if now - healLastPingSample >= 0.25 then
            healLastPingSample = now
            healSmoothPingMs = healSmoothPingMs * 0.7 + readServerPingMs() * 0.3
        end
        healLastFrameClock = now
    end)
    trackConnection("healPerfSampler", healPerfConn)
end

local function resetSmartHealState()
    healLastTrackedHealth = nil
    healLastDamageTime = 0
    healDamageBurstHits = 0
    healAdaptiveDelay = 0
    healNoGainStreak = 0
    healPendingHealthCheck = nil
    healPendingHealthAt = 0
    healSmartBursting = false
    healSmartCycleStart = 0
    healLagPauseUntil = 0
    healSmoothFps = 60
    healSmoothPingMs = 80
    invalidateHealFruitCache()
    table.clear(healRecentHitTimes)
end

local function pruneHealHitTimes(now)
    local window = tonumber(Settings.HealDoubleHitWindow) or 0.65
    for i = #healRecentHitTimes, 1, -1 do
        if now - healRecentHitTimes[i] > window then
            table.remove(healRecentHitTimes, i)
        end
    end
    healDamageBurstHits = #healRecentHitTimes
end

local function registerHealDamageHit()
    local now = os.clock()
    table.insert(healRecentHitTimes, now)
    pruneHealHitTimes(now)
    healLastDamageTime = now
    healAdaptiveDelay = math.max(0, healAdaptiveDelay * 0.45)
    healNoGainStreak = 0
    return healDamageBurstHits
end

-- Ping refresh from heal tick (FPS comes only from Heartbeat sampler).
local function sampleHealPerf(now)
    if now - healLastPingSample >= 0.25 then
        healLastPingSample = now
        healSmoothPingMs = healSmoothPingMs * 0.65 + readServerPingMs() * 0.35
    end
end

-- 0 = pause, 1 = full speed. Uses the worse of FPS vs ping.
-- Long-session note: never hard-zero on low FPS ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â that caused deaths when Event
-- features tanked frames after 1ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“2 hours. Keep a survival floor instead.
local function getPingFpsHealScale(hpPercent, recentlyDamaged)
    local fps = healSmoothFps
    local ping = healSmoothPingMs
    local critical = (hpPercent or 100) <= 45
    local underPressure = critical or recentlyDamaged or (isSmartHealOn() and healSmartBursting)

    local fpsScale
    if fps < 8 then
        fpsScale = underPressure and 0.55 or 0.4
    elseif fps < 15 then
        fpsScale = underPressure and 0.7 or (0.55 + (fps - 8) / 7 * 0.2)
    elseif fps < 25 then
        fpsScale = 0.75 + (fps - 15) / 10 * 0.15
    elseif fps < 40 then
        fpsScale = 0.9 + (fps - 25) / 15 * 0.08
    else
        fpsScale = 1
    end

    local pingScale
    if ping <= 90 then
        pingScale = 1
    elseif ping <= 140 then
        pingScale = 1 - (ping - 90) / 50 * 0.12
    elseif ping <= 200 then
        pingScale = 0.88 - (ping - 140) / 60 * 0.15
    elseif ping <= 300 then
        pingScale = 0.73 - (ping - 200) / 100 * 0.15
    elseif ping <= 450 then
        pingScale = 0.58 - (ping - 300) / 150 * 0.13
    else
        pingScale = underPressure and 0.45 or 0.35
    end

    local floor = underPressure and 0.45 or 0.32
    return math.clamp(math.min(fpsScale, pingScale), floor, 1)
end

function isSmartHealOn()
    -- Strict gate: SmartHeal/CMethod never runs unless the Combat toggle is ON.
    return Settings.AutoHealEnabled == true and Settings.SmartHealEnabled == true
end

function clearSmartHealRuntime()
    healSmartBursting = false
    healSmartCycleStart = 0
    healDamageBurstHits = 0
    healLastDamageTime = 0
    table.clear(healRecentHitTimes)
end

-- Returns: active (bool), secondsRemainingInPhase
local function getSmartHealDutyCycle(now)
    now = now or os.clock()
    if healSmartCycleStart <= 0 then
        healSmartCycleStart = now
    end
    local period = SMARTHEAL_ACTIVE_SEC + SMARTHEAL_PAUSE_SEC
    local elapsed = (now - healSmartCycleStart) % period
    if elapsed < SMARTHEAL_ACTIVE_SEC then
        return true, SMARTHEAL_ACTIVE_SEC - elapsed
    end
    return false, period - elapsed
end

function startSmartHealDutyCycle()
    -- Do not arm yet Ã¢â‚¬â€ wait for HP to hit 60-65% first.
    healSmartCycleStart = 0
    healSmartBursting = false
end

local function isRecentlyDamaged(now)
    now = now or os.clock()
    return (now - (healLastDamageTime or 0)) < 1.25
end

local function triggerDoubleHitBurst()
    if not isSmartHealOn() or not healSmartBursting then return end
    local active = getSmartHealDutyCycle()
    if not active then return end
    task.spawn(function()
        local burstCount = 8
        for _ = 1, burstCount do
            if not isSmartHealOn() or not healSmartBursting then break end
            local stillActive = getSmartHealDutyCycle()
            if not stillActive then break end
            local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
            if not hum or hum.Health <= 0 then break end
            local hpPercent = (hum.Health / hum.MaxHealth) * 100
            if hpPercent >= SMARTHEAL_RECOVER_PERCENT then break end
            executeHeal(true)
            task.wait(0.03)
        end
    end)
end

local function getEffectiveHealCPS()
    local now = os.clock()
    local lagPaused = now < healLagPauseUntil
    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    local hpPercent = 100
    if hum and hum.MaxHealth > 0 then
        hpPercent = (hum.Health / hum.MaxHealth) * 100
    end
    local recentlyDamaged = isRecentlyDamaged(now)

    local scale = getPingFpsHealScale(hpPercent, recentlyDamaged)
    local base
    if isSmartHealOn() then
        base = math.max(SMARTHEAL_CPS, math.clamp(tonumber(Settings.HealCPS) or 50, 1, 500))
    else
        base = math.clamp(tonumber(Settings.HealCPS) or 50, 1, 500)
    end

    -- Only damp after waiting for ping RTT. Never damp hard while taking damage.
    local gainScale = 1
    if not recentlyDamaged then
        if healNoGainStreak >= 8 then
            gainScale = 0.45
        elseif healNoGainStreak >= 5 then
            gainScale = 0.65
        elseif healNoGainStreak >= 3 then
            gainScale = 0.85
        end
    end

    local cps = base * scale * gainScale
    if lagPaused and not recentlyDamaged and hpPercent > 45 then
        cps = math.min(cps, math.max(14, base * 0.35))
    end

    local survivalFloor = 14
    if hpPercent <= 30 then
        survivalFloor = 28
    elseif hpPercent <= 45 then
        survivalFloor = 22
    elseif recentlyDamaged or (isSmartHealOn() and healSmartBursting) then
        survivalFloor = 18
    end
    if cps < survivalFloor then
        cps = survivalFloor
    end
    return math.clamp(cps, survivalFloor, base)
end

local function shouldWaitForSecondHit()
    if not isSmartHealOn() then return false end
    local window = tonumber(Settings.HealDoubleHitWindow) or 0.65
    local sinceDamage = os.clock() - healLastDamageTime
    pruneHealHitTimes(os.clock())
    return healDamageBurstHits == 1 and sinceDamage > 0 and sinceDamage < window
end

local function getHealInterval()
    local cps = getEffectiveHealCPS()
    if cps <= 0 then
        return 0.1
    end
    -- Cap adaptive delay so lag false-positives can't stall healing.
    local delay = math.min(healAdaptiveDelay or 0, 0.08)
    return math.max((1 / cps) + delay, 0.008)
end

local function bindSmartHealHealthWatch(character)
    if healHealthConn then
        healHealthConn:Disconnect()
        healHealthConn = nil
    end
    local hum = character and character:FindFirstChild("Humanoid")
    if not hum then return end
    healLastTrackedHealth = hum.Health
    healLastHealthChangeClock = os.clock()
    healHealthConn = hum.HealthChanged:Connect(function(newHealth)
        healLastHealthChangeClock = os.clock()
        -- Fresh health means replication is alive again.
        if healLagPauseUntil > 0 then
            healLagPauseUntil = 0
        end
        if not isSmartHealOn() then
            healLastTrackedHealth = newHealth
            healSmartBursting = false
            return
        end
        if healLastTrackedHealth and newHealth < healLastTrackedHealth - 0.01 then
            local hitCount = registerHealDamageHit()
            if hitCount == 2 then
                triggerDoubleHitBurst()
            end
        elseif healLastTrackedHealth and newHealth > healLastTrackedHealth + 0.75 then
            healNoGainStreak = 0
            healAdaptiveDelay = math.max(0, healAdaptiveDelay - 0.012)
        end
        healLastTrackedHealth = newHealth
    end)
    trackConnection("smartHealHealth", healHealthConn)
end

local function noteHealAttemptResult(healthBefore)
    if not healthBefore then return end
    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if not hum then return end
    local healthAfter = hum.Health
    if healthAfter <= healthBefore + 0.01 then
        -- Ignore false "no gain" while taking damage Ã¢â‚¬â€ HP can fall between packets.
        if isRecentlyDamaged() then
            return
        end
        healNoGainStreak = healNoGainStreak + 1
        if healNoGainStreak >= 4 then
            healAdaptiveDelay = math.min(0.12, healAdaptiveDelay + 0.008)
        end
    else
        healNoGainStreak = 0
        healAdaptiveDelay = math.max(0, healAdaptiveDelay - 0.02)
    end
end

local function runSmartHealTick()
    local now = os.clock()
    -- Wait ~1 RTT before judging heal gain, otherwise ping makes every heal look failed.
    if healPendingHealthCheck ~= nil then
        local waitFor = math.clamp((healSmoothPingMs or 80) / 1000 * 1.15, 0.08, 0.35)
        if (now - (healPendingHealthAt or 0)) >= waitFor then
            noteHealAttemptResult(healPendingHealthCheck)
            healPendingHealthCheck = nil
            healPendingHealthAt = 0
        end
    end
    pruneHealHitTimes(now)
    sampleHealPerf(now)

    local cps = getEffectiveHealCPS()
    if cps <= 0 then
        return 0.15, false
    end

    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if not hum or hum.Health <= 0 then
        return getHealInterval(), false
    end
    local hpPercent = (hum.Health / hum.MaxHealth) * 100
    local critical = hpPercent <= 45
    local recentlyDamaged = isRecentlyDamaged(now)

    -- Soft lag throttle only when safe Ã¢â‚¬â€ never leave you unhealable mid-fight.
    if now < healLagPauseUntil and not critical and not recentlyDamaged then
        return math.max(0.05, math.min(0.12, healLagPauseUntil - now)), false
    end

    if isSmartHealOn() then
        -- 1) Wait until HP hits 60-65% to arm.
        -- 2) Once armed: heal 7s -> pause 0.30s -> repeat until recovered.
        if not healSmartBursting then
            if hpPercent <= SMARTHEAL_TRIGGER_PERCENT then
                healSmartBursting = true
                healSmartCycleStart = now -- start on the HEAL phase first
            else
                return 0.08, false
            end
        elseif hpPercent >= SMARTHEAL_RECOVER_PERCENT then
            healSmartBursting = false
            healSmartCycleStart = 0
            healPendingHealthCheck = nil
            healPendingHealthAt = 0
            return 0.08, false
        end

        local cycleActive, phaseLeft = getSmartHealDutyCycle(now)
        if not cycleActive then
            -- Pause phase of the duty cycle
            healPendingHealthCheck = nil
            healPendingHealthAt = 0
            return math.clamp(phaseLeft, 0.05, 0.25), false
        end

        -- Heal phase
        if healPendingHealthCheck == nil then
            healPendingHealthCheck = hum.Health
            healPendingHealthAt = now
        end
        executeHeal(true)
        return getHealInterval(), true
    end

    -- Normal AutoHeal only (SmartHeal toggle OFF): threshold + Max Heal CPS.
    clearSmartHealRuntime()
    local threshold = tonumber(Settings.HealThreshold) or 70
    if hpPercent > threshold then
        healNoGainStreak = 0
        healAdaptiveDelay = math.max(0, healAdaptiveDelay - 0.006)
        return 0.1, false
    end
    if healPendingHealthCheck == nil then
        healPendingHealthCheck = hum.Health
        healPendingHealthAt = now
    end
    executeHeal(false)
    return getHealInterval(), true
end

function stopAutoHeal()
    healGeneration += 1
    healRunning = false
    healActive = false
    stopHealPerfSampler()
    if healConnection then
        healConnection:Disconnect()
        healConnection = nil
    end
    if healHealthConn then
        healHealthConn:Disconnect()
        healHealthConn = nil
    end
    resetSmartHealState()
end

if type(__ASTER_RUNTIME.stopAutoHeal) == "function" then
    pcall(__ASTER_RUNTIME.stopAutoHeal)
end
__ASTER_RUNTIME.stopAutoHeal = stopAutoHeal

function resolveHealFruitItemId(fruitName)
    if not fruitName or fruitName == "" then return nil end
    local cached = healFruitData[fruitName]
    if cached == false then cached = nil end
    if type(cached) == "number" and cached > 0 then return cached end
    local id = autoDiscoverItemID(fruitName)
    if id == nil and craftNameToID then
        id = craftNameToID[fruitName]
    end
    if type(id) == "number" and id > 0 then
        healFruitData[fruitName] = id
        return id
    end
    return nil
end

local healSwingAnimTrack = nil
local healSwingLastAnim = 0
local healSwingLastChar = nil

local function playHealSwingAnimation()
    if os.clock() - healSwingLastAnim < 0.3 then return end
    healSwingLastAnim = os.clock()
    pcall(function()
        local char = plr.Character
        if not char then return end
        if char ~= healSwingLastChar then
            healSwingLastChar = char
            healSwingAnimTrack = nil
        end
        local animator = char:FindFirstChild("Humanoid") and char.Humanoid:FindFirstChild("Animator")
        if animator and not healSwingAnimTrack then
            local anim = Instance.new("Animation")
            anim.AnimationId = "rbxassetid://10761451679"
            healSwingAnimTrack = animator:LoadAnimation(anim)
        end
        if healSwingAnimTrack then
            healSwingAnimTrack:Play()
        end
    end)
end

local function fireHealEquippedToolSwing()
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp or not ByteNetReliable then return end
    if not hasHealSwingTool() then return end

    pcall(function()
        local swingId = getPacketId("ClientSwing")
        if swingId then
            local swingBuf = buffer.create(2)
            buffer.writeu8(swingBuf, 0, 0)
            buffer.writeu8(swingBuf, 1, swingId)
            ByteNetReliable:FireServer(swingBuf)
        end
        playHealSwingAnimation()
        local char = plr.Character
        if char then
            for _, child in ipairs(char:GetChildren()) do
                if child:IsA("Tool") then
                    pcall(function() child:Activate() end)
                    break
                end
            end
        end
    end)
end

function getAutoHealType()
    local healType = Settings.AutoHealType or "AutoHeal"
    if healType == "SwingTool" then
        healType = "SwingHeal AnimationOnly"
        Settings.AutoHealType = healType
    end
    return healType
end

function isCombatSwingHitActive()
    return Settings.AutoHitStartEnabled == true and autoHitSelection == "SwingHit"
end

function isHealSwingModeActive()
    if not Settings.AutoHealEnabled then return false end
    if getAutoHealType() ~= "SwingHeal AnimationOnly" then return false end
    if not hasHealSwingTool() then return false end
    local humanoid = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if not humanoid or humanoid.Health <= 0 then return false end
    local hpPercent = (humanoid.Health / humanoid.MaxHealth) * 100
    return hpPercent <= (tonumber(Settings.HealThreshold) or 70)
end

function shouldHealSwingControl()
    return isHealSwingModeActive() and not isCombatSwingHitActive()
end

local function executeHealFruit()
    local fruitName = Settings.HealFruit
    if not fruitName or fruitName == "" or not ByteNetReliable then return end

    local now = os.clock()
    local fruitID = healCachedFruitId
    local slotID = healCachedSlotId
    local cacheFresh = healCachedFruitName == fruitName and now < healCacheRefreshAt

    if not cacheFresh or not fruitID or not slotID then
        fruitID = resolveHealFruitItemId(fruitName)
        slotID = fruitID and getlayout(fruitName) or nil
        if fruitID and slotID then
            healCachedFruitName = fruitName
            healCachedFruitId = fruitID
            healCachedSlotId = slotID
            -- Refresh often enough for bag reshuffles, not every packet.
            healCacheRefreshAt = now + 0.75
        else
            invalidateHealFruitCache()
            return
        end
    end

    local actionId = getPacketId("UseBagItem")
    if not actionId then return end
    local b = buffer.create(8)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, actionId)
    buffer.writeu32(b, 2, slotID)
    buffer.writeu16(b, 6, fruitID)
    ByteNetReliable:FireServer(b)
end

function executeHeal(forceSmartBurst)
    local now = os.clock()
    if now < healLagPauseUntil then
        local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
        local critical = hum and hum.MaxHealth > 0 and (hum.Health / hum.MaxHealth) <= 0.45
        if not critical then
            return
        end
    end
    pcall(function()
        local character = plr.Character
        local humanoid = character and character:FindFirstChild("Humanoid")
        if humanoid and humanoid.Health > 0 then
            local hpPercent = (humanoid.Health / humanoid.MaxHealth) * 100
            -- forceSmartBurst only valid while CMethod/SmartHeal toggle is ON.
            local allowHeal = (forceSmartBurst == true) and isSmartHealOn()
            if not allowHeal then
                local threshold = tonumber(Settings.HealThreshold) or 70
                allowHeal = hpPercent <= threshold
            end
            if allowHeal then
                local healType = getAutoHealType()
                if healType == "AutoHeal" or healType == "SwingHeal AnimationOnly" then
                    executeHealFruit()
                end
                if healType == "SwingHeal AnimationOnly" and not isCombatSwingHitActive() then
                    fireHealEquippedToolSwing()
                end
            end
        end
    end)
end

local function destroyMobileScreenGui(guiRef, guiName)
    if guiRef then
        pcall(function() guiRef:Destroy() end)
    end
    local function cleanup(parent, name)
        if not parent or not name then return end
        local existing = parent:FindFirstChild(name)
        while existing do
            existing:Destroy()
            existing = parent:FindFirstChild(name)
        end
    end
    local cover = asterGuiCoverName(guiName)
    local playerGui = plr and plr:FindFirstChild("PlayerGui")
    cleanup(playerGui, guiName)
    cleanup(playerGui, cover)
    pcall(function()
        local coreGui = game:GetService("CoreGui")
        cleanup(coreGui, guiName)
        cleanup(coreGui, cover)
    end)
    local hidden = getAsterHiddenUI()
    cleanup(hidden, guiName)
    cleanup(hidden, cover)
    return nil
end

function updateHealGui()
    if not Settings or not Settings.MobileAutoHealButton then
        if healMobileWidget then healMobileWidget.destroy() healMobileWidget = nil end
        healGui = destroyMobileScreenGui(healGui, "AsterHealGui")
        return
    end

    local isOn = Settings.AutoHealEnabled
    if healMobileWidget and healMobileWidget.gui and healMobileWidget.gui.Parent then
        healMobileWidget.setToggleState(isOn, "Heal")
        healGui = healMobileWidget.gui
        return
    end

    if healMobileWidget then healMobileWidget.destroy() healMobileWidget = nil end
    healGui = destroyMobileScreenGui(nil, "AsterHealGui")

    pcall(function()
        healMobileWidget = ASTER.CreateMobileWidget({
            guiName = "AsterHealGui",
            label = "Heal",
            position = ASTER.mobileWidgetPosition(0, "right"),
            mode = "toggle",
            initialOn = isOn,
            onClick = function()
                local newState = not Settings.AutoHealEnabled
                if Window.ElementRegistry["Auto Heal"] then
                    Window.ElementRegistry["Auto Heal"].SetValue(newState)
                else
                    Settings.AutoHealEnabled = newState
                    healRunning = newState
                    if newState then
                        startAutoHeal()
                    else
                        stopAutoHeal()
                    end
                end
                healMobileWidget.setToggleState(Settings.AutoHealEnabled, "Heal")
            end,
        })
        healGui = healMobileWidget.gui
    end)
end

function updateAutoChestGui()
    if not Settings or not Settings.MobileAutoChestButton then
        if autoChestMobileWidget then autoChestMobileWidget.destroy() autoChestMobileWidget = nil end
        autoChestGui = destroyMobileScreenGui(autoChestGui, "AsterAutoChestGui")
