        autoChestGui = autoChestMobileWidget.gui
        return
    end

    if autoChestMobileWidget then autoChestMobileWidget.destroy() autoChestMobileWidget = nil end
    autoChestGui = destroyMobileScreenGui(nil, "AsterAutoChestGui")

