        autoChestMobileWidget = ASTER.CreateMobileWidget({
            guiName = "AsterAutoChestGui",
            label = "Chest",
            position = ASTER.mobileWidgetPosition(1, "right"),
            mode = "toggle",
            initialOn = isOn,
            onClick = function()
                local newState = not Settings.AutoChestEnabled
                if Window.ElementRegistry["Enable AutoChest"] then
                    Window.ElementRegistry["Enable AutoChest"].SetValue(newState)
                else
                    Settings.AutoChestEnabled = newState
                end
                if ASTER.Options.setAutoChestLoop then
                    ASTER.Options.setAutoChestLoop(Settings.AutoChestEnabled)
                end
                autoChestMobileWidget.setToggleState(Settings.AutoChestEnabled, "Chest")
            end,
        })
        autoChestGui = autoChestMobileWidget.gui
    end)
