function startAutoHeal()
    if not Settings.AutoHealEnabled then return end

    healGeneration += 1
    local gen = healGeneration
    healActive = true
    healRunning = true
    resetSmartHealState()
    startHealPerfSampler()
    bindSmartHealHealthWatch(plr.Character)

    if healConnection then healConnection:Disconnect() healConnection = nil end
    if Settings.HealHeartbeat then
        local lastHeal = 0
        local pendingInterval = getHealInterval()
        healConnection = game:GetService("RunService").Heartbeat:Connect(function()
            if gen ~= healGeneration or not Settings.AutoHealEnabled then
                if healConnection then healConnection:Disconnect() healConnection = nil end
                if gen == healGeneration then
                    healActive = false
                    healRunning = false
                    stopHealPerfSampler()
                end
                return
            end
            if not Settings.HealHeartbeat then
                 if healConnection then healConnection:Disconnect() healConnection = nil end
                 healActive = false
                 healRunning = false
                 startAutoHeal()
                 return
            end
            if os.clock() - lastHeal >= pendingInterval then
                pendingInterval = runSmartHealTick()
                lastHeal = os.clock()
            end
        end)
    else
        task.spawn(function()
            while gen == healGeneration and Settings.AutoHealEnabled do
                local waitTime = runSmartHealTick()
                task.wait(waitTime)
            end
            if gen == healGeneration then
                healActive = false
                healRunning = false
                stopHealPerfSampler()
            end
        end)
    end
end
end -- AsterHeal

do -- AsterEatFuelPlantHarvest

local fuelActive = false
function startAutoFuel()
    if fuelActive then return end
    fuelActive = true
    task.spawn(function()
        local ItemIDS = nil
        pcall(function() ItemIDS = require(game:GetService("ReplicatedStorage").Modules.ItemIDS) end)
        
        while Settings.AutoFuelEnabled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                
                local fuelTypes = {}
                if Settings.FuelType == "All (Wood/Log/Leaves)" then
                    for _, fName in ipairs({"Wood", "Log", "Leaves"}) do 
                        if getlayout(fName) then 
                            local id = (ItemIDS and ItemIDS[fName]) or fueltoitemid[fName]
                            if id then table.insert(fuelTypes, {id = id}) end
                        end 
                    end
                else
                    if getlayout(Settings.FuelType) then 
                        local id = (ItemIDS and ItemIDS[Settings.FuelType]) or fueltoitemid[Settings.FuelType]
                        if id then table.insert(fuelTypes, {id = id}) end
                    end
                end

                if #fuelTypes > 0 then
                    local deployables = getWorkspaceDeployables()
                    if deployables then
                        for _, v in ipairs(deployables:GetChildren()) do
                            if v.Name == "Campfire" then
                                local textLabel = v:FindFirstChild("Board") and v.Board:FindFirstChild("Billboard") and v.Board.Billboard:FindFirstChild("Backdrop") and v.Board.Billboard.Backdrop:FindFirstChild("TextLabel")
                                if textLabel then
                                    local currentFuel = tonumber(textLabel.Text) or 0
                                    local threshold = Settings.FuelThreshold or 10
                                    if currentFuel < threshold then
                                        local dist = (v.Board.Position - hrp.Position).Magnitude
                                        if dist <= 35 then
                                            local eID = v:GetAttribute("EntityID")
                                            if eID and ByteNetReliable then
                                                local b = buffer.create(8)
                                                buffer.writeu8(b, 0, 0)
                                                buffer.writeu8(b, 1, getPacketId("InteractStructure"))
                                                buffer.writeu32(b, 2, eID)
                                                buffer.writeu16(b, 6, fuelTypes[1].id)
                                                ByteNetReliable:FireServer(b)
                                                task.wait(0.1)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end)
            task.wait(0.5)
        end
        fuelActive = false
    end)
end

-- [[ QUICK HUT LOGIC ]] --
function executeQuickHutScan()
    local plr = game:GetService("Players").LocalPlayer
    
    local function getPlayerItems(p)
        local items = {}
        if p.Character then
            for _, child in ipairs(p.Character:GetChildren()) do
                local id = child:GetAttribute("ItemID") or child:GetAttribute("itemID") or child:GetAttribute("ID")
                if id then items[tonumber(id)] = true end
            end
        end
        return items
    end

    local function hasGodSet(p)
        local items = getPlayerItems(p)
        return items[16] and items[26] and items[288]
    end

    local function placeHutOnPlayer(targetPlayer)
        if not targetPlayer or not targetPlayer.Character or not targetPlayer.Character.PrimaryPart then return end
        local pos = targetPlayer.Character.PrimaryPart.Position

        local packetId = getPacketId("PlaceStructure")
        if not packetId then return end
        
        if ByteNetReliable then
            local hutNames = {"Big Ol' Hut", "Hut", "Shelter"}
            for _, hutName in ipairs(hutNames) do
                local len = #hutName
                local b = buffer.create(4 + len + 18)
                buffer.writeu8(b, 0, 0)
                buffer.writeu8(b, 1, packetId)
                buffer.writeu16(b, 2, len)
                buffer.writestring(b, 4, hutName)
                
                local offset = 4 + len
                write18ByteCFrame(b, offset, CFrame.new(pos))
                
                ByteNetReliable:FireServer(b)
                task.wait(0.01)
            end
        end
    end

    local myPos = plr.Character and plr.Character.PrimaryPart and plr.Character.PrimaryPart.Position
    if not myPos then return end
    
    local bestTarget = nil
    local bestDist = 999999
    
    local fallbackTarget = nil
    local fallbackDist = 999999
    
    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
        if p ~= plr and p.Character and p.Character.PrimaryPart then
            local isTargetable = true
            
            -- Check Teams
            local myTeam = plr.Team
            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
            
            if myTeam and myTeam ~= noTribe and p.Team == myTeam then
                isTargetable = false
            end

            if isTargetable and isAlly(p) then
                isTargetable = false
            end
            
            if isTargetable then
                local dist = (p.Character.PrimaryPart.Position - myPos).Magnitude
                
                if hasGodSet(p) then
                    if dist < bestDist then
                        bestDist = dist
                        bestTarget = p
                    end
                end
                
                if dist < fallbackDist then
                    fallbackDist = dist
                    fallbackTarget = p
                end
            end
        end
    end
    
    local finalTarget = bestTarget or fallbackTarget
    if finalTarget then
        placeHutOnPlayer(finalTarget)
    end
end

end -- AsterFuelQuickHut

do -- AsterPlantHarvestRuntime



local function resolvePlantItemId(fruitName, ItemIDS)
    if not fruitName or fruitName == "" then return nil end
    local cached = fruittoitemid[fruitName]
    if type(cached) == "number" and cached > 0 then return cached end
    if ItemIDS then
        local id = ItemIDS[fruitName .. " Seed"] or ItemIDS[fruitName]
        if type(id) == "number" and id > 0 then return id end
    end
    local id = autoDiscoverItemID(fruitName .. " Seed") or autoDiscoverItemID(fruitName)
    if type(id) == "number" and id > 0 then
        fruittoitemid[fruitName] = id
        return id
    end
    return nil
end

local function hasSeedInInventory(fruitName)
    local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
    local list = mainGui
        and mainGui:FindFirstChild("RightPanel")
        and mainGui.RightPanel:FindFirstChild("Inventory")
        and mainGui.RightPanel.Inventory:FindFirstChild("List")
    if not list then return true end
    local want = { fruitName, fruitName .. " Seed" }
    for _, item in ipairs(list:GetChildren()) do
        if item:IsA("ImageLabel") then
            for _, n in ipairs(want) do
                if item.Name == n then return true end
            end
        end
    end
    return false
end

local function pickPlantFruitForBox(fruitsToPlant, startIdx, ItemIDS)
    local n = #fruitsToPlant
    if n == 0 then return nil, nil, startIdx end
    for offset = 0, n - 1 do
        local idx = ((startIdx + offset - 1) % n) + 1
        local fruitName = fruitsToPlant[idx]
        if hasSeedInInventory(fruitName) then
            local itemID = resolvePlantItemId(fruitName, ItemIDS)
            if itemID then
                return fruitName, itemID, idx
            end
        end
    end
    return nil, nil, startIdx
end

local plantActive = false

local function shouldPlantBoxes()
    return Settings.PlantEnabled
end

function isCachePlantEnabled()
    return Settings.CachePlantBoxes == true
end

function isCacheWalkEnabled()
    return Settings.CacheWalk == true
end

function isCacheScanEnabled()
    return isCachePlantEnabled() or isCacheWalkEnabled()
end

local function isPlantLoopActive()
    return shouldPlantBoxes() or isCacheScanEnabled()
end

local function getCacheFarmingSettings()
    local amount = math.clamp(math.floor(tonumber(Settings.CacheAmount) or 20), 1, 50)
    local timer = math.clamp(tonumber(Settings.CacheTimer) or 3, 1, 10)
    return amount, timer
end

function startPlant()
    if plantActive then return end
    if not isPlantLoopActive() then return end
    plantActive = true
    task.spawn(function()
        if not game:IsLoaded() then game.Loaded:Wait() end
        task.wait(0.1)
        
        local ItemIDS = require(game:GetService("ReplicatedStorage").Modules.ItemIDS)
        local clock = os.clock
        
        local overlapParams = OverlapParams.new()
        overlapParams.FilterType = Enum.RaycastFilterType.Include
        
        local MAX_CACHE_BOXES = 50
        local boxEids = table.create(MAX_CACHE_BOXES)
        local boxModels = table.create(MAX_CACHE_BOXES)
        local boxDistSq = table.create(MAX_CACHE_BOXES)
        local scanEids = table.create(MAX_CACHE_BOXES)
        local scanModels = table.create(MAX_CACHE_BOXES)
        local scanParts = table.create(MAX_CACHE_BOXES)
        local scanDistSq = table.create(MAX_CACHE_BOXES)
        local cachedEids = table.create(MAX_CACHE_BOXES)
        local cachedModels = table.create(MAX_CACHE_BOXES)
        local cachedParts = table.create(MAX_CACHE_BOXES)
        local cachedBushModels = table.create(MAX_CACHE_BOXES)
        local cachedBushParts = table.create(MAX_CACHE_BOXES)
        local cachedBushCount = 0
        local lastCacheBushUpdate = 0
        local seen = {}
        local cachedSeen = {}
        local cacheWalkSeen = {}
        local cacheWalkBoxes = {}
        local cacheWalkBushSeen = {}
        local cachedBoxCount = 0
        local cachePlantIdx = 1
        local lastCacheUpdate = 0
        local lastCacheRange = nil
        local lastCacheAmount = nil
        local lastCacheCenterPos = nil
        local lastCacheScanRange = nil
        local lastCachePlantBoxesEnabled = false
        local lastCacheWalkEnabled = false
        local lastCacheScanEnabled = false
        local lastCacheWalkTarget = nil
        local lastCacheWalkTargetKind = nil
        local lastCacheWalkTargetRef = nil
        local lastCacheWalkTargetDistSq = math.huge
        local nextCacheWalkMove = 0
        local cacheWalkPreferBush = true
        local boxCount = 0
        
        local fruitRotateIdx = 0
        local lastPlantedPrune = 0
        local smoothWalkTargetEid = nil
        local smoothWalkTargetVec = nil
        local smoothWalkTargetModel = nil
        local smoothWalkLastDist = nil
        local smoothWalkAnchor = nil
        
        while isPlantLoopActive() do
            local plantedCount = 0
            pcall(function()
                plantedCount = 0
                local char = plr.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                local deployables = getWorkspaceDeployables()
                if not deployables then return end
                
                local range = tonumber(Settings.PlantRange) or 20
                local rangeSq = range * range
                local cacheAmount, cacheTimer = getCacheFarmingSettings()
                local plantingEnabled = shouldPlantBoxes()
                local cachePlantEnabled = isCachePlantEnabled()
                local cacheWalkEnabled = isCacheWalkEnabled()
                local tweenFarmingActive = Settings.TweenToPlantBox or Settings.TweenToBush or Settings.TweenToBushAndBox
                if tweenFarmingActive then
                    cachePlantEnabled = false
                    cacheWalkEnabled = false
                end
                local cacheScanEnabled = isCacheScanEnabled()
                if tweenFarmingActive then
                    cacheScanEnabled = false
                end
                local cacheWalking = cacheWalkEnabled

                -- Planting uses the existing Planting Range slider (closest-first from player).
                local interactRange = range
                local interactRangeSq = rangeSq
                
                local fruitsToPlant = plantingEnabled and getActivePlantFruits() or nil
                if plantingEnabled and #fruitsToPlant == 0 then return end
                
                local hrpPos = hrp.Position
                local now = clock()

                -- Prune stale plant cooldown entries so this table can't grow forever.
                -- Cooldowns are <=1s, so anything older than 5s is dead weight.
                if now - lastPlantedPrune > 10 then
                    lastPlantedPrune = now
                    for eid, t in pairs(plantedboxes) do
                        if now - t > 5 then plantedboxes[eid] = nil end
                    end
                end

                if cacheScanEnabled ~= lastCacheScanEnabled
                    or cachePlantEnabled ~= lastCachePlantBoxesEnabled
                    or cacheWalkEnabled ~= lastCacheWalkEnabled then
                    table.clear(cacheWalkSeen)
                    table.clear(cacheWalkBoxes)
                    table.clear(cacheWalkBushSeen)
                    table.clear(seen)
                    table.clear(cachedSeen)
                    lastCachePlantBoxesEnabled = cachePlantEnabled
                    lastCacheWalkEnabled = cacheWalkEnabled
                    lastCacheScanEnabled = cacheScanEnabled
                    lastCacheWalkTarget = nil
                    lastCacheWalkTargetKind = nil
                    lastCacheWalkTargetRef = nil
                    lastCacheWalkTargetDistSq = math.huge
                    cacheWalkPreferBush = true
                    lastCacheUpdate = 0
                    lastCacheRange = nil
                    lastCacheAmount = nil
                    lastCacheCenterPos = nil
                    lastCacheScanRange = nil
                    cachePlantIdx = 1
                    cachedBoxCount = 0
                    cachedBushCount = 0
                    lastCacheBushUpdate = 0
                    for i = 1, MAX_CACHE_BOXES do
                        cachedEids[i] = nil
                        cachedModels[i] = nil
                        cachedParts[i] = nil
                        cachedBushModels[i] = nil
                        cachedBushParts[i] = nil
                    end
                end
                
                local cacheWalkBoxCount = 0
                if cacheScanEnabled then
                    for eid, cachedBox in pairs(cacheWalkBoxes) do
                        local model = cachedBox.model
                        local pp = cachedBox.part
                        if model and model.Parent and pp and pp.Parent and not (plantingEnabled and model:FindFirstChild("Seed")) and cacheWalkBoxCount < cacheAmount then
                            cacheWalkBoxCount = cacheWalkBoxCount + 1
                        else
                            cacheWalkBoxes[eid] = nil
                            cacheWalkSeen[eid] = nil
                        end
                    end
                end
                
                -- Cache refresh can be driven by time or movement. We also scan a bit wider than PlantRange
                -- so cache-walk/planting doesn't feel "short-sighted" while you move.
                local cacheRefreshDelay = math.clamp(cacheTimer, 0.05, 10)
                local moveMin = tonumber(Settings.CacheMoveRefreshMin) or 2
                local moveFactor = tonumber(Settings.CacheMoveRefreshFactor) or 0.1
                local moveThreshold = math.max(moveMin, range * moveFactor)
                local movedEnough = (not lastCacheCenterPos)
                    or ((hrpPos - lastCacheCenterPos).Magnitude >= moveThreshold)
                -- If Auto Plant has no empty boxes left in the current cache, rescan soon
                -- so we don't sit until CacheTimer elapses. Throttle so empty farms don't
                -- spam overlap queries every plant tick.
                local needsEmptyRescan = false
                if plantingEnabled and cacheScanEnabled and (now - lastCacheUpdate) >= 0.35 then
                    if cachedBoxCount <= 0 then
                        needsEmptyRescan = true
                    else
                        needsEmptyRescan = true
                        for i = 1, cachedBoxCount do
                            local model = cachedModels[i]
                            if model and model.Parent and not model:FindFirstChild("Seed") then
                                needsEmptyRescan = false
                                break
                            end
                        end
                    end
                end
                local shouldRefreshCache = cacheScanEnabled and (lastCacheUpdate == 0
                    or movedEnough
                    or needsEmptyRescan
                    or (now - lastCacheUpdate) >= cacheRefreshDelay
                    or lastCacheRange ~= range
                    or lastCacheAmount ~= cacheAmount)
                
                if shouldRefreshCache then
                    local scanRange = range
                    if cacheScanEnabled then
                        -- Wider scan makes cached targets follow you better without increasing plant range.
                        local mult = tonumber(Settings.CacheScanMultiplier) or 1.75
                        local maxR = tonumber(Settings.CacheScanMaxRange) or 120
                        scanRange = math.clamp(range * mult, range, maxR)
                    end
                    local scanRangeSq = scanRange * scanRange
                    overlapParams.FilterDescendantsInstances = {deployables}
                    local parts = workspace:GetPartBoundsInRadius(hrpPos, scanRange, overlapParams)
                    
                    local scanCount = 0
                    table.clear(seen)
                    
                    for _, part in ipairs(parts) do
                        local model = part.Parent
                        if model and model.Name == "Plant Box" then
                            local eid = model:GetAttribute("EntityID")
                            if eid and not seen[eid] then
                                seen[eid] = true
                                local pp = model.PrimaryPart or part
                                local diff = pp.Position - hrpPos
                                local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                if dSq <= scanRangeSq then
                                    scanCount = scanCount + 1
                                    scanEids[scanCount] = eid
                                    scanModels[scanCount] = model
                                    scanParts[scanCount] = pp
                                    scanDistSq[scanCount] = dSq
                                end
                            end
                        end
                    end
                    
                    if scanCount > 1 then
                        for i = 1, scanCount - 1 do
                            local minIdx = i
                            for j = i + 1, scanCount do
                                if scanDistSq[j] < scanDistSq[minIdx] then minIdx = j end
                            end
                            if minIdx ~= i then
                                scanEids[i], scanEids[minIdx] = scanEids[minIdx], scanEids[i]
                                scanModels[i], scanModels[minIdx] = scanModels[minIdx], scanModels[i]
                                scanParts[i], scanParts[minIdx] = scanParts[minIdx], scanParts[i]
                                scanDistSq[i], scanDistSq[minIdx] = scanDistSq[minIdx], scanDistSq[i]
                            end
                        end
                    end

                    if cacheWalkEnabled and not tweenFarmingActive then
                        local emptyInScan = 0
                        for i = 1, scanCount do
                            local m = scanModels[i]
                            if m and m.Parent and not m:FindFirstChild("Seed") then
                                emptyInScan = emptyInScan + 1
                                break
                            end
                        end
                        local maxR = tonumber(Settings.CacheScanMaxRange) or 120
                        if emptyInScan == 0 and scanRange < maxR - 0.5 then
                            scanRange = maxR
                            scanRangeSq = scanRange * scanRange
                            overlapParams.FilterDescendantsInstances = {deployables}
                            local parts2 = workspace:GetPartBoundsInRadius(hrpPos, scanRange, overlapParams)
                            scanCount = 0
                            table.clear(seen)
                            for _, part in ipairs(parts2) do
                                local model = part.Parent
                                if model and model.Name == "Plant Box" then
                                    local eid = model:GetAttribute("EntityID")
                                    if eid and not seen[eid] then
                                        seen[eid] = true
                                        local pp = model.PrimaryPart or part
                                        local diff = pp.Position - hrpPos
                                        local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                        if dSq <= scanRangeSq then
                                            scanCount = scanCount + 1
                                            scanEids[scanCount] = eid
                                            scanModels[scanCount] = model
                                            scanParts[scanCount] = pp
                                            scanDistSq[scanCount] = dSq
                                        end
                                    end
                                end
                            end
                            if scanCount > 1 then
                                for i = 1, scanCount - 1 do
                                    local minIdx = i
                                    for j = i + 1, scanCount do
                                        if scanDistSq[j] < scanDistSq[minIdx] then minIdx = j end
                                    end
                                    if minIdx ~= i then
                                        scanEids[i], scanEids[minIdx] = scanEids[minIdx], scanEids[i]
                                        scanModels[i], scanModels[minIdx] = scanModels[minIdx], scanModels[i]
                                        scanParts[i], scanParts[minIdx] = scanParts[minIdx], scanParts[i]
                                        scanDistSq[i], scanDistSq[minIdx] = scanDistSq[minIdx], scanDistSq[i]
                                    end
                                end
                            end
                        end
                    end
                    
                    table.clear(cachedSeen)
                    cachedBoxCount = 0
                    -- When Auto Plant is on, prefer unseeded boxes in the cache. Otherwise the
                    -- nearest CacheAmount boxes can all be seeded and CacheWalk sits forever
                    -- while empty boxes sit just outside that closest-N set.
                    if plantingEnabled then
                        for i = 1, scanCount do
                            if cachedBoxCount >= cacheAmount then break end
                            local model = scanModels[i]
                            if model and model.Parent and not model:FindFirstChild("Seed") then
                                local eid = scanEids[i]
                                cachedBoxCount = cachedBoxCount + 1
                                cachedEids[cachedBoxCount] = eid
                                cachedModels[cachedBoxCount] = model
                                cachedParts[cachedBoxCount] = scanParts[i]
                                cachedSeen[eid] = true
                            end
                        end
                    end
                    for i = 1, scanCount do
                        if cachedBoxCount >= cacheAmount then break end
                        local eid = scanEids[i]
                        if eid and not cachedSeen[eid] then
                            cachedBoxCount = cachedBoxCount + 1
                            cachedEids[cachedBoxCount] = eid
                            cachedModels[cachedBoxCount] = scanModels[i]
                            cachedParts[cachedBoxCount] = scanParts[i]
                            cachedSeen[eid] = true
                        end
                    end
                    
                    if cacheScanEnabled then
                        for i = 1, scanCount do
                            local eid = scanEids[i]
                            local scanModel = scanModels[i]
                            if plantingEnabled and scanModel and scanModel:FindFirstChild("Seed") then
                                continue
                            end
                            local cachedBox = cacheWalkBoxes[eid]
                            if cachedBox then
                                cachedBox.model = scanModel
                                cachedBox.part = scanParts[i]
                            elseif cacheWalkBoxCount < cacheAmount then
                                cacheWalkBoxCount = cacheWalkBoxCount + 1
                                cacheWalkBoxes[eid] = {
                                    eid = eid,
                                    model = scanModel,
                                    part = scanParts[i],
                                }
                            end
                        end
                    end
                    
                    for i = cachedBoxCount + 1, MAX_CACHE_BOXES do
                        cachedEids[i] = nil
                        cachedModels[i] = nil
                        cachedParts[i] = nil
                    end

                    -- Cache grown bushes inside the same scanned area so CacheWalk can route to them.
                    if cacheWalkEnabled then
                        local cacheWalkFruits = getActivePlantFruits()
                        local harvestables = getHarvestablesNear(hrpPos, scanRange, cacheWalkFruits)
                        cachedBushCount = math.min(#harvestables, MAX_CACHE_BOXES)
                        for i = 1, cachedBushCount do
                            cachedBushModels[i] = harvestables[i].model
                            cachedBushParts[i] = harvestables[i].part
                        end
                        for i = cachedBushCount + 1, MAX_CACHE_BOXES do
                            cachedBushModels[i] = nil
                            cachedBushParts[i] = nil
                        end
                        lastCacheBushUpdate = now
                    end
                    
                    lastCacheUpdate = now
                    lastCacheRange = range
                    lastCacheAmount = cacheAmount
                    lastCacheCenterPos = hrpPos
                    lastCacheScanRange = scanRange
                    cachePlantIdx = 1
                end
                
                if cacheWalking then
                    -- Restrict CacheWalk targets to the most recently scanned cache area
                    local cacheCenter = lastCacheCenterPos or hrpPos
                    local cacheRadius = lastCacheScanRange or range
                    local cacheRadiusSq = cacheRadius * cacheRadius
                    local walkTarget = nil
                    local walkTargetKind = nil
                    local walkTargetRef = nil
                    local walkTargetEid = nil
                    local closestSq = math.huge
                    local boxTarget = nil
                    local boxTargetRef = nil
                    local boxTargetEid = nil
                    local boxClosestSq = math.huge
                    local bushRouteModel = nil
                    local emptyTarget = nil
                    local emptyTargetRef = nil
                    local emptyTargetEid = nil
                    local emptyClosestSq = math.huge
                    local harvestTarget = nil
                    local harvestTargetRef = nil
                    local harvestTargetEid = nil
                    local harvestClosestSq = math.huge
                    local harvestBushModel = nil
                    
                    -- Empty boxes only (planting). Do NOT mark seeded boxes as visited â€”
                    -- that used to poison harvest routing and walk you off a full farm.
                    for i = 1, cachedBoxCount do
                        local eid = cachedEids[i]
                        local model = cachedModels[i]
                        local pp = cachedParts[i]
                        if eid and model and model.Parent and pp and pp.Parent then
                            if cacheWalkSeen[eid] then
                                continue
                            end
                            if plantingEnabled and model:FindFirstChild("Seed") then
                                continue
                            end
                            if not plantingEnabled then
                                continue
                            end
                            local diffCenter = pp.Position - cacheCenter
                            local dCenterSq = diffCenter.X * diffCenter.X + diffCenter.Y * diffCenter.Y + diffCenter.Z * diffCenter.Z
                            if dCenterSq > cacheRadiusSq then
                                continue
                            end
                            local diff = pp.Position - hrpPos
                            local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                            if dSq < emptyClosestSq then
                                emptyClosestSq = dSq
                                emptyTarget = getPlantBoxTweenTarget(pp, hrpPos)
                                emptyTargetRef = model
                                emptyTargetEid = eid
                            end
                        end
                    end

                    -- If we've visited every empty box this cycle, reset and pick again.
                    if not emptyTarget and plantingEnabled and cachedBoxCount > 0 then
                        table.clear(cacheWalkSeen)
                        for i = 1, cachedBoxCount do
                            local eid = cachedEids[i]
                            local model = cachedModels[i]
                            local pp = cachedParts[i]
                            if eid and model and model.Parent and pp and pp.Parent then
                                if model:FindFirstChild("Seed") then
                                    -- skip seeded; leave for harvest routing
                                else
                                    local diffCenter = pp.Position - cacheCenter
                                    local dCenterSq = diffCenter.X * diffCenter.X + diffCenter.Y * diffCenter.Y + diffCenter.Z * diffCenter.Z
                                    if dCenterSq <= cacheRadiusSq then
                                        local diff = pp.Position - hrpPos
                                        local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                        if dSq < emptyClosestSq then
                                            emptyClosestSq = dSq
                                            emptyTarget = getPlantBoxTweenTarget(pp, hrpPos)
                                            emptyTargetRef = model
                                            emptyTargetEid = eid
                                        end
                                    end
                                end
                            end
                        end
                    end

                    local cacheWalkFruits = getActivePlantFruits()

                    -- Track harvestables only inside the cached scan area (never outside cache).
                    -- With no plant boxes, still scan from the player so CacheWalk can harvest bushes.
                    if Settings.HarvestEnabled and (now - lastCacheBushUpdate) >= 0.5 then
                        local bushCenter = cacheCenter
                        local bushRadius = cacheRadius
                        if cachedBoxCount <= 0 then
                            bushCenter = hrpPos
                            bushRadius = math.max(cacheRadius, tonumber(Settings.HarvestRange) or 30)
                        end
                        local harvestables = getHarvestablesNear(bushCenter, bushRadius, cacheWalkFruits)
                        cachedBushCount = math.min(#harvestables, MAX_CACHE_BOXES)
                        for i = 1, cachedBushCount do
                            cachedBushModels[i] = harvestables[i].model
                            cachedBushParts[i] = harvestables[i].part
                        end
                        for i = cachedBushCount + 1, MAX_CACHE_BOXES do
                            cachedBushModels[i] = nil
                            cachedBushParts[i] = nil
                        end
                        lastCacheBushUpdate = now
                        if cachedBoxCount <= 0 then
                            cacheCenter = bushCenter
                            cacheRadius = bushRadius
                            cacheRadiusSq = bushRadius * bushRadius
                        end
                    end

                    -- Bushes in cache: prefer nearest plant box top; if no boxes exist,
                    -- walk straight to the bush so Auto Harvest can still collect.
                    if Settings.HarvestEnabled then
                        local function pickHarvestWalkForBush(bushModel, bushPart)
                            if not bushModel or not bushModel.Parent then return nil, nil, nil end
                            local bushPos = bushModel:GetPivot().Position
                            if not isInsideCacheArea(bushPos, cacheCenter, cacheRadiusSq) then
                                return nil, nil, nil
                            end
                            local top, model, eid = findCachedPlantBoxTopNear(
                                bushPos, cacheCenter, cacheRadiusSq,
                                cachedBoxCount, cachedEids, cachedModels, cachedParts, nil
                            )
                            if top then
                                return top, model, eid
                            end
                            -- No plant boxes in cache: stand at the bush itself.
                            local bp = bushPart
                            if not (bp and bp.Parent) then
                                bp = bushModel.PrimaryPart or bushModel:FindFirstChildWhichIsA("BasePart")
                            end
                            if not bp then return nil, nil, nil end
                            local _, _, groundHit = hasGroundBeneath(bp.Position)
                            local targetY = groundHit and (groundHit.Y + 1) or (bp.Position.Y + 1)
                            local direct = Vector3.new(bp.Position.X, targetY, bp.Position.Z)
                            if isAboveWater(direct) then
                                local hasGround, groundDist = hasGroundBeneath(direct + Vector3.new(0, 8, 0))
                                if not (hasGround and groundDist and groundDist < 25) then
                                    return nil, nil, nil
                                end
                            end
                            return direct, bushModel, nil
                        end

                        for i = 1, cachedBushCount do
                            local bushModel = cachedBushModels[i]
                            if bushModel and bushModel.Parent and not cacheWalkBushSeen[bushModel] then
                                local target, model, eid = pickHarvestWalkForBush(bushModel, cachedBushParts[i])
                                if target then
                                    local toPlayer = target - hrpPos
                                    local playerSq = toPlayer.X * toPlayer.X + toPlayer.Y * toPlayer.Y + toPlayer.Z * toPlayer.Z
                                    if playerSq < harvestClosestSq then
                                        harvestClosestSq = playerSq
                                        harvestTarget = target
                                        harvestTargetRef = model
                                        harvestTargetEid = eid
                                        harvestBushModel = bushModel
                                    end
                                end
                            end
                        end
                        if not harvestTarget and cachedBushCount > 0 then
                            table.clear(cacheWalkBushSeen)
                            for i = 1, cachedBushCount do
                                local bushModel = cachedBushModels[i]
                                if bushModel and bushModel.Parent then
                                    local target, model, eid = pickHarvestWalkForBush(bushModel, cachedBushParts[i])
                                    if target then
                                        local toPlayer = target - hrpPos
                                        local playerSq = toPlayer.X * toPlayer.X + toPlayer.Y * toPlayer.Y + toPlayer.Z * toPlayer.Z
                                        if playerSq < harvestClosestSq then
                                            harvestClosestSq = playerSq
                                            harvestTarget = target
                                            harvestTargetRef = model
                                            harvestTargetEid = eid
                                            harvestBushModel = bushModel
                                        end
                                    end
                                end
                            end
                        end
                    end

                    -- Prefer ripe bushes when Auto Harvest is on. Only walk to empty boxes
                    -- for planting when nothing ripe is in cache, or the empty is clearly
                    -- closer than the harvest target (avoids leaving a ripe plot to plant).
                    -- If unseeded boxes exist, keep planting them â€” don't stall on harvest-only
                    -- when the farm still has empty boxes in cache.
                    if emptyTarget and plantingEnabled then
                        local harvestIsCloser = harvestTarget
                            and Settings.HarvestEnabled
                            and harvestClosestSq + 25 < emptyClosestSq
                        if harvestIsCloser then
                            boxTarget = harvestTarget
                            boxTargetRef = harvestTargetRef
                            boxTargetEid = harvestTargetEid
                            boxClosestSq = harvestClosestSq
                            bushRouteModel = harvestBushModel
                        else
                            boxTarget = emptyTarget
                            boxTargetRef = emptyTargetRef
                            boxTargetEid = emptyTargetEid
                            boxClosestSq = emptyClosestSq
                            bushRouteModel = nil
                        end
                    elseif harvestTarget and Settings.HarvestEnabled then
                        boxTarget = harvestTarget
                        boxTargetRef = harvestTargetRef
                        boxTargetEid = harvestTargetEid
                        boxClosestSq = harvestClosestSq
                        bushRouteModel = harvestBushModel
                    end

                    if boxTarget then
                        walkTarget = boxTarget
                        walkTargetKind = "PlantBox"
                        walkTargetRef = boxTargetRef
                        walkTargetEid = boxTargetEid
                        closestSq = boxClosestSq
                    end
                    
                    local busyPlantWalking = false
                    if plantingEnabled then
                        local _, itemID, newIdx = pickPlantFruitForBox(fruitsToPlant, fruitRotateIdx + 1, ItemIDS)
                        if itemID then
                            fruitRotateIdx = newIdx
                            for i = 1, cachedBoxCount do
                                local eid = cachedEids[i]
                                local model = cachedModels[i]
                                local pp = cachedParts[i]
                                if eid and model and model.Parent and pp and pp.Parent then
                                    if plantedboxes[eid] and (now - plantedboxes[eid] < 0.05) then continue end
                                    if model:FindFirstChild("Seed") then
                                        plantedboxes[eid] = now
                                        continue
                                    end
                                    local diff = pp.Position - hrpPos
                                    local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if dSq <= interactRangeSq then
                                        plant(eid, itemID)
                                        plantedCount = plantedCount + 1
                                        if plantedCount >= 8 then break end
                                    end
                                end
                            end
                        end
                    end

                    -- If Auto Plant has nothing nearby to walk to, fall through to harvest / cache walk.
                    -- Only block true open-ocean targets; platform farms sit above water terrain
                    -- but still have plant-box/ground under the stand point.
                    if not busyPlantWalking and walkTarget and isAboveWater(walkTarget) then
                        local hasGround, groundDist = hasGroundBeneath(walkTarget + Vector3.new(0, 8, 0))
                        if not (hasGround and groundDist and groundDist < 25) then
                            walkTarget = nil
                            closestSq = math.huge
                        end
                    end
                    if not busyPlantWalking and walkTarget and now >= nextCacheWalkMove then
                        if closestSq <= 225 then
                            if walkTargetEid and not bushRouteModel then
                                cacheWalkSeen[walkTargetEid] = true
                            end
                            if bushRouteModel then
                                cacheWalkBushSeen[bushRouteModel] = true
                            end
                            cacheWalkPreferBush = not cacheWalkPreferBush
                        end

                        local retarget = not lastCacheWalkTarget
                            or (walkTarget - lastCacheWalkTarget).Magnitude > 2
                            or walkTargetKind ~= lastCacheWalkTargetKind
                            or walkTargetRef ~= lastCacheWalkTargetRef
                            or closestSq < (lastCacheWalkTargetDistSq - 16)
                        
                        if retarget then
                            lastCacheWalkTarget = walkTarget
                            lastCacheWalkTargetKind = walkTargetKind
                            lastCacheWalkTargetRef = walkTargetRef
                            lastCacheWalkTargetDistSq = closestSq
                        else
                            lastCacheWalkTargetDistSq = closestSq
                        end
                        nextCacheWalkMove = now + 0.15
                    end

                    -- Keep movement alive every plant tick. Tween needs continuous
                    -- AlignPosition updates; Walk/SmoothWalk need BV/MoveTo refresh.
                    -- (Do not plantRemoveAlign here â€” that broke Tween mode.)
                    if not busyPlantWalking and walkTarget then
                        local hum = char:FindFirstChild("Humanoid")
                        if hum then
                            moveToTargetUsingGoldLogic(walkTarget)
                        end
                    elseif not busyPlantWalking and not walkTarget then
                        -- Nothing to walk to: stop BodyVelocity/MoveTo so we don't keep
                        -- drifting into water after the cache goes empty offshore.
                        plantStopMovement()
                        table.clear(cacheWalkSeen)
                        table.clear(cacheWalkBushSeen)
                        lastCacheWalkTarget = nil
                        lastCacheWalkTargetKind = nil
                        lastCacheWalkTargetRef = nil
                        lastCacheWalkTargetDistSq = math.huge
                    end
                elseif lastCacheWalkTarget then
                    plantStopMovement()
                    lastCacheWalkTarget = nil
                    lastCacheWalkTargetKind = nil
                    lastCacheWalkTargetRef = nil
                    lastCacheWalkTargetDistSq = math.huge
                end
                
                boxCount = 0
                
                if cachePlantEnabled then
                    -- Use the cache's sorted "closest boxes" list so we always plant around current HRP,
                    -- even if cacheWalkBoxes currently contains stale/far entries while moving.
                    -- Always build candidates from current HRP outward (closest-first).
                    for i = 1, cachedBoxCount do
                        local eid = cachedEids[i]
                        local model = cachedModels[i]
                        local pp = cachedParts[i]
                        if eid and model and model.Parent and pp and pp.Parent then
                            if plantedboxes[eid] and (now - plantedboxes[eid] < 0.05) then continue end
                            if plantingEnabled and model:FindFirstChild("Seed") then
                                plantedboxes[eid] = now
                                continue
                            end
                            local diff = pp.Position - hrpPos
                            local dSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                            if dSq <= interactRangeSq then
                                boxCount = boxCount + 1
                                boxEids[boxCount] = eid
                                boxModels[boxCount] = model
                                boxDistSq[boxCount] = dSq
                            end
                        end
                    end
                    -- Cache miss: if we're trying to plant but found nothing in-range from cache,
                    -- force a refresh next loop so new nearby boxes aren't "ignored" until timer/move refresh.
                    if plantingEnabled and boxCount == 0 then
                        lastCacheUpdate = 0
                        lastCacheCenterPos = nil
                        lastCacheScanRange = nil
                        cachePlantIdx = 1
                    end
                else
                    local boxes = getPlantBoxModelsCached()
                    table.clear(seen)
                    if boxes then
                        for _, model in ipairs(boxes) do
                            if model and model.Parent and not model:FindFirstChild("Seed") then
                                local part = getPlantBoxPartCheap(model)
                                if part then
                                    local diff = hrpPos - part.Position
                                    local distSq = diff.X * diff.X + diff.Y * diff.Y + diff.Z * diff.Z
                                    if distSq <= interactRangeSq then
                                        local eid = model:GetAttribute("EntityID") or getHarvestEntityId(model)
                                        if eid and not seen[eid] then
                                            seen[eid] = true
                                            if plantedboxes[eid] and (now - plantedboxes[eid] < 0.05) then continue end
                                            boxCount = boxCount + 1
                                            boxEids[boxCount] = eid
                                            boxModels[boxCount] = model
                                            boxDistSq[boxCount] = distSq
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                
                if boxCount > 1 then
                    for i = 1, boxCount - 1 do
                        local minIdx = i
                        for j = i + 1, boxCount do
                            if boxDistSq[j] < boxDistSq[minIdx] then minIdx = j end
                        end
                        if minIdx ~= i then
                            boxEids[i], boxEids[minIdx] = boxEids[minIdx], boxEids[i]
                            boxModels[i], boxModels[minIdx] = boxModels[minIdx], boxModels[i]
                            boxDistSq[i], boxDistSq[minIdx] = boxDistSq[minIdx], boxDistSq[i]
                        end
                    end
                end
                
                if plantingEnabled and boxCount > 0 and not cacheWalking then
                    local fruitName, itemID, newIdx = pickPlantFruitForBox(fruitsToPlant, fruitRotateIdx + 1, ItemIDS)
                    if itemID then
                        fruitRotateIdx = newIdx
                        local maxPlantThisTick = math.min(boxCount, 8)
                        for i = 1, boxCount do
                            if not isPlantLoopActive() then break end
                            if (boxDistSq[i] or 0) > interactRangeSq then continue end
                            local model = boxModels[i]
                            if model and model.Parent then
                                if not model:FindFirstChild("Seed") then
                                    plant(boxEids[i], itemID)
                                    plantedCount = plantedCount + 1
                                else
                                    plantedboxes[boxEids[i]] = now
                                end
                            end
                            if plantedCount >= maxPlantThisTick then break end
                            if plantedCount > 0 and plantedCount % 4 == 0 then
                                task.wait()
                            end
                        end
                    end
                end
            end)
            
            local delay = math.max(tonumber(Settings.PlantDelay) or 0.05, 0.05)
            if plantedCount > 0 then
                task.wait(math.max(delay, 0.08))
            else
                task.wait(delay)
            end
        end
        if not (Settings.TweenToPlantBox or Settings.TweenToBush or Settings.TweenToBushAndBox) then
            plantStopMovement()
        end
        plantActive = false
    end)
end

end -- AsterPlantRuntime

do -- AsterHarvestRuntime

local harvestActive = false
function startHarvest()
    if harvestActive then return end
    harvestActive = true
    task.spawn(function()
        local attemptedItems = {}
        local scanRange = 8
        local scanStep = 8

        while Settings.HarvestEnabled do
            local foundAny = false
            pcall(function()
                local currentTime = tick()
                for item, attemptTime in pairs(attemptedItems) do
                    if currentTime > attemptTime then
                        attemptedItems[item] = nil
                    end
                end

                local range = tonumber(Settings.HarvestRange) or 25
                scanRange = math.min(scanRange, range)
                local items = getHarvestables(scanRange)

                if #items > 0 then
                    foundAny = true
                    local rawBatch = tonumber(Settings.HarvestBatchSize) or 20
                    local batchSize = math.min(math.clamp(rawBatch, 1, 50), #items)
                    local harvestedCount = 0

                    for _, item in ipairs(items) do
                        if not Settings.HarvestEnabled or harvestedCount >= batchSize then break end

                        local eid = item.entityid
                        if not eid and item.model then
                            eid = getHarvestEntityId(item.model)
                        end
                        eid = math.floor(tonumber(eid) or 0)

                        if eid > 0 and ByteNetReliable and not attemptedItems[eid] then
                            attemptedItems[eid] = currentTime + 0.04
                            if fireByteNetPickup(eid) then
                                harvestedCount = harvestedCount + 1
                                local modelName = item.model and item.model.Name or ""
                                local ws = __ASTER_RUNTIME.webhookStats
                                if ws then ws.harvested = (ws.harvested or 0) + 1 end
                                if modelName ~= "" and __ASTER_RUNTIME.recordGrindGain then
                                    __ASTER_RUNTIME.recordGrindGain(modelName, 1)
                                end
                            end

                            if harvestedCount % 20 == 0 then
                                task.wait()
                            end
                        end
                    end
                else
                    scanRange = math.min(range, scanRange + scanStep)
                end
            end)
            task.wait(foundAny and 0.015 or 0.06)
        end
        harvestActive = false
    end)
end
end -- AsterEatFuelPlantHarvest
do -- AsterSandFarm
-- Sand farm: stack Sand Amount mounds at one spot (shovel) -> god pick break all -> repeat
local sandActive = false
local sandSpot = nil
local sandPhase = "dig" -- "dig" | "break"
local sandBreakAttempts = 0

local function getSandAmount()
    local amount = tonumber(Settings.SandAmount)
    local reg = Window and Window.ElementRegistry and Window.ElementRegistry["Sand Amount"]
    if reg and reg.GetValue then
        local uiVal = tonumber(reg.GetValue())
        if uiVal then amount = uiVal end
    end
    amount = math.floor(amount or 1)
    if amount < 1 then return 1 end
    if amount > 40 then return 40 end
    return amount
end

local function lockSandSpot()
    if sandSpot then
        Settings.SandFarmSpot = sandSpot
        return sandSpot
    end
    local root = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end
    -- Lock one dig point (X/Z/Y) for the whole cycle ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â Y does not follow you up the stack.
    sandSpot = {
        x = math.floor(root.Position.X + 0.5),
        z = math.floor(root.Position.Z + 0.5),
        y = root.Position.Y - (Settings.SandHeight or 1),
    }
    Settings.SandFarmSpot = sandSpot
    return sandSpot
end

local function playerOnSandFarmSpot(hrp, spot)
    if not hrp or not spot then return false end
    return math.abs(hrp.Position.X - spot.x) < 3 and math.abs(hrp.Position.Z - spot.z) < 3
end

local function alignToSandFarmSpot(hrp, spot)
    if not hrp or not spot then return false end
    if updateRayParams then updateRayParams() end
    local hit = workspace:Raycast(Vector3.new(spot.x, hrp.Position.Y + 20, spot.z), Vector3.new(0, -80, 0), rayParams)
    local groundY = hit and hit.Position.Y or spot.y
    local standPos = Vector3.new(spot.x, groundY + 3, spot.z)
    local distXZ = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(spot.x, 0, spot.z)).Magnitude
    if distXZ < 1.5 and math.abs(hrp.Position.Y - standPos.Y) < 4 then
        return false
    end
    local lookAt = Vector3.new(spot.x, groundY + 1.5, spot.z)
    hrp.CFrame = CFrame.lookAt(standPos, lookAt)
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if hum then hum:MoveTo(standPos) end
    return true
end

local function nudgeOffSandStack(hrp, spot)
    if not hrp or not spot or not playerOnSandFarmSpot(hrp, spot) then return false end
    -- Only step aside when actually standing on the stacked mounds, not when beside the tile.
    if hrp.Position.Y <= spot.y + 2 then return false end
    if updateRayParams then updateRayParams() end

    local lookAt = Vector3.new(spot.x, spot.y + 1.5, spot.z)
    local offsets = {
        Vector3.new(5, 0, 0),
        Vector3.new(-5, 0, 0),
        Vector3.new(0, 0, 5),
        Vector3.new(0, 0, -5),
    }
    local bestPos = nil
    local bestDist = 0
    for _, off in ipairs(offsets) do
        local tx, tz = spot.x + off.X, spot.z + off.Z
        local hit = workspace:Raycast(Vector3.new(tx, hrp.Position.Y + 20, tz), Vector3.new(0, -80, 0), rayParams)
        local groundY = hit and hit.Position.Y or spot.y
        local standPos = Vector3.new(tx, groundY + 3, tz)
        local dist = (Vector3.new(tx, 0, tz) - Vector3.new(spot.x, 0, spot.z)).Magnitude
        if dist > bestDist then
            bestDist = dist
            bestPos = standPos
        end
    end
    if not bestPos then return false end

    hrp.CFrame = CFrame.lookAt(bestPos, lookAt)
    hrp.AssemblyLinearVelocity = Vector3.zero
    hrp.AssemblyAngularVelocity = Vector3.zero
    local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
    if hum then hum:MoveTo(bestPos) end
    return true
end

local function sandPileCenter(spot)
    return Vector3.new(spot.x, spot.y + 1.5, spot.z)
end

local function getSandMoundEntityId(model)
    if not model then return nil end
    local keys = { "EntityID", "NetworkId", "networkId", "NetworkID", "ID", "Id", "Eid", "EntityId" }
    for _, key in ipairs(keys) do
        local v = model:GetAttribute(key)
        if v ~= nil then
            local n = math.floor(tonumber(v) or 0)
            if n > 0 then return n end
        end
    end
    return nil
end

local function sandMoundAtSpot(moundName)
    local spot = sandSpot
    local resources = getWorkspaceResources()
    if not resources or not spot then return nil end
    local best, bestDist = nil, 9
    local function consider(m)
        if not m or m.Name ~= moundName then return end
        local ok, p = pcall(function() return m:GetPivot().Position end)
        if not ok or not p then return end
        local dx, dz = p.X - spot.x, p.Z - spot.z
        local dist = math.sqrt(dx * dx + dz * dz)
        if dist < bestDist then
            bestDist = dist
            best = m
        end
    end
    for _, m in ipairs(resources:GetChildren()) do
        consider(m)
        if m:IsA("Folder") then
            for _, sub in ipairs(m:GetChildren()) do
                consider(sub)
            end
        end
    end
    return best
end

local function countSandMoundsAtSpot()
    local spot = sandSpot
    local resources = getWorkspaceResources()
    if not resources or not spot then return 0 end
    local count = 0
    local function consider(m)
        if not m or m.Name ~= "Sand Mound" then return end
        local ok, p = pcall(function() return m:GetPivot().Position end)
        if not ok or not p then return end
        if math.abs(p.X - spot.x) < 3 and math.abs(p.Z - spot.z) < 3 then
            count = count + 1
        end
    end
    for _, m in ipairs(resources:GetChildren()) do
        consider(m)
        if m:IsA("Folder") then
            for _, sub in ipairs(m:GetChildren()) do
                consider(sub)
            end
        end
    end
    return count
end

local function collectSandFarmBreakTargets()
    local spot = sandSpot
    local resources = getWorkspaceResources()
    local targets = {}
    if not resources or not spot then return targets end
    local function consider(m)
        if not m or (m.Name ~= "Sand Mound" and m.Name ~= "_MOUND") then return end
        local ok, p = pcall(function() return m:GetPivot().Position end)
        if not ok or not p then return end
        if math.abs(p.X - spot.x) >= 3 or math.abs(p.Z - spot.z) >= 3 then return end
        local id = getSandMoundEntityId(m)
        if id then
            table.insert(targets, { eid = id, name = m.Name, pos = p })
        end
    end
    for _, m in ipairs(resources:GetChildren()) do
        consider(m)
        if m:IsA("Folder") then
            for _, sub in ipairs(m:GetChildren()) do
                consider(sub)
            end
        end
    end
    table.sort(targets, function(a, b)
        if a.name == b.name then return false end
        return a.name == "Sand Mound"
    end)
    return targets
end

local function ensureShovel()
    local tools = workspace.Players[plr.Name]:FindFirstChild("Tools")
    if tools and not tools:FindFirstChild("Shovel") and getToolSlot("Shovel") then
        equipItemPacket("Shovel")
    end
end

local function ensureShovelOnly()
    local char = plr.Character
    if not char then return end
    if char:FindFirstChild("God Pick") then
        local hum = char:FindFirstChild("Humanoid")
        if hum then hum:UnequipTools() end
    end
    ensureShovel()
    local bp = plr.Backpack:FindFirstChild("Shovel")
    local hum = char:FindFirstChild("Humanoid")
    if bp and hum and not char:FindFirstChild("Shovel") then
        hum:EquipTool(bp)
    end
end

local function ensureGodPick()
    local char = plr.Character
    if not char then return end
    local pickName = "God Pick"
    if not char:FindFirstChild(pickName) and getToolSlot(pickName) then
        equipItemPacket(pickName)
        task.wait(0.02)
    end
    if not char:FindFirstChild(pickName) then
        local bp = plr.Backpack:FindFirstChild(pickName)
        local hum = char:FindFirstChild("Humanoid")
        if bp and hum then hum:EquipTool(bp) end
    end
end

-- Dig (captured):
--   no mound:  [0][Dig][u8 0][f32 x][f32 y][f32 z]                 -- 15 bytes
--   with eid:  [0][Dig][u8 1][u32 eid][f32 x][f32 y][f32 z]         -- 19 bytes
local function fireSandDig(spot, entityId)
    if not ByteNetReliable or not spot then return end
    local digId = getPacketId("Dig")
    if not digId then return end

    local eid = math.floor(tonumber(entityId) or 0)
    if eid > 0 then
        local b = buffer.create(19)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, digId)
        buffer.writeu8(b, 2, 1)
        buffer.writeu32(b, 3, eid)
        buffer.writef32(b, 7, spot.x)
        buffer.writef32(b, 11, spot.y)
        buffer.writef32(b, 15, spot.z)
        ByteNetReliable:FireServer(b)
    else
        local b = buffer.create(15)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, digId)
        buffer.writeu8(b, 2, 0)
        buffer.writef32(b, 3, spot.x)
        buffer.writef32(b, 7, spot.y)
        buffer.writef32(b, 11, spot.z)
        ByteNetReliable:FireServer(b)
    end
end

function startAutoSand()
    if sandActive then return end
    sandActive = true
    sandSpot = nil
    sandPhase = "dig"
    sandBreakAttempts = 0
    Settings.SandFarmSpot = nil
    Settings.SandFarmDigCount = 0
    Settings.SandFarmAllowBreak = false
    Settings.SandFarmPhase = "dig"

    task.spawn(function()
        while Settings.AutoSandEnabled do
            pcall(function()
                local spot = lockSandSpot()
                if not spot then return end

                local level1 = sandMoundAtSpot("_MOUND")
                local delay = math.max(tonumber(Settings.SandFarmSpeed) or 0.4, 0.2)
                local sandAmount = getSandAmount()
                Settings.SandAmount = sandAmount
                local moundCount = countSandMoundsAtSpot()
                Settings.SandFarmDigCount = moundCount

                if sandPhase == "dig" then
                    Settings.SandFarmAllowBreak = false
                    Settings.SandFarmPhase = "dig"
                    ensureShovelOnly()
                    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if hrp and alignToSandFarmSpot(hrp, spot) then
                        task.wait(0.08)
                    end

                    if moundCount >= sandAmount then
                        task.wait(math.max(delay, 0.35))
                        sandPhase = "break"
                        Settings.SandFarmPhase = "break"
                        ensureGodPick()
                        task.wait(math.max(delay * 0.5, 0.2))
                    else
                        local id = level1 and getSandMoundEntityId(level1)
                        fireSandDig(spot, id)
                        task.wait(delay)
                    end
                else
                    Settings.SandFarmAllowBreak = true
                    Settings.SandFarmPhase = "break"
                    local targets = collectSandFarmBreakTargets()
                    if #targets > 0 then
                        sandBreakAttempts = sandBreakAttempts + 1
                        if sandBreakAttempts > 15 then
                            sandBreakAttempts = 0
                            sandPhase = "dig"
                            Settings.SandFarmPhase = "dig"
                            Settings.SandFarmAllowBreak = false
                            ensureShovelOnly()
                            local hrpRetry = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                            if hrpRetry and alignToSandFarmSpot(hrpRetry, spot) then
                                task.wait(0.08)
                            end
                            local level1 = sandMoundAtSpot("_MOUND")
                            fireSandDig(spot, level1 and getSandMoundEntityId(level1))
                            task.wait(delay)
                        else
                        ensureGodPick()
                        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            if nudgeOffSandStack(hrp, spot) then
                                task.wait(0.08)
                            end

                            local pileCenter = sandPileCenter(spot)
                            local swings = {}
                            for i = 1, #targets do
                                if targets[i].name == "Sand Mound" then
                                    table.insert(swings, {
                                        eid = targets[i].eid,
                                        pos = targets[i].pos or pileCenter,
                                    })
                                end
                            end
                            if #swings == 0 then
                                for i = 1, #targets do
                                    table.insert(swings, {
                                        eid = targets[i].eid,
                                        pos = targets[i].pos or pileCenter,
                                    })
                                end
                            end
                            local maxPick = math.clamp(#swings, 1, 9)
                            local packed = {}
                            for i = 1, maxPick do
                                packed[i] = swings[i]
                            end
                            local fromPos = hrp.Position + Vector3.new(0, 1.25, 0)
                            local swingOpts = {
                                maxPerPacket = maxPick,
                                skipLead = true,
                                fromPos = fromPos,
                                cframe = CFrame.lookAt(fromPos, pileCenter),
                            }
                            fireByteNetSwingToolPackedMultiHit(packed, hrp, { maxTargets = maxPick })
                            fireByteNetSwingTool(packed, hrp, swingOpts)
                        end
                        task.wait(delay)
                        end
                    else
                        sandBreakAttempts = 0
                        task.wait(math.max(delay, 0.35))
                        sandPhase = "dig"
                        Settings.SandFarmPhase = "dig"
                        Settings.SandFarmDigCount = 0
                        Settings.SandFarmAllowBreak = false
                        ensureShovelOnly()
                        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                        if hrp and alignToSandFarmSpot(hrp, spot) then
                            task.wait(0.08)
                        end
                        task.wait(delay)
                    end
                end
            end)
            task.wait(math.max(tonumber(Settings.SandFarmSpeed) or 0.4, 0.2))
        end
        sandSpot = nil
        sandPhase = "dig"
        Settings.SandFarmSpot = nil
        Settings.SandFarmDigCount = 0
        Settings.SandFarmAllowBreak = false
        Settings.SandFarmPhase = "dig"
        sandActive = false
    end)
end


end -- AsterSandFarm

do -- AsterPlaceGridPreview
local placeGridActive = false
local pendingPlacements = {}
-- [[ PLANT BOX PREVIEW SYSTEM ]] --
local PreviewCache = {}
PreviewContainer = asterEnsureWorldFolder("AsterPreviewContainer")

local function getPreviewModel()
    local rs = game:GetService("ReplicatedStorage")
    local template = nil
    
    local quickFolders = {"Deployables", "PlaceStructures", "Structures", "Models"}
    for _, fname in ipairs(quickFolders) do
        local folder = rs:FindFirstChild(fname)
        if folder and folder:FindFirstChild("Plant Box") then
            template = folder:FindFirstChild("Plant Box")
            break
        end
    end
    
    if not template then
        for _, v in ipairs(rs:GetDescendants()) do
            if (v:IsA("Model") or v:IsA("BasePart")) and v.Name == "Plant Box" then
                template = v
                break
            end
        end
    end

    local model
    if template then
        model = template:Clone()
    else
        -- Fallback to simple part if model is missing (should rarely happen)
        model = Instance.new("Part")
        model.Size = Vector3.new(4, 1, 4)
        model.Color = Color3.fromRGB(0, 255, 100)
        model.CastShadow = false
    end
    
    model.Name = "PreviewBox"
    
    -- Recursive function to setup visual properties for all parts in the model
    local function setupVisuals(obj)
        if obj:IsA("BasePart") then
            obj.Transparency = 0.65
            obj.CanCollide = false
            obj.CastShadow = false
            -- Disable physics/raycast interactions
            pcall(function() obj.CanQuery = false obj.CanTouch = false end)
        end
        for _, child in ipairs(obj:GetChildren()) do
            setupVisuals(child)
        end
    end
    
    setupVisuals(model)
    
    -- Optimization for BulkMoveTo:
    -- We want to move only the PrimaryPart (Anchored) and have children (Unanchored + Welded) follow.
    if model:IsA("Model") then
        if not model.PrimaryPart then
            model.PrimaryPart = model:FindFirstChildWhichIsA("BasePart", true)
        end
        
        local pp = model.PrimaryPart
        if pp then
            pp.Anchored = true
            for _, desc in ipairs(model:GetDescendants()) do
                if desc:IsA("BasePart") and desc ~= pp then
                    desc.Anchored = false
                    local w = Instance.new("WeldConstraint")
                    w.Part0 = pp
                    w.Part1 = desc
                    w.Parent = pp
                end
            end
        end
    elseif model:IsA("BasePart") then
        model.Anchored = true
    end
    
    return model
end

local GroundHeightCache = {}
local OccupancyCache = {}
local CachedRayParams = nil
local LastParamsUpdate = 0

local function getPlantBoxRotationCFrame()
    return CFrame.Angles(0, math.rad(Settings.PlantBoxRotation or 0), 0)
end

local function getPlantBoxGridSpacings()
    local xGap = tonumber(Settings.PlantBoxSpacingX) or 5.1
    local zGap = tonumber(Settings.PlantBoxSpacingZ) or 5.1
    return zGap, xGap, xGap * 0.5
end

local function getPlantBoxEulerAngles()
    return getPlantBoxRotationCFrame():ToEulerAnglesXYZ()
end

local function clearPlantBoxPreview()
    if PreviewContainer then
        PreviewContainer:ClearAllChildren()
    end
    table.clear(PreviewCache)
    table.clear(GroundHeightCache)
    table.clear(OccupancyCache)
end

local function updatePreview()
    -- Strict check: Only show if the toggle is actually enabled
    if not Settings.ShowPlantBoxPreview then
        clearPlantBoxPreview()
        return
    end
    
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    
    local currentTime = tick()

    -- [[ OPTIMIZATION: Persistent RaycastParams ]]
    -- Update params only once every 2 seconds or if missing
    if not CachedRayParams or (currentTime - LastParamsUpdate > 2.0) then
        local rayParams = RaycastParams.new()
        local ignoreList = {}
        if plr.Character then table.insert(ignoreList, plr.Character) end
        if PreviewContainer then table.insert(ignoreList, PreviewContainer) end
        local ignoreFolders = {"Resources", "Rubble", "Critters", "Items", "Players", "MeteorParts"}
        for _, name in ipairs(ignoreFolders) do
            local f = workspace:FindFirstChild(name)
            if f then table.insert(ignoreList, f) end
        end
        rayParams.FilterDescendantsInstances = ignoreList
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.IgnoreWater = true
        
        CachedRayParams = rayParams
        LastParamsUpdate = currentTime
    end
    
    local Z_GAP, X_GAP, OFFSET = getPlantBoxGridSpacings()
    
    -- Determine Center
    local centerPos = hrp.Position
    
    local baseRow = math.floor(centerPos.Z / Z_GAP + 0.5)
    local baseCol = math.floor(centerPos.X / X_GAP + 0.5)
    
    -- Determine Radius based on Mode
    local RADIUS = 6
    if Settings.PlantMode == "SinglePlantBoxPlacement" then
        RADIUS = 0 -- Single Box Mode
    end
    
    local activeKeys = {}
    local partsToMove = {}
    local cframesToMove = {}
    local plantRotCF = getPlantBoxRotationCFrame()
    
    for r = baseRow - RADIUS, baseRow + RADIUS do
        for c = baseCol - RADIUS, baseCol + RADIUS do
            local rowDiff = r 
            local currentOffset = (math.abs(rowDiff) % 2 == 1) and OFFSET or 0
            local targetX = (c * X_GAP) + currentOffset
            local targetZ = (r * Z_GAP)
            local key = string.format("%.1f,%.1f", targetX, targetZ)
            
            -- Check validity based on mode
            local isValid = false
            
            if RADIUS == 0 then
                -- Strict Single Box
                isValid = (r == baseRow and c == baseCol)
            else
                -- Multi Box: Square Grid
                isValid = true
            end
            
            if isValid then
                activeKeys[key] = true
                
                -- [[ Terrain Adaptation with Caching ]]
                local cellY = hrp.Position.Y - 3 -- Default fallback
                local cached = GroundHeightCache[key]
                
                -- Re-check height every 3 seconds
                if cached and (currentTime - cached.t < 3.0) then
                    cellY = cached.y
                else
                    local rayOrigin = Vector3.new(targetX, hrp.Position.Y + 30, targetZ)
                    local rayDir = Vector3.new(0, -100, 0)
                    local hit = workspace:Raycast(rayOrigin, rayDir, CachedRayParams)
                    
                    if hit then
                        cellY = hit.Position.Y
                        GroundHeightCache[key] = {y = cellY, t = currentTime}
                    else
                        GroundHeightCache[key] = {y = cellY, t = currentTime}
                    end
                end
                
                -- [[ Occupancy Check with Caching ]]
                -- GetPartBoundsInBox is expensive, so we cache the result for 0.25 seconds.
                -- This reduces physics queries by ~15x.
                local occupied = false
                local occCached = OccupancyCache[key]
                
                if occCached and (currentTime - occCached.t < 0.25) then
                    occupied = occCached.val
                else
                    local checkCFrame = CFrame.new(targetX, cellY + 5, targetZ) * plantRotCF
                    local checkSize = Vector3.new(4, 10, 4) 
                    local parts = workspace:GetPartBoundsInBox(checkCFrame, checkSize)
                    
                    for _, p in ipairs(parts) do 
                        local model = p:FindFirstAncestorOfClass("Model")
                        if model and model.Name == "Plant Box" then
                             local pPos = model:GetPivot().Position
                             local distToCenter = math.sqrt((pPos.X - targetX)^2 + (pPos.Z - targetZ)^2)
                             if distToCenter < 2.0 then
                                occupied = true 
                                break 
                             end
                        end 
                    end
                    OccupancyCache[key] = {val = occupied, t = currentTime}
                end
                
                if not occupied and not pendingPlacements[key] then
                    -- Show Preview
                    local model = PreviewCache[key]
                    if not model then
                        model = getPreviewModel()
                        model.Parent = PreviewContainer
                        PreviewCache[key] = model
                    end
                    
                    local pp = model.PrimaryPart or (model:IsA("BasePart") and model)
                    if pp then
                        table.insert(partsToMove, pp)
                        local heightOffset = pp.Size.Y / 2
                        table.insert(cframesToMove, CFrame.new(targetX, cellY + heightOffset, targetZ) * plantRotCF)
                    end
                else
                    -- Remove if occupied or pending
                    if PreviewCache[key] then
                        PreviewCache[key]:Destroy()
                        PreviewCache[key] = nil
                    end
                end
            end
        end
    end
    
    -- Cleanup inactive previews and cache
    for key, model in pairs(PreviewCache) do
        if not activeKeys[key] then
            model:Destroy()
            PreviewCache[key] = nil
            if GroundHeightCache[key] then GroundHeightCache[key] = nil end
            if OccupancyCache[key] then OccupancyCache[key] = nil end
        end
    end
    
    -- [[ BulkMoveTo Optimization ]] --
    if #partsToMove > 0 then
        workspace:BulkMoveTo(partsToMove, cframesToMove)
    end
end

-- PERF FIX: Throttle preview updates to 10 FPS instead of every frame
local _previewAccum = 0
local _plantPreviewWasEnabled = false
local PREVIEW_INTERVAL = 1/10
registerFrameUpdate("plantPreview", function(dt)
    if not Settings.ShowPlantBoxPreview then
        if _plantPreviewWasEnabled then
            clearPlantBoxPreview()
            _plantPreviewWasEnabled = false
        end
        _previewAccum = 0
        return
    end
    _plantPreviewWasEnabled = true
    _previewAccum = _previewAccum + dt
    if _previewAccum >= PREVIEW_INTERVAL then
        _previewAccum = 0
        updatePreview()
    end
end)
ensureMasterFrameLoop()

function startMultiplyPlantBox()
    if placeGridActive then return end
    placeGridActive = true
    table.clear(pendingPlacements) -- Reset state
    
    task.spawn(function()
        while Settings.MultiplyPlantBox or Settings.SoloPatternPlantBoxes do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then task.wait(0.02) continue end
            
            -- Retry Logic: Cleanup pending placements after 1s to retry failed spots sooner (multi-grid)
            local now = tick()
            for key, time in pairs(pendingPlacements) do 
                if now - time > 1.0 then pendingPlacements[key] = nil end 
            end

            local Z_GAP, X_GAP, OFFSET = getPlantBoxGridSpacings()
            
            -- Determine Center
            local centerPos = hrp.Position
            -- Follow Aim removed as requested
            
            local baseRow = math.floor(centerPos.Z / Z_GAP + 0.5)
            local baseCol = math.floor(centerPos.X / X_GAP + 0.5)
            
            local RADIUS = 6
            if Settings.SoloPatternPlantBoxes and not Settings.MultiplyPlantBox then
                RADIUS = 0 
            end

            -- Reuse preview ray filter when possible (same ignores); avoids rebuilding RaycastParams per cell
            local plantRay = CachedRayParams
            if not plantRay then
                plantRay = RaycastParams.new()
                local ignoreList = {}
                if plr.Character then table.insert(ignoreList, plr.Character) end
                if PreviewContainer then table.insert(ignoreList, PreviewContainer) end
        for _, name in ipairs({"Resources", "Rubble", "Critters", "Items", "Players", "MeteorParts"}) do
                    local f = workspace:FindFirstChild(name)
                    if f then table.insert(ignoreList, f) end
                end
                plantRay.FilterDescendantsInstances = ignoreList
                plantRay.FilterType = Enum.RaycastFilterType.Exclude
                plantRay.IgnoreWater = true
                CachedRayParams = plantRay
                LastParamsUpdate = tick()
            end

            local candidates = {}
            local rx, ry, rz = getPlantBoxEulerAngles()
            local plantRotCF = getPlantBoxRotationCFrame()
            
            for r = baseRow - RADIUS, baseRow + RADIUS do
                for c = baseCol - RADIUS, baseCol + RADIUS do
                    local rowDiff = r 
                    local currentOffset = (math.abs(rowDiff) % 2 == 1) and OFFSET or 0
                    local targetX = (c * X_GAP) + currentOffset
                    local targetZ = (r * Z_GAP)
                    
                    -- Distance Check (Square for Multi, Exact for Solo)
                    local isValid = true
                    if RADIUS == 0 then
                        isValid = (r == baseRow and c == baseCol)
                    end
                    
                    if isValid then
                         local occY = hrp.Position.Y
                         local floorHit = workspace:Raycast(Vector3.new(targetX, hrp.Position.Y + 35, targetZ), Vector3.new(0, -500, 0), plantRay)
                         if floorHit then
                             occY = floorHit.Position.Y
                         end
                         local checkCFrame = CFrame.new(targetX, occY + 5, targetZ) * plantRotCF
                         local checkSize = Vector3.new(4, 10, 4) 
                         local parts = workspace:GetPartBoundsInBox(checkCFrame, checkSize)
                         local occupied = false
                         
                         for _, p in ipairs(parts) do 
                             local model = p:FindFirstAncestorOfClass("Model")
                             if model and model.Name == "Plant Box" then
                                  local pPos = model:GetPivot().Position
                                  local distToCenter = math.sqrt((pPos.X - targetX)^2 + (pPos.Z - targetZ)^2)
                                  if distToCenter < 2.0 then
                                     occupied = true 
                                     break 
                                  end
                             end 
                         end
                         
                         if not occupied then
                             local key = string.format("%.1f,%.1f", targetX, targetZ)
                             if not pendingPlacements[key] then
                                 table.insert(candidates, {x = targetX, z = targetZ, key = key, gr = r, gc = c})
                             end
                         end
                    end
                end
            end
            
            -- Row by row (low grid r / low Z first), then right-to-left along staggered rows (high gc first)
            table.sort(candidates, function(a, b)
                if a.gr ~= b.gr then
                    return a.gr < b.gr
                end
                return a.gc > b.gc
            end)
            
            local placedCount = 0
            for _, cand in ipairs(candidates) do
                if placedCount >= 1 then break end
                
                -- Raycast to find ground height
                local rayOrigin = Vector3.new(cand.x, hrp.Position.Y + 30, cand.z)
                local rayDir = Vector3.new(0, -500, 0)
                
                local hit = workspace:Raycast(rayOrigin, rayDir, plantRay)
                if hit then
                    local validSurface = false
                    if hit.Instance:IsA("Terrain") then
                        validSurface = true
                    else
                        local model = hit.Instance:FindFirstAncestorOfClass("Model")
                        if model and model.Parent and model.Parent.Name == "Deployables" then
                            validSurface = true
                        end
                    end

                    if validSurface then
                        local targetY = hit.Position.Y
                        local pos = Vector3.new(cand.x, targetY, cand.z)
                        local name = "Plant Box"
                        
                        if ByteNetReliable then
                            local nameLen = #name
                            local b = buffer.create(4 + nameLen + 24)
                            buffer.writeu8(b, 0, 0)
                            buffer.writeu8(b, 1, getPacketId("PlaceStructure"))
                            buffer.writeu16(b, 2, nameLen)
                            for i = 1, nameLen do buffer.writeu8(b, 3 + i, string.byte(name, i)) end
                            
                            local offset = 4 + nameLen
                            buffer.writef32(b, offset, pos.X)
                            buffer.writef32(b, offset + 4, pos.Y)
                            buffer.writef32(b, offset + 8, pos.Z)
                            buffer.writef32(b, offset + 12, rx) -- RotX
                            buffer.writef32(b, offset + 16, ry) -- RotY
                            buffer.writef32(b, offset + 20, rz) -- RotZ
                            
                            ByteNetReliable:FireServer(b)
                            
                            pendingPlacements[cand.key] = tick()
                            placedCount = placedCount + 1
                            
                            -- Instant visual feedback: Remove ghost ONLY if Multi mode
                            -- For Single/Solo mode, we keep the ghost until the actual part is detected by collision loop
                            if Settings.MultiplyPlantBox and PreviewCache[cand.key] then
                                PreviewCache[cand.key]:Destroy()
                                PreviewCache[cand.key] = nil
                            end
                        end
                    end
                end
            end
            
            local delayTime = 0.28
            if Settings.SoloPatternPlantBoxes and not Settings.MultiplyPlantBox then
                delayTime = 0.05
            end
            task.wait(delayTime)
        end
        placeGridActive = false
    end)
end

local placeWalkingActive = false
-- startAutoPlaceUnderMeWalking function removed as requested

function startSoloPatternPlantBoxes()
    -- Redirect to unified placement logic
    startMultiplyPlantBox()
end

function clearPlantBoxPreviewVisuals()
    clearPlantBoxPreview()
end
end -- AsterPlaceGridPreview

do -- AsterCustomPlacement
local customPlacementPreviewCache = {}
local customPlacementGroundCache = {}
local customPlacementOccCache = {}
local customPlacementPending = {}
local customPlacementRayParams = nil
local customPlacementRayParamsAt = 0
local customPlacementPreviewActive = false
local customPlacementStartActive = false
local customPlacementTweenActive = false
local customPlacementLockedPreset = nil
local customPlacementFrozenAnchor = nil
local customPlacementTemplateCache = {}
local customPlacementPreviewAccum = 0
local customPlacementPreviewWasEnabled = false
local customPlacementLocationSpot1 = nil
local customPlacementLocationSpot2 = nil
local customPlacementFilledCells = nil
local customPlacementBoxRefY = nil
local customPlacementBoxBounds = nil
local customPlacementSelectConn = nil
local CUSTOM_PLACEMENT_PREVIEW_INTERVAL = 1 / 10
local CUSTOM_PLACEMENT_FIXED_ROT = CFrame.new()
local CUSTOM_PLACEMENT_DOCK_SNAP_MAX_DIST = 120

function clearCustomPlacementTemplateCache()
    table.clear(customPlacementTemplateCache)
end

function isShowPlacementPreviewEnabled()
    return Settings.ShowPlacementPreview == true or Settings.PreviewPlacement == true
end

function isPreviewPresetSaveEnabled()
    return Settings.PreviewPresetSave == true or Settings.LockPreviewPreset == true
end

function isPreviewSnapEnabled()
    return Settings.PreviewSnap == true
end

function normalizeDeployableKey(name)
    if type(name) ~= "string" then return "" end
    return string.lower((name:gsub("%s+", "")))
end

function normalizePlacementTypeName(name)
    if type(name) ~= "string" then return "" end
    name = name:match("^%s*(.-)%s*$") or ""
    if name == "" then return "" end
    local deployables = getPlacementDeployablesFolder()
    if not deployables then return name end
    if deployables:FindFirstChild(name) then return name end
    local nameKey = normalizeDeployableKey(name)
    for _, child in ipairs(deployables:GetChildren()) do
        if normalizeDeployableKey(child.Name) == nameKey then
            return child.Name
        end
    end
    return name
end

function parseSelectedPlacementTypes(raw)
    local types = {}
    local seen = {}
    if type(raw) ~= "string" or raw == "" then
        return types
    end
    for part in string.gmatch(raw, "([^,]+)") do
        local name = normalizePlacementTypeName(part)
        if name ~= "" and name ~= "None" then
            local key = normalizeDeployableKey(name)
            if not seen[key] then
                seen[key] = true
                table.insert(types, name)
            end
        end
    end
    return types
end

function getResolvedPlacementTypeNames()
    local raw = Settings.SelectedPlacementType
    if (type(raw) ~= "string" or raw == "") and Window and Window.ElementRegistry then
        local reg = Window.ElementRegistry["SelectPlacementType"]
        if reg and reg.GetValue then
            raw = reg:GetValue()
            if type(raw) == "string" and raw ~= "" then
                Settings.SelectedPlacementType = raw:match("^%s*(.-)%s*$") or ""
            end
        end
    end
    return parseSelectedPlacementTypes(raw)
end

function getResolvedPlacementTypeName()
    local types = getResolvedPlacementTypeNames()
    return types[1] or ""
end

function getPlacementTypesForCell(cell)
    local types = getResolvedPlacementTypeNames()
    if cell and cell.structureName and cell.structureName ~= "" then
        local ordered = { cell.structureName }
        for _, name in ipairs(types) do
            if name ~= cell.structureName then
                table.insert(ordered, name)
            end
        end
        return ordered
    end
    return types
end

function isPreviewCenterEnabled()
    return Settings.PreviewCenter == true
end

function getCustomPlacementOffsets()
    local offX = Settings.PlacementOffsetX
    local offY = Settings.PlacementOffsetY
    local offZ = Settings.PlacementOffsetZ
    if offX == nil then offX = 0 end
    if offY == nil then offY = 0 end
    if offZ == nil then offZ = 0 end
    if isPreviewPresetSaveEnabled() and customPlacementLockedPreset then
        offX = customPlacementLockedPreset.offsetX
        offZ = customPlacementLockedPreset.offsetZ
    end
    return offX, offY, offZ
end

function getCustomPlacementSpacings()
    local spacingX = Settings.PlacementSpacingX
    local spacingZ = Settings.PlacementSpacingZ
    if spacingX == nil then spacingX = 13 end
    if spacingZ == nil then spacingZ = 13 end
    if isPreviewPresetSaveEnabled() and customPlacementLockedPreset then
        spacingX = customPlacementLockedPreset.spacingX
        spacingZ = customPlacementLockedPreset.spacingZ
    end
    return spacingX, spacingZ
end

function snapAxisToSpacing(value, spacing)
    if spacing == nil or spacing <= 0 then
        return value
    end
    return math.round(value / spacing) * spacing
end

function findNearestPlacementStructure(structureName, referencePos)
    if not structureName or structureName == "" or structureName == "None" then return nil end
    if not referencePos then return nil end
    local deployables = getWorkspaceDeployables()
    if not deployables then return nil end
    local lowerName = normalizeDeployableKey(structureName)
    local nearest, nearestDistSq = nil, math.huge
    local refFlat = Vector3.new(referencePos.X, 0, referencePos.Z)
    for _, child in ipairs(deployables:GetChildren()) do
        if normalizeDeployableKey(child.Name) == lowerName then
            local pivot = child:GetPivot()
            local pos = pivot.Position
            local flat = Vector3.new(pos.X, 0, pos.Z)
            local distSq = (flat - refFlat).Magnitude ^ 2
            if distSq < nearestDistSq then
                nearestDistSq = distSq
                nearest = child
            end
        end
    end
    return nearest
end

function computeCustomPlacementFreeAnchorCFrame(hrp)
    local structureName = getResolvedPlacementTypeName()
    if not structureName or structureName == "" or structureName == "None" then return nil end
    if not hrp then return nil end

    local offX, offY, offZ = getCustomPlacementOffsets()
    return CFrame.new(hrp.Position + Vector3.new(offX, offY, offZ))
end

function computeCustomPlacementAnchorCFrame(hrp)
    if not isPreviewSnapEnabled() then
        return computeCustomPlacementFreeAnchorCFrame(hrp)
    end

    local structureName = getResolvedPlacementTypeName()
    if not structureName or structureName == "" or structureName == "None" then return nil end
    if not hrp then return nil end

    local offX, offY, offZ = getCustomPlacementOffsets()
    local nearest = findNearestPlacementStructure(structureName, hrp.Position)
    if nearest then
        local dockPos = nearest:GetPivot().Position
        local flatDist = (Vector3.new(dockPos.X, 0, dockPos.Z) - Vector3.new(hrp.Position.X, 0, hrp.Position.Z)).Magnitude
        if flatDist > CUSTOM_PLACEMENT_DOCK_SNAP_MAX_DIST then
            nearest = nil
        end
    end
    if nearest then
        return CFrame.new((nearest:GetPivot() * CFrame.new(offX, offY, offZ)).Position)
    end
    return computeCustomPlacementFreeAnchorCFrame(hrp)
end

function computeCustomPlacementPlayerAnchorCFrame(hrp)
    return computeCustomPlacementFreeAnchorCFrame(hrp)
end

function captureCustomPlacementPreset()
    customPlacementLockedPreset = {
        offsetX = Settings.PlacementOffsetX == nil and 0 or Settings.PlacementOffsetX,
        offsetZ = Settings.PlacementOffsetZ == nil and 0 or Settings.PlacementOffsetZ,
        spacingX = Settings.PlacementSpacingX == nil and 13 or Settings.PlacementSpacingX,
        spacingZ = Settings.PlacementSpacingZ == nil and 13 or Settings.PlacementSpacingZ,
    }
end

function clearCustomPlacementPreset()
    customPlacementLockedPreset = nil
end

function refreshCustomPlacementPresetSaveState()
    Settings.PreviewPresetSave = Settings.PreviewPresetSave == true
    Settings.LockPreviewPreset = Settings.PreviewPresetSave

    if Settings.PreviewPresetSave then
        captureCustomPlacementPreset()
    else
        clearCustomPlacementPreset()
    end

    if Settings.FillLocations and customPlacementLocationSpot1 and customPlacementLocationSpot2 then
        fillCustomPlacementLocations()
    end
end

function refreshCustomPlacementSnapState()
    Settings.PreviewSnap = Settings.PreviewSnap == true

    if isPreviewCenterEnabled() then
        refreshCustomPlacementCenterState()
    else
        clearCustomPlacementPreview()
        if isShowPlacementPreviewEnabled() then
            if not customPlacementPreviewActive then
                startCustomPlacementPreviewLoop()
            end
            updateCustomPlacementPreview()
        end
    end
end

function refreshCustomPlacementLockState()
    refreshCustomPlacementPresetSaveState()
    refreshCustomPlacementSnapState()
end

function refreshCustomPlacementCenterState()
    if isPreviewCenterEnabled() then
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        customPlacementFrozenAnchor = computeCustomPlacementAnchorCFrame(hrp)
        if not customPlacementFrozenAnchor and hrp then
            customPlacementFrozenAnchor = computeCustomPlacementPlayerAnchorCFrame(hrp)
        end
    else
        customPlacementFrozenAnchor = nil
    end
    clearCustomPlacementPreview()
    if isShowPlacementPreviewEnabled() then
        if not customPlacementPreviewActive then
            startCustomPlacementPreviewLoop()
        end
        updateCustomPlacementPreview()
    end
end

function getCustomPlacementBaseCFrame(hrp)
    if isPreviewCenterEnabled() and customPlacementFrozenAnchor then
        return customPlacementFrozenAnchor
    end
    return computeCustomPlacementAnchorCFrame(hrp)
end

local CustomPlacementPreviewContainer = asterEnsureWorldFolder("AsterCustomPlacementPreview")
local CustomPlacementLocationContainer = asterEnsureWorldFolder("AsterCustomPlacementLocations")

function clearCustomPlacementLocationVisuals()
    if CustomPlacementLocationContainer then
        CustomPlacementLocationContainer:ClearAllChildren()
    end
end

function createLocationMarker(name, position, color)
    local part = Instance.new("Part")
    part.Name = name
    part.Size = Vector3.new(1.5, 0.4, 1.5)
    part.Anchored = true
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
    part.CastShadow = false
    part.Material = Enum.Material.Neon
    part.Color = color
    part.Transparency = 0.2
    part.CFrame = CFrame.new(position + Vector3.new(0, 0.2, 0))
    part.Parent = CustomPlacementLocationContainer
    return part
end

function createLocationEdge(name, fromPos, toPos, color)
    local delta = toPos - fromPos
    local length = delta.Magnitude
    if length < 0.05 then return end
    local part = Instance.new("Part")
    part.Name = name
    part.Size = Vector3.new(0.35, 0.35, length)
    part.Anchored = true
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
    part.CastShadow = false
    part.Material = Enum.Material.Neon
    part.Color = color
    part.Transparency = 0.35
    part.CFrame = CFrame.new(fromPos, toPos) * CFrame.new(0, 0, -length * 0.5)
    part.Parent = CustomPlacementLocationContainer
    return part
end

function updateCustomPlacementBoxVisual()
    clearCustomPlacementLocationVisuals()
    if customPlacementLocationSpot1 and not customPlacementLocationSpot2 then
        createLocationMarker("PlacementSpot1", customPlacementLocationSpot1, Color3.fromRGB(80, 180, 255))
        return
    end
    if not customPlacementLocationSpot1 or not customPlacementLocationSpot2 then return end

    local spot1 = customPlacementLocationSpot1
    local spot2 = customPlacementLocationSpot2
    createLocationMarker("PlacementSpot1", spot1, Color3.fromRGB(80, 180, 255))
    createLocationMarker("PlacementSpot2", spot2, Color3.fromRGB(255, 190, 80))

    local minX = math.min(spot1.X, spot2.X)
    local maxX = math.max(spot1.X, spot2.X)
    local minZ = math.min(spot1.Z, spot2.Z)
    local maxZ = math.max(spot1.Z, spot2.Z)
    local y = (spot1.Y + spot2.Y) * 0.5 + 0.15
    local c1 = Vector3.new(minX, y, minZ)
    local c2 = Vector3.new(maxX, y, minZ)
    local c3 = Vector3.new(maxX, y, maxZ)
    local c4 = Vector3.new(minX, y, maxZ)
    local edgeColor = Settings.LockLocations and Color3.fromRGB(255, 90, 90)
        or (Settings.FillLocations and Color3.fromRGB(120, 255, 140) or Color3.fromRGB(170, 120, 255))
    createLocationEdge("PlacementEdge1", c1, c2, edgeColor)
    createLocationEdge("PlacementEdge2", c2, c3, edgeColor)
    createLocationEdge("PlacementEdge3", c3, c4, edgeColor)
    createLocationEdge("PlacementEdge4", c4, c1, edgeColor)
end

function getCustomPlacementBoxBounds()
    if not customPlacementLocationSpot1 or not customPlacementLocationSpot2 then return nil end
    local spot1 = customPlacementLocationSpot1
    local spot2 = customPlacementLocationSpot2
    return {
        minX = math.min(spot1.X, spot2.X),
        maxX = math.max(spot1.X, spot2.X),
        minZ = math.min(spot1.Z, spot2.Z),
        maxZ = math.max(spot1.Z, spot2.Z),
    }
end

function clearCustomPlacementLocationFill()
    customPlacementFilledCells = nil
    customPlacementBoxRefY = nil
    customPlacementBoxBounds = nil
    Settings.FillLocations = false
    if not Settings.LockLocations then
        clearCustomPlacementPreview()
    end
end

function clearCustomPlacementLocations(resetSpots)
    if resetSpots then
        customPlacementLocationSpot1 = nil
        customPlacementLocationSpot2 = nil
    end
    Settings.LockLocations = false
    clearCustomPlacementLocationFill()
    clearCustomPlacementLocationVisuals()
end

function getCustomPlacementFillGridPhases(bounds)
    -- Always anchor the fill grid to the selection box corners (never world/player grid).
    return bounds.minX, bounds.minZ
end

function isCustomPlacementCellOverlapsBounds(cell, cellType, bounds, spacingX, spacingZ)
    if not bounds or not cell then return true end
    cellType = cellType or cell.structureName or getResolvedPlacementTypeName()
    if not cellType or cellType == "" or cellType == "None" then return false end

    local sizeX, sizeZ, pivotToWest, pivotToNorth = getCustomPlacementFillMetrics(
        cellType, bounds, spacingX or 13, spacingZ or 13
    )
    local edgeMinX = cell.x + pivotToWest
    local edgeMaxX = edgeMinX + sizeX
    local edgeMinZ = cell.z + pivotToNorth
    local edgeMaxZ = edgeMinZ + sizeZ

    return edgeMaxX >= bounds.minX - 0.01
        and edgeMinX <= bounds.maxX + 0.01
        and edgeMaxZ >= bounds.minZ - 0.01
        and edgeMinZ <= bounds.maxZ + 0.01
end

function buildAxisFillCovering(minBound, maxBound, spacing, pivotToMin, structureSize, gridPhase)
    spacing = math.max(spacing, 0.01)
    structureSize = math.max(structureSize or spacing, 0.01)
    gridPhase = gridPhase or 0

    -- Overlap the box edges so corners/gaps get covered (okay to go slightly past the line).
    local pLow = minBound - pivotToMin - structureSize
    local pScanHigh = maxBound - pivotToMin + structureSize

    local scanStart = gridPhase + math.floor((pLow - spacing - gridPhase) / spacing) * spacing
    local scanEnd = gridPhase + math.ceil((pScanHigh - gridPhase) / spacing) * spacing

    local positions = {}
    local val = scanStart
    while val <= scanEnd + 0.01 do
        local edgeMin = val + pivotToMin
        local edgeMax = edgeMin + structureSize
        if edgeMax >= minBound - 0.01 and edgeMin <= maxBound + 0.01 then
            table.insert(positions, val)
        end
        val = val + spacing
    end

    if #positions == 0 then
        local fallback = gridPhase + math.floor((pLow - gridPhase) / spacing + 1e-6) * spacing
        local edgeMin = fallback + pivotToMin
        local edgeMax = edgeMin + structureSize
        if edgeMax >= minBound - 0.01 and edgeMin <= maxBound + 0.01 then
            table.insert(positions, fallback)
        end
    else
        -- Extend past the far edge until the box interior is covered.
        local last = positions[#positions]
        local lastCover = last + pivotToMin + structureSize
        while lastCover < maxBound - 0.01 do
            local extra = last + spacing
            local edgeMin = extra + pivotToMin
            local edgeMax = edgeMin + structureSize
            if edgeMax < minBound - 0.01 then
                break
            end
            table.insert(positions, extra)
            last = extra
            lastCover = edgeMax
        end

        -- Extend before the near edge for the same reason.
        local first = positions[1]
        local firstEdgeMin = first + pivotToMin
        while firstEdgeMin > minBound + 0.01 do
            local prev = first - spacing
            local edgeMin = prev + pivotToMin
            local edgeMax = edgeMin + structureSize
            if edgeMax < minBound - 0.01 then
                break
            end
            table.insert(positions, 1, prev)
            first = prev
            firstEdgeMin = edgeMin
        end
    end

    return positions
end

function fillCustomPlacementLocations()
    local bounds = getCustomPlacementBoxBounds()
    if not bounds then return false end

    if isPreviewPresetSaveEnabled() and not customPlacementLockedPreset then
        captureCustomPlacementPreset()
    end

    local spacingX, spacingZ = getCustomPlacementSpacings()
    if spacingX <= 0 then spacingX = 13 end
    if spacingZ <= 0 then spacingZ = 13 end

    customPlacementBoxRefY = (customPlacementLocationSpot1.Y + customPlacementLocationSpot2.Y) * 0.5
    customPlacementBoxBounds = bounds

    local structureName = getResolvedPlacementTypeName()
    if not structureName or structureName == "" or structureName == "None" then return false end

    local placementTypes = getResolvedPlacementTypeNames()
    if #placementTypes == 0 then return false end

    local sizeX, sizeZ, pivotToWest, pivotToNorth = getCustomPlacementFillMetrics(
        structureName, bounds, spacingX, spacingZ
    )

    local gridPhaseX, gridPhaseZ = getCustomPlacementFillGridPhases(bounds)

    local xPositions = buildAxisFillCovering(
        bounds.minX, bounds.maxX, spacingX, pivotToWest, sizeX, gridPhaseX
    )
    local zPositions = buildAxisFillCovering(
        bounds.minZ, bounds.maxZ, spacingZ, pivotToNorth, sizeZ, gridPhaseZ
    )

    local cells = {}
    local typeIndex = 0
    for _, x in ipairs(xPositions) do
        for _, z in ipairs(zPositions) do
            typeIndex = typeIndex + 1
            local key = string.format("%.2f,%.2f", x, z)
            local cellType = placementTypes[((typeIndex - 1) % #placementTypes) + 1]
            local cell = {
                x = x,
                z = z,
                key = key,
                rotCF = CUSTOM_PLACEMENT_FIXED_ROT,
                structureName = cellType,
            }
            if isCustomPlacementCellOverlapsBounds(cell, cellType, bounds, spacingX, spacingZ) then
                table.insert(cells, cell)
            end
        end
    end

    customPlacementFilledCells = cells
    Settings.FillLocations = #cells > 0
    updateCustomPlacementBoxVisual()
    if isShowPlacementPreviewEnabled() then
        updateCustomPlacementPreview()
    end
    return #cells > 0
end

function orderCustomPlacementCellsSerpentine(cells)
    if not cells or #cells <= 1 then
        return cells
    end

    local rowMap = {}
    local zKeys = {}
    local zValues = {}

    for _, cell in ipairs(cells) do
        local zKey = string.format("%.2f", cell.z)
        if not rowMap[zKey] then
            rowMap[zKey] = {}
            table.insert(zKeys, zKey)
            zValues[zKey] = cell.z
        end
        table.insert(rowMap[zKey], cell)
    end

    table.sort(zKeys, function(a, b)
        return zValues[a] < zValues[b]
    end)

    local ordered = {}
    for rowIndex, zKey in ipairs(zKeys) do
        local rowCells = rowMap[zKey]
        table.sort(rowCells, function(a, b)
            if rowIndex % 2 == 1 then
                return a.x < b.x
            end
            return a.x > b.x
        end)
        for _, cell in ipairs(rowCells) do
            table.insert(ordered, cell)
        end
    end
    return ordered
end

function getMousePlacementHit()
    local mouse = plr:GetMouse()
    if mouse and mouse.Hit then
        return mouse.Hit.Position
    end
    return nil
end

function onSelectPlacementLocationClick()
    if not Settings.SelectPlacementLocations or Settings.LockLocations then return end
    local hit = getMousePlacementHit()
    if not hit then return end

    if customPlacementLocationSpot1 and customPlacementLocationSpot2 then
        customPlacementLocationSpot1 = hit
        customPlacementLocationSpot2 = nil
        clearCustomPlacementLocationFill()
    elseif not customPlacementLocationSpot1 then
        customPlacementLocationSpot1 = hit
    else
        customPlacementLocationSpot2 = hit
    end

    updateCustomPlacementBoxVisual()
    if customPlacementLocationSpot1 and customPlacementLocationSpot2 and Settings.FillLocations then
        fillCustomPlacementLocations()
    end
end

function refreshSelectPlacementLocationsState()
    Settings.SelectPlacementLocations = Settings.SelectPlacementLocations == true
    if customPlacementSelectConn then
        customPlacementSelectConn:Disconnect()
        customPlacementSelectConn = nil
    end
    if Settings.SelectPlacementLocations and not Settings.LockLocations then
        local mouse = plr:GetMouse()
        customPlacementSelectConn = mouse.Button1Down:Connect(onSelectPlacementLocationClick)
    end
end

function clearPlacementLocations()
    Settings.FillLocations = false
    Settings.LockLocations = false
    Settings.StartPlacement = false
    Settings.TweenPlacement = false
    clearCustomPlacementLocations(true)

    local reg = Window and Window.ElementRegistry
    if reg then
        for _, key in ipairs({"FillLocations", "LockLocations", "StartPlacement", "TweenPlacement"}) do
            if reg[key] and reg[key].SetValue then
                reg[key].SetValue(false)
            end
        end
    end

    if isShowPlacementPreviewEnabled() then
        updateCustomPlacementPreview()
    end
end

function refreshFillLocationsState()
    Settings.FillLocations = Settings.FillLocations == true
    if Settings.LockLocations then return end
    if Settings.FillLocations then
        if not fillCustomPlacementLocations() then
            Settings.FillLocations = false
        else
            Settings.ShowPlacementPreview = true
            if not customPlacementPreviewActive then
                startCustomPlacementPreviewLoop()
            end
        end
    else
        clearCustomPlacementLocationFill()
        updateCustomPlacementBoxVisual()
        if isShowPlacementPreviewEnabled() then
            updateCustomPlacementPreview()
        end
    end
end

function refreshLockLocationsState()
    Settings.LockLocations = Settings.LockLocations == true
    if Settings.LockLocations then
        if not customPlacementLocationSpot1 or not customPlacementLocationSpot2 then
            Settings.LockLocations = false
            return
        end
        if not fillCustomPlacementLocations() then
            Settings.LockLocations = false
            return
        end
        Settings.FillLocations = true
        Settings.SelectPlacementLocations = false
        refreshSelectPlacementLocationsState()
    end
    updateCustomPlacementBoxVisual()
    if isShowPlacementPreviewEnabled() then
        if not customPlacementPreviewActive then
            startCustomPlacementPreviewLoop()
        end
        updateCustomPlacementPreview()
    end
end

function isCustomPlacementLocationsActive()
    return Settings.LockLocations and customPlacementFilledCells and #customPlacementFilledCells > 0
end

function getPlacementDeployablesFolder()
    return game:GetService("ReplicatedStorage"):FindFirstChild("Deployables")
end

function getDeployableTypeList()
    local list = {}
    local seen = {}
    local deployables = getPlacementDeployablesFolder()
    if deployables then
        for _, child in ipairs(deployables:GetChildren()) do
            local name = child.Name
            if not seen[name] then
                seen[name] = true
                table.insert(list, name)
            end
        end
    end
    table.sort(list)
    if #list == 0 then
        table.insert(list, "None")
    end
    return list
end

function findDeployableChildByName(folder, name)
    if not folder or not name or name == "" then return nil end
    local child = folder:FindFirstChild(name)
    if child then return child end
    local nameKey = normalizeDeployableKey(name)
    for _, c in ipairs(folder:GetChildren()) do
        if normalizeDeployableKey(c.Name) == nameKey then
            return c
        end
    end
    return nil
end

function extractDeployableTemplate(instance)
    if not instance then return nil end
    if instance:IsA("Model") or instance:IsA("BasePart") then
        return instance
    end
    return instance:FindFirstChildWhichIsA("Model", true) or instance:FindFirstChildWhichIsA("BasePart", true)
end

function getCustomPlacementTemplate(name)
    if not name or name == "" or name == "None" then return nil end
    local resolvedName = normalizePlacementTypeName(name)
    local cacheKey = normalizeDeployableKey(resolvedName)
    if customPlacementTemplateCache[cacheKey] ~= nil then
        return customPlacementTemplateCache[cacheKey] or nil
    end

    local template = nil
    local deployables = getPlacementDeployablesFolder()
    if deployables then
        template = extractDeployableTemplate(findDeployableChildByName(deployables, resolvedName))
    end

    if not template then
        local workspaceDeployables = getWorkspaceDeployables()
        if workspaceDeployables then
            template = extractDeployableTemplate(findDeployableChildByName(workspaceDeployables, resolvedName))
        end
    end

    if not template then
        local rs = game:GetService("ReplicatedStorage")
        for _, fname in ipairs({"Deployables", "PlaceStructures", "Structures", "Models"}) do
            local folder = rs:FindFirstChild(fname)
            if folder then
                template = extractDeployableTemplate(findDeployableChildByName(folder, resolvedName))
                if template then break end
            end
        end
    end

    customPlacementTemplateCache[cacheKey] = template or false
    return template
end

function getCustomPlacementFillMetrics(structureName, bounds, spacingX, spacingZ)
    local sizeX = spacingX
    local sizeZ = spacingZ
    local pivotToWest = -sizeX * 0.5
    local pivotToNorth = -sizeZ * 0.5

    local template = getCustomPlacementTemplate(structureName)
    if template then
        local pivotCF = template:IsA("Model") and template:GetPivot() or template.CFrame
        local collision = template:FindFirstChild("CollisionBox", true)
            or template:FindFirstChild("collisionBox", true)
            or template:FindFirstChild("RedPart", true)
        if collision and collision:IsA("BasePart") then
            sizeX = collision.Size.X
            sizeZ = collision.Size.Z
            local rel = pivotCF:ToObjectSpace(collision.CFrame)
            pivotToWest = rel.X - collision.Size.X * 0.5
            pivotToNorth = rel.Z - collision.Size.Z * 0.5
        elseif template:IsA("Model") then
            local bboxCF, bboxSize = template:GetBoundingBox()
            sizeX = bboxSize.X
            sizeZ = bboxSize.Z
            local rel = pivotCF:ToObjectSpace(bboxCF)
            pivotToWest = rel.X - bboxSize.X * 0.5
            pivotToNorth = rel.Z - bboxSize.Z * 0.5
        elseif template:IsA("BasePart") then
            sizeX = template.Size.X
            sizeZ = template.Size.Z
            pivotToWest = -template.Size.X * 0.5
            pivotToNorth = -template.Size.Z * 0.5
        end
    end

    return sizeX, sizeZ, pivotToWest, pivotToNorth
end

function isShowCollisionPartEnabled()
    return Settings.ShowCollisionPart == true
end

function isPreviewCollisionPart(part)
    if not part or not part:IsA("BasePart") then return false end
    local n = string.lower(part.Name)
    if n == "collisionbox" or n == "collision" or n == "hitbox" or n == "redpart" or n == "default" then
        return true
    end
    if n:find("collision", 1, true) or n:find("hitbox", 1, true) or n:find("place", 1, true) then
        return true
    end
    return false
end

function setupCustomPreviewVisuals(model)
    local heightOffset = 0.5
    local showCollision = isShowCollisionPartEnabled()
    local function applyVisuals(obj)
        if obj:IsA("BasePart") then
            local isCollision = isPreviewCollisionPart(obj)
            if showCollision and isCollision then
                obj.Transparency = 0.15
                obj.Color = Color3.fromRGB(255, 70, 70)
                obj.Material = Enum.Material.Neon
            elseif showCollision then
                obj.Transparency = 0.72
            else
                obj.Transparency = 0.55
            end
            obj.CanCollide = false
            obj.CastShadow = false
            pcall(function()
                obj.CanQuery = false
                obj.CanTouch = false
            end)
        end
        for _, child in ipairs(obj:GetChildren()) do
            applyVisuals(child)
        end
    end
    applyVisuals(model)
    if model:IsA("Model") then
        local _, size = model:GetBoundingBox()
        heightOffset = size.Y / 2
        if not model.PrimaryPart then
            for _, desc in ipairs(model:GetDescendants()) do
                if desc:IsA("BasePart") and not isPreviewCollisionPart(desc) then
                    model.PrimaryPart = desc
                    break
                end
            end
            if not model.PrimaryPart then
                model.PrimaryPart = model:FindFirstChildWhichIsA("BasePart", true)
            end
        end
        local pp = model.PrimaryPart
        if pp then
            pp.Anchored = true
            for _, desc in ipairs(model:GetDescendants()) do
                if desc:IsA("BasePart") and desc ~= pp then
                    desc.Anchored = false
                    local w = Instance.new("WeldConstraint")
                    w.Part0 = pp
                    w.Part1 = desc
                    w.Parent = pp
                end
            end
        end
    elseif model:IsA("BasePart") then
        model.Anchored = true
        heightOffset = model.Size.Y / 2
    end
    model:SetAttribute("PreviewHeightOffset", heightOffset)
    return heightOffset
end

function refreshCustomPlacementCollisionVisuals()
    clearCustomPlacementPreview()
    updateCustomPlacementPreview()
end

function getCustomPlacementPreviewModel(name)
    local template = getCustomPlacementTemplate(name)
    local model
    if template then
        model = template:Clone()
    else
        model = Instance.new("Part")
        model.Size = Vector3.new(8, 1, 8)
        model.Color = Color3.fromRGB(120, 180, 255)
        model.Material = Enum.Material.Neon
    end
    model.Name = "PreviewPlacement"
    setupCustomPreviewVisuals(model)
    return model
end

function getCustomPlacementRayParams()
    local now = tick()
    if customPlacementRayParams and (now - customPlacementRayParamsAt) < 2 then
        return customPlacementRayParams
    end
    local rayParams = RaycastParams.new()
    local ignoreList = {}
    if plr.Character then table.insert(ignoreList, plr.Character) end
    if PreviewContainer then table.insert(ignoreList, PreviewContainer) end
    if CustomPlacementPreviewContainer then table.insert(ignoreList, CustomPlacementPreviewContainer) end
    for _, folderName in ipairs({"Resources", "Rubble", "Critters", "Items", "Players", "MeteorParts"}) do
        local f = workspace:FindFirstChild(folderName)
        if f then table.insert(ignoreList, f) end
    end
    rayParams.FilterDescendantsInstances = ignoreList
    rayParams.FilterType = Enum.RaycastFilterType.Exclude
    rayParams.IgnoreWater = false
    customPlacementRayParams = rayParams
    customPlacementRayParamsAt = now
    return rayParams
end

function customPlacementOccPartSkip(p)
    if not p then return true end
    if plr.Character and p:IsDescendantOf(plr.Character) then return true end
    if CustomPlacementPreviewContainer and p:IsDescendantOf(CustomPlacementPreviewContainer) then return true end
    return false
end

function getCustomPlacementGroundY(x, z, refY, currentTime, useBoxSurface)
    local key = string.format("%.2f,%.2f", x, z)
    local cached = customPlacementGroundCache[key]
    if cached and (currentTime - cached.t < 2.5) then
        return cached.y
    end

    local rayParams = getCustomPlacementRayParams()
    local cellY = refY or 0
    local rayStartY, rayDepth

    if useBoxSurface then
        -- Stay on the selection box plane; short ray only for small local bumps.
        rayStartY = cellY + 8
        rayDepth = -20
    else
        rayStartY = cellY + 40
        rayDepth = -500
        cellY = cellY - 3
    end

    local hit = workspace:Raycast(Vector3.new(x, rayStartY, z), Vector3.new(0, rayDepth, 0), rayParams)
    if hit then
        if useBoxSurface then
            if hit.Position.Y >= (refY or 0) - 5 and hit.Position.Y <= (refY or 0) + 8 then
                cellY = hit.Position.Y
            end
        else
            cellY = hit.Position.Y
        end
    end

    customPlacementGroundCache[key] = {y = cellY, t = currentTime}
    return cellY
end

function isCustomPlacementOccupied(x, z, y, rotCF, structureName, currentTime)
    local key = string.format("%.2f,%.2f", x, z)
    local occCached = customPlacementOccCache[key]
    if occCached and (currentTime - occCached.t < 0.5) then
        return occCached.val
    end
    local occupied = false
    local checkCFrame = CFrame.new(Vector3.new(x, y + 2, z)) * rotCF
    local parts = workspace:GetPartBoundsInBox(checkCFrame, Vector3.new(6, 8, 6))
    for _, p in ipairs(parts) do
        if customPlacementOccPartSkip(p) then continue end
        local model = p:FindFirstAncestorOfClass("Model")
        if model and normalizeDeployableKey(model.Name) == normalizeDeployableKey(structureName) then
            local pPos = model:GetPivot().Position
            local dist = math.sqrt((pPos.X - x)^2 + (pPos.Z - z)^2)
            if dist < 2.5 then
                occupied = true
                break
            end
        end
    end
    customPlacementOccCache[key] = {val = occupied, t = currentTime}
    return occupied
end

function parsePlacementAmountInput(val, fallback)
    fallback = math.max(1, math.floor(tonumber(fallback) or 3))
    if val == nil or val == "" then return fallback end
    if type(val) == "number" then
        return math.max(1, math.floor(val))
    end
    local text = tostring(val):gsub("%s+", "")
    local n = tonumber(text:match("^(%d+)")) or tonumber(text)
    return math.max(1, math.floor(n or fallback))
end

function getCustomPlacementAxisAmounts()
    local legacySide = math.max(1, math.ceil(math.sqrt(tonumber(Settings.PlacementAmount) or 9)))
    local amountX = parsePlacementAmountInput(Settings.PlacementAmountX, Settings.PlacementAmountX or legacySide)
    local amountY = parsePlacementAmountInput(Settings.PlacementAmountY, Settings.PlacementAmountY or legacySide)
    return amountX, amountY
end

local applyingPlacementAxisAmount = false

function applyPlacementAxisAmount(axis, text)
    if applyingPlacementAxisAmount then return end
    applyingPlacementAxisAmount = true
    local textClean = tostring(text or ""):gsub("%s+", "")
    if textClean:find("/") then
        local left, right = textClean:match("^(%d+)/(%d+)$")
        if left and right then
            Settings.PlacementAmountX = math.max(1, math.floor(tonumber(left) or 3))
            Settings.PlacementAmountY = math.max(1, math.floor(tonumber(right) or 3))
        end
    else
        local n = parsePlacementAmountInput(textClean, axis == "X" and Settings.PlacementAmountX or Settings.PlacementAmountY)
        if axis == "X" then
            Settings.PlacementAmountX = n
        else
            Settings.PlacementAmountY = n
        end
    end

    local amountX, amountY = getCustomPlacementAxisAmounts()
    Settings.PlacementAmount = amountX * amountY

    local xReg = Window.ElementRegistry["X Amount"]
    local yReg = Window.ElementRegistry["Y Amount"]
    if xReg and xReg.SetValue then xReg.SetValue(tostring(amountX)) end
    if yReg and yReg.SetValue then yReg.SetValue(tostring(amountY)) end

    applyingPlacementAxisAmount = false
    updateCustomPlacementPreview()
end

function buildCustomPlacementCellsFromAnchor(hrp, baseGridCFrame)
    if not baseGridCFrame then return {}, nil end
    local spacingX, spacingZ = getCustomPlacementSpacings()
    local amountX, amountY = getCustomPlacementAxisAmounts()
    Settings.PlacementAmount = amountX * amountY
    local anchorPos = baseGridCFrame.Position

    local offsets = {}
    for r = 0, amountY - 1 do
        for c = 0, amountX - 1 do
            table.insert(offsets, {r = r, c = c})
        end
    end

    local cells = {}
    for _, off in ipairs(offsets) do
        local worldTarget = anchorPos + Vector3.new(off.c * spacingX, 0, off.r * spacingZ)
        local key = string.format("%.2f,%.2f", worldTarget.X, worldTarget.Z)
        table.insert(cells, {
            x = worldTarget.X,
            z = worldTarget.Z,
            key = key,
            rotCF = CUSTOM_PLACEMENT_FIXED_ROT,
        })
    end
    return cells, baseGridCFrame
end

function buildCustomPlacementCells(hrp)
    if Settings.LockLocations then
        if customPlacementFilledCells and #customPlacementFilledCells > 0 then
            local refY = customPlacementBoxRefY
            if refY == nil and hrp then
                refY = hrp.Position.Y
            end
            refY = refY or 0
            local anchorCF = CFrame.new(customPlacementFilledCells[1].x, refY, customPlacementFilledCells[1].z)
            return customPlacementFilledCells, anchorCF
        end
        return {}, nil
    end
    return buildCustomPlacementCellsFromAnchor(hrp, getCustomPlacementBaseCFrame(hrp))
end

function renderCustomPlacementCellsList(cells, refY, structureName, currentTime, fillOptions)
    if not cells or #cells == 0 then return 0 end

    fillOptions = fillOptions or {}
    local useBoxSurface = fillOptions.useBoxSurface == true

    local activeKeys = {}
    local partsToMove = {}
    local cframesToMove = {}
    local visibleCount = 0

    for _, cell in ipairs(cells) do
        local cellType = cell.structureName or structureName
        if not cellType or cellType == "" or cellType == "None" then continue end

        activeKeys[cell.key] = true
        local cellY = getCustomPlacementGroundY(cell.x, cell.z, refY, currentTime, useBoxSurface)
        if isCustomPlacementOccupied(cell.x, cell.z, cellY, cell.rotCF, cellType, currentTime) then
            if customPlacementPreviewCache[cell.key] then
                customPlacementPreviewCache[cell.key]:Destroy()
                customPlacementPreviewCache[cell.key] = nil
            end
            continue
        end

        local model = customPlacementPreviewCache[cell.key]
        if model and model:GetAttribute("PreviewStructureName") ~= cellType then
            model:Destroy()
            model = nil
            customPlacementPreviewCache[cell.key] = nil
        end
        if not model or not model.Parent then
            model = getCustomPlacementPreviewModel(cellType)
            model:SetAttribute("PreviewStructureName", cellType)
            model.Parent = CustomPlacementPreviewContainer
            customPlacementPreviewCache[cell.key] = model
        end

        local heightOffset = model:GetAttribute("PreviewHeightOffset") or 0.5
        local targetCFrame = CFrame.new(Vector3.new(cell.x, cellY + heightOffset, cell.z)) * cell.rotCF
        local movePart = model:IsA("Model") and (model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart", true))
            or (model:IsA("BasePart") and model)
        if movePart then
            table.insert(partsToMove, movePart)
            table.insert(cframesToMove, targetCFrame)
            visibleCount = visibleCount + 1
        elseif model:IsA("Model") then
            model:PivotTo(targetCFrame)
            visibleCount = visibleCount + 1
        end
    end

    if #partsToMove > 0 then
        pcall(function()
            workspace:BulkMoveTo(partsToMove, cframesToMove)
        end)
    end

    for key, model in pairs(customPlacementPreviewCache) do
        if not activeKeys[key] then
            model:Destroy()
            customPlacementPreviewCache[key] = nil
            customPlacementGroundCache[key] = nil
            customPlacementOccCache[key] = nil
        end
    end

    return visibleCount
end

function renderCustomPlacementPreviewPass(hrp, baseGridCFrame, structureName, currentTime)
    local cells, resolvedBase = buildCustomPlacementCellsFromAnchor(hrp, baseGridCFrame)
    if not resolvedBase then return 0 end
    return renderCustomPlacementCellsList(cells, resolvedBase.Position.Y, structureName, currentTime)
end

function clearCustomPlacementPreview()
    for _, model in pairs(customPlacementPreviewCache) do
        if model then model:Destroy() end
    end
    table.clear(customPlacementPreviewCache)
    table.clear(customPlacementGroundCache)
    table.clear(customPlacementOccCache)
    if CustomPlacementPreviewContainer then
        CustomPlacementPreviewContainer:ClearAllChildren()
    end
end

function updateCustomPlacementPreview()
    if not isShowPlacementPreviewEnabled() then
        clearCustomPlacementPreview()
        return
    end

    local structureName = getResolvedPlacementTypeName()
    if not structureName or structureName == "" or structureName == "None" then
        clearCustomPlacementPreview()
        return
    end

    local currentTime = tick()
    if (Settings.FillLocations or Settings.LockLocations) and customPlacementFilledCells and #customPlacementFilledCells > 0 then
        local refY = customPlacementBoxRefY
        if refY == nil then
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            refY = hrp and hrp.Position.Y or 0
        end
        renderCustomPlacementCellsList(customPlacementFilledCells, refY, structureName, currentTime, {
            useBoxSurface = true,
            bounds = customPlacementBoxBounds,
            spacingX = Settings.PlacementSpacingX,
            spacingZ = Settings.PlacementSpacingZ,
        })
        return
    end

    -- While defining or filling a box, do not show the player-follow grid away from it.
    if Settings.SelectPlacementLocations or Settings.FillLocations or Settings.LockLocations then
        clearCustomPlacementPreview()
        return
    end

    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local baseGridCFrame = getCustomPlacementBaseCFrame(hrp)
    if not baseGridCFrame then
        clearCustomPlacementPreview()
        return
    end

    local visibleCount = renderCustomPlacementPreviewPass(hrp, baseGridCFrame, structureName, currentTime)
    if visibleCount == 0 and not isPreviewCenterEnabled() and not Settings.LockLocations then
        clearCustomPlacementPreview()
        local playerAnchor = computeCustomPlacementPlayerAnchorCFrame(hrp)
        if playerAnchor then
            renderCustomPlacementPreviewPass(hrp, playerAnchor, structureName, currentTime)
        end
    end
end

function canUseCustomPlacementModes()
    if Settings.FillLocations and not Settings.LockLocations then
        return false
    end
    if Settings.LockLocations then
        return customPlacementFilledCells ~= nil and #customPlacementFilledCells > 0
    end
    return true
end

function fireCustomPlacementPacket(structureName, targetCFrame)
    if not ByteNetReliable or not structureName or structureName == "" or structureName == "None" then return false end
    if not targetCFrame then return false end
    local packetId = getPacketId("PlaceStructure")
    if not packetId then return false end
    local nameLen = #structureName
    local b = buffer.create(4 + nameLen + 18)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, packetId)
    buffer.writeu16(b, 2, nameLen)
    for i = 1, nameLen do buffer.writeu8(b, 3 + i, string.byte(structureName, i)) end
    write18ByteCFrame(b, 4 + nameLen, targetCFrame)
    ByteNetReliable:FireServer(b)
    return true
end

function applyPlacementTypeSpacing(placementType)
    local types = getResolvedPlacementTypeNames()
    if placementType and placementType ~= "" then
        types = { placementType }
    end
    local hasDock = false
    for _, name in ipairs(types) do
        if string.lower(name) == "dock" then
            hasDock = true
            break
        end
    end
    if not hasDock then return end
    if Settings.PreviewPresetSave then return end
    Settings.PlacementSpacingX = 13
    Settings.PlacementSpacingZ = 32
    Settings.PlacementSpeed = 16
    local reg = Window and Window.ElementRegistry
    if reg then
        if reg["Spacing X"] and reg["Spacing X"].SetValue then
            reg["Spacing X"].SetValue(13)
        end
        if reg["Spacing Z"] and reg["Spacing Z"].SetValue then
            reg["Spacing Z"].SetValue(32)
        end
        if reg["PlacementSpeed"] and reg["PlacementSpeed"].SetValue then
            reg["PlacementSpeed"].SetValue(16)
        end
    end
end

function refreshPlacementTypeDropdown()
    applyPlacementTypeSpacing(getResolvedPlacementTypeName())
    updateCustomPlacementPreview()
end

function startCustomPlacementPreviewLoop()
    if customPlacementPreviewActive then return end
    customPlacementPreviewActive = true
    customPlacementPreviewAccum = 0
    customPlacementPreviewWasEnabled = true
    registerFrameUpdate("customPlacementPreview", function(dt)
        if not isShowPlacementPreviewEnabled() then
            if customPlacementPreviewWasEnabled then
                clearCustomPlacementPreview()
                customPlacementPreviewWasEnabled = false
            end
            customPlacementPreviewAccum = 0
            return
        end
        customPlacementPreviewWasEnabled = true
        customPlacementPreviewAccum = customPlacementPreviewAccum + dt
        if customPlacementPreviewAccum >= CUSTOM_PLACEMENT_PREVIEW_INTERVAL then
            customPlacementPreviewAccum = 0
            updateCustomPlacementPreview()
        end
    end)
    ensureMasterFrameLoop()
    updateCustomPlacementPreview()
end

function stopCustomPlacementPreviewLoop()
    if not customPlacementPreviewActive then return end
    customPlacementPreviewActive = false
    unregisterFrameUpdate("customPlacementPreview")
    customPlacementPreviewAccum = 0
    customPlacementPreviewWasEnabled = false
    clearCustomPlacementPreview()
end

function getPlacementSpeed()
    local speed = Settings.PlacementSpeed
    if speed == nil then speed = 16 end
    return math.max(speed, 0)
end

function tryPlaceNextCustomCell(hrp, structureName, now)
    for key, time in pairs(customPlacementPending) do
        if now - time > 1.0 then customPlacementPending[key] = nil end
    end

    local cells, baseGridCFrame = buildCustomPlacementCells(hrp)
    if not baseGridCFrame then return false end
    local useBoxSurface = Settings.LockLocations and customPlacementBoxRefY ~= nil
    local refY = useBoxSurface and customPlacementBoxRefY or baseGridCFrame.Position.Y
    for _, cell in ipairs(cells) do
        if customPlacementPending[cell.key] then continue end
        local typesToTry = getPlacementTypesForCell(cell)
        if #typesToTry == 0 and structureName and structureName ~= "" then
            typesToTry = { structureName }
        end

        for _, cellType in ipairs(typesToTry) do
            local cellY = getCustomPlacementGroundY(cell.x, cell.z, refY, now, useBoxSurface)
            if isCustomPlacementOccupied(cell.x, cell.z, cellY, cell.rotCF, cellType, now) then continue end

            local pos = Vector3.new(cell.x, cellY, cell.z)
            local targetCFrame = CFrame.new(pos) * cell.rotCF
            if fireCustomPlacementPacket(cellType, targetCFrame) then
                cell.structureName = cellType
                customPlacementPending[cell.key] = tick()
                if customPlacementPreviewCache[cell.key] then
                    customPlacementPreviewCache[cell.key]:Destroy()
                    customPlacementPreviewCache[cell.key] = nil
                end
                return true, cell, pos
            end
        end
    end
    return false
end

function findCustomPlacementCollisionPart(template)
    if not template then return nil end
    for _, name in ipairs({"CollisionBox", "collisionBox", "RedPart", "Hitbox", "default"}) do
        local part = template:FindFirstChild(name, true)
        if part and part:IsA("BasePart") then
            return part
        end
    end
    for _, desc in ipairs(template:GetDescendants()) do
        if desc:IsA("BasePart") and isPreviewCollisionPart(desc) then
            return desc
        end
    end
    return nil
end

function getCustomPlacementCollisionTopY(structureName, cellX, cellY, cellZ, rotCF)
    local clearance = 2.5
    local template = getCustomPlacementTemplate(structureName)
    if not template then
        return cellY + clearance + 3
    end

    local placeCF = CFrame.new(cellX, cellY, cellZ) * rotCF
    local collisionPart = findCustomPlacementCollisionPart(template)
    if collisionPart then
        local templateCF = template:IsA("Model") and template:GetPivot() or template.CFrame
        local relCF = templateCF:ToObjectSpace(collisionPart.CFrame)
        local topCF = placeCF * relCF * CFrame.new(0, collisionPart.Size.Y * 0.5, 0)
        return topCF.Position.Y + clearance
    end

    if template:IsA("Model") then
        local _, size = template:GetBoundingBox()
        return cellY + size.Y + clearance
    elseif template:IsA("BasePart") then
        return cellY + template.Size.Y + clearance
    end
    return cellY + clearance + 3
end

function waitUntilNearPlacement(hrp, hum, targetVec, speed, maxDist, timeout)
    local start = tick()
    while tick() - start < timeout do
        if not hrp or not hrp.Parent then return false end
        if not Settings.TweenPlacement then return false end
        if isTweening then
            noclip()
            if alignPosition and alignAttachment1 then
                alignPosition.MaxVelocity = getRandomizedSpeed(speed)
                alignAttachment1.WorldPosition = Vector3.new(targetVec.X, targetVec.Y, targetVec.Z)
            end
        end
        local flat = Vector3.new(targetVec.X - hrp.Position.X, 0, targetVec.Z - hrp.Position.Z)
        if flat.Magnitude <= maxDist then
            return true
        end
        task.wait(0.05)
    end
    return false
end

function tryTweenPlaceNextCustomCell(hrp, hum, structureName, now)
    for key, time in pairs(customPlacementPending) do
        if now - time > 1.0 then customPlacementPending[key] = nil end
    end

    local cells, baseGridCFrame = buildCustomPlacementCells(hrp)
    if not baseGridCFrame or not cells or #cells == 0 then return false end
    if Settings.LockLocations and customPlacementFilledCells and #customPlacementFilledCells > 0 then
        cells = orderCustomPlacementCellsSerpentine(cells)
    end
    local useBoxSurface = Settings.LockLocations and customPlacementBoxRefY ~= nil
    local refY = useBoxSurface and customPlacementBoxRefY or baseGridCFrame.Position.Y
    local speed = getPlacementSpeed()

    for _, cell in ipairs(cells) do
        if not Settings.TweenPlacement then return false end
        if customPlacementPending[cell.key] then continue end

        local typesToTry = getPlacementTypesForCell(cell)
        if #typesToTry == 0 and structureName and structureName ~= "" then
            typesToTry = { structureName }
        end

        for _, cellType in ipairs(typesToTry) do
            local cellY = getCustomPlacementGroundY(cell.x, cell.z, refY, now, useBoxSurface)
            if isCustomPlacementOccupied(cell.x, cell.z, cellY, cell.rotCF, cellType, now) then continue end

            local pos = Vector3.new(cell.x, cellY, cell.z)
            local targetCFrame = CFrame.new(pos) * cell.rotCF
            local tweenY = getCustomPlacementCollisionTopY(cellType, cell.x, cellY, cell.z, cell.rotCF)
            local tweenTarget = Vector3.new(cell.x, tweenY, cell.z)
            tweenToWaypoint(hrp, hum, tweenTarget, getRandomizedSpeed(speed))
            noclip()

            if waitUntilNearPlacement(hrp, hum, tweenTarget, speed, 4, 10) then
                stopAutoPlacementMovement(hrp, hum)
                if fireCustomPlacementPacket(cellType, targetCFrame) then
                    cell.structureName = cellType
                    customPlacementPending[cell.key] = tick()
                    if customPlacementPreviewCache[cell.key] then
                        customPlacementPreviewCache[cell.key]:Destroy()
                        customPlacementPreviewCache[cell.key] = nil
                    end
                    return true
                end
            else
                stopAutoPlacementMovement(hrp, hum)
            end
        end
    end
    return false
end

function startStartCustomPlacement()
    if customPlacementStartActive then return end
    customPlacementStartActive = true
    table.clear(customPlacementPending)

    task.spawn(function()
        while Settings.StartPlacement do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not hrp then
                task.wait(0.1)
                continue
            end

            local structureName = getResolvedPlacementTypeName()
            if not structureName or structureName == "" or structureName == "None" then
                task.wait(0.25)
                continue
            end

            local placed = tryPlaceNextCustomCell(hrp, structureName, tick())
            task.wait(placed and 0.35 or 0.15)
        end
        customPlacementStartActive = false
        table.clear(customPlacementPending)
    end)
end

function startTweenCustomPlacement()
    if customPlacementTweenActive then return end
    customPlacementTweenActive = true
    table.clear(customPlacementPending)

    task.spawn(function()
        while Settings.TweenPlacement do
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChild("Humanoid")
            if not hrp or not hum then
                task.wait(0.1)
                continue
            end

            local structureName = getResolvedPlacementTypeName()
            if not structureName or structureName == "" or structureName == "None" then
                task.wait(0.25)
                continue
            end

            local placed = tryTweenPlaceNextCustomCell(hrp, hum, structureName, tick())
            task.wait(placed and 0.35 or 0.15)
        end

        local char = plr.Character
        stopAutoPlacementMovement(
            char and char:FindFirstChild("HumanoidRootPart"),
            char and char:FindFirstChild("Humanoid")
        )
        customPlacementTweenActive = false
        table.clear(customPlacementPending)
    end)
end

function startAutoStartCustomPlacement()
    Settings.TweenPlacement = true
    startTweenCustomPlacement()
end

task.defer(function()
    for _ = 1, 20 do
        if getPlacementDeployablesFolder() then break end
        task.wait(0.5)
    end
    refreshPlacementTypeDropdown()
end)
end -- AsterCustomPlacement

do -- AsterRebirthEatCap
rebirthActive = false
function startAutoRebirth()
    if rebirthActive then return end
    rebirthActive = true
    task.spawn(function()
        local player = game.Players.LocalPlayer
        local topbar = player:WaitForChild("PlayerGui"):WaitForChild("Topbar", 10)
        local levelLabel = topbar and topbar.Topbar.Right.Level.Level
        local lastAttempt = 0
        local attemptCooldown = 10
        local function processRebirth()
            if not Settings.AutoRebirthEnabled or not levelLabel then return end
            if (tick() - lastAttempt) < attemptCooldown then return end
            local rawText = levelLabel.Text
            local levelNumber = tonumber(rawText:match("%d+"))
            local targetLevel = Settings.RebirthLevel or 100
            if levelNumber and levelNumber >= targetLevel then
                lastAttempt = tick()
                -- pcall(function() performRebirth() end) -- OLD LOGIC
                
                -- PACKET LOGIC (Rebirth via static PACKET_IDS)
                if ByteNetReliable then
                     local b = buffer.create(2)
                     buffer.writeu8(b, 0, 0)
                     buffer.writeu8(b, 1, getPacketId("Rebirth"))
                     ByteNetReliable:FireServer(b)
                end
                
                task.wait(5)
            end
        end
        local connection = levelLabel:GetPropertyChangedSignal("Text"):Connect(processRebirth)
        while Settings.AutoRebirthEnabled do
            pcall(processRebirth)
            task.wait(2)
        end
        if connection then connection:Disconnect() end
        rebirthActive = false
    end)
end
end

do
respawnActive = false
function startAutoRespawn()
    if respawnActive then return end
    respawnActive = true
    local spawnMenuPos = Vector3.new(-1686.31201, -3, -2534.19409)
    local detectionRange = 5
    local lastAttempt = 0
    local attemptCooldown = 5
    task.spawn(function()
        while Settings.AutoRespawnEnabled do
            pcall(function()
                local char = plr.Character
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if root then
                    local distance = (root.Position - spawnMenuPos).Magnitude
                    if distance <= detectionRange and (tick() - lastAttempt) > attemptCooldown then
                        lastAttempt = tick()
                        task.wait(2)
                        pcall(function()
                            if ByteNetReliable then
                                local b = buffer.create(4)
                                buffer.writeu8(b, 0, 0)
                                buffer.writeu8(b, 1, getPacketId("RequestBedSpawn"))
                                buffer.writeu16(b, 2, 128)
                                ByteNetReliable:FireServer(b)
                                
                                task.wait(0.2)
                                -- Second call with no args? Original: packets.RequestBedSpawn.send()
                                -- Assuming no args = empty/default. 
                                -- Let's send just header + action.
                                local b2 = buffer.create(2)
                                buffer.writeu8(b2, 0, 0)
                                buffer.writeu8(b2, 1, getPacketId("RequestBedSpawn"))
                                ByteNetReliable:FireServer(b2)
                            end
                        end)
                        pcall(function()
                            local pGui = plr.PlayerGui
                            for _, gui in pairs(pGui:GetDescendants()) do
                                if (gui:IsA("TextButton") or gui:IsA("ImageButton")) and gui.Visible then
                                    local text = gui:IsA("TextButton") and gui.Text:lower() or ""
                                    local name = gui.Name:lower()
                                    if name:find("bed") or text:find("bed") or name:find("spawn") or text:find("spawn") then
                                        if firesignal then firesignal(gui.MouseButton1Click) firesignal(gui.Activated) end
                                        break
                                    end
                                end
                            end
                        end)
                    end
                end
            end)
            task.wait(1)
        end
        respawnActive = false
    end)
end
end

do
