do
chestEngineActive = false
function startBigChestEngine()
    if chestEngineActive then return end
    if not Settings.BigChests then return end
    chestEngineActive = true
    local goldConnection = nil
    -- Multi-chest slot state
    local slotChestState = {}   -- [chest] = originalHitboxSize
    local slotHighlights = {}   -- [chest] = Highlight
    local slotBillboards = {}   -- [chest] = BillboardGui (ShowDistance&Chest)
    local currentSlotChests = {} -- resolved { chest=, slot= } for the current tick
    local teleportingItems = setmetatable({}, { __mode = "k" }) -- [item] = true while a pull thread is active

    local function slotItemsText(slot)
        local t = {}
        for k in pairs(slot and slot.items or {}) do t[#t + 1] = k end
        if #t == 0 then return "none" end
        table.sort(t)
        return table.concat(t, "+")
    end

    -- ===== Multi-Chest Slot helpers =====
    local function anySlotLocked()
        for _, s in ipairs(Settings.ChestSlots) do
            if s.pos then return true end
        end
        return false
    end

    local function findChestNearPosition(deployables, pos, tol)
        tol = tol or 5
        for _, obj in ipairs(deployables:GetChildren()) do
            if (obj.Name:find("Chest") or obj.Name:find("Box")) and not obj.Name:find("Plant Box") then
                if (obj:GetPivot().Position - pos).Magnitude < tol then
                    return obj
                end
            end
        end
        return nil
    end

    local function doTeleportItemToChest(item, chest)
        if not chest or not chest:FindFirstChild("Contents") then return end
        if teleportingItems[item] then return end -- already being pulled, don't stack threads
        local root = item:IsA("BasePart") and item or item:FindFirstChildWhichIsA("BasePart")
        if not root then return end

        -- Try to claim network ownership so the server accepts our position writes (best effort)
        pcall(function()
            if sethiddenproperty then
                sethiddenproperty(root, "NetworkOwnershipRule", 1)
            end
        end)

        teleportingItems[item] = true
        task.spawn(function()
            local itemsFolder = workspace:FindFirstChild("Items")
            local startClock = os.clock()
            -- Hold the item inside the chest hitbox every frame until it gets absorbed
            -- (item leaves Items folder) or we time out.
            local itemName = item.Name or "Unknown"
            local absorbed = false
            while item.Parent and item.Parent == itemsFolder and chest.Parent do
                local targetPart = chest:FindFirstChild("Hitbox")
                local targetCFrame = targetPart and targetPart.CFrame or chest:GetPivot()
                root.CFrame = targetCFrame
                root.AssemblyAngularVelocity = Vector3.zero
                root.AssemblyLinearVelocity = Vector3.new(0, -2, 0)
                if os.clock() - startClock > 3 then break end
                task.wait()
            end
            -- Item left the world Items folder = successfully absorbed into the chest
            if not item.Parent or item.Parent ~= itemsFolder then
                absorbed = true
            end
            if absorbed and __ASTER_RUNTIME.recordChestTeleport then
                __ASTER_RUNTIME.recordChestTeleport(itemName, 1)
            end
            teleportingItems[item] = nil
        end)
    end

    local function slotAcceptsItem(slot, item)
        if not slot or not slot.items then return false end
        local name = string.lower(item.Name or "")
        if name == "" then return false end
        for token in pairs(slot.items) do
            if token == "[Essence]" then
                if name:find("essence", 1, true) then return true end
            elseif token ~= "" and string.lower(token) == name then
                return true
            end
        end
        return false
    end

    local function routeItemMulti(item, slotChests)
        local root = item:IsA("BasePart") and item or item:FindFirstChildWhichIsA("BasePart")
        if not root then return end
        local best, bestDist = nil, math.huge
        for _, sc in ipairs(slotChests) do
            if sc.chest and sc.chest.Parent and slotAcceptsItem(sc.slot, item) then
                local d = (sc.chest:GetPivot().Position - root.Position).Magnitude
                if d < bestDist then bestDist = d best = sc.chest end
            end
        end
        if best then doTeleportItemToChest(item, best) end
    end

    local function restoreAllSlotChests()
        for chest, origSize in pairs(slotChestState) do
            if chest and chest.Parent then
                local hb = chest:FindFirstChild("Hitbox") or chest:FindFirstChild("default")
                if hb then
                    hb.Size = origSize
                    hb.Transparency = 1
                    hb.CastShadow = false
                end
            end
            slotChestState[chest] = nil
        end
        for chest, h in pairs(slotHighlights) do
            if h then h:Destroy() end
            slotHighlights[chest] = nil
        end
        for chest, b in pairs(slotBillboards) do
            if b then b:Destroy() end
            slotBillboards[chest] = nil
        end
    end

    local function handleMultiSlots(deployables, hrp)
        local slotChests = {}
        local activeSet = {}
        for i, slot in ipairs(Settings.ChestSlots) do
            if slot.pos then
                local chest = findChestNearPosition(deployables, slot.pos, 5)
                if chest then
                    table.insert(slotChests, { chest = chest, slot = slot, idx = i })
                    activeSet[chest] = true
                end
            end
        end

        -- Restore any chests no longer part of a slot
        for chest, origSize in pairs(slotChestState) do
            if not activeSet[chest] or not chest.Parent then
                if chest and chest.Parent then
                    local hb = chest:FindFirstChild("Hitbox") or chest:FindFirstChild("default")
                    if hb then hb.Size = origSize hb.Transparency = 1 hb.CastShadow = false end
                end
                slotChestState[chest] = nil
                if slotHighlights[chest] then slotHighlights[chest]:Destroy() slotHighlights[chest] = nil end
                if slotBillboards[chest] then slotBillboards[chest]:Destroy() slotBillboards[chest] = nil end
            end
        end

        local targetSize = Settings.ChestHitboxSize or 6
        for _, sc in ipairs(slotChests) do
            local chest = sc.chest
            local hb = chest:FindFirstChild("Hitbox") or chest:FindFirstChild("default")
            if hb then
                if slotChestState[chest] == nil then
                    if hb.Size.X < 500 then slotChestState[chest] = hb.Size else slotChestState[chest] = Vector3.new(4, 4, 4) end
                end
                hb.Size = Vector3.new(targetSize, targetSize, targetSize)
                hb.Transparency = 1
                hb.CanCollide = false
                hb.CastShadow = false
                hb.Massless = true
            end
            if not slotHighlights[chest] then
                local h = Instance.new("Highlight")
                h.Name = "SlotChestHighlight"
                h.FillColor = (Settings.ESPColors and Settings.ESPColors["Big Chests"]) or Color3.fromRGB(255, 170, 0)
                h.OutlineColor = Color3.fromRGB(255, 255, 255)
                h.FillTransparency = 0.5
                h.OutlineTransparency = 0
                h.Parent = chest
                slotHighlights[chest] = h
            elseif slotHighlights[chest].Parent ~= chest then
                slotHighlights[chest].Parent = chest
            end

            -- ShowDistance&Chest: floating label with the chest number, items and distance
            if Settings.ShowChestDistance then
                local adornee = chest:FindFirstChild("Hitbox") or chest:FindFirstChildWhichIsA("BasePart") or chest.PrimaryPart
                if adornee then
                    local bb = slotBillboards[chest]
                    if not bb or not bb.Parent then
                        bb = Instance.new("BillboardGui")
                        bb.Name = "SlotChestBillboard"
                        bb.Size = UDim2.new(0, 220, 0, 34)
                        bb.StudsOffset = Vector3.new(0, 4, 0)
                        bb.AlwaysOnTop = true
                        bb.MaxDistance = 1000
                        local lbl = Instance.new("TextLabel")
                        lbl.Name = "Label"
                        lbl.Size = UDim2.new(1, 0, 1, 0)
                        lbl.BackgroundTransparency = 1
                        lbl.Font = Enum.Font.GothamBold
                        lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
                        lbl.TextStrokeTransparency = 0
                        lbl.TextScaled = true
                        lbl.Parent = bb
                        bb.Adornee = adornee
                        bb.Parent = adornee
                        slotBillboards[chest] = bb
                    else
                        bb.Adornee = adornee
                    end
                    local lbl = bb:FindFirstChild("Label")
                    if lbl then
                        local dist = math.floor((chest:GetPivot().Position - hrp.Position).Magnitude + 0.5)
                        lbl.Text = "Chest" .. sc.idx .. " [" .. slotItemsText(sc.slot) .. "]  " .. dist .. "m"
                    end
                end
            elseif slotBillboards[chest] then
                slotBillboards[chest]:Destroy()
                slotBillboards[chest] = nil
            end
        end

        currentSlotChests = slotChests

        if #slotChests > 0 then
            local items = workspace:FindFirstChild("Items")
            if items then
                for _, item in ipairs(items:GetChildren()) do
                    routeItemMulti(item, slotChests)
                end
            end
        end
    end

    -- Setup Connection for New Items
    if workspace:FindFirstChild("Items") then
        goldConnection = workspace.Items.ChildAdded:Connect(function(item)
            if anySlotLocked() then
                task.wait(0.1)
                routeItemMulti(item, currentSlotChests)
            end
        end)
    end
    
    task.spawn(function()
        while Settings.BigChests do
            if anySlotLocked() then
                local mhrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                local mdep = getWorkspaceDeployables()
                if mhrp and mdep then
                    handleMultiSlots(mdep, mhrp)
                end
                task.wait(0.3)
            else
                if next(slotChestState) ~= nil then
                    restoreAllSlotChests()
                end
                task.wait(0.5)
            end
        end
        restoreAllSlotChests()
        if goldConnection then goldConnection:Disconnect() goldConnection = nil end
        chestEngineActive = false
    end)
end
end

do
deletionActive = false
function startItemDeletion()
    if deletionActive then return end
    deletionActive = true
    task.spawn(function()
        while Settings.ItemDeletionEnabled do
            pcall(function()
                local filterText = Settings.ItemDeletion or ""
                
                if filterText ~= "" then
                    local itemsToDelete = {}
                    for word in string.gmatch(filterText, '([^,]+)') do
                        local cleanWord = word:match("^%s*(.-)%s*$"):lower()
                        if cleanWord ~= "" then itemsToDelete[cleanWord] = true end
                    end

                    local itemsFolder = workspace:FindFirstChild("Items")
                    if itemsFolder then
                        for _, item in ipairs(itemsFolder:GetChildren()) do
                            if itemsToDelete[item.Name:lower()] then
                                item:Destroy()
                            end
                        end
                    end

                    local deployables = getWorkspaceDeployables()
                    if deployables then
                        for _, chest in ipairs(deployables:GetChildren()) do
                            if (chest.Name:find("Chest") or chest.Name:find("Box")) and chest:FindFirstChild("Contents") then
                                for _, item in ipairs(chest.Contents:GetChildren()) do
                                    if itemsToDelete[item.Name:lower()] then
                                        item:Destroy()
                                    end
                                end
                            end
                        end
                    end
                end
            end)
            task.wait(1)
        end
        deletionActive = false
    end)
end
end

do
coinActive = false
function startCoinPresser()
    if coinActive then return end
    coinActive = true
    task.spawn(function()
        local cachedPress = nil
        local ItemIDS = require(game:GetService("ReplicatedStorage").Modules.ItemIDS)
        local goldID = ItemIDS["Gold"] or ItemIDS["Gold Ore"]
        
        local function getHiddenID(object)
             local exact = object:GetAttribute("NetworkId") or object:GetAttribute("networkId") or object:GetAttribute("ID") or object:GetAttribute("Id")
             if exact then return exact end
             for name, value in pairs(object:GetAttributes()) do
                 if typeof(value) == "number" then return value end
             end
             local val = object:FindFirstChildWhichIsA("IntValue", true) or object:FindFirstChildWhichIsA("NumberValue", true)
             if val then return val.Value end
             local parsed = tonumber(object.Name)
             if parsed then return parsed end
             return nil
        end
        
        -- Local helper to avoid dependency on outer getlayout
        local function getlayout(name)
             local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
             local inventory = mainGui and mainGui.RightPanel and mainGui.RightPanel.Inventory and mainGui.RightPanel.Inventory.List
             if inventory and inventory:FindFirstChild(name) then return true end
             return false
        end

        while Settings.CoinPresserEnabled do
            local success = pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                
                -- Check for Gold in Inventory
                local hasGold = false
                if getlayout("Gold") then hasGold = true end

                if hasGold then
                    -- 2. Find the Coin Press nearby
                    local targetPress = nil
                    
                    if cachedPress and cachedPress.Parent and cachedPress:GetPivot() then
                        local dist = (cachedPress:GetPivot().Position - hrp.Position).Magnitude
                        if dist < 20 then
                            targetPress = cachedPress
                        else
                            cachedPress = nil
                        end
                    end
                    
                    if not targetPress then
                        local deployables = getWorkspaceDeployables()
                        if deployables then
                            for _, obj in pairs(deployables:GetChildren()) do
                                if obj.Name:find("Press") then
                                    local dist = (obj:GetPivot().Position - hrp.Position).Magnitude
                                    if dist < 20 then
                                        targetPress = obj
                                        cachedPress = obj
                                        break
                                    end
                                end
                            end
                        end
                    end

                    if targetPress then
                        local networkID = getHiddenID(targetPress)
                        
                        if networkID and ByteNetReliable then
                            -- 4. Recreate the 8-byte buffer: [Namespace, Action(201), PressID(u32), GoldID(u16)]
                            local b = buffer.create(8)
                            buffer.writeu8(b, 0, 0)
                            buffer.writeu8(b, 1, getPacketId("InteractStructure"))
                            buffer.writeu32(b, 2, networkID) -- Target Press Network ID
                            buffer.writeu16(b, 6, goldID)    -- Gold Item ID from ItemIDS
                            
                            ByteNetReliable:FireServer(b)
                        end
                    end
                end
            end)
            wait(0.01) -- Small delay
        end
        coinActive = false
    end)
end

multiCoinActive = false
function startMultiCoinPresser()
    if multiCoinActive then return end
    multiCoinActive = true
    task.spawn(function()
        local ItemIDS = require(game:GetService("ReplicatedStorage").Modules.ItemIDS)
        local goldID = ItemIDS["Gold"] or ItemIDS["Gold Ore"]
        local interactPacketId = getPacketId("InteractStructure")

        local function getPressNetworkID(object)
            local exact = object:GetAttribute("EntityID")
                or object:GetAttribute("NetworkId")
                or object:GetAttribute("networkId")
                or object:GetAttribute("ID")
                or object:GetAttribute("Id")
            if exact then return exact end
            for _, value in pairs(object:GetAttributes()) do
                if typeof(value) == "number" then return value end
            end
            local val = object:FindFirstChildWhichIsA("IntValue", true) or object:FindFirstChildWhichIsA("NumberValue", true)
            if val then return val.Value end
            return tonumber(object.Name)
        end

        local function isCoinPress(obj)
            if not obj or not obj:IsA("Model") then return false end
            local name = string.lower(obj.Name or "")
            return name:find("coin press", 1, true) ~= nil
                or name:find("coinpress", 1, true) ~= nil
                or name:find("press", 1, true) ~= nil
        end

        local function getlayout(name)
            local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
            local inventory = mainGui and mainGui.RightPanel and mainGui.RightPanel.Inventory and mainGui.RightPanel.Inventory.List
            if inventory and inventory:FindFirstChild(name) then return true end
            return false
        end

        local PRESS_RANGE = 45

        local function collectNearbyCoinPresses(hrp)
            local presses = {}
            if not hrp then return presses end
            local deployables = getWorkspaceDeployables()
            if not deployables then return presses end
            local playerPos = hrp.Position
            for _, obj in ipairs(deployables:GetChildren()) do
                if isCoinPress(obj) then
                    local ok, pivot = pcall(function() return obj:GetPivot() end)
                    if ok and pivot and (pivot.Position - playerPos).Magnitude <= PRESS_RANGE then
                        presses[#presses + 1] = obj
                    end
                end
            end
            return presses
        end

        while Settings.MultiCoinPresserEnabled do
            pcall(function()
                local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                if not hrp then return end
                if not getlayout("Gold") then return end
                if not interactPacketId or not ByteNetReliable then return end

                local presses = collectNearbyCoinPresses(hrp)
                for _, targetPress in ipairs(presses) do
                    if not Settings.MultiCoinPresserEnabled then break end
                    if not targetPress.Parent then continue end
                    local networkID = getPressNetworkID(targetPress)
                    if networkID then
                        local b = buffer.create(8)
                        buffer.writeu8(b, 0, 0)
                        buffer.writeu8(b, 1, interactPacketId)
                        buffer.writeu32(b, 2, networkID)
                        buffer.writeu16(b, 6, goldID)
                        ByteNetReliable:FireServer(b)
                        task.wait(0.05)
                    end
                end
            end)
            task.wait(0.1)
        end
        multiCoinActive = false
    end)
end
end

do
function getInventorySlotAndCount(itemName)
    local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
    if not mainGui then return nil, nil end
    local inventory = mainGui.RightPanel and mainGui.RightPanel.Inventory and mainGui.RightPanel.Inventory.List
    if not inventory then return nil, nil end
    local item = inventory:FindFirstChild(itemName)
    if item then
        local slotID = item.LayoutOrder
        local count = 0
        local qtyImage = item:FindFirstChild("QuantityImage")
        if qtyImage then
            local qtyText = qtyImage:FindFirstChild("QuantityText")
            if qtyText and qtyText.Text ~= "" then
                local clean = qtyText.Text:gsub("%D", "")
                count = tonumber(clean) or 0
            end
        end
        if count == 0 then
             local attrCount = item:GetAttribute("Count") or item:GetAttribute("Amount")
             if attrCount then count = attrCount end
        end
        return slotID, count
    end
    return nil, nil
end

function eatDownToCap(fruitName, cap)
    local fruitID = resolveHealFruitItemId(fruitName)
    if not fruitID then return end
    cap = tonumber(cap) or 0
    local slotID, count = getInventorySlotAndCount(fruitName)
    
    if slotID and count then
        if count > cap then
            local toEat = count - cap
            if toEat > 20 then toEat = 20 end 
            for i = 1, toEat do
                if not (Settings.WasteFruitsEnabled or Settings.EatCapEnabled) then break end
                pcall(function() 
                    local actionId = getPacketId("UseBagItem")
                    local b = buffer.create(8)
                    buffer.writeu8(b, 0, 0)
                    buffer.writeu8(b, 1, actionId)
                    buffer.writeu32(b, 2, slotID)
                    buffer.writeu16(b, 6, fruitID)
                    if ByteNetReliable then ByteNetReliable:FireServer(b) end
                end)
                task.wait(0.25) 
            end
        end
    end
end

function startEatCap()
    task.spawn(function()
        while Settings.WasteFruitsEnabled or Settings.EatCapEnabled do
            local wasteFruit = Settings.WasteFruit or "Bloodfruit"
            local cap = tonumber(Settings.FruitsCapAmount) or tonumber(Settings.EatCap) or 100
            if wasteFruit and cap then eatDownToCap(wasteFruit, cap) end
            task.wait(1)
        end
    end)
end
end -- AsterRebirthEatCap

do -- AsterFishReset
fishActive = false

-- Helper to find fishing packet names from live packet table
function getFishingPacketIDs()
    return resolvePacketId("RodSwing", "CreateBobber"),
           resolvePacketId("RodEnd", "RodBubble")
end

function startAutoReset()
    task.spawn(function()
        while Settings.AutoResetEnabled do
            if plr.Character and plr.Character:FindFirstChild("Humanoid") then
                plr.Character.Humanoid.Health = 0
            end
            task.wait(3) -- Wait 3 seconds before resetting again
        end
    end)
end
end -- AsterFishReset

do -- AsterAutoSaddle
saddleActive = false
BIG_SADDLE_NAME = "Big Saddle"
BANTO_SADDLE_NAME = "Saddle"
-- Saddle apply uses TargetTool: \0 + TargetTool + \1 + u32 EntityID LE

function getSaddleApplyPacketId()
    return getPacketId("TargetTool")
end

-- Which saddle item works on which critter (name in workspace.Critters).
CRITTER_SADDLE_MAP = {
    ["Sand Mammoth"] = BIG_SADDLE_NAME,
    ["Baby Sand Mammoth"] = BIG_SADDLE_NAME,
    ["Snow Mammoth"] = BIG_SADDLE_NAME,
    ["Giant Shelly"] = BIG_SADDLE_NAME,
    ["Banto"] = BANTO_SADDLE_NAME,
    ["Bantae"] = BANTO_SADDLE_NAME,
    ["Lil Banto"] = BANTO_SADDLE_NAME,
    ["Golden Banto"] = BANTO_SADDLE_NAME,
    ["Crystal Bantae"] = BANTO_SADDLE_NAME,
    ["Rentae"] = BANTO_SADDLE_NAME,
    ["Rento"] = BANTO_SADDLE_NAME,
}

-- TargetTool wire format: \0 + TargetTool + \1 + u32 critter EntityID LE
function readSaddleTargetIdFromInstance(inst)
    if not inst then return nil end
    local eid = inst:GetAttribute("EntityID") or inst:GetAttribute("ID")
        or inst:GetAttribute("NetworkId") or inst:GetAttribute("networkId")
        or inst:GetAttribute("NetworkID") or inst:GetAttribute("Id")
    if eid ~= nil then
        local n = math.floor(tonumber(eid) or 0)
        if n > 0 then return n end
    end
    for _, key in ipairs({"EntityID", "NetworkId", "networkId", "NetworkID", "ID", "Id"}) do
        local v = inst:GetAttribute(key)
        if v ~= nil then
            local n = math.floor(tonumber(v) or 0)
            if n > 0 then return n end
        end
    end
    for name, value in pairs(inst:GetAttributes()) do
        if typeof(value) == "number" and value > 1000 then
            return math.floor(value)
        end
    end
    for name, value in pairs(inst:GetAttributes()) do
        if typeof(value) == "number" then
            local ln = string.lower(tostring(name))
            if ln:find("network", 1, true) or ln == "id" or ln:find("entity", 1, true) then
                local n = math.floor(value)
                if n > 0 then return n end
            end
        end
    end
    if inst:IsA("ValueBase") then
        local n = math.floor(inst.Value)
        if n > 0 then return n end
    end
    return nil
end

local SaddleCritterIDCache = setmetatable({}, { __mode = "k" })

function getCritterNetworkId(model)
    if not model then return nil end
    if SaddleCritterIDCache[model] then return SaddleCritterIDCache[model] end

    local id = readSaddleTargetIdFromInstance(model)
    if id then
        SaddleCritterIDCache[model] = id
        return id
    end

    local root = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart") or model:FindFirstChildWhichIsA("BasePart")
    if root then
        id = readSaddleTargetIdFromInstance(root)
        if id then
            SaddleCritterIDCache[model] = id
            return id
        end
    end

    for _, desc in ipairs(model:GetDescendants()) do
        if desc:IsA("IntValue") or desc:IsA("NumberValue") then
            local n = math.floor(desc.Value)
            if n > 1000 then
                SaddleCritterIDCache[model] = n
                return n
            end
        elseif desc:IsA("ValueBase") or desc:IsA("BasePart") then
            id = readSaddleTargetIdFromInstance(desc)
            if id then
                SaddleCritterIDCache[model] = id
                return id
            end
        end
    end

    return nil
end

function playerHasSaddleItem(toolName)
    if getToolSlot and getToolSlot(toolName) then return true end
    if getlayout and getlayout(toolName) then return true end
    if getInventorySlotAndCount and select(1, getInventorySlotAndCount(toolName)) then return true end
    if plr.Backpack and plr.Backpack:FindFirstChild(toolName) then return true end
    if plr.Character and plr.Character:FindFirstChild(toolName) then return true end
    return false
end

function critterUsesBigSaddle(model)
    if not model then return false end
    local mapped = CRITTER_SADDLE_MAP[model.Name]
    if mapped == BIG_SADDLE_NAME then return true end
    if mapped == BANTO_SADDLE_NAME then return false end
    local lname = string.lower(model.Name)
    if string.find(lname, "mammoth", 1, true) or string.find(lname, "giant shelly", 1, true) then return true end
    if string.find(lname, "banto", 1, true) or string.find(lname, "bantae", 1, true)
        or string.find(lname, "rentae", 1, true) or string.find(lname, "rento", 1, true) then
        return false
    end
    local ok, ext = pcall(function() return model:GetExtentsSize() end)
    if ok and ext then
        if math.max(ext.X, ext.Y, ext.Z) >= 18 then return true end
    end
    return false
end

function pickSaddleToolForCritter(model)
    if not model or not model:IsA("Model") then return nil end
    -- Banto: equip "Saddle" then TargetTool. Mammoth: equip "Big Saddle" then same packet.
    if critterUsesBigSaddle(model) then
        return BIG_SADDLE_NAME
    end
    return BANTO_SADDLE_NAME
end

function isSaddlableCritter(model)
    if not model or not model:IsA("Model") then return false end
    if CRITTER_SADDLE_MAP[model.Name] then return true end
    local lname = string.lower(model.Name)
    if string.find(lname, "mammoth", 1, true) or string.find(lname, "giant shelly", 1, true) then return true end
    if string.find(lname, "banto", 1, true) or string.find(lname, "bantae", 1, true)
        or string.find(lname, "rentae", 1, true) or string.find(lname, "rento", 1, true) then
        return true
    end
    local ok, ext = pcall(function() return model:GetExtentsSize() end)
    if ok and ext and math.max(ext.X, ext.Y, ext.Z) >= 18 then return true end
    return false
end

function getCritterModelInFront(folder, hrp, reach)
    if not folder or not hrp then return nil end
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Include
    params.FilterDescendantsInstances = {folder}
    local hit = workspace:Raycast(hrp.Position, hrp.CFrame.LookVector * reach, params)
    if hit and hit.Instance then
        local m = hit.Instance:FindFirstAncestorOfClass("Model")
        if m and (m.Parent == folder or m:IsDescendantOf(folder)) then
            return m
        end
    end
    return nil
end

function critterAlreadyHasSaddle(model)
    if model:GetAttribute("Saddled") or model:GetAttribute("HasSaddle") or model:GetAttribute("Mounted") then
        return true
    end
    return false
end

function resolveSaddleItemId(toolName)
    local id = autoDiscoverItemID(toolName)
    if not id and type(craftNameToID) == "table" then
        id = craftNameToID[toolName]
    end
    if not id then
        pcall(function()
            local ItemIDS = require(game:GetService("ReplicatedStorage").Modules.ItemIDS)
            id = ItemIDS[toolName]
        end)
    end
    return id
end

function isSaddleEquipped(toolName)
    if not toolName then return false end
    local char = plr.Character
    if char then
        local charTools = char:FindFirstChild("Tools")
        if charTools and charTools:FindFirstChild(toolName) then
            return true
        end
        if char:FindFirstChild(toolName) then
            return true
        end
    end
    if isToolEquipped(toolName) then return true end
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local tools = playersFolder:FindFirstChild(plr.Name) and playersFolder[plr.Name]:FindFirstChild("Tools")
        if tools and tools:FindFirstChild(toolName) then
            return true
        end
    end
    return false
end

function equipSaddleTool(toolName)
    if not ByteNetReliable or not toolName then return false end
    if isSaddleEquipped(toolName) then return true end

    equipItemPacket(toolName)
    for _ = 1, 12 do
        if not Settings.AutoSaddleEnabled then break end
        if isSaddleEquipped(toolName) then return true end
        task.wait(0.1)
    end

    if plr.Backpack and plr.Character then
        local hum = plr.Character:FindFirstChildOfClass("Humanoid")
        local t = plr.Backpack:FindFirstChild(toolName)
        if hum and t and not isSaddleEquipped(toolName) then
            pcall(function() hum:EquipTool(t) end)
            task.wait(0.15)
        end
    end

    return isSaddleEquipped(toolName)
end

-- TargetTool wire format: \0 + TargetTool + \1 + u32 EntityID LE
function fireSaddleOnAnimal(targetId)
    if not ByteNetReliable then return end
    targetId = math.floor(tonumber(targetId) or 0)
    if targetId <= 0 then return end

    local actionId = getSaddleApplyPacketId()
    if not actionId then return end
    local b = buffer.create(7)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, actionId)
    buffer.writeu8(b, 2, 1)
    buffer.writeu32(b, 3, targetId)
    ByteNetReliable:FireServer(b)
end

function findNearestCritterForAutoSaddle(maxDist)
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil, nil, nil end

    local folder = getWorkspaceCritters()
    if not folder then return nil, nil, nil end

    -- Prefer the critter you're standing on / looking at (raycast).
    local frontModel = getCritterModelInFront(folder, hrp, math.min(maxDist, 25))
    if frontModel and not critterAlreadyHasSaddle(frontModel) and isSaddlableCritter(frontModel) then
        local toolName = pickSaddleToolForCritter(frontModel)
        local netId = getCritterNetworkId(frontModel)
        if toolName and netId then
            local part = frontModel.PrimaryPart or frontModel:FindFirstChildWhichIsA("BasePart")
            if part and (part.Position - hrp.Position).Magnitude <= maxDist then
                return frontModel, netId, toolName
            end
        end
    end

    -- Fallback: nearest model in workspace.Critters (distance only ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â id resolved after).
    local bestModel, bestTool, bestDist = nil, nil, maxDist
    for _, model in ipairs(folder:GetChildren()) do
        if model:IsA("Model") and not critterAlreadyHasSaddle(model) then
            if isSaddlableCritter(model) then
                local toolName = pickSaddleToolForCritter(model)
                local part = model.PrimaryPart or model:FindFirstChild("HumanoidRootPart") or model:FindFirstChildWhichIsA("BasePart")
                if part then
                    local dist = (part.Position - hrp.Position).Magnitude
                    if dist < bestDist then
                        bestDist = dist
                        bestModel = model
                        bestTool = toolName
                    end
                end
            end
        end
    end

    if bestModel and bestDist < 20 then
        local netId = getCritterNetworkId(bestModel)
        if not netId then
            pcall(function()
                local mouse = plr:GetMouse()
                if mouse and mouse.Target and mouse.Target:IsDescendantOf(bestModel) then
                    netId = readSaddleTargetIdFromInstance(mouse.Target)
                        or readSaddleTargetIdFromInstance(mouse.Target:FindFirstAncestorOfClass("Model"))
                end
            end)
        end
        if netId then
            return bestModel, netId, bestTool
        end
    elseif bestModel then
        local netId = getCritterNetworkId(bestModel)
        if netId then
            return bestModel, netId, bestTool
        end
    end
    return nil, nil, nil
end
end -- AsterAutoSaddle

do -- AsterMiscAutomation
local fishClickConnection = nil
local fishCirclePart = nil
local fishCastActive = false
local fishBiteReady = false

local function getFishingRod()
    local character = plr.Character
    local tools = character and character:FindFirstChild("Tools")
    return tools and tools:FindFirstChild("Fishing Rod")
end

local function updateFishingCircle()
    if not fishCirclePart then return end
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then
        fishCirclePart.Transparency = 1
        return
    end
    local distance = math.clamp(tonumber(Settings.FishDistance) or 11, 10, 12)
    fishCirclePart.CFrame = CFrame.new(hrp.Position + hrp.CFrame.LookVector * distance - Vector3.new(0, 2.8, 0)) * CFrame.Angles(0, 0, math.rad(90))
    fishCirclePart.Transparency = Settings.AutoFishEnabled and 0.65 or 1
end

local function ensureFishingCircle()
    if fishCirclePart and fishCirclePart.Parent then return end
    fishCirclePart = Instance.new("Part")
    fishCirclePart.Name = "AsterFishingCircle"
    fishCirclePart.Shape = Enum.PartType.Cylinder
    fishCirclePart.Size = Vector3.new(0.12, 22, 22)
    fishCirclePart.Anchored = true
    fishCirclePart.CanCollide = false
    fishCirclePart.CanTouch = false
    fishCirclePart.CanQuery = false
    fishCirclePart.Material = Enum.Material.Neon
    fishCirclePart.Color = Color3.fromRGB(40, 220, 255)
    fishCirclePart.Transparency = 1
    fishCirclePart.Parent = getAsterHiddenWorkspace() or workspace
end

local function stopFishingClickMode()
    fishCastActive = false
    fishBiteReady = false
    if fishClickConnection then
        fishClickConnection:Disconnect()
        fishClickConnection = nil
    end
    if fishCirclePart then
        fishCirclePart:Destroy()
        fishCirclePart = nil
    end
end

local function sendFishingCast()
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    local rod = getFishingRod()
    if not hrp or not rod or not ByteNetReliable then return false end
    local castID = getFishingPacketIDs()
    if not castID then return false end
    local distance = math.clamp(tonumber(Settings.FishDistance) or 11, 10, 12)
    local origin = hrp.Position
    local target = origin + hrp.CFrame.LookVector * distance
    local b = buffer.create(26)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, castID)
    buffer.writef32(b, 2, target.X)
    buffer.writef32(b, 6, target.Y)
    buffer.writef32(b, 10, target.Z)
    buffer.writef32(b, 14, origin.X)
    buffer.writef32(b, 18, origin.Y)
    buffer.writef32(b, 22, origin.Z)
    ByteNetReliable:FireServer(b)
    return true
end

local function sendFishingReel()
    if not ByteNetReliable then return false end
    local _, reelID = getFishingPacketIDs()
    if not reelID then return false end
    local b = buffer.create(2)
    buffer.writeu8(b, 0, 0)
    buffer.writeu8(b, 1, reelID)
    ByteNetReliable:FireServer(b)
    return true
end

local function fishingBobberIsDown()
    local rod = getFishingRod()
    local bobber = rod and rod:FindFirstChild("Bobber")
    local emitter = bobber and bobber:FindFirstChild("ParticleEmitter")
    return emitter and (not emitter:IsA("ParticleEmitter") or emitter.Enabled) or false
end

function startAutoSaddle()
    if saddleActive then return end
    saddleActive = true
    task.spawn(function()
        while Settings.AutoSaddleEnabled do
            local critter, netId, toolName = findNearestCritterForAutoSaddle(80)
            if critter and netId and toolName then
                pcall(function()
                    if equipSaddleTool(toolName) then
                        task.wait(0.2)
                        fireSaddleOnAnimal(netId)
                        task.wait(0.1)
                        fireSaddleOnAnimal(netId)
                    end
                end)
            end
            task.wait(0.5)
        end
        saddleActive = false
    end)
end

function startAutoFish()
    if fishClickConnection then return end
    fishActive = true
    ensureFishingCircle()
    updateFishingCircle()
    fishClickConnection = UserInputService.InputBegan:Connect(function(input, gameProcessed)
        if gameProcessed or not Settings.AutoFishEnabled then return end
        if input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        if not getFishingRod() then
            equipItemPacket("Fishing Rod")
            return
        end
        if fishCastActive and fishingBobberIsDown() then
            if sendFishingReel() then
                fishCastActive = false
                fishBiteReady = false
            end
        elseif not fishCastActive then
            if sendFishingCast() then
                fishCastActive = true
                fishBiteReady = false
            end
        end
    end)
    task.spawn(function()
        while Settings.AutoFishEnabled and fishClickConnection do
            updateFishingCircle()
            if fishCastActive and fishingBobberIsDown() then
                fishBiteReady = true
            end
            task.wait(0.05)
        end
        fishActive = false
        stopFishingClickMode()
    end)
end
end -- AsterMiscAutomation

do -- AsterWorldESP
local traderESPActive = false 
local fishermanESPActive = false

local function getFishermanCharacter()
    for _, name in ipairs({ "Fisherman Trader", "The Fisherman", "Fisherman" }) do
        local character = workspace:FindFirstChild(name) or workspace:FindFirstChild(name, true)
        if character then return character end
    end
    return nil
end

function startFishermanESP()
    if fishermanESPActive then return end
    fishermanESPActive = true
    task.spawn(function()
        local currentHighlight = nil
        local currentBg = nil
        while Settings.FishermanVisible and not ScriptKilled do
            local npcFolder = workspace:FindFirstChild("DialogNPCs")
            local normalFolder = npcFolder and npcFolder:FindFirstChild("Normal")
            local character = normalFolder and normalFolder:FindFirstChild("Fisherman Trader")
            character = character or getFishermanCharacter()

            if character and character:IsA("Model") then
                if not currentHighlight or currentHighlight.Adornee ~= character or not currentHighlight.Parent then
                    if currentHighlight then currentHighlight:Destroy() end
                    if currentBg then currentBg:Destroy() end

                    local color = Color3.fromRGB(0, 220, 255)
                    local highlight = Instance.new("Highlight")
                    highlight.Name = "FishermanTraderESP"
                    highlight.FillColor = color
                    highlight.OutlineColor = color
                    highlight.FillTransparency = 0.5
                    highlight.OutlineTransparency = 0
                    highlight.Adornee = character
                    highlight.Parent = character
                    currentHighlight = highlight

                    local bg = Instance.new("BillboardGui")
                    bg.Name = "FishermanTraderESP"
                    bg.Adornee = character:FindFirstChild("Head") or character.PrimaryPart
                    bg.Size = UDim2.new(0, 200, 0, 50)
                    bg.StudsOffset = Vector3.new(0, 4, 0)
                    bg.AlwaysOnTop = true

                    local text = Instance.new("TextLabel")
                    text.BackgroundTransparency = 1
                    text.Size = UDim2.fromScale(1, 1)
                    text.TextColor3 = color
                    text.TextStrokeTransparency = 0.5
                    text.Font = Enum.Font.GothamBold
                    text.TextSize = 12
                    text.Text = "Fisherman Trader"
                    text.Parent = bg
                    bg.Parent = character
                    currentBg = bg
                end
            else
                if currentHighlight then currentHighlight:Destroy(); currentHighlight = nil end
                if currentBg then currentBg:Destroy(); currentBg = nil end
            end
            task.wait(0.2)
        end
        if currentHighlight then currentHighlight:Destroy() end
        if currentBg then currentBg:Destroy() end
        fishermanESPActive = false
    end)
end

function startWanderingTraderESP() 
    if traderESPActive then return end 
    traderESPActive = true 
    task.spawn(function() 
        local currentHighlight = nil 
        local currentBg = nil
        while Settings.WanderingTraderESPEnabled and not ScriptKilled do 
            local npcFolder = workspace:FindFirstChild("DialogNPCs") 
            local normalFolder = npcFolder and npcFolder:FindFirstChild("Normal") 
            -- Try direct index first, then FindFirstChild
            local trader = normalFolder and normalFolder:FindFirstChild("Wandering Trader")
            
            if trader and trader:IsA("Model") then 
                local adorn = trader 
                if not currentHighlight or currentHighlight.Adornee ~= adorn or not currentHighlight.Parent then 
                    if currentHighlight then 
                        currentHighlight:Destroy() 
                    end 
                    if currentBg then currentBg:Destroy() end
                    
                    local h = Instance.new("Highlight") 
                    local color = Settings.ESPColors["Wandering Trader ESP"] or Color3.fromRGB(255, 255, 255)
                    h.FillColor = color 
                    h.OutlineColor = color
                    h.FillTransparency = 0.5 
                    h.OutlineTransparency = 0 
                    h.Adornee = adorn 
                    h.Parent = adorn 
                    currentHighlight = h 
                    
                    local bg = Instance.new("BillboardGui")
                    bg.Name = "TraderESP"
                    bg.Adornee = adorn:FindFirstChild("Head") or adorn.PrimaryPart
                    bg.Size = UDim2.new(0, 200, 0, 50)
                    bg.StudsOffset = Vector3.new(0, 4, 0)
                    bg.AlwaysOnTop = true
                    
                    local text = Instance.new("TextLabel")
                    text.Parent = bg
                    text.Size = UDim2.new(1, 0, 1, 0)
                    text.BackgroundTransparency = 1
                    text.TextColor3 = color
                    text.TextStrokeTransparency = 0.5
                    text.Font = Enum.Font.GothamBold
                    text.TextSize = 12
                    text.Text = "Wandering Trader"
                    
                    bg.Parent = adorn
                    currentBg = bg
                else
                    -- Update Color if needed
                    local color = Settings.ESPColors["Wandering Trader ESP"] or Color3.fromRGB(255, 255, 255)
                    if currentHighlight then
                         currentHighlight.OutlineColor = color
                         currentHighlight.FillColor = color
                    end
                    if currentBg and currentBg:FindFirstChild("TextLabel") then
                         currentBg.TextLabel.TextColor3 = color
                    end
                end 
            else 
                if currentHighlight then currentHighlight:Destroy() currentHighlight = nil end 
                if currentBg then currentBg:Destroy() currentBg = nil end
            end 
            task.wait(0.2) 
        end 
        if currentHighlight then currentHighlight:Destroy() end 
        if currentBg then currentBg:Destroy() end
        traderESPActive = false 
    end) 
end
end

do
local critterESPActive = false
function startCritterESP()
    if critterESPActive then return end
    critterESPActive = true
    task.spawn(function()
        local highlights = {} -- map item -> {bg, text, adorn, color}
        
        while Settings.CritterESPEnabled and not ScriptKilled do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                 local crittersFolder = getWorkspaceCritters()
                 local currentStepItems = {}

                 if crittersFolder then
                     for _, item in ipairs(crittersFolder:GetChildren()) do
                         if item:IsA("Model") and Settings.SelectedCritters and (Settings.SelectedCritters["All"] or Settings.SelectedCritters[item.Name]) then
                             currentStepItems[item] = true
                             
                             if not highlights[item] then
                                 local adorn = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                                 
                                 if adorn then
                                     local bg = Instance.new("BillboardGui")
                                     bg.Name = "CritterESP"
                                     bg.Adornee = adorn
                                     bg.Size = UDim2.new(0, 200, 0, 50)
                                     bg.StudsOffset = Vector3.new(0, 5, 0)
                                     bg.AlwaysOnTop = true
                                     
                                     local text = Instance.new("TextLabel")
                                     text.Parent = bg
                                     text.Size = UDim2.new(1, 0, 1, 0)
                                     text.BackgroundTransparency = 1
                                     
                                    local color = Settings.ESPColors["Critter ESP"] or Color3.fromRGB(255, 150, 50)
                                     
                                     text.TextColor3 = color
                                     text.TextStrokeTransparency = 1 
                                     text.Font = Enum.Font.GothamBold
                                     text.TextSize = 12
                                     text.Text = item.Name
                                     
                                     local stroke = Instance.new("UIStroke")
                                     stroke.Parent = text
                                     stroke.Thickness = 0.5 
                                     stroke.Transparency = 0 
                                     stroke.Color = Color3.new(0,0,0)
                                     
                                     bg.Parent = item
                                     
                                     highlights[item] = {bg = bg, text = text, adorn = adorn}
                                 end
                             else
                                -- Update distance and color
                                local data = highlights[item]
                                if data and data.adorn and data.text then
                                    local dist = (data.adorn.Position - hrp.Position).Magnitude
                                    local color = Settings.ESPColors["Critter ESP"] or Color3.fromRGB(255, 150, 50)
                                    data.text.Text = string.format("%s [%d]", item.Name, math.floor(dist))
                                    data.text.TextColor3 = color
                                end
                             end
                         end
                     end
                 end
                 
                 -- Cleanup
                 for item, data in pairs(highlights) do
                     if not item.Parent or not currentStepItems[item] then
                         if data.bg then data.bg:Destroy() end
                         highlights[item] = nil
                     end
                 end
            end
            task.wait(0.1)
        end
        
        for _, data in pairs(highlights) do
             if data.bg then data.bg:Destroy() end
        end
        critterESPActive = false
    end)
end
end

do
local godBossESPActive = false
function startGodBossESP()
    if godBossESPActive then return end
    godBossESPActive = true
    task.spawn(function()
        local highlights = {} -- map item -> {bg, text, adorn, color}
        
