do
local oreESPActive = false

local function getOreESPColor(name)
    if name == "Gold Node" then return Color3.fromRGB(255, 215, 0) end
    if name == "Iron Node" then return Color3.fromRGB(200, 200, 200) end
    if name == "Coal Node" then return Color3.fromRGB(40, 40, 40) end
    if name == "Adurite Node" then return Color3.fromRGB(255, 50, 50) end
    if name == "Emerald Lode" then return Color3.fromRGB(80, 200, 120) end
    if name == "Pink Diamond Lode" then return Color3.fromRGB(255, 105, 180) end
    if name == "Crystal Lode" then return Color3.fromRGB(0, 255, 255) end
    return Color3.fromRGB(255, 255, 255)
end

-- Collect selected ore models: top-level Resources children AND nested under Breakaway
-- (e.g. Resources.<pack>.Breakaway["Gold Node"]).
local function collectSelectedOreModels(resourcesFolder)
    local selected = Settings.SelectedOres
    local out = {}
    if not selected or not resourcesFolder then return out end

    for _, item in ipairs(resourcesFolder:GetChildren()) do
        if item:IsA("Model") and selected[item.Name] then
            out[#out + 1] = item
        end
        local breakaway = item:FindFirstChild("Breakaway")
        if breakaway then
            for _, nested in ipairs(breakaway:GetChildren()) do
                if nested:IsA("Model") and selected[nested.Name] then
                    out[#out + 1] = nested
                end
            end
        end
    end
    return out
end

function startOreESP()
    if oreESPActive then return end
    oreESPActive = true
    task.spawn(function()
        local highlights = {} -- map item -> {highlight, billboard}
        
        while Settings.OreESPEnabled and not ScriptKilled do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                 local resourcesFolder = getWorkspaceResources()
                 local currentStepItems = {}

                 if resourcesFolder and Settings.SelectedOres then
                     for _, item in ipairs(collectSelectedOreModels(resourcesFolder)) do
                             currentStepItems[item] = true
                             
                             if not highlights[item] then
                                 local adorn = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
                                 
                                 if adorn then
                                     local bg = Instance.new("BillboardGui")
                                     bg.Name = "OreESP"
                                     bg.Adornee = adorn
                                     bg.Size = UDim2.new(0, 200, 0, 50)
                                     bg.StudsOffset = Vector3.new(0, 5, 0)
                                     bg.AlwaysOnTop = true
                                     
                                     local text = Instance.new("TextLabel")
                                     text.Parent = bg
                                     text.Size = UDim2.new(1, 0, 1, 0)
                                     text.BackgroundTransparency = 1
                                     
                                     local color = getOreESPColor(item.Name)
                                     
                                     text.TextColor3 = color
                                     text.TextStrokeTransparency = 1 
                                     text.Font = Enum.Font.GothamBold
                                     text.TextSize = 12
                                     text.Text = item.Name
                                     
                                     local stroke = Instance.new("UIStroke")
                                     stroke.Parent = text
                                     stroke.Thickness = 0.5 
                                     stroke.Transparency = 0 
                                     stroke.Color = Color3.new(0,0,0)
                                     
                                     bg.Parent = item
                                     
                                     highlights[item] = {bg = bg, text = text, adorn = adorn, color = color}
                                 end
                             else
                                -- Update distance and color
                                local data = highlights[item]
                                if data and data.adorn and data.text then
                                    local dist = (data.adorn.Position - hrp.Position).Magnitude
                                    data.text.Text = string.format("%s [%d]", item.Name, math.floor(dist))
                                    data.text.TextColor3 = data.color
                                end
                             end
                     end
                 end
                 
                 -- Cleanup
                 for item, data in pairs(highlights) do
                     if not item.Parent or not currentStepItems[item] then
                         if data.h then data.h:Destroy() end
                         if data.bg then data.bg:Destroy() end
                         highlights[item] = nil
                     end
                 end
            end
            task.wait(0.1)
        end
        
        for _, data in pairs(highlights) do
             if data.h then data.h:Destroy() end
             if data.bg then data.bg:Destroy() end
        end
        oreESPActive = false
    end)
end

local itemESPActive = false
function startItemESP()
    if itemESPActive then return end
    itemESPActive = true
    task.spawn(function()
        local highlights = {}   -- item -> {h, bg, text, adorn}
        local queries = {}
        local lastQuery = nil
        local count = 0
        local MAX_ITEMS = 200   -- safety cap so a broad search can't spawn thousands of ESPs
        local color = (Settings.ESPColors and Settings.ESPColors["Item ESP"]) or Color3.fromRGB(0, 255, 140)

        local function parseQueries()
            queries = {}
            for token in string.gmatch(Settings.ItemESPQuery or "", "([^,]+)") do
                local t = token:gsub("^%s+", ""):gsub("%s+$", ""):lower()
                if t ~= "" then table.insert(queries, t) end
            end
        end

        local function matches(item)
            if #queries == 0 then return false end
            local lname = item.Name:lower()
            for _, q in ipairs(queries) do
                if string.find(lname, q, 1, true) then return true end
            end
            return false
        end

        local function removeESP(item)
            local data = highlights[item]
            if data then
                if data.h then data.h:Destroy() end
                if data.bg then data.bg:Destroy() end
                highlights[item] = nil
                count = count - 1
            end
        end

        local function addESP(item)
            if highlights[item] or count >= MAX_ITEMS then return end
            local adorn
            if item:IsA("Model") then
                adorn = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart")
            elseif item:IsA("BasePart") then
                adorn = item
            end
            if not adorn then return end

            local bg = Instance.new("BillboardGui")
            bg.Name = "ItemESP"
            bg.Adornee = adorn
            bg.Size = UDim2.new(0, 200, 0, 50)
            bg.StudsOffset = Vector3.new(0, 2.5, 0)
            bg.AlwaysOnTop = true

            local text = Instance.new("TextLabel")
            text.Parent = bg
            text.Size = UDim2.new(1, 0, 1, 0)
            text.BackgroundTransparency = 1
            text.TextColor3 = color
            text.Font = Enum.Font.GothamBold
            text.TextSize = 12
            text.Text = item.Name

            local stroke = Instance.new("UIStroke")
            stroke.Parent = text
            stroke.Thickness = 0.5
            stroke.Color = Color3.new(0, 0, 0)

            local h = Instance.new("Highlight")
            h.FillColor = color
            h.FillTransparency = 0.6
            h.OutlineColor = Color3.new(1, 1, 1)
            h.Adornee = item
            h.Parent = item

            bg.Parent = item
            highlights[item] = { h = h, bg = bg, text = text, adorn = adorn }
            count = count + 1
        end

        local function rescanAll(folder)
            for item in pairs(highlights) do removeESP(item) end
            if folder then
                for _, item in ipairs(folder:GetChildren()) do
                    if matches(item) then addESP(item) end
                end
            end
        end

        local itemsFolder = workspace:FindFirstChild("Items") or workspace:WaitForChild("Items", 10)

        -- Event-driven: only react when items are added/removed (no full-folder polling).
        local addedConn, removedConn
        if itemsFolder then
            addedConn = itemsFolder.ChildAdded:Connect(function(item)
                if not Settings.ItemESPEnabled then return end
                task.wait() -- let PrimaryPart / parts populate
                if Settings.ItemESPEnabled and matches(item) then addESP(item) end
            end)
            removedConn = itemsFolder.ChildRemoved:Connect(function(item)
                removeESP(item)
            end)
        end

        -- Light maintenance loop: handle query changes + distance text over tracked items only.
        while Settings.ItemESPEnabled and not ScriptKilled do
            if Settings.ItemESPQuery ~= lastQuery then
                lastQuery = Settings.ItemESPQuery
                parseQueries()
                rescanAll(itemsFolder)
            end
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                for item, data in pairs(highlights) do
                    if item.Parent and data.adorn and data.adorn.Parent then
                        local dist = (data.adorn.Position - hrp.Position).Magnitude
                        data.text.Text = string.format("%s [%d]", item.Name, math.floor(dist))
                    else
                        removeESP(item)
                    end
                end
            end
            task.wait(0.3)
        end

        if addedConn then addedConn:Disconnect() end
        if removedConn then removedConn:Disconnect() end
        for item in pairs(highlights) do removeESP(item) end
        itemESPActive = false
    end)
end
end

function getESPOptionDistance(optionName)
    if Settings.ESPOptionDistances and Settings.ESPOptionDistances[optionName] then
        return Settings.ESPOptionDistances[optionName]
    end
    return 500
end



do
local tribeTotemESPActive = false
function startTribeTotemESP()
    if tribeTotemESPActive then return end
    tribeTotemESPActive = true
    task.spawn(function()
        local highlights = {} 
        
        while Settings.TribeTotemESPEnabled and not ScriptKilled do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                 local totemsFolder = workspace:FindFirstChild("Totems")
                 local currentStepTotems = {}

                 if totemsFolder then
                     for _, item in ipairs(totemsFolder:GetChildren()) do
                         local tribeColorObj = item:FindFirstChild("TribeColor")
                         if tribeColorObj then
                             currentStepTotems[item] = true
                             
                             if not highlights[item] then
                                 local adorn = item
                                 if item:IsA("Model") then adorn = item.PrimaryPart or item:FindFirstChildWhichIsA("BasePart") end
                                 
                                 if adorn then
                                     -- Determine Color
                                     local totemColor = Color3.fromRGB(255, 255, 255)
                                     local colorName = "Unknown"
                                     
                                     local tribeColorObj = item:FindFirstChild("TribeColor")
                                     if tribeColorObj then colorName = tostring(tribeColorObj.Value) end
                                     
                                     local coloration = item:FindFirstChild("Coloration")
                                     if coloration and coloration:IsA("BasePart") then
                                         totemColor = coloration.Color
                                     elseif tribeColorObj then
                                         pcall(function() totemColor = BrickColor.new(colorName).Color end)
                                     end
                                     
                                     -- Create Highlight
                                     local h = Instance.new("Highlight")
                                     h.FillColor = totemColor
                                     h.OutlineColor = totemColor
                                     h.FillTransparency = 0.5
                                     h.OutlineTransparency = 0
                                     h.Adornee = item
                                     h.Parent = item
                                     
                                     local bg = Instance.new("BillboardGui")
                                     bg.Name = "TotemESP"
                                     bg.Adornee = adorn
                                     bg.Size = UDim2.new(0, 200, 0, 50)
                                     bg.StudsOffset = Vector3.new(0, 5, 0)
                                     bg.AlwaysOnTop = true
                                     
                                     local text = Instance.new("TextLabel")
                                     text.Parent = bg
                                     text.Size = UDim2.new(1, 0, 1, 0)
                                     text.BackgroundTransparency = 1
                                     text.TextColor3 = totemColor 
                                     text.TextStrokeTransparency = 1 
                                     text.Font = Enum.Font.GothamBold
                                     text.TextSize = 12
                                     text.Text = string.format("[%s] Totem", colorName)
                                     
                                     local stroke = Instance.new("UIStroke")
                                     stroke.Parent = text
                                     stroke.Thickness = 0.5 
                                     stroke.Transparency = 0 
                                     stroke.Color = Color3.new(0,0,0)
                                     
                                     bg.Parent = item
                                     
                                     highlights[item] = {h = h, bg = bg, text = text, adorn = adorn, colorName = colorName}
                                 end
                             else
                                -- Update distance
                                local data = highlights[item]
                                if data and data.adorn and data.text then
                                    local dist = (data.adorn.Position - hrp.Position).Magnitude
                                    data.text.Text = string.format("[%s] Totem [%d]", data.colorName, math.floor(dist))
                                    -- Dynamic color update
                                    local coloration = item:FindFirstChild("Coloration")
                                    local newColor = data.h.FillColor -- Default to current
                                    if coloration and coloration:IsA("BasePart") then
                                        newColor = coloration.Color
                                    end
                                    
                                    if data.h then 
                                        data.h.FillColor = newColor 
                                        data.h.OutlineColor = newColor 
                                    end
                                    if data.text then 
                                        data.text.TextColor3 = newColor 
                                    end
                                end
                             end
                         end
                     end
                 end
                 
                 -- Cleanup
                 for item, data in pairs(highlights) do
                     if not item.Parent or not currentStepTotems[item] then
                         if data.h then data.h:Destroy() end
                         if data.bg then data.bg:Destroy() end
                         highlights[item] = nil
                     end
                 end
            end
            task.wait(0.1)
        end
        
        for _, data in pairs(highlights) do
             if data.h then data.h:Destroy() end
             if data.bg then data.bg:Destroy() end
        end
        tribeTotemESPActive = false
    end)
end
end

local meteorESPActive = false
local meteorHighlights = {}

local function getMeteorDisplayName(name)
    if name == "Meteor Core" then
        return "Magnetite Meteor Core"
    end
    return name
end

local function isMeteorCoreInstance(inst)
    if not inst or not inst.Parent then return false end
    local n = inst.Name
    if n == "Meteor Core" or n == "Crystal Meteor Core" then return true end
    return n:find("Meteor Core", 1, true) ~= nil
end

local function collectMeteorCores()
    local found = {}
    local seen = {}

    local function tryAdd(inst)
        if seen[inst] or not isMeteorCoreInstance(inst) then return end
        if not (inst:IsA("Model") or inst:IsA("BasePart")) then return end
        seen[inst] = true
        table.insert(found, inst)
    end

    for _, child in ipairs(workspace:GetChildren()) do
        tryAdd(child)
    end

    local meteorParts = workspace:FindFirstChild("MeteorParts")
    if meteorParts then
        for _, inst in ipairs(meteorParts:GetDescendants()) do
            tryAdd(inst)
        end
    end

    return found
end

local function getMeteorAdorn(meteor)
    if meteor:IsA("BasePart") then return meteor end
    if meteor:IsA("Model") then
        return meteor.PrimaryPart
            or meteor:FindFirstChild("Hitbox")
            or meteor:FindFirstChildWhichIsA("BasePart", true)
    end
    return nil
end

local function getMeteorPosition(meteor)
    local adorn = getMeteorAdorn(meteor)
    if adorn then return adorn.Position end
    local ok, pos = pcall(function() return meteor:GetPivot().Position end)
    if ok then return pos end
    return nil
end

function startMeteorESP()
    if meteorESPActive then return end
    meteorESPActive = true
    task.spawn(function()
        while Settings.MeteorCoreESPEnabled and not ScriptKilled do
            local currentMeteors = {}
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")

            for _, meteor in ipairs(collectMeteorCores()) do
                local adorn = getMeteorAdorn(meteor)
                if adorn then
                    currentMeteors[meteor] = true
                    local color = Settings.ESPColors["Meteor Core ESP"] or Color3.fromRGB(170, 85, 255)
                    local displayName = getMeteorDisplayName(meteor.Name)

                    if not meteorHighlights[meteor] then
                        local highlight = Instance.new("Highlight")
                        highlight.Name = "ESP_Highlight"
                        highlight.FillColor = color
                        highlight.OutlineColor = color
                        highlight.FillTransparency = 0.5
                        highlight.OutlineTransparency = 0
                        highlight.Adornee = meteor:IsA("Model") and meteor or adorn
                        highlight.Parent = meteor

                        local billboard = Instance.new("BillboardGui")
                        billboard.Name = "ESP_Billboard"
                        billboard.Adornee = adorn
                        billboard.Size = UDim2.new(0, 200, 0, 50)
                        billboard.StudsOffset = Vector3.new(0, 3, 0)
                        billboard.AlwaysOnTop = true
                        billboard.Parent = meteor

                        local textLabel = Instance.new("TextLabel")
                        textLabel.Name = "ESP_TextLabel"
                        textLabel.Parent = billboard
                        textLabel.BackgroundTransparency = 1
                        textLabel.Size = UDim2.new(1, 0, 1, 0)
                        textLabel.Font = Enum.Font.GothamBold
                        textLabel.TextSize = 14
                        textLabel.TextStrokeTransparency = 0.5
                        textLabel.TextColor3 = color
                        textLabel.Text = displayName

                        meteorHighlights[meteor] = {
                            highlight = highlight,
                            billboard = billboard,
                            textLabel = textLabel,
                            adorn = adorn,
                        }
                    else
                        local data = meteorHighlights[meteor]
                        if data.highlight then
                            data.highlight.FillColor = color
                            data.highlight.OutlineColor = color
                        end
                        if data.textLabel then
                            data.textLabel.TextColor3 = color
                            if hrp then
                                local pos = getMeteorPosition(meteor)
                                if pos then
                                    local dist = (pos - hrp.Position).Magnitude
                                    data.textLabel.Text = string.format("%s [%.0fm]", displayName, dist)
                                else
                                    data.textLabel.Text = displayName
                                end
                            else
                                data.textLabel.Text = displayName
                            end
                        end
                        if data.adorn ~= adorn then
                            data.adorn = adorn
                            if data.billboard then
                                data.billboard.Adornee = adorn
                            end
                        end
                    end
                end
            end

            for model, highlightStuff in pairs(meteorHighlights) do
                if not currentMeteors[model] then
                    if highlightStuff.highlight then highlightStuff.highlight:Destroy() end
                    if highlightStuff.billboard then highlightStuff.billboard:Destroy() end
                    meteorHighlights[model] = nil
                end
            end

            task.wait(0.15)
        end

        for model, highlightStuff in pairs(meteorHighlights) do
            if highlightStuff.highlight then highlightStuff.highlight:Destroy() end
            if highlightStuff.billboard then highlightStuff.billboard:Destroy() end
        end
        meteorHighlights = {}
        meteorESPActive = false
    end)
end -- AsterWorldESP

do -- AsterPlayerESP
local playerESPActive = false
function startPlayerESP()
    if playerESPActive then return end
    playerESPActive = true
    task.spawn(function()
        local esps = {} -- player -> {bg, text, h}
        
        local TribeColors = { 
             ["Yellow"] = Color3.fromRGB(255, 200, 0), 
             ["Green"] = Color3.fromRGB(0, 255, 0), 
             ["Red"] = Color3.fromRGB(255, 0, 0), 
             ["Violet"] = Color3.fromRGB(255, 39, 245), 
             ["Blue"] = Color3.fromRGB(13, 105, 172), 
             ["Grey"] = Color3.fromRGB(75, 75, 75), 
             ["Teal"] = Color3.fromRGB(88, 255, 219), 
             ["Olive"] = Color3.fromRGB(128, 128, 0), 
             ["White"] = Color3.fromRGB(200, 200, 200), 
             ["Black"] = Color3.fromRGB(0, 0, 0), 
             ["Orange"] = Color3.fromRGB(255, 170, 0), 
             ["Brown"] = Color3.fromRGB(124, 92, 70), 
             ["Maroon"] = Color3.fromRGB(128, 0, 0), 
             ["Purple"] = Color3.fromRGB(61, 21, 133) 
         }

        local function getESPCharacter(player)
            if not player then return nil end
            local playersFolder = workspace:FindFirstChild("Players")
            if playersFolder then
                local customChar = playersFolder:FindFirstChild(player.Name)
                if customChar then return customChar end
            end
            return player.Character
        end

        local function getESPCharacterHumanoid(player)
            local char = getESPCharacter(player)
            return char and (char:FindFirstChildOfClass("Humanoid") or char:FindFirstChild("Humanoid"))
        end

        local ESP_HITBOX_W_SCALE = 3.5
        local ESP_HITBOX_H_SCALE = 6.7
        local ESP_HEALTH_WIDTH_RATIO = 0.14

        local function applyFixedOverlayLayout(bill, showHealth, showHitbox, hitboxColor)
            if not bill then return end
            bill.Size = UDim2.new(ESP_HITBOX_W_SCALE, 0, ESP_HITBOX_H_SCALE, 0)

            local hitboxFrame = bill:FindFirstChild("Box")
            local healthBg = bill:FindFirstChild("HealthBg")
                or (hitboxFrame and hitboxFrame:FindFirstChild("HealthBg"))

            if hitboxFrame then
                hitboxFrame.Visible = showHealth or showHitbox
                hitboxFrame.Position = UDim2.new(0, 0, 0, 0)
                hitboxFrame.Size = UDim2.new(1, 0, 1, 0)
                local outline = hitboxFrame:FindFirstChild("Outline")
                if outline then
                    outline.Transparency = showHitbox and 0 or 1
                    if hitboxColor then
                        outline.Color = hitboxColor
                    end
                end
            end

            if healthBg then
                healthBg.Visible = showHealth
                healthBg.Position = UDim2.new(0, 0, 0, 0)
                healthBg.Size = UDim2.new(ESP_HEALTH_WIDTH_RATIO, 0, 1, 0)
                healthBg.ZIndex = 2
            end
        end

        local function updatePlayersHealthBar(data, hum)
            local fill = data and (data.healthFill or data.godHealthFill)
            if not fill or not hum or hum.MaxHealth <= 0 then return end
            local hp = math.clamp(hum.Health / hum.MaxHealth, 0, 1)
            fill.Size = UDim2.new(1, 0, hp, 0)
            fill.BackgroundColor3 = Color3.fromHSV(hp * 0.33, 1, 1)
        end

        local function clearPlayersHealthBindings(data)
            if not data then return end
            if data.healthConn then
                data.healthConn:Disconnect()
                data.healthConn = nil
            end
            if data.maxHealthConn then
                data.maxHealthConn:Disconnect()
                data.maxHealthConn = nil
            end
            data.healthHum = nil
        end

        local function bindPlayersHealthChanged(player, data)
            clearPlayersHealthBindings(data)
            local hum = getESPCharacterHumanoid(player)
            if not hum then return end
            data.healthHum = hum
            updatePlayersHealthBar(data, hum)
            data.healthConn = hum.HealthChanged:Connect(function()
                if Settings.ESP_ShowPlayersHealth and (data.healthBill or data.godHealthFill) and (data.healthFill or data.godHealthFill) then
                    if data.healthBill then data.healthBill.Enabled = true end
                    updatePlayersHealthBar(data, hum)
                end
            end)
            data.maxHealthConn = hum:GetPropertyChangedSignal("MaxHealth"):Connect(function()
                if Settings.ESP_ShowPlayersHealth and (data.healthBill or data.godHealthFill) and (data.healthFill or data.godHealthFill) then
                    updatePlayersHealthBar(data, hum)
                end
            end)
        end

        local function cleanupLocalESPHitboxes()
            local myChar = getESPCharacter(plr) or plr.Character
            if not myChar then return end
            for _, name in ipairs({"ESPHitboxVisual", "GodESPHitboxVisual", "PlayersHealthESP"}) do
                local stray = myChar:FindFirstChild(name, true)
                if stray then stray:Destroy() end
            end
        end

        local function ensureESPOverlay(char, data, key, showHitbox, showHealth, hitboxColor)
            if not char or not data then return end
            key = key or "espOverlay"
            if not showHitbox and not showHealth then
                if data[key] then data[key]:Destroy() end
                data[key] = nil
                if key == "godEspOverlay" then
                    data.godHealthFill = nil
                else
                    data.healthBill = nil
                    data.healthFill = nil
                    data.hitboxPart = nil
                end
                return
            end

            local hrp = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
            if not hrp then return end

            local bill = data[key]
            if not bill or not bill.Parent then
                bill = Instance.new("BillboardGui")
                bill.Name = key == "godEspOverlay" and "GodESPHitboxVisual" or "ESPHitboxVisual"
                bill.Adornee = hrp
                bill.AlwaysOnTop = true
                bill.LightInfluence = 0
                bill.MaxDistance = 0
                bill.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
                bill.StudsOffset = Vector3.new(0, 0.3, 0)
                bill.Parent = char

                local hitboxFrame = Instance.new("Frame")
                hitboxFrame.Name = "Box"
                hitboxFrame.BackgroundTransparency = 1
                hitboxFrame.BorderSizePixel = 0
                hitboxFrame.Parent = bill

                local outline = Instance.new("UIStroke")
                outline.Name = "Outline"
                outline.Thickness = 1
                outline.Parent = hitboxFrame

                local healthBg = Instance.new("Frame")
                healthBg.Name = "HealthBg"
                healthBg.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
                healthBg.BorderSizePixel = 0
                healthBg.ZIndex = 2
                healthBg.Parent = hitboxFrame

                local healthStroke = Instance.new("UIStroke")
                healthStroke.Color = Color3.fromRGB(0, 0, 0)
                healthStroke.Thickness = 1.5
                healthStroke.Parent = healthBg

                local healthFill = Instance.new("Frame")
                healthFill.Name = "HealthFill"
                healthFill.BackgroundColor3 = Color3.fromRGB(80, 255, 80)
                healthFill.BorderSizePixel = 0
                healthFill.AnchorPoint = Vector2.new(0, 1)
                healthFill.Position = UDim2.new(0, 0, 1, 0)
                healthFill.Size = UDim2.new(1, 0, 1, 0)
                healthFill.Parent = healthBg

                local uic = Instance.new("UICorner")
                uic.CornerRadius = UDim.new(1, 0)
                uic.Parent = healthBg
                local uic2 = Instance.new("UICorner")
                uic2.CornerRadius = UDim.new(1, 0)
                uic2.Parent = healthFill

                data[key] = bill
                if key == "godEspOverlay" then
                    data.godHealthFill = healthFill
                else
                    data.healthBill = bill
                    data.healthFill = healthFill
                    data.hitboxPart = bill
                end
            end

            bill = data[key]
            bill.Adornee = hrp
            bill.Enabled = true
            applyFixedOverlayLayout(bill, showHealth, showHitbox, hitboxColor)
        end

        local function destroyPlayerESP(data)
            if not data then return end
            clearPlayersHealthBindings(data)
            if data.bg then data.bg:Destroy() end
            if data.h then data.h:Destroy() end
            if data.espOverlay then data.espOverlay:Destroy() end
            if data.godEspOverlay then data.godEspOverlay:Destroy() end
            if data.godBg then data.godBg:Destroy() end
            if data.godH then data.godH:Destroy() end
            if data.godHealthBill then data.godHealthBill:Destroy() end
        end
        
        local function isGodPlayerCharacter(char)
            if not char then return false end
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hum and hum.MaxHealth > 1000 then
                return true
            end
            for _, pieceName in ipairs({"God Halo", "God Chestplate", "God Legs"}) do
                if char:FindFirstChild(pieceName) then
                    return true
                end
            end
            return false
        end

        local function getGodArmorCount(char)
            local count = 0
            for _, pieceName in ipairs({"God Halo", "God Chestplate", "God Legs"}) do
                if char:FindFirstChild(pieceName) then
                    count = count + 1
                end
            end
            return count
        end

        local function shouldUseGodPlayerEsp(char, dist)
            if Settings.ESP_ShowGodPlayer ~= true or not isGodPlayerCharacter(char) then
                return false
            end
            dist = dist or math.huge
            return dist <= getESPOptionDistance("GodPlayer Esp")
        end

        local function buildPlayerEspLabel(player, char, dist, useGodPlayerEsp)
            local str = ""
            if Settings.ESP_ShowNames and dist <= getESPOptionDistance("Show Names") then
                str = player.Name
            end

            if useGodPlayerEsp then
                if str ~= "" then
                    str = str .. " God"
                else
                    str = "God"
                end
            end

            if Settings.ESP_ShowDistance and dist <= getESPOptionDistance("Show Distance") then
                if str ~= "" then
                    str = str .. string.format(" [%d]", math.floor(dist))
                else
                    str = string.format("[%d]", math.floor(dist))
                end
            end

            if useGodPlayerEsp and Settings.ESP_ShowGodArmor and dist <= getESPOptionDistance("GodArmor Pieces") then
                if str ~= "" then str = str .. " " end
                str = str .. string.format("[%d/3]", getGodArmorCount(char))
            end

            return str
        end

        local function getPlayerEspColor(player, char, dist, useGodPlayerEsp)
            if useGodPlayerEsp then
                local godColor = Settings.ESPColors["GodESP"]
                if typeof(godColor) == "Color3" then
                    return godColor
                elseif type(godColor) == "table" and godColor.R then
                    return Color3.new(godColor.R, godColor.G, godColor.B)
                end
                return Color3.fromRGB(255, 255, 0)
            end
            local col = Color3.fromRGB(255, 105, 180)
            if Settings.ESP_UseTeamColor == true and dist <= getESPOptionDistance("Use Team Color") then
                if player.Team and TribeColors[player.Team.Name] then
                    col = TribeColors[player.Team.Name]
                end
            elseif Settings.ESPColors["PlayerESP"] then
                local c = Settings.ESPColors["PlayerESP"]
                if typeof(c) == "Color3" then
                    col = c
                elseif type(c) == "table" and c.R then
                    col = Color3.new(c.R, c.G, c.B)
                end
            end
            return col
        end

        while Settings.PlayerESPEnabled and not ScriptKilled do
            local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if hrp then
                cleanupLocalESPHitboxes()
                 for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
                     if player == plr then continue end
                     local char = getESPCharacter(player)
                     if not char or not char.Parent then
                         if esps[player] then
                             destroyPlayerESP(esps[player])
                             esps[player] = nil
                         end
                         continue
                     end

                         -- Check for Teams if option is enabled (Exception for NoTribe)
                        if Settings.HideTeams and player.Team == plr.Team and player.Team.Name ~= "NoTribe" then
                            -- If currently showing, destroy it
                             if esps[player] then 
                                 destroyPlayerESP(esps[player])
                                 esps[player] = nil
                             end
                             continue 
                         end

                         local ppart = char:FindFirstChild("HumanoidRootPart") or char.PrimaryPart
                         
                         if ppart then
                            local playerDist = (ppart.Position - hrp.Position).Magnitude
                            local useGodPlayerEsp = shouldUseGodPlayerEsp(char, playerDist)

                            if not esps[player] or not esps[player].bg or not esps[player].bg.Parent or esps[player].bg.Adornee ~= (char:FindFirstChild("Head") or ppart) then
                                 -- Cleanup old if exists (e.g. respawn)
                                 if esps[player] then
                                     destroyPlayerESP(esps[player])
                                 end
                                 
                                 -- Create Highlight
                                local h = Instance.new("Highlight")
                                local col = getPlayerEspColor(player, char, playerDist, useGodPlayerEsp)
                                h.FillColor = col 
                                h.OutlineColor = col
                                h.FillTransparency = 0.5
                                h.OutlineTransparency = 0
                                h.Adornee = char
                                h.Parent = char
                                
                                local bg = Instance.new("BillboardGui")
                                bg.Name = "PlayerESP"
                                 bg.Adornee = char:FindFirstChild("Head") or ppart
                                bg.Size = UDim2.new(0, 200, 0, 50)
                                bg.StudsOffset = Vector3.new(0, 5.0, 0) -- Moved back to 5.0
                                bg.AlwaysOnTop = true
                                
                                local text = Instance.new("TextLabel")
                                text.Parent = bg
                                text.Size = UDim2.new(1, 0, 1, 0)
                                text.BackgroundTransparency = 1
                                text.TextColor3 = col -- Match Highlight Color
                                text.TextStrokeTransparency = 1 -- Disable default stroke
                                text.Font = Enum.Font.GothamBold
                                text.TextSize = 12 -- Match Merchant
                                text.Text = buildPlayerEspLabel(player, char, playerDist, useGodPlayerEsp)
                                
                                local stroke = Instance.new("UIStroke")
                                stroke.Parent = text
                                stroke.Thickness = 0.5 -- Match Merchant
                                stroke.Transparency = 0
                                stroke.Color = Color3.new(0,0,0) -- Black Outline
                                 
                                bg.Parent = char
                                
                                esps[player] = {bg = bg, text = text, adorn = ppart, h = h, healthChar = getESPCharacter(player) or char}
                            end
                            
                            -- Dynamic Color Update (Runs every frame to ensure responsiveness)
                            if esps[player] then
                                local data = esps[player]
                                local dist = data.adorn and hrp and (data.adorn.Position - hrp.Position).Magnitude or math.huge
                                local useGodPlayerEsp = shouldUseGodPlayerEsp(char, dist)
                                local targetCol = getPlayerEspColor(player, char, dist, useGodPlayerEsp)
                                -- Apply changes if color differs
                                -- Force update on toggle switch
                                if data.h.FillColor ~= targetCol then
                                    data.h.FillColor = targetCol
                                    data.h.OutlineColor = targetCol
                                    if data.text then data.text.TextColor3 = targetCol end
                                end
                            end
                         end
                 end
                 
                 -- Update distances and cleanup
                 for player, data in pairs(esps) do
                     if not player.Parent then
                         destroyPlayerESP(data)
                         esps[player] = nil
                     else
                        local char = getESPCharacter(player)
                        if player == plr or not char or not char.Parent then
                            destroyPlayerESP(data)
                            esps[player] = nil
                        -- Re-check team status dynamically (e.g. if they switch teams mid-game)
                        elseif Settings.HideTeams and player.Team == plr.Team and player.Team.Name ~= "NoTribe" then
                             destroyPlayerESP(data)
                             esps[player] = nil
                         elseif data.adorn and data.adorn.Parent then
                            local dist = (data.adorn.Position - hrp.Position).Magnitude
                            local useGodPlayerEsp = shouldUseGodPlayerEsp(char, dist)
                            local col = getPlayerEspColor(player, char, dist, useGodPlayerEsp)
                            if data.text then 
                                data.text.TextColor3 = col
                                
                                local str = buildPlayerEspLabel(player, char, dist, useGodPlayerEsp)
                                if str ~= "" then
                                    data.text.Visible = true
                                    data.text.Text = str
                                else
                                    data.text.Visible = false
                                end
                            end
                            if data.h then 
                                data.h.OutlineColor = col 
                                data.h.FillColor = col 
                                
                                -- Highlight Toggle Logic
                                data.h.Enabled = Settings.ESP_ShowHighlight == true and dist <= getESPOptionDistance("Show Highlight")
                            end

                            local espChar = data.healthChar or getESPCharacter(player) or char
                            local showHitbox = Settings.ESP_ShowHitbox == true and dist <= getESPOptionDistance("Show Hitbox")
                            local showHealth = Settings.ESP_ShowPlayersHealth == true and dist <= getESPOptionDistance("Show PlayersHealth")
                            ensureESPOverlay(espChar, data, "espOverlay", showHitbox, showHealth, col)
                            if showHealth then
                                local hum = getESPCharacterHumanoid(player)
                                if hum and data.healthFill then
                                    if data.healthHum ~= hum then
                                        bindPlayersHealthChanged(player, data)
                                    end
                                    updatePlayersHealthBar(data, hum)
                                end
                            end
                            
                         else
                            destroyPlayerESP(data)
                            esps[player] = nil
                        end
                     end
                 end
            end
            task.wait(0.1)
        end
        
        for _, data in pairs(esps) do
            destroyPlayerESP(data)
        end
        playerESPActive = false
    end)
end
end -- AsterPlayerESP

do -- AsterStaffDetection
local BOOGA_STAFF_GROUP_ID = 15829231
-- Group dropdown order (low -> high rank). Clan Owner+ display as "Staff" in-game.
local BOOGA_GROUP_ROLE_ORDER = {
    "VIP",
    "Content Creator",
    "Clan Owner",
    "Roblox Verified",
    "Evaluator",
    "Staff",
    "Admin",
    "Manager",
    "Owner",
}
local BOOGA_GROUP_ROLE_RANK = {}
for i, name in ipairs(BOOGA_GROUP_ROLE_ORDER) do
    BOOGA_GROUP_ROLE_RANK[string.lower(name)] = i
end
local BOOGA_STAFF_DISPLAY_RANK = BOOGA_GROUP_ROLE_RANK["clan owner"]
local BOOGA_CAUTIOUS_MAX_RANK = BOOGA_GROUP_ROLE_RANK["content creator"]

local staffDetectionActive = false
local lastStaffAlertKey = ""
local lastCautiousAlertKey = ""
local staffEspData = {}

local function getStaffDetectionCharacter(player)
    if not player then return nil end
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local customChar = playersFolder:FindFirstChild(player.Name)
        if customChar then return customChar end
    end
    return player.Character
end

local function formatStaffRoleLabel(role)
    local label = role:match("|%s*(.+)$") or role
    return (label:gsub("^%s+", ""):gsub("%s+$", ""))
end

local function normalizeBoogaRoleName(role)
    local label = formatStaffRoleLabel(role)
    label = label:gsub("-", " ")
    return string.lower(label)
end

local function getBoogaRoleRank(role)
    if not role or role == "" or role == "Guest" then
        return nil
    end
    local label = normalizeBoogaRoleName(role)
    local exact = BOOGA_GROUP_ROLE_RANK[label]
    if exact then
        return exact
    end
    local bestRank, bestLen = nil, 0
    for name, rank in pairs(BOOGA_GROUP_ROLE_RANK) do
        if label:find(name, 1, true) and #name > bestLen then
            bestRank, bestLen = rank, #name
        end
    end
    return bestRank
end

local function isBoogaTrackedGroupRole(role)
    return getBoogaRoleRank(role) ~= nil
end

local function getBoogaRolePublicLabel(role)
    local rank = getBoogaRoleRank(role)
    if not rank then
        return formatStaffRoleLabel(role)
    end
    if rank >= BOOGA_STAFF_DISPLAY_RANK then
        return "Staff"
    end
    return formatStaffRoleLabel(role)
end

local function isBoogaCautiousRole(role)
    local rank = getBoogaRoleRank(role)
    return rank ~= nil and rank <= BOOGA_CAUTIOUS_MAX_RANK
end

local function shouldBoogaStaffAlert(role)
    local rank = getBoogaRoleRank(role)
    return rank ~= nil and rank >= BOOGA_STAFF_DISPLAY_RANK
end

local function getStaffRoleColor(roleLabel, showCaution)
    if showCaution then
        return Color3.fromRGB(255, 170, 40)
    end
    local lower = string.lower(roleLabel or "")
    if lower == "staff" then
        return Color3.fromRGB(90, 150, 255)
    end
    return Color3.fromRGB(255, 210, 60)
end

local function getBoogaGroupRole(player)
    if not player or player == plr then
        return nil
    end
    local okInGroup, inGroup = pcall(function()
        return player:IsInGroup(BOOGA_STAFF_GROUP_ID)
    end)
    if not okInGroup or not inGroup then
        return nil
    end
    local okRole, role = pcall(function()
        return player:GetRoleInGroup(BOOGA_STAFF_GROUP_ID)
    end)
    if not okRole or not isBoogaTrackedGroupRole(role) then
        return nil
    end
    return role
end

local function getStaffAlertGui()
    local gui = asterFindGui("AsterStaffAlertGui")
    if gui then return gui end
    gui = Instance.new("ScreenGui")
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 1000
    if game:GetService("RunService"):IsStudio() then
        gui.Name = asterGuiCoverName("AsterStaffAlertGui")
        gui.Parent = plr:WaitForChild("PlayerGui")
    else
        asterParentGui(gui, "AsterStaffAlertGui")
    end
    return gui
end

local function buildStaffAlertKey(staffMembers)
    local ids = {}
    for _, entry in ipairs(staffMembers) do
        table.insert(ids, tostring(entry.userId))
    end
    table.sort(ids)
    return table.concat(ids, ",")
end

local function collectStaffInServer()
    local staffMembers = {}
    local cautiousMembers = {}
    local groupMembers = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= plr then
            local role = getBoogaGroupRole(player)
            if role then
                local entry = {
                    userId = player.UserId,
                    name = player.Name,
                    roleLabel = getBoogaRolePublicLabel(role),
                    showCaution = isBoogaCautiousRole(role),
                }
                table.insert(groupMembers, entry)
                if entry.showCaution then
                    table.insert(cautiousMembers, entry)
                else
                    table.insert(staffMembers, entry)
                end
            end
        end
    end
    local sortByName = function(a, b)
        return a.name:lower() < b.name:lower()
    end
    table.sort(groupMembers, sortByName)
    table.sort(staffMembers, sortByName)
    table.sort(cautiousMembers, sortByName)
    return staffMembers, cautiousMembers, groupMembers
end

local function getStaffAlertThemeColors()
    local theme = CurrentTheme or Themes.Premium or Themes.Starfield
    return {
        background = UI.Surface.Card,
        accent = theme.Main,
        text = UI.Surface.Text,
        muted = UI.Surface.Muted,
    }
end

local function showGroupDetectionAlert(alertTitle, members, buildBodyText)
    if not members or #members == 0 then return end

    local bodyText = buildBodyText(members)
    if not bodyText or bodyText == "" then return end

    local themeColors = getStaffAlertThemeColors()
    local lineCount = math.max(1, math.ceil(#bodyText / 42))
    local toastHeight = 52 + (lineCount * 16)
    local toastTransparency = math.clamp(GlobalTransparency or 0, 0, 0.35)

    local gui = getStaffAlertGui()
    local toast = Instance.new("Frame")
    toast.Name = "StaffAlert_" .. tostring(tick())
    toast.Size = UDim2.fromOffset(420, toastHeight)
    toast.Position = UDim2.new(0.5, -210, 0, 18)
    toast.BackgroundColor3 = themeColors.background
    toast.BackgroundTransparency = toastTransparency
    toast.BorderSizePixel = 0
    toast.Parent = gui

    uiCorner(toast, UI.Radius.md)

    local stroke = uiStroke(toast, 1.5, 0.25, themeColors.accent)
    ApplyGradient(stroke)

    local accentBar = Instance.new("Frame", toast)
    accentBar.Size = UDim2.new(1, -24, 0, 2)
    accentBar.Position = UDim2.fromOffset(12, 8)
    accentBar.BorderSizePixel = 0
    accentBar.BackgroundColor3 = themeColors.accent
    ApplyGradient(accentBar)
    uiCorner(accentBar, UI.Radius.sm)

    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Position = UDim2.fromOffset(14, 14)
    title.Size = UDim2.new(1, -28, 0, 22)
    title.Font = UI.FontTitle
    title.TextSize = 16
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.Text = alertTitle
    title.Parent = toast
    applyHollowEffect(title, 1.1, true)

    local body = Instance.new("TextLabel")
    body.BackgroundTransparency = 1
    body.Position = UDim2.fromOffset(14, 38)
    body.Size = UDim2.new(1, -28, 1, -46)
    body.Font = UI.FontLabel
    body.TextSize = 13
    body.TextXAlignment = Enum.TextXAlignment.Left
    body.TextYAlignment = Enum.TextYAlignment.Top
    body.TextWrapped = true
    body.TextColor3 = themeColors.muted
    body.Text = bodyText
    body.Parent = toast

    toast.BackgroundTransparency = 1
    title.TextTransparency = 1
    body.TextTransparency = 1
    accentBar.BackgroundTransparency = 1
    stroke.Transparency = 1
    local titleStroke = title:FindFirstChild("UIStroke")
    if titleStroke then titleStroke.Transparency = 1 end

    tweenProp(toast, { BackgroundTransparency = toastTransparency }, UI.Ease.Med)
    tweenProp(title, { TextTransparency = 0 }, UI.Ease.Med)
    tweenProp(body, { TextTransparency = 0 }, UI.Ease.Med)
    tweenProp(accentBar, { BackgroundTransparency = 0 }, UI.Ease.Med)
    tweenProp(stroke, { Transparency = 0.25 }, UI.Ease.Med)
    if titleStroke then tweenProp(titleStroke, { Transparency = 0 }, UI.Ease.Med) end

    task.delay(6, function()
        if not toast or not toast.Parent then return end
        tweenProp(toast, { BackgroundTransparency = 1 }, UI.Ease.Smooth)
        tweenProp(title, { TextTransparency = 1 }, UI.Ease.Smooth)
        tweenProp(body, { TextTransparency = 1 }, UI.Ease.Smooth)
        tweenProp(accentBar, { BackgroundTransparency = 1 }, UI.Ease.Smooth)
        tweenProp(stroke, { Transparency = 1 }, UI.Ease.Smooth)
        if titleStroke then tweenProp(titleStroke, { Transparency = 1 }, UI.Ease.Smooth) end
        task.delay(0.4, function()
            if toast then toast:Destroy() end
        end)
    end)
end

local function showStaffDetectionAlert(staffMembers)
    local title = #staffMembers == 1 and "Staff Detected" or string.format("Staff Detected (%d)", #staffMembers)
    showGroupDetectionAlert(title, staffMembers, function(members)
        if #members == 1 then
            return string.format("%s is in server (%s)", members[1].name, members[1].roleLabel)
        end
        local names = {}
        for _, entry in ipairs(members) do
            table.insert(names, entry.name)
        end
        return "Staff in server: " .. table.concat(names, ", ")
    end)
end

local function showCautiousDetectionAlert(cautiousMembers)
    local title = #cautiousMembers == 1 and "Be Careful" or string.format("Be Careful (%d)", #cautiousMembers)
    showGroupDetectionAlert(title, cautiousMembers, function(members)
        local lines = {}
        for _, entry in ipairs(members) do
            table.insert(lines, string.format("%s is in server (%s) - Be Careful", entry.name, entry.roleLabel))
        end
        return table.concat(lines, "\n")
    end)
end

local function destroyStaffDetectionESP(player)
    local data = staffEspData[player]
    if not data then return end
    if data.h then data.h:Destroy() end
    if data.bg then data.bg:Destroy() end
    staffEspData[player] = nil
end

local function formatStaffDetectionEspText(player, roleLabel, showCaution)
    if showCaution then
        return string.format("%s\n[%s]\nBe Careful", player.Name, roleLabel)
    end
    return string.format("%s\n[%s]", player.Name, roleLabel)
end

local function ensureStaffDetectionESP(player, roleLabel, showCaution)
    showCaution = showCaution == true
    local char = getStaffDetectionCharacter(player)
    if not char then
        destroyStaffDetectionESP(player)
        return
    end

    local adorn = char:FindFirstChild("Head") or char:FindFirstChild("HumanoidRootPart") or char:FindFirstChildWhichIsA("BasePart")
    if not adorn then
        destroyStaffDetectionESP(player)
        return
    end

    local color = getStaffRoleColor(roleLabel, showCaution)
    local espText = formatStaffDetectionEspText(player, roleLabel, showCaution)
    local data = staffEspData[player]
    if not data or not data.h or not data.h.Parent or data.h.Adornee ~= char
        or not data.bg or not data.bg.Parent or data.bg.Adornee ~= adorn then
        destroyStaffDetectionESP(player)

        local h = Instance.new("Highlight")
        h.Name = "StaffDetectionHighlight"
        h.FillColor = color
        h.OutlineColor = color
        h.FillTransparency = 0.45
        h.OutlineTransparency = 0
        h.Adornee = char
        h.Parent = char

        local bg = Instance.new("BillboardGui")
        bg.Name = "StaffDetectionESP"
        bg.Adornee = adorn
        bg.Size = UDim2.new(0, 220, 0, showCaution and 72 or 56)
        bg.StudsOffset = Vector3.new(0, 5.5, 0)
        bg.AlwaysOnTop = true
        bg.Parent = char

        local text = Instance.new("TextLabel")
        text.BackgroundTransparency = 1
        text.Size = UDim2.new(1, 0, 1, 0)
        text.Font = Enum.Font.GothamBold
        text.TextSize = 14
        text.TextColor3 = color
        text.TextStrokeTransparency = 1
        text.Text = espText
        text.Parent = bg

        local textStroke = Instance.new("UIStroke")
        textStroke.Thickness = 0.6
        textStroke.Color = Color3.new(0, 0, 0)
        textStroke.Parent = text

        staffEspData[player] = { h = h, bg = bg, text = text }
        return
    end

    data.h.FillColor = color
    data.h.OutlineColor = color
    data.bg.Size = UDim2.new(0, 220, 0, showCaution and 72 or 56)
    data.text.TextColor3 = color
    data.text.Text = espText
end

do -- AsterRecordingMode
local recordingModeActive = false
local RECORDING_STAT_TEXT = "Inf - AsterHub"
local RECORDING_NAME = "AsterHub"
local recordingSavedTopbar = {}
local recordingSavedNameLabels = {}

local function getRecordingNameHints()
    local hints = { plr.Name }
    if ASTER.RecordingModeSavedDisplayName and ASTER.RecordingModeSavedDisplayName ~= plr.Name then
        table.insert(hints, ASTER.RecordingModeSavedDisplayName)
    end
    local displayName = plr.DisplayName
    if displayName and displayName ~= plr.Name then
        table.insert(hints, displayName)
    end
    return hints
end

local function spoofRecordingNameLabels(root)
    if not root then return end
    local hints = getRecordingNameHints()
    for _, desc in ipairs(root:GetDescendants()) do
        if desc:IsA("TextLabel") or desc:IsA("TextButton") then
            local currentText = desc.Text
            if currentText ~= RECORDING_NAME then
                for _, hint in ipairs(hints) do
                    if hint and hint ~= "" and currentText == hint then
                        if not recordingSavedNameLabels[desc] then
                            recordingSavedNameLabels[desc] = currentText
                        end
                        desc.Text = RECORDING_NAME
                        break
                    end
                end
            end
        end
    end
end

local function getRecordingPlayerListRoot()
    local playerGui = plr:FindFirstChild("PlayerGui")
    if not playerGui then return nil end
    local secondaryGui = playerGui:FindFirstChild("SecondaryGui")
    if not secondaryGui then return nil end
    return secondaryGui:FindFirstChild("PlayerList")
end

local function getRecordingTopbarRefs()
    local playerGui = plr:FindFirstChild("PlayerGui")
    if not playerGui then return nil end
    local topbar = playerGui:FindFirstChild("Topbar")
    if not topbar then return nil end
    local tb = topbar:FindFirstChild("Topbar")
    if not tb then return nil end
    local left = tb:FindFirstChild("Left")
    local right = tb:FindFirstChild("Right")
    if not left or not right then return nil end
    local coins = left:FindFirstChild("Coins")
    local mojo = left:FindFirstChild("Mojo")
    local levelFrame = right:FindFirstChild("Level")
    return {
        coinsLabel = coins and coins:FindFirstChild("Label"),
        mojoLabel = mojo and mojo:FindFirstChild("Label"),
        expLabel = levelFrame and levelFrame:FindFirstChild("Exp"),
        topbarRoot = topbar,
    }
end

local function applyRecordingModeSpoofs()
    local refs = getRecordingTopbarRefs()
    if refs then
        local statLabels = {
            coinsLabel = refs.coinsLabel,
            mojoLabel = refs.mojoLabel,
            expLabel = refs.expLabel,
        }
        for key, label in pairs(statLabels) do
            if label and (label:IsA("TextLabel") or label:IsA("TextButton")) then
                if recordingSavedTopbar[key] == nil then
                    recordingSavedTopbar[key] = label.Text
                end
                label.Text = RECORDING_STAT_TEXT
            end
        end
        spoofRecordingNameLabels(refs.topbarRoot)
    end

    spoofRecordingNameLabels(getRecordingPlayerListRoot())

    pcall(function()
        if sethiddenproperty then
            sethiddenproperty(plr, "DisplayName", RECORDING_NAME)
        end
    end)
end

local function restoreRecordingModeSpoofs()
    local refs = getRecordingTopbarRefs()
    if refs then
        local statLabels = {
            coinsLabel = refs.coinsLabel,
            mojoLabel = refs.mojoLabel,
            expLabel = refs.expLabel,
        }
        for key, label in pairs(statLabels) do
            local saved = recordingSavedTopbar[key]
            if label and saved ~= nil then
                label.Text = saved
            end
        end
    end

    for label, savedText in pairs(recordingSavedNameLabels) do
        if label and label.Parent and savedText ~= nil then
            label.Text = savedText
        end
    end

    pcall(function()
        if sethiddenproperty and ASTER.RecordingModeSavedDisplayName then
            sethiddenproperty(plr, "DisplayName", ASTER.RecordingModeSavedDisplayName)
        end
    end)

    recordingSavedTopbar = {}
    recordingSavedNameLabels = {}
    ASTER.RecordingModeSavedDisplayName = nil
end

function startRecordingMode()
    if recordingModeActive then return end
    recordingModeActive = true
    ASTER.RecordingModeSavedDisplayName = plr.DisplayName

    task.spawn(function()
        if not getRecordingTopbarRefs() and not getRecordingPlayerListRoot() then
            local playerGui = plr:FindFirstChild("PlayerGui") or plr:WaitForChild("PlayerGui", 10)
            if playerGui then
                if not playerGui:FindFirstChild("Topbar") then
                    playerGui:WaitForChild("Topbar", 8)
                end
                if not playerGui:FindFirstChild("SecondaryGui") then
                    playerGui:WaitForChild("SecondaryGui", 8)
                end
            end
        end
        if Settings.RecordingMode and recordingModeActive then
            pcall(applyRecordingModeSpoofs)
        end
    end)
end

function stopRecordingMode()
    if not recordingModeActive then return end
    recordingModeActive = false
    pcall(restoreRecordingModeSpoofs)
end
end -- AsterRecordingMode

function startStaffDetection()
    if staffDetectionActive then return end
    staffDetectionActive = true
    lastStaffAlertKey = ""
    lastCautiousAlertKey = ""

    task.spawn(function()
        while (Settings.StaffDetectionsEnabled or Settings.LeaveOnStaff) and not ScriptKilled do
            local staffMembers, cautiousMembers, groupMembers = collectStaffInServer()
            local seenStaff = {}

            if Settings.StaffDetectionsEnabled then
                for _, entry in ipairs(groupMembers) do
                    local player = Players:GetPlayerByUserId(entry.userId)
                    if player then
                        seenStaff[player] = true
                        ensureStaffDetectionESP(player, entry.roleLabel, entry.showCaution)
                    end
                end

                for player in pairs(staffEspData) do
                    if not player.Parent or not seenStaff[player] then
                        destroyStaffDetectionESP(player)
                    end
                end

                if #staffMembers > 0 then
                    local alertKey = buildStaffAlertKey(staffMembers)
                    if alertKey ~= lastStaffAlertKey then
                        lastStaffAlertKey = alertKey
                        showStaffDetectionAlert(staffMembers)
                    end
                else
                    lastStaffAlertKey = ""
                end

                if #cautiousMembers > 0 then
                    local alertKey = buildStaffAlertKey(cautiousMembers)
                    if alertKey ~= lastCautiousAlertKey then
                        lastCautiousAlertKey = alertKey
                        showCautiousDetectionAlert(cautiousMembers)
                    end
                else
                    lastCautiousAlertKey = ""
                end
            end

            if Settings.LeaveOnStaff and #staffMembers > 0 then
                local leaveConfigName = "Asterhub - Leave on Staff Members"
                pcall(function()
                    if ASTER and ASTER.ConfigSystem and ASTER.ConfigSystem.SaveConfig then
                        ASTER.ConfigSystem.SaveConfig(leaveConfigName)
                        Settings.SelectedConfig = leaveConfigName
                        if ASTER.Options and ASTER.Options.ConfigDropdown then
                            if ASTER.Options.ConfigDropdown.SetValues then
                                ASTER.Options.ConfigDropdown:SetValues(ASTER.ConfigSystem.GetConfigs())
                            end
                            if ASTER.Options.ConfigDropdown.SetValue then
                                ASTER.Options.ConfigDropdown:SetValue(leaveConfigName)
                            end
                        end
                    end
                end)
                pcall(function()
                    local privateServerId = workspace:GetAttribute("privateServerId") or ""
                    if privateServerId ~= "" then
                        Players.LocalPlayer:Kick("\n\nAsterHub: Staff detected ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â left server.\nConfig saved: " .. leaveConfigName .. "\nVIP ID: " .. privateServerId)
                    else
                        Players.LocalPlayer:Kick("\n\nAsterHub: Staff detected ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â left server.\nConfig saved: " .. leaveConfigName)
                    end
                end)
                break
            end

            task.wait(2)
        end

        for player in pairs(staffEspData) do
            destroyStaffDetectionESP(player)
        end
        lastStaffAlertKey = ""
        lastCautiousAlertKey = ""
        staffDetectionActive = false
    end)
end
end -- AsterStaffDetection

do -- AsterPreTabInit
autoEatActive = false
function startAutoEat()
    if autoEatActive then return end
    autoEatActive = true
    task.spawn(function()
        while Settings.AutoEatEnabled do
            if plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                -- Get Hunger from GUI
                local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
                local hungerVal = 100 -- Default safe value
                if mainGui then
                    local bars = mainGui:FindFirstChild("Panels") and mainGui.Panels:FindFirstChild("Stats") and mainGui.Panels.Stats:FindFirstChild("Bars")
                    if bars then
                        local hungerLabel = bars:FindFirstChild("Hunger") and bars.Hunger:FindFirstChild("ValueLabel")
                        if hungerLabel and hungerLabel:IsA("TextLabel") then
                            local num = tonumber(hungerLabel.Text)
                            if num then hungerVal = num end
                        end
                    end
                end

                if hungerVal <= (Settings.EatThreshold or 70) then
                     -- Use Heal settings for food and speed
                     local fruitName = Settings.EatFruit or "Bloodfruit"
                     local fruitID = resolveHealFruitItemId(fruitName)
                     
                     if fruitID and mainGui then
                         local rightPanel = mainGui:FindFirstChild("RightPanel")
                         local inventory = rightPanel and rightPanel:FindFirstChild("Inventory")
                         local list = inventory and inventory:FindFirstChild("List")
                         
                         local slotID = nil
                         if list then
                             for _, item in ipairs(list:GetChildren()) do
                                 if item:IsA("ImageLabel") and item.Name == fruitName then
                                     slotID = item.LayoutOrder
                                     break
                                 end
                             end
                         end
                         
                         if slotID then 
                             pcall(function()
                                 local actionId = getPacketId("UseBagItem")
                                 local b = buffer.create(8)
                                 buffer.writeu8(b, 0, 0)
                                 buffer.writeu8(b, 1, actionId)
                                 buffer.writeu32(b, 2, slotID)
                                 buffer.writeu16(b, 6, fruitID)
                                 if ByteNetReliable then ByteNetReliable:FireServer(b) end
                             end)
                             local delayTime = 1 / (Settings.HealCPS or 1)
                             task.wait(delayTime)
                         else
                             -- Item not found in bag
                             task.wait(1)
                         end
                     else
                         task.wait(1)
                     end
                else
                     task.wait(0.5)
                end
            else
                task.wait(1)
            end
        end
        autoEatActive = false
    end)
end

-- // CHEST SLOTS PERSISTENCE (workspace/Paid.txt) // --
ASTER.ChestSlotsFile = "Paid.txt"

function ASTER.SerializeChestSlots(slots)
    local out = {}
    for i, slot in ipairs(slots or {}) do
        local entry = { items = {} }
        if slot.pos then
            entry.pos = { X = slot.pos.X, Y = slot.pos.Y, Z = slot.pos.Z }
        end
        for item, enabled in pairs(slot.items or {}) do
            if enabled and item ~= "" then
                table.insert(entry.items, tostring(item))
            end
        end
        table.sort(entry.items)
        out[i] = entry
    end
    return out
end

function ASTER.DeserializeChestSlots(data)
    local out = {}
    for i, entry in ipairs(data or {}) do
        local slot = { items = {} }
        if entry.pos then
            slot.pos = Vector3.new(
                tonumber(entry.pos.X) or 0,
                tonumber(entry.pos.Y) or 0,
                tonumber(entry.pos.Z) or 0
            )
        end
        if type(entry.items) == "table" then
            for _, item in ipairs(entry.items) do
                if type(item) == "string" and item ~= "" then
                    slot.items[item] = true
                end
            end
            for k, v in pairs(entry.items) do
                if type(k) == "string" and v == true then
                    slot.items[k] = true
                end
            end
        end
        out[i] = slot
    end
    return out
end

function ASTER.SaveChestSlotsToFile()
    if not writefile then return end
    local data = { ChestSlots = ASTER.SerializeChestSlots(Settings.ChestSlots) }
    pcall(function()
        writefile(ASTER.ChestSlotsFile, httpservice:JSONEncode(data))
    end)
end

function ASTER.LoadChestSlotsFromFile()
    if not isfile or not isfile(ASTER.ChestSlotsFile) then return false end
    local ok, data = pcall(function()
        return httpservice:JSONDecode(readfile(ASTER.ChestSlotsFile))
    end)
    if ok and data and type(data.ChestSlots) == "table" then
        Settings.ChestSlots = ASTER.DeserializeChestSlots(data.ChestSlots)
        if ASTER.RefreshChestSlotDropdown then
            ASTER.RefreshChestSlotDropdown()
        end
        return true
    end
    return false
end

-- // CONFIG SYSTEM // --
ASTER.ConfigSystem = {}
ASTER.ConfigFolder = "ASTER/Configs"

if not isfolder("ASTER") then makefolder("ASTER") end
if not isfolder(ASTER.ConfigFolder) then makefolder(ASTER.ConfigFolder) end

local CONFIG_META_KEYS = {
    EnabledSettings = true,
    SettingsBooleans = true,
    MobileButtonPositions = true,
    ChestSlots = true,
    ToggleKeybinds = true,
    SelectedToggleKeybinds = true,
    SelectedToggleMobileButtons = true,
    KeybindOverlaySelection = true,
    CustomMobileToggleEnabled = true,
    BuiltinKeybinds = true,
    ESPColors = true,
    recordedPositions = true,
    GateConfigs = true,
}

local function configSerializeColor3(c)
    if typeof(c) == "Color3" then
        return {
            math.floor(c.R * 255 + 0.5),
            math.floor(c.G * 255 + 0.5),
            math.floor(c.B * 255 + 0.5),
        }
    end
    return nil
end

local function configDeserializeColor3(t)
    if type(t) == "table" and t[1] and t[2] and t[3] then
        return Color3.fromRGB(tonumber(t[1]) or 255, tonumber(t[2]) or 255, tonumber(t[3]) or 255)
    end
    return nil
end

local function configCopyStringMap(tbl)
    if type(tbl) ~= "table" then return {} end
    local out = {}
    for k, v in pairs(tbl) do
        if type(v) == "string" and v ~= "" then
            out[tostring(k)] = v
        end
    end
    return out
end

local function configCopyBoolMap(tbl)
    if type(tbl) ~= "table" then return {} end
    local out = {}
    for k, v in pairs(tbl) do
        if v then out[tostring(k)] = true end
    end
    return out
end

function ASTER.ConfigSystem.GetConfigs()
    local list = {}
    if isfolder(ASTER.ConfigFolder) then
        for _, file in ipairs(listfiles(ASTER.ConfigFolder)) do
            if file:sub(-5) == ".json" then
                table.insert(list, file:match("([^/\\]+)%.json$"))
            end
        end
    end
    return list
end

function ASTER.ConfigSystem.SaveConfig(name)
    if not name or name == "" then return end

    local function isArray(t)
        if type(t) ~= "table" then return false end
        local n = 0
        for k, _ in pairs(t) do
            if type(k) ~= "number" or k < 1 or k % 1 ~= 0 then
                return false
            end
            n += 1
        end
        for i = 1, n do
            if t[i] == nil then return false end
        end
        return true
    end

    local function escapeJsonString(s)
        return tostring(s)
            :gsub("\\", "\\\\")
            :gsub("\"", "\\\"")
            :gsub("\b", "\\b")
            :gsub("\f", "\\f")
            :gsub("\n", "\\n")
            :gsub("\r", "\\r")
            :gsub("\t", "\\t")
    end

    local function jsonEncodePrettySorted(value, indent, level)
        indent = indent or "  "
        level = level or 0
        local t = type(value)
        if t == "nil" then return "null" end
        if t == "number" then return tostring(value) end
        if t == "boolean" then return value and "true" or "false" end
        if t == "string" then return "\"" .. escapeJsonString(value) .. "\"" end
        if t ~= "table" then
            return "\"<non-serializable:" .. escapeJsonString(t) .. ">\""
        end

        local pad = string.rep(indent, level)
        local nextPad = string.rep(indent, level + 1)

        if isArray(value) then
            if #value == 0 then return "[]" end
            local parts = {}
            for i = 1, #value do
                parts[i] = nextPad .. jsonEncodePrettySorted(value[i], indent, level + 1)
            end
            return "[\n" .. table.concat(parts, ",\n") .. "\n" .. pad .. "]"
        end

        local keys = {}
        for k, _ in pairs(value) do
            table.insert(keys, k)
        end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)

        if #keys == 0 then return "{}" end
        local parts = {}
        for i, k in ipairs(keys) do
            local keyStr = "\"" .. escapeJsonString(tostring(k)) .. "\""
            parts[i] = nextPad .. keyStr .. ": " .. jsonEncodePrettySorted(value[k], indent, level + 1)
        end
        return "{\n" .. table.concat(parts, ",\n") .. "\n" .. pad .. "}"
    end

    local data = {}
    local count = 0
    for key, reg in pairs(Window.ElementRegistry) do
        if reg.GetValue then
            data[key] = reg.GetValue()
            count = count + 1
        end
    end

    -- Persist all "enabled" (boolean true) Settings flags, even if they aren't in ElementRegistry.
    -- This avoids JSON issues with non-serializable Settings entries (e.g., Color3 in ESPColors).
    data.EnabledSettings = {}
    for k, v in pairs(Settings) do
        if type(v) == "boolean" and v == true then
            table.insert(data.EnabledSettings, k)
        end
    end
    table.sort(data.EnabledSettings, function(a, b) return tostring(a) < tostring(b) end)

    data.MobileButtonPositions = {}
    for name, frame in pairs(Window.MobileButtons) do
        data.MobileButtonPositions[name] = {
            X = { Scale = frame.Position.X.Scale, Offset = frame.Position.X.Offset },
            Y = { Scale = frame.Position.Y.Scale, Offset = frame.Position.Y.Offset },
        }
    end

    data.ChestSlots = ASTER.SerializeChestSlots(Settings.ChestSlots)
    ASTER.SaveChestSlotsToFile()

    data.SettingsBooleans = {}
    for k, v in pairs(Settings) do
        if type(v) == "boolean" then
            data.SettingsBooleans[k] = v
        end
    end

    data.ToggleKeybinds = configCopyStringMap(Settings.ToggleKeybinds)
    data.SelectedToggleKeybinds = configCopyBoolMap(Settings.SelectedToggleKeybinds)
    data.SelectedToggleMobileButtons = configCopyBoolMap(Settings.SelectedToggleMobileButtons)
    data.KeybindOverlaySelection = configCopyBoolMap(Settings.KeybindOverlaySelection)
    data.CustomMobileToggleEnabled = configCopyBoolMap(Settings.CustomMobileToggleEnabled)

    data.BuiltinKeybinds = {
        AutoHitKey = Settings.AutoHitKey,
        QuickHealKey = Settings.QuickHealKey,
        AutoChestKey = Settings.AutoChestKey,
        QuickHutKey = Settings.QuickHutKey,
        FollowKey = Settings.FollowKey,
        PinchKey = ConfigPinch and ConfigPinch.Keybind or nil,
        VoodooKey = ASTER.Options and ASTER.Options.VoodooSpell and ASTER.Options.VoodooSpell.Keybind or nil,
        UIBind = Settings.Keybind,
    }

    data.ESPColors = {}
    for k, c in pairs(Settings.ESPColors or {}) do
        local ser = configSerializeColor3(c)
        if ser then data.ESPColors[k] = ser end
    end

    if Settings.recordedPositions and #Settings.recordedPositions > 0 then
        data.recordedPositions = Settings.recordedPositions
    end

    if GateConfigs then
        data.GateConfigs = GateConfigs
    end

    local json = jsonEncodePrettySorted(data)
    writefile(ASTER.ConfigFolder .. "/" .. name .. ".json", json)
end

function ASTER.ConfigSystem.LoadConfig(name)
    if not name or name == "" or name == "None" then 

        return 
    end
    local path = ASTER.ConfigFolder .. "/" .. name .. ".json"
    if not isfile(path) then 

        return 
    end
    
    local success, data = pcall(function() return httpservice:JSONDecode(readfile(path)) end)
    if success and data then
        if data["FreeCam PC"] or data["FreeCam Phone"] then
            data["FreeCam"] = data["FreeCam"] or data["FreeCam PC"] or data["FreeCam Phone"]
        end
        data["FreeCam PC"] = nil
        data["FreeCam Phone"] = nil
        if data["SelectToggleButton"] and not data["SelectToggleMobileButton"] then
            data["SelectToggleMobileButton"] = data["SelectToggleButton"]
        end
        if data["LockPreviewPreset"] ~= nil and data["PreviewPresetSave"] == nil then
            data["PreviewPresetSave"] = data["LockPreviewPreset"]
        end
        if data["PreviewSnap"] == true and data["PreviewPresetSave"] == nil then
            data["PreviewPresetSave"] = true
        end
        if data["AutoStartPlacement"] == true then
            data["TweenPlacement"] = true
        end
        if data["Placement Style"] == "Tween Placement" then
            data["TweenPlacement"] = true
        end
        data["Placement Style"] = nil
        data["LockPreviewPreset"] = nil
        local placementSliderAliases = {
            ["Placement Offset X"] = "Offset X",
            ["Placement Offset Z"] = "Offset Z",
            ["Placement Spacing X"] = "Spacing X",
            ["Placement Spacing Z"] = "Spacing Z",
        }
        for oldKey, newKey in pairs(placementSliderAliases) do
            if data[oldKey] ~= nil and data[newKey] == nil then
                data[newKey] = data[oldKey]
            end
            data[oldKey] = nil
        end

        ASTER.ConfigSystem.Loading = true
        local loaded = 0
        for key, value in pairs(data) do
            if key ~= "StartPathFinder" and not CONFIG_META_KEYS[key] then
                if Window.ElementRegistry[key] then
                    if Window.ElementRegistry[key].SetValue then
                        Window.ElementRegistry[key].SetValue(value)
                        loaded = loaded + 1
                    end
                else
                    -- warn("[Config] Key not found in registry: " .. tostring(key))
                end
            end
        end

        if type(data.SettingsBooleans) == "table" then
            for k, v in pairs(data.SettingsBooleans) do
                if type(v) == "boolean" then
                    Settings[k] = v
                end
            end
        end

        -- Re-enable Settings that were saved as "enabled" even if no UI element exists.
        local enabledSettingToRegistry = {
            AutoHealEnabled = "Auto Heal",
            AutoEatEnabled = "Auto Eat",
            MobileAutoHealButton = "Mobile Auto Heal Button",
            MobileAutoChestButton = "AutoChest Button",
            MobileAutoHitButton = "Mobile AutoHit Button",
            MobileHutButton = "Mobile Auto Hut Button",
            MobileVoodooButton = "Mobile Voodoo Button",
            MobileFollowButton = "Mobile Follow Button (Doesnt jump/turn)",
            MobilePinchButton = "Mobile Pinch Button",
            MobilePickupButton = "Mobile Auto Pickup Button",
            FreeCamPhone = "FreeCam",
            LockPreviewPreset = "PreviewPresetSave",
            LockPreviewPlacements = "PreviewPresetSave",
            AutoStartPlacement = "TweenPlacement",
        }
        if data.EnabledSettings then
            for _, settingKey in ipairs(data.EnabledSettings) do
                if settingKey ~= "PathFinderEnabled" then
                    Settings[settingKey] = true
                    -- If a UI element exists with the same name, use it so callbacks run.
                    local registryKey = enabledSettingToRegistry[settingKey] or settingKey
                    if Window.ElementRegistry[registryKey] and Window.ElementRegistry[registryKey].SetValue then
                        Window.ElementRegistry[registryKey].SetValue(true)
                    end
                end
            end
        end
        if Settings.AutoStartPlacement then
            Settings.AutoStartPlacement = false
            Settings.TweenPlacement = true
            if Window.ElementRegistry["TweenPlacement"] and Window.ElementRegistry["TweenPlacement"].SetValue then
                Window.ElementRegistry["TweenPlacement"].SetValue(true)
            end
        end

        Settings.PathFinderEnabled = false
        if Window.ElementRegistry["StartPathFinder"] and Window.ElementRegistry["StartPathFinder"].SetValue then
            Window.ElementRegistry["StartPathFinder"].SetValue(false)
        end

        if data.MobileButtonPositions then
            for name, pos in pairs(data.MobileButtonPositions) do
                if Window.MobileButtons[name] then
                    Window.MobileButtons[name].Position = UDim2.new(pos.X.Scale, pos.X.Offset, pos.Y.Scale, pos.Y.Offset)
                end
            end
        end

        if type(data.ChestSlots) == "table" then
            Settings.ChestSlots = ASTER.DeserializeChestSlots(data.ChestSlots)
            ASTER.SaveChestSlotsToFile()
        else
            ASTER.LoadChestSlotsFromFile()
        end
        if ASTER.RefreshChestSlotDropdown then
            ASTER.RefreshChestSlotDropdown()
        end

        if type(data.ToggleKeybinds) == "table" then
            Settings.ToggleKeybinds = data.ToggleKeybinds
        end
        if type(data.SelectedToggleKeybinds) == "table" then
            Settings.SelectedToggleKeybinds = data.SelectedToggleKeybinds
        end
        if type(data.SelectedToggleMobileButtons) == "table" then
            Settings.SelectedToggleMobileButtons = data.SelectedToggleMobileButtons
        end
        if type(data.KeybindOverlaySelection) == "table" then
            Settings.KeybindOverlaySelection = data.KeybindOverlaySelection
        end
        if type(data.CustomMobileToggleEnabled) == "table" then
            Settings.CustomMobileToggleEnabled = data.CustomMobileToggleEnabled
        end

        if type(data.BuiltinKeybinds) == "table" then
            local b = data.BuiltinKeybinds
            if b.AutoHitKey ~= nil then Settings.AutoHitKey = b.AutoHitKey end
            if b.QuickHealKey ~= nil then Settings.QuickHealKey = b.QuickHealKey end
            if b.AutoChestKey ~= nil then Settings.AutoChestKey = b.AutoChestKey end
            if b.QuickHutKey ~= nil then Settings.QuickHutKey = b.QuickHutKey end
            if b.FollowKey ~= nil then Settings.FollowKey = b.FollowKey end
            if b.PinchKey ~= nil and ConfigPinch then ConfigPinch.Keybind = b.PinchKey end
            if b.VoodooKey ~= nil then
                ASTER.Options = ASTER.Options or {}
                ASTER.Options.VoodooSpell = ASTER.Options.VoodooSpell or {}
                ASTER.Options.VoodooSpell.Keybind = b.VoodooKey
            end
            if b.UIBind ~= nil then
                Settings.Keybind = b.UIBind
                if Window.ElementRegistry["UI Keybind"] and Window.ElementRegistry["UI Keybind"].SetValue then
                    Window.ElementRegistry["UI Keybind"].SetValue(b.UIBind or "")
                end
            end
        end

        if type(data.ESPColors) == "table" then
            Settings.ESPColors = Settings.ESPColors or {}
            for k, v in pairs(data.ESPColors) do
                local c = configDeserializeColor3(v)
                if c then Settings.ESPColors[k] = c end
            end
            local targetReg = Window.ElementRegistry["Target ESP Color"]
            if targetReg and targetReg.GetValue then
                local target = targetReg.GetValue()
                local c = target and Settings.ESPColors[target]
                if c then
                    if Window.ElementRegistry["ESP Red"] then
                        Window.ElementRegistry["ESP Red"].SetValue(math.floor(c.R * 255 + 0.5))
                    end
                    if Window.ElementRegistry["ESP Green"] then
                        Window.ElementRegistry["ESP Green"].SetValue(math.floor(c.G * 255 + 0.5))
                    end
                    if Window.ElementRegistry["ESP Blue"] then
                        Window.ElementRegistry["ESP Blue"].SetValue(math.floor(c.B * 255 + 0.5))
                    end
                end
            end
        end

        if type(data.recordedPositions) == "table" then
            Settings.recordedPositions = data.recordedPositions
            if updateVisualNodes then pcall(updateVisualNodes) end
        end

        if type(data.GateConfigs) == "table" then
            for k, v in pairs(data.GateConfigs) do
                if type(v) == "table" then
                    GateConfigs[k] = v
                end
            end
        end

        local plantFruitReg = Window.ElementRegistry["Plant Fruit"]
        if plantFruitReg and plantFruitReg.SetValue then
            local migrated
            if data["MultiPlant"] == true and type(data["MultiPlantFruits"]) == "table" then
                migrated = data["MultiPlantFruits"]
            elseif type(data["Plant Fruit"]) == "string" and data["Plant Fruit"] ~= "" then
                migrated = { [data["Plant Fruit"]] = true }
            elseif type(data["Plant Fruit"]) == "table" then
                migrated = data["Plant Fruit"]
            end
            if migrated then
                plantFruitReg.SetValue(migrated)
            end
        end

        ASTER.ConfigSystem.Loading = false

        if ASTER.ToggleBind and ASTER.ToggleBind.finishInit then
            ASTER.ToggleBind.finishInit()
        end

        local auraReg = Window.ElementRegistry["SelectAuraType"]
        if auraReg and auraReg.SetValue and not data["SelectAuraType"] then
            local sel = {}
            for _, name in ipairs(AURA_TYPES) do
                if data[name] == true then sel[name] = true end
            end
            auraReg.SetValue(sel)
        end

        if not data["TurnOnAura"] then
            local wasOn = data["Resource Aura"] == true or data["Critter Aura"] == true or data["Structure Aura"] == true
                or Settings.ResourceAuraEnabled or Settings.CritterAuraEnabled or Settings.StructureAuraEnabled
            if wasOn then
                local turnReg = Window.ElementRegistry["TurnOnAura"]
                if turnReg and turnReg.SetValue then
                    turnReg.SetValue(true)
                else
                    Settings.TurnOnAura = true
                end
            end
        end

    else
    end
end

function ASTER.ConfigSystem.DeleteConfig(name)
    local path = ASTER.ConfigFolder .. "/" .. name .. ".json"
    if isfile(path) then delfile(path) end
end

-- Auto Load Logic
local AutoLoadFile = "ASTER/AutoLoad.txt"
function ASTER.ConfigSystem.SetAutoLoad(name)
    writefile(AutoLoadFile, name)
end

function ASTER.ConfigSystem.GetAutoLoad()
    if isfile(AutoLoadFile) then
        return readfile(AutoLoadFile)
    end
    return nil
end
