    ASTER.Tabs.Main:AddToggle("Start Tween", false, function(v)
            Settings.GoldCircuitEnabled = v
            if v then
                startGoldCircuit()
            else
                stopGoldCircuit()
            end
        end)
    ASTER.Tabs.Main:AddSlider("Tween Speed", 1, 21, 18, 1, function(v)
        Settings.GoldSpeed = v
        WALK_SPEED = v
    end)
    ASTER.Tabs.Main:AddSlider("Gold Delay", 0, 2, 0.25, 0.01, function(v) 
        Settings.GoldDelay = v
    end)
    ASTER.Tabs.Main:AddToggle("Visual Waypoints", false, function(v)
        Settings.GoldVisual = v
        updateVisualNodes()
    end)
    ASTER.Tabs.Main:AddToggle("Tween Only (Recommended)", false, function(v)
        Settings.TweenOnly = v
    end)
end

do
    ASTER.Tabs.Main:AddLabel("Path Management")
    ASTER.Options.GlobalPathDropdown = ASTER.Tabs.Main:AddDropdown("Select Path", getGoldPathList(), "None", function(v)
        if v == "None" then
            Settings.recordedPositions = {}
            updateVisualNodes()
            if ASTER.Options.WaypointDropdown then 
                ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
                ASTER.Options.WaypointDropdown:SetValue("None")
            end
        else
            if loadPath(v) then 
                updateVisualNodes() 
                if ASTER.Options.WaypointDropdown then 
                    ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
                    ASTER.Options.WaypointDropdown:SetValue("None")
                end
            end
        end
    end)

    -- Paste waypoints directly instead of selecting a saved file. Accepts the full
    -- saved-path JSON ({"positions":[...]}), a bare array of points, or plain
    -- coordinate triples like "x,y,z x,y,z" / "Vector3.new(x,y,z), ...".
    ASTER.Tabs.Main:AddInput("InputPath", "", function(v)
        if not v or v == "" then return end
        local positions

        local ok, decoded = pcall(function() return httpservice:JSONDecode(v) end)
        if ok and type(decoded) == "table" then
            if type(decoded.positions) == "table" then
                positions = decoded.positions
            elseif decoded[1] ~= nil then
                positions = decoded
            end
        end

        if not positions then
            local nums = {}
            for n in tostring(v):gmatch("[-%d%.]+") do
                local num = tonumber(n)
                if num then nums[#nums + 1] = num end
            end
            if #nums >= 3 then
                positions = {}
                for i = 1, #nums - 2, 3 do
                    positions[#positions + 1] = { X = nums[i], Y = nums[i + 1], Z = nums[i + 2] }
                end
            end
        end

        local clean = {}
        if positions then
            for _, p in ipairs(positions) do
                if type(p) == "table" then
                    local x = tonumber(p.X or p.x)
                    local y = tonumber(p.Y or p.y)
                    local z = tonumber(p.Z or p.z)
                    if x and y and z then
                        local entry = { X = x, Y = y, Z = z }
                        local wt = tonumber(p.waitTime)
                        if wt then entry.waitTime = wt end
                        clean[#clean + 1] = entry
                    end
                end
            end
        end

        if #clean > 0 then
            Settings.recordedPositions = clean
            updateVisualNodes()
            -- NOTE: don't call GlobalPathDropdown:SetValue("None") here - SetValue fires
            -- its callback, whose "None" branch would wipe the positions we just loaded.
            if ASTER.Options.WaypointDropdown then
                ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
                ASTER.Options.WaypointDropdown:SetValue("None")
            end
        end
    end)



    ASTER.Tabs.Main:AddInput("New Path Name", "", function(v)
        Settings.CustomPathName = v
    end)

    ASTER.Tabs.Main:AddButton("Save/Create Path", function()
        local name = Settings.CustomPathName
        if not name or name == "" then
            name = "GoldCircuit_"..os.date("%H%M%S")
        end
        saveCurrentPath(name)
        if ASTER.Options.GlobalPathDropdown then ASTER.Options.GlobalPathDropdown:SetValues(getGoldPathList()) end
    end)

    ASTER.Tabs.Main:AddButton("Delete Selected Path", function()
        local pathName = ASTER.Options.GlobalPathDropdown:GetValue()
        if pathName and pathName ~= "None" then
            local pathFolder = "ASTERTween"
            local filePath = pathFolder .. "/" .. pathName .. ".json"
            if isfile(filePath) then
                if delfile then delfile(filePath) elseif deletefile then deletefile(filePath) end
                Settings.recordedPositions = {}
                updateVisualNodes()
                if ASTER.Options.GlobalPathDropdown then 
                   ASTER.Options.GlobalPathDropdown:SetValues(getGoldPathList()) 
                   ASTER.Options.GlobalPathDropdown:SetValue("None")
                end
            end
        end
    end)

    ASTER.Tabs.Main:AddButton("Refresh Path List", function()
        if ASTER.Options.GlobalPathDropdown then ASTER.Options.GlobalPathDropdown:SetValues(getGoldPathList()) end
    end)
end

do
    ASTER.Tabs.Main:AddLabel("Waypoint Editor")
    function ASTER.getWaypointList()
        local t = {}
        if Settings.recordedPositions then
            for i=1, #Settings.recordedPositions do table.insert(t, tostring(i)) end
        end
        if #t == 0 then t = {"None"} end
        return t
    end

    ASTER.Options.WaypointDropdown = ASTER.Tabs.Main:AddDropdown("Select Waypoint", ASTER.getWaypointList(), "None", function(v)
        Settings.SelectedWaypointIndex = tonumber(v)
    end)
    
    ASTER.Tabs.Main:AddButton("Refresh Waypoint List", function()
        if ASTER.Options.WaypointDropdown then 
            ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
            ASTER.Options.WaypointDropdown:SetValue("None")
        end
    end)

    ASTER.Tabs.Main:AddButton("Move Selected Waypoint Here", function()
        local idx = Settings.SelectedWaypointIndex
        if idx and Settings.recordedPositions and Settings.recordedPositions[idx] then
             local character = game:GetService("Players").LocalPlayer.Character
             local hrp = character and character:FindFirstChild("HumanoidRootPart")
             if hrp then
                 Settings.recordedPositions[idx] = {X = hrp.Position.X, Y = hrp.Position.Y, Z = hrp.Position.Z}
                 updateVisualNodes()
             end
        end
    end)

    ASTER.Tabs.Main:AddButton("Delete Selected Waypoint", function()
        local idx = Settings.SelectedWaypointIndex
        if idx and Settings.recordedPositions and Settings.recordedPositions[idx] then
             table.remove(Settings.recordedPositions, idx)
             updateVisualNodes()
             if ASTER.Options.WaypointDropdown then 
                ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
                ASTER.Options.WaypointDropdown:SetValue("None")
             end
        end
    end)
    
    ASTER.Tabs.Main:AddSlider("Waypoint Wait Time", 0, 10, 0, 0.01, function(v)
        Settings.WaypointWaitTime = v
    end)

    ASTER.Tabs.Main:AddButton("Set Wait to Selected Waypoint", function()
        local idx = Settings.SelectedWaypointIndex
        if idx and Settings.recordedPositions and Settings.recordedPositions[idx] then
             Settings.recordedPositions[idx].waitTime = Settings.WaypointWaitTime or 0
        end
    end)
end

do
    ASTER.Tabs.Main:AddLabel("Path Recorder")
    if not __ASTER_RUNTIME.waypointDropdownLoopStarted then
        __ASTER_RUNTIME.waypointDropdownLoopStarted = true
        local session = CURRENT_SESSION
        task.spawn(function()
            while isRuntimeSessionActive(session) do
                if Settings.needsDropdownUpdate then
                    Settings.needsDropdownUpdate = false
                    if ASTER.Options.WaypointDropdown then 
                        ASTER.Options.WaypointDropdown:SetValues(ASTER.getWaypointList())
                    end
                end
                task.wait(2)
            end
        end)
    end

    ASTER.Tabs.Main:AddToggle("Auto Record Path", false, function(v)
        Settings.recordingPath = v
        if v then
            task.spawn(function()
                local player = game:GetService("Players").LocalPlayer
                while Settings.recordingPath do
                    local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        if not Settings.recordedPositions then Settings.recordedPositions = {} end
                        local lastPos = Settings.recordedPositions[#Settings.recordedPositions]
                        local shouldAdd = true
                        if lastPos then
                            local dist = (Vector3.new(lastPos.X, lastPos.Y, lastPos.Z) - hrp.Position).Magnitude
                            if dist < 2 then shouldAdd = false end
                        end
                        if shouldAdd then
                            table.insert(Settings.recordedPositions, {X = hrp.Position.X, Y = hrp.Position.Y, Z = hrp.Position.Z})
                            if updateVisualNodes then updateVisualNodes() end
                            Settings.needsDropdownUpdate = true
                        end
                    end
                    task.wait(Settings.recordInterval or 1)
                end
            end)
        end
    end)

    ASTER.Tabs.Main:AddSlider("Recording Interval", 0.1, 5, 1, 0.1, function(v)
        Settings.recordInterval = v
    end)

    ASTER.Tabs.Main:AddButton("Add Manual Waypoint", function()
         local player = game:GetService("Players").LocalPlayer
         local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
         if hrp then
             if not Settings.recordedPositions then Settings.recordedPositions = {} end
             table.insert(Settings.recordedPositions, {X = hrp.Position.X, Y = hrp.Position.Y, Z = hrp.Position.Z})
             if updateVisualNodes then updateVisualNodes() end
             Settings.needsDropdownUpdate = true
         end
    end)

    ASTER.Tabs.Main:AddButton("Clear Path", function()
        Settings.recordedPositions = {}
        updateVisualNodes()
    end)


end

-- AutoChest (standalone section)
do
    local RunService = game:GetService("RunService")
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer

    local function resolveAutoChestStructureName()
        local desired = tostring(Settings.AutoChestSelectedChest or "")
        if desired == "" then desired = "Chest" end

        -- Ensure discovery/cache is populated if possible, then prefer canonical name.
        local id = (type(autoDiscoverItemID) == "function") and autoDiscoverItemID(desired) or nil
        if id and type(craftItemIDs) == "table" then
            local canonical = craftItemIDs[id]
            if type(canonical) == "string" and canonical ~= "" then
                return canonical
            end
        end

        return desired
    end

    local function getGroundY(pos)
        local rayParams = RaycastParams.new()
        rayParams.FilterType = Enum.RaycastFilterType.Exclude
        rayParams.FilterDescendantsInstances = (lp and lp.Character) and { lp.Character } or {}
        local ray = workspace:Raycast(pos + Vector3.new(0, 5, 0), Vector3.new(0, -500, 0), rayParams)
        if ray then return ray.Position.Y end
        return pos.Y - 4
    end

    local function predictPosition(character, dt)
        local hrp = character and character:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local vel = hrp.AssemblyLinearVelocity or Vector3.new(0, 0, 0)
        return hrp.Position + vel * dt
    end

    local GRAVITY = workspace.Gravity or 196.2
    local function predictLanding(character, maxTime)
        local hrp = character and character:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil, nil end
        local hum = character:FindFirstChild("Humanoid")
        if not hum then return nil, nil end

        local vel = hrp.AssemblyLinearVelocity
        local pos = hrp.Position
        local v0y = vel.Y
        local y0 = pos.Y
        local t = 0
        local step = 0.05
        local posXZ = Vector2.new(pos.X, pos.Z)
        local velXZ = Vector2.new(vel.X, vel.Z)

        while t <= maxTime do
            local xz = posXZ + velXZ * t
            local y = y0 + v0y * t - 0.5 * GRAVITY * t * t
            local groundY = getGroundY(Vector3.new(xz.X, y, xz.Y))
            if y <= groundY then
                local low, high = t - step, t
                for _ = 1, 5 do
                    local mid = (low + high) / 2
                    local xzm = posXZ + velXZ * mid
                    local ym = y0 + v0y * mid - 0.5 * GRAVITY * mid * mid
                    if ym > getGroundY(Vector3.new(xzm.X, ym, xzm.Y)) then
                        low = mid
                    else
                        high = mid
                    end
                end
                local impactTime = (low + high) / 2
                local landingXZ = posXZ + velXZ * impactTime
                local landingPos = Vector3.new(
                    landingXZ.X,
                    getGroundY(Vector3.new(landingXZ.X, 0, landingXZ.Y)),
                    landingXZ.Y
                )
                return landingPos, impactTime
            end
            t = t + step
        end

        local finalPos = pos + vel * maxTime
        finalPos = Vector3.new(finalPos.X, getGroundY(finalPos), finalPos.Z)
        return finalPos, maxTime
    end

    local function getTargetCharacter()
        local targetPlayer = (ConfigPinch and ConfigPinch.TargetPlayer) or nil
        if targetPlayer and targetPlayer.Character then
            return targetPlayer.Character
        end
        return lp and lp.Character or nil
    end

    local function placeChestAt(cframe)
        if not ByteNetReliable then return end
        local packetId = getPacketId("PlaceStructure")
        if not packetId then return end

        local itemName = resolveAutoChestStructureName()
        local len = #itemName
        local b = buffer.create(4 + len + 18)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, packetId)
        buffer.writeu16(b, 2, len)
        for i = 1, len do buffer.writeu8(b, 3 + i, string.byte(itemName, i)) end

        local offset = 4 + len
        write18ByteCFrame(b, offset, cframe)
        ByteNetReliable:FireServer(b)
    end

    local MAX_PREDICTION_TIME = 2.0
    local lastPlaceAt = 0
    local lastFallTriggered = false
    local wasAirborne = false
    -- Previous-frame horizontal camera look + move vector (for "turned ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ place under" behavior).
    local lastLookFlatXZ = nil
    local lastMoveDirForLeadXZ = nil

    local function stepAutoChest()
        if not Settings.AutoChestEnabled then
            lastFallTriggered = false
            wasAirborne = false
            lastLookFlatXZ = nil
            lastMoveDirForLeadXZ = nil
            return
        end

        local char = getTargetCharacter()
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChild("Humanoid")
        if not (hrp and hum) then
            lastFallTriggered = false
            wasAirborne = false
            lastLookFlatXZ = nil
            lastMoveDirForLeadXZ = nil
            return
        end

        local airborne = hum.FloorMaterial == Enum.Material.Air

        local predTime = Settings.AutoChestPredictionTime or 0.2
        local vel = hrp.AssemblyLinearVelocity or Vector3.zero
        local horizontalVel = Vector3.new(vel.X, 0, vel.Z)
        -- Full 3D linear prediction (used for vertical / dy); timing unchanged.
        local feetPredict = predictPosition(char, predTime) or hrp.Position

        -- Trigger clearance must use ground under the body's current column. If we used
        -- feetPredict.XZ, horizontal prediction shifts the ray while moving and dy often
        -- misses the narrow window (works when jumping in place, fails when strafing).
        local probeForDy = Vector3.new(hrp.Position.X, feetPredict.Y, hrp.Position.Z)
        local groundYFeet = getGroundY(probeForDy)
        local dy = feetPredict.Y - groundYFeet

        -- Horizontal placement: where the body will be in predTime on the XZ plane (velocity),
        -- with Y still from full prediction / landing so ground snap stays consistent.
        local horizLead = horizontalVel * predTime
        local placeXZ = Vector3.new(hrp.Position.X + horizLead.X, feetPredict.Y, hrp.Position.Z + horizLead.Z)

        local placeAnchor
        if Settings.AutoChestJumpPrediction then
            local landPos = select(1, predictLanding(char, MAX_PREDICTION_TIME))
            if landPos then
                placeAnchor = Vector3.new(landPos.X, landPos.Y, landPos.Z)
            else
                placeAnchor = placeXZ
            end
        else
            placeAnchor = placeXZ
        end

        -- Forward offset for AutoChestForwardOffset: WASD when meaningful, else horizontal velocity, else camera facing.
        local function placementForwardXZ()
            local md = hum.MoveDirection
            local mdH = Vector3.new(md.X, 0, md.Z)
            if mdH.Magnitude > 0.05 then
                return mdH.Unit
            end
            if horizontalVel.Magnitude > 0.15 then
                return horizontalVel.Unit
            end
            local look = hrp.CFrame.LookVector
            local flat = Vector3.new(look.X, 0, look.Z)
            if flat.Magnitude > 0.01 then
                return flat.Unit
            end
            return Vector3.new(0, 0, -1)
        end

        -- Direction of actual movement on XZ (for forward lead). Nil when effectively still.
        local MOVE_VEL_EPS = 0.5
        local MOVE_INPUT_EPS = 0.05
        local function horizontalMoveDirectionOrNil()
            if horizontalVel.Magnitude >= MOVE_VEL_EPS then
                return horizontalVel.Unit
            end
            local mdH = Vector3.new(hum.MoveDirection.X, 0, hum.MoveDirection.Z)
            if mdH.Magnitude >= MOVE_INPUT_EPS then
                return mdH.Unit
            end
            return nil
        end

        local function flatUnitXZ(v)
            local f = Vector3.new(v.X, 0, v.Z)
            if f.Magnitude < 1e-3 then return nil end
            return f.Unit
        end

        local cam = workspace.CurrentCamera
        local lookSource = (cam and cam.CFrame.LookVector) or hrp.CFrame.LookVector
        local lookFlatXZ = flatUnitXZ(lookSource)

        local forwardXZ = placementForwardXZ()
        local basePos = placeAnchor + forwardXZ * (Settings.AutoChestForwardOffset or 0)
        local moveDirXZ = horizontalMoveDirectionOrNil()

        -- Sharp turn only: small camera / strafe wobble used to false-trigger at ~38ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â°.
        -- Ignore look-based changes when barely moving horizontally; require real speed for move-dir compare too.
        local DIR_CHANGE_COS = math.cos(math.rad(58))
        local DIR_SNAP_MIN_HSPEED = 1.6
        local directionChanged = false
        if lookFlatXZ and lastLookFlatXZ and horizontalVel.Magnitude >= DIR_SNAP_MIN_HSPEED then
            if lastLookFlatXZ:Dot(lookFlatXZ) < DIR_CHANGE_COS then
                directionChanged = true
            end
        end
        if not directionChanged and moveDirXZ and lastMoveDirForLeadXZ and horizontalVel.Magnitude >= DIR_SNAP_MIN_HSPEED then
            if lastMoveDirForLeadXZ:Dot(moveDirXZ) < DIR_CHANGE_COS then
                directionChanged = true
            end
        end

        local MOVE_LEAD_STUDS = 5
        local offsetPos = (moveDirXZ and not directionChanged) and (basePos + moveDirXZ * MOVE_LEAD_STUDS) or basePos

        if lookFlatXZ then
            lastLookFlatXZ = lookFlatXZ
        end
        lastMoveDirForLeadXZ = moveDirXZ

        -- Mid-air sharp turn: drop predicted/lead placement and put chest straight under the root (column + ground Y).
        local chestXZX, chestXZZ
        if airborne and directionChanged then
            chestXZX, chestXZZ = hrp.Position.X, hrp.Position.Z
        else
            chestXZX, chestXZZ = offsetPos.X, offsetPos.Z
        end
        local groundYChest = getGroundY(Vector3.new(chestXZX, hrp.Position.Y, chestXZZ))
        local chestCF = CFrame.new(chestXZX, groundYChest, chestXZZ)

        -- Place at "hitbox touch" moment: descending + within threshold to ground.
        if airborne then
            wasAirborne = true
            local vy = (hrp.AssemblyLinearVelocity and hrp.AssemblyLinearVelocity.Y) or 0
            if vy < 0 and not lastFallTriggered then
                local threshold = Settings.AutoChestFallThreshold or 0.6
                if dy > 0 and dy <= threshold then
                    local now = tick()
                    local cooldown = Settings.AutoChestPlaceCooldown or 0.02
                    if now - lastPlaceAt >= cooldown then
                        placeChestAt(chestCF)
                        lastPlaceAt = now
                        lastFallTriggered = true
                    end
                end
            end
        else
            -- Reset once we land so repeated jumps work.
            if wasAirborne then
                lastFallTriggered = false
                wasAirborne = false
            end
        end
    end

    ASTER.Options.setAutoChestLoop = function(enabled)
        if enabled then
            registerHeartbeatUpdate("autoChest", stepAutoChest)
            ensureMasterHeartbeatLoop()
        else
            unregisterHeartbeatUpdate("autoChest")
            lastFallTriggered = false
            wasAirborne = false
            lastLookFlatXZ = nil
            lastMoveDirForLeadXZ = nil
        end
    end
end

