do
    ASTER.Tabs.Pickup:AddLabel("Crates")

    local selectedCrate = "10 SkinCrate"
    ASTER.Tabs.Pickup:AddDropdown("SelectCrates", {"10 SkinCrate", "1 SkinCrate"}, "10 SkinCrate", function(v)
        selectedCrate = v
    end)

    local openCrateTask
    ASTER.Tabs.Pickup:AddToggle("Open Skin Crate", false, function(v)
        Settings.OpenSkinCrate = v
        if v then
            openCrateTask = task.spawn(function()
                local bn = game:GetService("ReplicatedStorage"):WaitForChild("ByteNetReliable")
                local crateName = "Skin Crate"
                local nameLen = #crateName
                
                while Settings.OpenSkinCrate do
                    local cratePkt = getPacketId("PurchaseCrate")
                    if cratePkt then
                        local b = buffer.create(8 + nameLen)
                        buffer.writeu8(b, 0, 0)
                        buffer.writeu8(b, 1, cratePkt)
                        buffer.writeu32(b, 2, 1)

                        buffer.writeu16(b, 6, nameLen)
                        for i = 1, nameLen do
                            buffer.writeu8(b, 7 + i, string.byte(crateName, i))
                        end

                        bn:FireServer(b)
                    end
                    task.wait(0.1)
                end
            end)
        else
            if openCrateTask then
                task.cancel(openCrateTask)
                openCrateTask = nil
            end
        end
    end)

    local autoSkipTask
    ASTER.Tabs.Pickup:AddToggle("Auto Skip Crate", false, function(v)
        Settings.AutoSkipCrate = v
        if v then
            autoSkipTask = task.spawn(function()
                while Settings.AutoSkipCrate do
                    pcall(function()
                        local opening = plr.PlayerGui.CrateUI.Crates.CrateMenu.Container.Opening
                        if opening and opening.Visible then
                            local action = opening:FindFirstChild("Action")
                            if action then
                                local vim = game:GetService("VirtualUser")
                                local absPos = action.AbsolutePosition
                                local absSize = action.AbsoluteSize
                                local center = Vector2.new(absPos.X + absSize.X/2, absPos.Y + absSize.Y/2)
                                vim:ClickButton1(center)
                                
                                if getconnections then
                                    for _, c in pairs(getconnections(action.Activated)) do pcall(function() c:Fire() end) end
                                end
                                if typeof(firesignal) == "function" then
                                    pcall(function() firesignal(action.Activated) end)
                                end
                            end
                        end
                    end)
                    task.wait(0.05)
                end
            end)
        else
            if autoSkipTask then
                task.cancel(autoSkipTask)
                autoSkipTask = nil
            end
        end
    end)
end

do
    ASTER.Tabs.Pickup:AddLabel("Chest Teleport")

    -- ===== Multi-Chest (click chests to add + choose items per chest) =====
    local slotDropdownObj
    local selectedSlotIndex = 0
    local selectedItem = "Raw Gold"
    local slotSyncing = false
    local selectClickConn

    local function slotItemsToStr(slot)
        local t = {}
        for k in pairs(slot.items or {}) do table.insert(t, k) end
        if #t == 0 then return "none" end
        table.sort(t)
        return table.concat(t, "+")
    end

    local function slotLabelList()
        local names = {}
        for i, slot in ipairs(Settings.ChestSlots) do
            local loc = slot.pos and "" or " (empty)"
            names[i] = "Chest" .. i .. " [" .. slotItemsToStr(slot) .. "]" .. loc
        end
        if #names == 0 then names = { "(no chests)" } end
        return names
    end

    local function refreshSlotDropdown()
        slotSyncing = true
        if slotDropdownObj and slotDropdownObj.SetValues then
            slotDropdownObj:SetValues(slotLabelList())
        end
        if slotDropdownObj and slotDropdownObj.SetValue then
            if selectedSlotIndex >= 1 and selectedSlotIndex <= #Settings.ChestSlots then
                slotDropdownObj:SetValue(slotLabelList()[selectedSlotIndex])
            else
                slotDropdownObj:SetValue(slotLabelList()[1])
            end
        end
        slotSyncing = false
    end

    local function ensureChestEngine()
        if not Settings.BigChests then
            if Window.ElementRegistry["ShowChestHighlights"] and Window.ElementRegistry["ShowChestHighlights"].SetValue then
                Window.ElementRegistry["ShowChestHighlights"].SetValue(true)
            else
                Settings.BigChests = true
                startBigChestEngine()
            end
        end
    end

    local function getTargetChestSlot()
        if selectedSlotIndex >= 1 and selectedSlotIndex <= #Settings.ChestSlots then
            return Settings.ChestSlots[selectedSlotIndex]
        end
        if #Settings.ChestSlots > 0 then
            selectedSlotIndex = 1
            refreshSlotDropdown()
            return Settings.ChestSlots[1]
        end
        return nil
    end

    local function addItemsToSelectedSlot(itemNames)
        local slot = getTargetChestSlot()
        if not slot then return end
        slot.items = slot.items or {}
        for _, itemName in ipairs(itemNames) do
            slot.items[itemName] = true
        end
        refreshSlotDropdown()
    end

    local function removeItemsFromSelectedSlot(itemNames)
        local slot = getTargetChestSlot()
        if not slot or not slot.items then return end
        for _, itemName in ipairs(itemNames) do
            slot.items[itemName] = nil
        end
        refreshSlotDropdown()
    end

    -- Add the chest at pos as a new numbered chest, or remove it if already added
    local function addOrToggleChestByPosition(pos)
        local foundIdx
        for i, slot in ipairs(Settings.ChestSlots) do
            if slot.pos and (slot.pos - pos).Magnitude < 5 then foundIdx = i break end
        end
        if foundIdx then
            table.remove(Settings.ChestSlots, foundIdx)
            selectedSlotIndex = math.min(selectedSlotIndex, #Settings.ChestSlots)
        else
            table.insert(Settings.ChestSlots, { pos = pos, items = {} })
            selectedSlotIndex = #Settings.ChestSlots
            ensureChestEngine()
        end
        refreshSlotDropdown()
    end

    -- Click chests in the world to add (Chest1, Chest2, ...) / click again to remove
    ASTER.Tabs.Pickup:AddToggle("ClickToSelectChests", false, function(v)
        if selectClickConn then selectClickConn:Disconnect() selectClickConn = nil end
        if v then
            local mouse = plr:GetMouse()
            selectClickConn = mouse.Button1Down:Connect(function()
                local target = mouse.Target
                if not target then return end
                local d = getWorkspaceDeployables()
                if not d then return end
                local obj = target
                while obj and obj.Parent and obj.Parent ~= d do obj = obj.Parent end
                if obj and obj.Parent == d and (obj.Name:find("Chest") or obj.Name:find("Box")) and not obj.Name:find("Plant Box") then
                    addOrToggleChestByPosition(obj:GetPivot().Position)
                end
            end)
        end
    end)

    ASTER.Tabs.Pickup:AddSlider("ChestHitboxSize", 4, 10000, 6, 1, function(v)
        Settings.ChestHitboxSize = v
    end)

    ASTER.Tabs.Pickup:AddToggle("ShowChestHighlights", false, function(v)
        Settings.BigChests = v
        if v then startBigChestEngine() end
    end)

    ASTER.Tabs.Pickup:AddToggle("ShowDistance&Chest", false, function(v)
        Settings.ShowChestDistance = v
    end)

    slotDropdownObj = ASTER.Tabs.Pickup:AddDropdown("SelectChest", { "(no chests)" }, "(no chests)", function(v)
        if slotSyncing then return end
        local n = tostring(v):match("Chest(%d+)")
        selectedSlotIndex = tonumber(n) or 0
    end)

    -- Type the item name that should go to the selected chest
    ASTER.Tabs.Pickup:AddInput("ItemToChest", "Raw Gold", function(v)
        selectedItem = v
    end)

    ASTER.Tabs.Pickup:AddToggle("Gold to Chest (Use Chest Hitbox)", false, function(v)
        Settings.TeleportGoldToChest = v
        if v then
            addItemsToSelectedSlot({ "Gold", "Raw Gold" })
            ensureChestEngine()
        else
            removeItemsFromSelectedSlot({ "Gold", "Raw Gold" })
        end
    end)
    ASTER.Tabs.Pickup:AddToggle("Essence to Chest (Use Chest Hitbox)", false, function(v)
        Settings.TeleportEssenceToChest = v
        if v then
            addItemsToSelectedSlot({ "[Essence]" })
            ensureChestEngine()
        else
            removeItemsFromSelectedSlot({ "[Essence]" })
        end
    end)

    ASTER.Tabs.Pickup:AddButton("Add Item To Selected Chest", function()
        local slot = Settings.ChestSlots[selectedSlotIndex]
        if not slot then return end
        slot.items = slot.items or {}
        if selectedItem and selectedItem ~= "" then
            slot.items[selectedItem] = true
            refreshSlotDropdown()
        end
    end)

    ASTER.Tabs.Pickup:AddButton("Remove Item From Selected Chest", function()
        local slot = Settings.ChestSlots[selectedSlotIndex]
        if not slot or not slot.items then return end
        if selectedItem then
            slot.items[selectedItem] = nil
            refreshSlotDropdown()
        end
    end)

    ASTER.Tabs.Pickup:AddButton("Add Nearest Chest", function()
        local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
        local d = getWorkspaceDeployables()
        if not hrp or not d then return end
        local closest, dist = nil, math.huge
        for _, obj in ipairs(d:GetChildren()) do
            if (obj.Name:find("Chest") or obj.Name:find("Box")) and not obj.Name:find("Plant Box") then
                local dd = (obj:GetPivot().Position - hrp.Position).Magnitude
                if dd < dist then dist = dd closest = obj end
            end
        end
        if closest and dist < 60 then
            addOrToggleChestByPosition(closest:GetPivot().Position)
        end
    end)

    ASTER.Tabs.Pickup:AddButton("Remove Selected Chest", function()
        if selectedSlotIndex >= 1 and selectedSlotIndex <= #Settings.ChestSlots then
            table.remove(Settings.ChestSlots, selectedSlotIndex)
            selectedSlotIndex = math.min(selectedSlotIndex, #Settings.ChestSlots)
            refreshSlotDropdown()
        end
    end)

    ASTER.Tabs.Pickup:AddButton("Clear All Chests", function()
        table.clear(Settings.ChestSlots)
        selectedSlotIndex = 0
        refreshSlotDropdown()
    end)

    ASTER.RefreshChestSlotDropdown = refreshSlotDropdown
end

