do
    local function findNearestPlayer()
        local nearestPlayer, minDistance = nil, math.huge
        if not plr or not plr.Character or not plr.Character:FindFirstChild("HumanoidRootPart") then return nil end
        local localPlayerPos = plr.Character.HumanoidRootPart.Position
        for _, p in pairs(Players:GetPlayers()) do
            if p ~= plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                local distance = (localPlayerPos - p.Character.HumanoidRootPart.Position).magnitude
                if distance < minDistance then
                    minDistance = distance
                    nearestPlayer = p
                end
            end
        end
        return nearestPlayer
    end
    
    local PlayerList = {}
    
    local function RefreshPlayerList()
        local currentSelection = Settings.SelectedTargetPlayer
        PlayerList = {"None"}
        for _, p in pairs(Players:GetPlayers()) do
            if p ~= plr then
                local isTargetable = true
                local myTeam = plr.Team
                local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                
                if myTeam and myTeam ~= noTribe and p.Team == myTeam then
                    isTargetable = false
                end

                if isTargetable and isAlly(p) then
                    isTargetable = false
                end
                
                if isTargetable then
                    table.insert(PlayerList, p.Name)
                end
            end
        end
        table.sort(PlayerList)
        if ASTER.Options.PlayerSelectDropdown then
            ASTER.Options.PlayerSelectDropdown:SetValues(PlayerList)
            
            -- Always reset to None unless in Auto Target Mode
            if Settings.TargetMode ~= "Auto Target Mode" and Settings.TargetMode ~= "Target GodOnly" then
                ASTER.Options.PlayerSelectDropdown:SetValue("None")
                Settings.SelectedTargetPlayer = "None"
                ConfigPinch.TargetPlayer = nil
                if ASTER.Options.TargetingLabel then ASTER.Options.TargetingLabel.Text = "Targeting: None" end
            elseif table.find(PlayerList, currentSelection) then
                ASTER.Options.PlayerSelectDropdown:SetValue(currentSelection)
            else
                ASTER.Options.PlayerSelectDropdown:SetValue("None")
                Settings.SelectedTargetPlayer = "None"
            end
        end
    end
    
        ASTER.Tabs.Combat:AddLabel("Target Player")
    ASTER.Options.TargetingLabel = ASTER.Tabs.Combat:AddButton("Targeting: None", function() end)

    ASTER.Tabs.Combat:AddToggle("Target Hitbox", false, function(v)
        Settings.TargetHighlightEnabled = v
        local toggleObject = Window.ElementRegistry["Target Hitbox"]
        if v then
            if toggleObject and toggleObject.Label then
                toggleObject.Label.Text = "Target"
            end
        else
            if toggleObject and toggleObject.Label then
                toggleObject.Label.Text = "Target Hitbox"
            end
            -- Cleanup if disabled
            for _, player in ipairs(game:GetService("Players"):GetPlayers()) do
                if player.Character then
                    local hl = player.Character:FindFirstChild("TargetHighlight")
                    if hl then hl:Destroy() end
                    local gui = player.Character:FindFirstChild("TargetLabelGui")
                    if gui then gui:Destroy() end
                end
            end
        end
    end)

    ASTER.Options.TargetModeDropdown = ASTER.Tabs.Combat:AddDropdown("Select Target Mode", {"Auto Target Mode", "Target GodOnly", "None", "PlayerList"}, "Auto Target Mode", function(v)
        Settings.TargetMode = v
        if v == "Auto Target Mode" or v == "Target GodOnly" then
            if ASTER.Options.PlayerSelectDropdown and ASTER.Options.PlayerSelectDropdown.dFrame then ASTER.Options.PlayerSelectDropdown.dFrame.Visible = false end
            if ASTER.Options.TargetingLabel then ASTER.Options.TargetingLabel.Text = "Targeting: Scanning..." end
        elseif v == "PlayerList" then
            if ASTER.Options.PlayerSelectDropdown and ASTER.Options.PlayerSelectDropdown.dFrame then ASTER.Options.PlayerSelectDropdown.dFrame.Visible = true end
        else -- v == "None"
            if ASTER.Options.PlayerSelectDropdown and ASTER.Options.PlayerSelectDropdown.dFrame then ASTER.Options.PlayerSelectDropdown.dFrame.Visible = false end
            ConfigPinch.TargetPlayer = nil
            if ASTER.Options.TargetingLabel then ASTER.Options.TargetingLabel.Text = "Targeting: None" end
        end
        RefreshPlayerList()
    end)

function UpdateTargetingLabel(v)
    if v ~= "None" then
        local p = Players:FindFirstChild(v)
        if p then
            ConfigPinch.TargetPlayer = p
            if ASTER.Options.TargetingLabel then
                ASTER.Options.TargetingLabel.Text = "Targeting: " .. p.Name
            end
        end
    else
        ConfigPinch.TargetPlayer = nil
        if ASTER.Options.TargetingLabel then
            ASTER.Options.TargetingLabel.Text = "Targeting: None"
        end
    end
end

    ASTER.Options.PlayerSelectDropdown = ASTER.Tabs.Combat:AddDropdown("PlayerList", PlayerList, Settings.SelectedTargetPlayer, function(v)
        Settings.SelectedTargetPlayer = v
        UpdateTargetingLabel(v)
    end)
    if ASTER.Options.PlayerSelectDropdown.dFrame then ASTER.Options.PlayerSelectDropdown.dFrame.Visible = false end

    if Settings.TargetMode == "PlayerList" then
        if ASTER.Options.PlayerSelectDropdown and ASTER.Options.PlayerSelectDropdown.dFrame then
            ASTER.Options.PlayerSelectDropdown.dFrame.Visible = true
        end
    else
        if ASTER.Options.PlayerSelectDropdown and ASTER.Options.PlayerSelectDropdown.dFrame then
            ASTER.Options.PlayerSelectDropdown.dFrame.Visible = false
        end
    end

    ASTER.Tabs.Combat:AddButton("Refresh Players", RefreshPlayerList)

    Players.PlayerAdded:Connect(RefreshPlayerList)
    Players.PlayerRemoving:Connect(RefreshPlayerList)
end

