    ASTER.Tabs.Combat:AddSlider("Ping Scale", 0.25, 3, 1, 0.01, function(v)
        ConfigPinch.PredictTime = v
    end)
    
    local previewParts = {}
    local previewConnection = nil
    
    local function updatePreviewModels()
        -- Clear old preview models
        for _, p in ipairs(previewParts) do 
            if p then p:Destroy() end
        end
        table.clear(previewParts)
        
        local itemName = ConfigPinch.ItemName or "Crystal Gate"
        local modelTemplate = nil
        local rs = game:GetService("ReplicatedStorage")
        
        -- 1. Fast check common Booga Booga Reborn folders
        local quickFolders = {"Deployables", "PlaceStructures", "Structures", "Models"}
        for _, fname in ipairs(quickFolders) do
            local folder = rs:FindFirstChild(fname)
            if folder and folder:FindFirstChild(itemName) then
                modelTemplate = folder:FindFirstChild(itemName)
                break
            end
        end
        
        -- 2. Deep search ReplicatedStorage if not found in common folders
        if not modelTemplate then
            for _, v in ipairs(rs:GetDescendants()) do
                if (v:IsA("Model") or v:IsA("BasePart")) and v.Name == itemName then
                    modelTemplate = v
                    break
                end
            end
        end
        
        for i = 1, 2 do
            local previewObj
            if modelTemplate then
                previewObj = modelTemplate:Clone()
                
                -- Make translucent and uncollidable
                if previewObj:IsA("BasePart") then
                    previewObj.CanCollide = false
                    previewObj.Anchored = true
                    previewObj.Transparency = 0.5
                    previewObj.Material = Enum.Material.ForceField
                    previewObj.Color = Color3.new(0, 1, 0)
                end
                
                for _, desc in ipairs(previewObj:GetDescendants()) do
                    if desc:IsA("BasePart") then
                        desc.CanCollide = false
                        desc.Anchored = true
                        desc.Transparency = 0.5
                        desc.Material = Enum.Material.ForceField
                        desc.Color = Color3.new(0, 1, 0)
                    end
                end
                
                -- Ensure PrimaryPart exists for moving the model
                if previewObj:IsA("Model") and not previewObj.PrimaryPart then
                    local firstPart = previewObj:FindFirstChildWhichIsA("BasePart", true)
                    if firstPart then
                        previewObj.PrimaryPart = firstPart
                    else
                        -- Fallback if no parts exist in model
                        previewObj:Destroy()
                        previewObj = nil
                    end
                end
            end
            
            -- Fallback to simple part if model not found
            if not previewObj then
                previewObj = Instance.new("Part")
                previewObj.Name = "PinchPreviewFallbackPart" .. i
                previewObj.Size = Vector3.new(4, 8, 1)
                previewObj.Anchored = true
                previewObj.CanCollide = false
                previewObj.Material = Enum.Material.ForceField
                previewObj.Color = Color3.new(0, 1, 0)
                previewObj.Transparency = 0.3
            else
                previewObj.Name = "PinchPreviewPart" .. i
            end
            
            previewObj.Parent = workspace
            previewParts[i] = previewObj
        end
    end
    
    ASTER.Tabs.Combat:AddToggle("Preview Pinch Placements", false, function(v)
        if v then
            updatePreviewModels()
            
            previewConnection = game:GetService("RunService").Heartbeat:Connect(function()
                if ConfigPinch.TargetPlayer and ConfigPinch.TargetPlayer.Character then
                    local char = ConfigPinch.TargetPlayer.Character
                    local hrp = char:FindFirstChild("HumanoidRootPart")
                    local hum = char:FindFirstChild("Humanoid")
                    if hrp then
                        local compute = ASTER.Options.computePinchPlacementCFrames
                        local cf1, cf2
                        if compute then
                            cf1, cf2 = compute(hrp, hum, 1 / 60)
                        end
                        if not cf1 or not cf2 then
                            return
                        end
                        
                        -- Set CFrame based on object type
                        for i, cframe in ipairs({cf1, cf2}) do
                            local obj = previewParts[i]
                            if obj then
                                if obj:IsA("Model") then
                                    -- The visual model's PrimaryPart often has its own internal rotation offset
                                    -- We need to rotate the preview model by 90 degrees on the Y axis to match the actual placement
                                    obj:SetPrimaryPartCFrame(cframe * CFrame.Angles(0, math.rad(90), 0))
                                elseif obj.Name:match("FallbackPart") then
                                    -- This is the fallback simple part, offset by 4
                                    obj.CFrame = cframe * CFrame.new(0, 4, 0)
                                else
                                    -- This is an actual BasePart model from the game
                                    obj.CFrame = cframe
                                end
                            end
                        end
                    end
                else
                    -- Hide preview if no target is selected
                    for i = 1, 2 do
                        local obj = previewParts[i]
                        if obj then
                            if obj:IsA("Model") then
                                obj:SetPrimaryPartCFrame(CFrame.new(0, -1000, 0))
                            else
                                obj.CFrame = CFrame.new(0, -1000, 0)
                            end
                        end
                    end
                end
            end)
        else
            if previewConnection then 
                previewConnection:Disconnect() 
                previewConnection = nil
            end
            for _, p in ipairs(previewParts) do 
                if p then p:Destroy() end
            end
            table.clear(previewParts)
        end
    end)

    ASTER.Tabs.Combat:AddToggle("Pinch", false, function(v)
        ConfigPinch.Enabled = v
        
        -- Sync Mobile Button
        if Settings.MobilePinchButton then
            local widget = ASTER.GetMobileWidgetByGuiName("AsterPinchGui")
            if widget then
                widget.setToggleState(v, "Pinch")
            end
        end
    end)
end

do
    ASTER.Tabs.Combat:AddLabel("Reach&Killaura")
    
    local autoCraftEquipItems = {
        ["God Halo"] = {equip = true},
        ["God Chestplate"] = {equip = true},
        ["God Legs"] = {equip = true},
        ["God Rock"] = {equip = true},
        ["Iron Bow"] = {equip = true},
        ["Bow"] = {equip = true},
        ["God Pick"] = {equip = true},
        ["God Axe"] = {equip = true},
    }
    local autoCraftEquipList = {
        "God Halo", "God Chestplate", "God Legs", 
        "God Rock", "Iron Bow", "Bow", "God Pick", "God Axe"
    }

    local autoCraftEquipActive = false

    local function playerOwnsCraftEquipItem(itemName)
        if not itemName or itemName == "" then return false end
        if type(getlayout) == "function" and getlayout(itemName) then return true end
        if type(getToolSlot) == "function" and getToolSlot(itemName) then return true end
        if type(isToolEquipped) == "function" and isToolEquipped(itemName) then return true end
        if plr.Character and plr.Character:FindFirstChild(itemName) then return true end
        if plr.Backpack and plr.Backpack:FindFirstChild(itemName) then return true end
        local mainGui = plr.PlayerGui:FindFirstChild("MainGui")
        local inventory = mainGui and mainGui:FindFirstChild("RightPanel")
            and mainGui.RightPanel:FindFirstChild("Inventory")
            and mainGui.RightPanel.Inventory:FindFirstChild("List")
        if inventory then
            if inventory:FindFirstChild(itemName) then return true end
            local lowerTarget = string.lower((tostring(itemName):match("^%s*(.-)%s*$") or ""))
            if lowerTarget ~= "" then
                for _, child in ipairs(inventory:GetChildren()) do
                    if child:IsA("GuiObject") then
                        local cn = string.lower((tostring(child.Name):match("^%s*(.-)%s*$") or ""))
                        if cn == lowerTarget then
                            return true
                        end
                    end
                end
            end
        end
        return false
    end

    local function isCraftEquipItemEquipped(itemName)
        if plr.Character and plr.Character:FindFirstChild(itemName) then return true end
        if type(isToolEquipped) == "function" and isToolEquipped(itemName) then return true end
        return false
    end

    function startAutoCraftEquip()
        if autoCraftEquipActive then return end
        autoCraftEquipActive = true
        task.spawn(function()
            while Settings.AutoCraftEquipEnabled do
                local selections = Settings.SelectedCraftEquipItems
                if type(selections) == "table" then
                    for itemName, isSelected in pairs(selections) do
                        if not Settings.AutoCraftEquipEnabled then break end
                        if isSelected then
                            local info = autoCraftEquipItems[itemName]
                            if info then
                                local hasItem = playerOwnsCraftEquipItem(itemName)
                                local isEquipped = isCraftEquipItemEquipped(itemName)

                                -- Only craft when the item is missing. Never recraft owned items.
                                if not hasItem then
                                    pcall(function()
                                        if ByteNetReliable then
                                            local itemID = autoDiscoverItemID(itemName)
                                            if not itemID and craftNameToID then
                                                itemID = craftNameToID[itemName]
                                            end
                                            local craftId = getPacketId("CraftItem")
                                            if itemID and craftId then
                                                local b = buffer.create(4)
                                                buffer.writeu8(b, 0, 0)
                                                buffer.writeu8(b, 1, craftId)
                                                buffer.writeu16(b, 2, itemID)
                                                ByteNetReliable:FireServer(b)
                                            end
                                        end
                                    end)

                                    local retries = 0
                                    while Settings.AutoCraftEquipEnabled and not getlayout(itemName) and retries < 50 do
                                        task.wait()
                                        retries = retries + 1
                                    end
                                    hasItem = playerOwnsCraftEquipItem(itemName)
                                end

                                if info.equip and hasItem and not isEquipped then
                                    task.spawn(function()
                                        local equipRetries = 0
                                        local actionId = getPacketId("UseBagItem")

                                        while Settings.AutoCraftEquipEnabled
                                            and plr.Character
                                            and not isCraftEquipItemEquipped(itemName)
                                            and equipRetries < 25 do
                                            local slotID = getlayout(itemName)
                                            local itemID = autoDiscoverItemID(itemName)
                                            if not itemID and craftNameToID then
                                                itemID = craftNameToID[itemName]
                                            end
                                            if slotID and actionId and ByteNetReliable and itemID then
                                                local b = buffer.create(8)
                                                buffer.writeu8(b, 0, 0)
                                                buffer.writeu8(b, 1, actionId)
                                                buffer.writeu32(b, 2, slotID)
                                                buffer.writeu16(b, 6, itemID)
                                                ByteNetReliable:FireServer(b)
                                            end
                                            task.wait(0.15)
                                            equipRetries = equipRetries + 1
                                        end
                                    end)
                                end
                                task.wait(0.01)
                            end
                        end
                    end
                end
                task.wait(0.4)
            end
            autoCraftEquipActive = false
        end)
    end

    ASTER.Tabs.Combat:AddDropdown("SelectAutoHit", {"SwingHit", "NoSwingHit"}, autoHitSelection, function(v)
        if autoHitSelection == v then return end

        local wasEnabled = Settings.AutoHitStartEnabled
        if wasEnabled then
            stopAutoHit()
        end

        autoHitSelection = v

        if wasEnabled then
            Settings.AutoHitStartEnabled = true
            if autoHitSelection == "NoSwingHit" then
                startNoSwingAutoHit()
            else
                startSwingAutoHit()
            end
        end

        updateAutoHitGui()
    end)

    ASTER.Tabs.Combat:AddToggle("AutoHitStart", false, function(v)
        Settings.AutoHitStartEnabled = v
        autoHitRunning = v
        if v then
            if autoHitSelection == "NoSwingHit" then
                startNoSwingAutoHit()
            else
                startSwingAutoHit()
            end
        else
            stopAutoHit()
        end
        updateAutoHitGui()
    end)

    ASTER.Tabs.Combat:AddToggle("FaceEnemy", false, (function()
        local faceEnemyConnection = nil

        local function getCharacter(player)
            if not player then return nil end
            local playersFolder = workspace:FindFirstChild("Players")
            if playersFolder then
                local customChar = playersFolder:FindFirstChild(player.Name)
                if customChar then return customChar end
            end
            return player.Character
        end

        local function isTargetablePlayer(player)
            if not player or player == plr then return false end
            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
            local myTeam = plr.Team
            if myTeam ~= noTribe and player.Team == myTeam then
                return false
            end
            if isAlly(player) then
                return false
            end
            return true
        end

        local function getPlayerHitboxPart(char)
            if not char then return nil end
            local hrp = char:FindFirstChild("HumanoidRootPart")
            if hrp and hrp:IsA("BasePart") then
                return hrp
            end
            local hitbox = char:FindFirstChild("Hitbox")
            if hitbox and hitbox:IsA("BasePart") then
                return hitbox
            end
            return char:FindFirstChildWhichIsA("BasePart")
        end

        local function getHitboxFacePosition(hitboxPart, fromPos)
            if not hitboxPart or not fromPos then
                return nil
            end
            if not hitboxPart:IsA("BasePart") then
                return hitboxPart.Position
            end
            local localPoint = hitboxPart.CFrame:PointToObjectSpace(fromPos)
            local half = hitboxPart.Size * 0.5
            local clamped = Vector3.new(
                math.clamp(localPoint.X, -half.X, half.X),
                math.clamp(localPoint.Y, -half.Y, half.Y),
                math.clamp(localPoint.Z, -half.Z, half.Z)
            )
            return hitboxPart.CFrame:PointToWorldSpace(clamped)
        end

        local function getTargetHitboxDistance(char, fromPos)
            local hitboxPart = getPlayerHitboxPart(char)
            if not hitboxPart or not fromPos then
                return math.huge
            end
            local facePos = getHitboxFacePosition(hitboxPart, fromPos)
            if not facePos then
                return math.huge
            end
            return (facePos - fromPos).Magnitude
        end

        local function getNearestEnemyForFace()
            local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end

            local closestDistance = math.huge
            local closestPlayer = nil

            for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                if isTargetablePlayer(player) then
                    local char = getCharacter(player)
                    if char then
                        local distance = getTargetHitboxDistance(char, myRoot.Position)
                        if distance < closestDistance then
                            closestDistance = distance
                            closestPlayer = player
                        end
                    end
                end
            end
            return closestPlayer
        end

        local function getFollowFaceTarget()
            local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end

            local closestDistance = math.huge
            local closestPlayer = nil

            for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                if isTargetablePlayer(player) then
                    local char = getCharacter(player)
                    if char then
                        local distance = getTargetHitboxDistance(char, myRoot.Position)
                        if distance < closestDistance then
                            closestDistance = distance
                            closestPlayer = player
                        end
                    end
                end
            end
            return closestPlayer
        end

        local function getAutoHitFaceTarget()
            local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end

            local range = Settings.PlayerReachRange or 8
            local rangeSq = range * range
            local detectionRange = range + 10
            local detectionRangeSq = detectionRange * detectionRange
            local hrpPos = myRoot.Position
            local closestDistSq = math.huge
            local closestPlayer = nil

            for _, other in ipairs(game:GetService("Players"):GetPlayers()) do
                if other ~= plr and isTargetablePlayer(other) then
                    local char = getCharacter(other) or other.Character
                    local hitboxPart = getPlayerHitboxPart(char)
                    if hitboxPart then
                        local facePos = getHitboxFacePosition(hitboxPart, hrpPos) or hitboxPart.Position
                        local diff = facePos - hrpPos
                        local distSq = diff:Dot(diff)
                        if distSq <= detectionRangeSq then
                            local flatDiff = Vector3.new(diff.X, 0, diff.Z)
                            local flatDistSq = flatDiff:Dot(flatDiff)
                            local yDist = math.abs(diff.Y)
                            if flatDistSq <= detectionRangeSq and yDist <= 20 and flatDistSq <= rangeSq then
                                if flatDistSq < closestDistSq then
                                    closestDistSq = flatDistSq
                                    closestPlayer = other
                                end
                            end
                        end
                    end
                end
            end
            return closestPlayer
        end

        local function getFaceTarget()
            if Settings.FollowEnabled then
                return getFollowFaceTarget()
            end
            if Settings.AutoTraceEnabled and ASTER.GetTraceTarget then
                return ASTER.GetTraceTarget()
            end
            if Settings.AutoHitStartEnabled then
                return getAutoHitFaceTarget()
            end
            return getNearestEnemyForFace()
        end

        local function setAutoRotate(enabled)
            local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
            if hum then hum.AutoRotate = enabled end
        end

        return function(v)
            Settings.FaceEnemyEnabled = v

            if v then
                if not faceEnemyConnection then
                    -- RenderStepped so facing runs after movement (AutoTrace MoveTo on Heartbeat).
                    -- If FaceEnemy is enabled first, AutoRotate=false blocks AutoTrace movement.
                    faceEnemyConnection = runs.RenderStepped:Connect(function()
                        if not Settings.FaceEnemyEnabled then return end

                        local myChar = plr.Character
                        if not myChar then return end
                        local hum = myChar:FindFirstChildOfClass("Humanoid")
                        local myRoot = myChar:FindFirstChild("HumanoidRootPart")
                        if not hum or not myRoot then return end

                        local target = getFaceTarget()
                        if target then
                            local targetChar = getCharacter(target)
                            local hitboxPart = getPlayerHitboxPart(targetChar)
                            if hitboxPart then
                                local facePos = getHitboxFacePosition(hitboxPart, myRoot.Position) or hitboxPart.Position
                                local lookPos = Vector3.new(facePos.X, myRoot.Position.Y, facePos.Z)
                                if Settings.AutoTraceEnabled then
                                    -- Keep AutoRotate on so AutoTrace MoveTo still works when enabled after FaceEnemy.
                                    hum.AutoRotate = true
                                else
                                    hum.AutoRotate = false
                                end
                                -- When you walk into/overlap the target, lookPos is almost on top
                                -- of us horizontally. CFrame.lookAt with a ~zero direction produces
                                -- a NaN/degenerate CFrame that makes the character spin/fling.
                                -- Only re-orient when there's a meaningful horizontal gap.
                                if (lookPos - myRoot.Position).Magnitude > 0.25 then
                                    myRoot.CFrame = CFrame.lookAt(myRoot.Position, lookPos)
                                end
                                return
                            end
                        end

                        hum.AutoRotate = true
                    end)
                end
            else
                if faceEnemyConnection then
                    faceEnemyConnection:Disconnect()
                    faceEnemyConnection = nil
                end
                setAutoRotate(true)
            end
        end
    end)())

