    local function resolveArmorItemId(piece)
        local id = piece.id
        if not id and type(craftNameToID) == "table" then
            id = craftNameToID[piece.name]
        end
        if not id and type(autoDiscoverItemID) == "function" then
            id = autoDiscoverItemID(piece.name)
        end
        return id
    end

    local function playerOwnsArmorPiece(itemName)
        if type(getlayout) == "function" and getlayout(itemName) then
            return true
        end
        if type(playerOwnsCraftEquipItem) == "function" and playerOwnsCraftEquipItem(itemName) then
            return true
        end
        return false
    end

    local function isArmorPieceEquipped(itemName)
        if type(isCraftEquipItemEquipped) == "function" and isCraftEquipItemEquipped(itemName) then
            return true
        end
        if plr.Character and plr.Character:FindFirstChild(itemName) then
            return true
        end
        if type(isToolEquipped) == "function" and isToolEquipped(itemName) then
            return true
        end
        return false
    end

    local function playerOwnsArmorSet(setName)
        local pieces = ARMOR_SWITCH_SETS[setName]
        if not pieces then return false end
        for _, piece in ipairs(pieces) do
            if not playerOwnsArmorPiece(piece.name) then
                return false
            end
        end
        return true
    end

    local function isArmorSetFullyEquipped(setName)
        local pieces = ARMOR_SWITCH_SETS[setName]
        if not pieces then return false end
        for _, piece in ipairs(pieces) do
            if not isArmorPieceEquipped(piece.name) then
                return false
            end
        end
        return true
    end

    local ARMOR_SET_ORDER = {
        "Leaf Set", "Hide Set", "Iron Set", "Steel Set", "Adurite Set",
        "Crystal Set", "Magnetite Set", "Emerald Set", "Pink Diamond Set", "Void Set", "God Set",
    }

    local function getArmorSetList()
        local owned, unowned = {}, {}
        for _, setName in ipairs(ARMOR_SET_ORDER) do
            if ARMOR_SWITCH_SETS[setName] then
                if playerOwnsArmorSet(setName) then
                    table.insert(owned, setName)
                else
                    table.insert(unowned, setName)
                end
            end
        end
        for setName in pairs(ARMOR_SWITCH_SETS) do
            if not table.find(owned, setName) and not table.find(unowned, setName) then
                if playerOwnsArmorSet(setName) then
                    table.insert(owned, setName)
                else
                    table.insert(unowned, setName)
                end
            end
        end
        local names = {}
        for _, setName in ipairs(owned) do
            table.insert(names, setName)
        end
        for _, setName in ipairs(unowned) do
            table.insert(names, setName)
        end
        return names
    end

    local function getActiveArmorSet()
        for setName in pairs(ARMOR_SWITCH_SETS) do
            if isArmorSetFullyEquipped(setName) then
                return setName
            end
        end
        return nil
    end

    local function equipArmorPiece(piece)
        local itemName = piece.name
        if isArmorPieceEquipped(itemName) then
            return true
        end

        local slotID = type(getlayout) == "function" and getlayout(itemName) or nil
        local itemID = resolveArmorItemId(piece)
        local actionId = getPacketId("UseBagItem")
        if not slotID or not itemID or not actionId or not ByteNetReliable then
            return false
        end

        local b = buffer.create(8)
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, actionId)
        buffer.writeu32(b, 2, slotID)
        buffer.writeu16(b, 6, itemID)
        ByteNetReliable:FireServer(b)
        return true
    end

    local function equipArmorSet(setName)
        local pieces = ARMOR_SWITCH_SETS[setName]
        if not pieces or not playerOwnsArmorSet(setName) then
            return false
        end

        local changed = false
        for _, piece in ipairs(pieces) do
            if not isArmorPieceEquipped(piece.name) then
                if equipArmorPiece(piece) then
                    changed = true
                end
                task.wait(0.12)
            end
        end
        return changed or isArmorSetFullyEquipped(setName)
    end

    local switchSetsDropdown
    local autoSwitchActive = false
    local autoSwitchUsingBackup = false
    local autoSwitchPrimarySet = nil
    local autoSwitchLastAt = 0
    local AUTO_SWITCH_COOLDOWN = 1.25

    local function refreshSwitchSetsDropdown()
        if not switchSetsDropdown or not switchSetsDropdown.SetValues then return end
        local values = getArmorSetList()
        switchSetsDropdown:SetValues(values)

        local current = Settings.SelectedSwitchSet
        if current and current ~= "" and table.find(values, current) then
            switchSetsDropdown:SetValue(current)
        elseif values[1] then
            switchSetsDropdown:SetValue(values[1])
            Settings.SelectedSwitchSet = values[1]
        end
    end
    ASTER.RefreshSwitchSetsDropdown = refreshSwitchSetsDropdown

    local initialSwitchSets = getArmorSetList()
    local initialSwitchSet = Settings.SelectedSwitchSet
    if not initialSwitchSet or initialSwitchSet == "" or not table.find(initialSwitchSets, initialSwitchSet) then
        initialSwitchSet = initialSwitchSets[1] or ""
        Settings.SelectedSwitchSet = initialSwitchSet
    end

