    local function startAutoSwitchSets()
        if autoSwitchActive then return end
        autoSwitchActive = true
        autoSwitchUsingBackup = false
        autoSwitchPrimarySet = getActiveArmorSet()

        task.spawn(function()
            while Settings.AutoSwitchSetsEnabled do
                local hum = plr.Character and plr.Character:FindFirstChild("Humanoid")
                if hum and hum.Health > 0 and hum.MaxHealth > 0 then
                    local hpPct = (hum.Health / hum.MaxHealth) * 100
                    local threshold = tonumber(Settings.SelectSwitchHealth) or 30
                    local backupSet = Settings.SelectedSwitchSet
                    local now = os.clock()

                    if backupSet and backupSet ~= "" and backupSet ~= "(none)" then
                        if hpPct <= threshold then
                            if not autoSwitchUsingBackup and (now - autoSwitchLastAt) >= AUTO_SWITCH_COOLDOWN then
                                local wornSet = getActiveArmorSet()
                                if wornSet and wornSet ~= "" and wornSet ~= "(none)" and wornSet ~= backupSet then
                                    autoSwitchPrimarySet = wornSet
                                end
                                if autoSwitchPrimarySet ~= backupSet and equipArmorSet(backupSet) then
                                    autoSwitchUsingBackup = true
                                    autoSwitchLastAt = now
                                end
                            end
                        elseif Settings.AutoSwitchBack == true
                            and autoSwitchUsingBackup
                            and autoSwitchPrimarySet
                            and autoSwitchPrimarySet ~= ""
                            and autoSwitchPrimarySet ~= "(none)"
                            and (now - autoSwitchLastAt) >= AUTO_SWITCH_COOLDOWN then
                            if equipArmorSet(autoSwitchPrimarySet) then
                                autoSwitchUsingBackup = false
                                autoSwitchLastAt = now
                            end
                        end
                    end
                end
                task.wait(0.15)
            end
            autoSwitchActive = false
            autoSwitchUsingBackup = false
        end)
    end

