ASTER.Tabs.Combat:AddToggle("Follow Nearest Player", false, (function()
        local followConnection = nil
        
        -- Helper to find character in custom folder or standard location
        local function getCharacter(player)
            if not player then return nil end
            
            -- Check workspace.Players first (Custom Game Structure)
            local playersFolder = workspace:FindFirstChild("Players")
            if playersFolder then
                local char = playersFolder:FindFirstChild(player.Name)
                if char then return char end
            end
            
            -- Fallback to standard
            return player.Character
        end
        
        local function getNearestPlayerForFollow()
             local closestDistance = math.huge
             local closestPlayer = nil
             local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
             if not myRoot then return nil end
             
             for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                 if player ~= plr then
                     local isTargetable = true
                     
                     -- Check Teams
                     local myTeam = plr.Team
                     local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                     
                     if myTeam ~= noTribe and player.Team == myTeam then
                         isTargetable = false
                     end

                     if isTargetable and isAlly(player) then
                         isTargetable = false
                     end
                     
                     if isTargetable then
                         local char = getCharacter(player)
                         if char and char:FindFirstChild("HumanoidRootPart") then
                             local targetRoot = char.HumanoidRootPart
                             local distance = (targetRoot.Position - myRoot.Position).Magnitude
                             if distance < closestDistance then
                                 closestDistance = distance
                                 closestPlayer = player
                             end
                         end
                     end
                 end
             end
             return closestPlayer
        end
        
        return function(v)
            Settings.FollowEnabled = v
            
            -- Mobile Button Sync (Visual Only)
            if Settings.MobileFollowButton then
                local widget = ASTER.GetMobileWidgetByGuiName("AsterFollowGui")
                if widget then
                    widget.setToggleState(v, "Follow")
                end
            end
            
            if v then
                if not followConnection then
                    followConnection = game:GetService("RunService").Heartbeat:Connect(function()
                        if not Settings.FollowEnabled then return end
                        
                        local myChar = plr.Character
                        if not myChar then return end
                        local hum = myChar:FindFirstChild("Humanoid")
                        local root = myChar:FindFirstChild("HumanoidRootPart")
                        
                        if hum and root then
                            local target = getNearestPlayerForFollow()
                            if target then
                                local targetChar = getCharacter(target)
                                if targetChar and targetChar:FindFirstChild("HumanoidRootPart") then
                                    local targetRoot = targetChar.HumanoidRootPart
                                    
                                    -- Movement Only
                                    hum:MoveTo(targetRoot.Position)
                                end
                            else
                                -- Stop if no target (move to self to stop)
                                hum:MoveTo(root.Position)
                            end
                        end
                    end)
                end
            else
                if followConnection then
                    followConnection:Disconnect()
                    followConnection = nil
                end
                -- Stop moving
                if plr.Character and plr.Character:FindFirstChild("Humanoid") and plr.Character:FindFirstChild("HumanoidRootPart") then
                    plr.Character.Humanoid:MoveTo(plr.Character.HumanoidRootPart.Position)
                end
            end
        end
    end)())

    do
        local traceConnection = nil

        local function getCharacterForTrace(player)
            if not player then return nil end
            local playersFolder = workspace:FindFirstChild("Players")
            if playersFolder then
                local char = playersFolder:FindFirstChild(player.Name)
                if char then return char end
            end
            return player.Character
        end

        local function isTargetableForTrace(player)
            if not player or player == plr then return false end
            local myTeam = plr.Team
            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
            if myTeam ~= noTribe and player.Team == myTeam then
                return false
            end
            if isAlly(player) then
                return false
            end
            return true
        end

        local function getTraceRange()
            return Settings.TraceRange or Settings.PlayerReachRange or 8
        end

        local function getAutoTraceTarget()
            if not Settings.AutoTraceEnabled then return nil end

            local closestDistance = math.huge
            local closestPlayer = nil
            local myRoot = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
            if not myRoot then return nil end

            local traceRange = getTraceRange()
            local threshold = Settings.AutoTraceHealth or 10
            for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                if isTargetableForTrace(player) then
                    local char = getCharacterForTrace(player)
                    local hum = char and char:FindFirstChild("Humanoid")
                    local targetRoot = char and char:FindFirstChild("HumanoidRootPart")
                    if hum and targetRoot and hum.Health > 0 and hum.Health <= threshold + 0.05 then
                        local distance = (targetRoot.Position - myRoot.Position).Magnitude
                        if distance <= traceRange and distance < closestDistance then
                            closestDistance = distance
                            closestPlayer = player
                        end
                    end
                end
            end
            return closestPlayer
        end

        ASTER.GetTraceTarget = getAutoTraceTarget

        local function stopTraceMovement()
            if plr.Character and plr.Character:FindFirstChild("Humanoid") and plr.Character:FindFirstChild("HumanoidRootPart") then
                plr.Character.Humanoid:MoveTo(plr.Character.HumanoidRootPart.Position)
            end
        end

        local function updateTraceLoop()
            if Settings.AutoTraceEnabled then
                if Settings.FaceEnemyEnabled then
                    local hum = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid")
                    if hum then hum.AutoRotate = true end
                end
                if not traceConnection then
                    traceConnection = game:GetService("RunService").Heartbeat:Connect(function()
                        if not Settings.AutoTraceEnabled then return end

                        local myChar = plr.Character
                        if not myChar then return end
                        local hum = myChar:FindFirstChild("Humanoid")
                        local root = myChar:FindFirstChild("HumanoidRootPart")
                        if not hum or not root then return end

                        local target = getAutoTraceTarget()
                        if target then
                            local targetChar = getCharacterForTrace(target)
                            local targetRoot = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
                            if targetRoot then
                                hum:MoveTo(targetRoot.Position)
                            else
                                hum:MoveTo(root.Position)
                            end
                        else
                            hum:MoveTo(root.Position)
                        end
                    end)
                end
            else
                if traceConnection then
                    traceConnection:Disconnect()
                    traceConnection = nil
                end
                stopTraceMovement()
            end
        end

        ASTER.Tabs.Combat:AddToggle("AutoTrace", false, function(v)
            Settings.AutoTraceEnabled = v
            updateTraceLoop()
        end)

        ASTER.Tabs.Combat:AddSlider("AutoTraceHealth", 1, 100, 10, 1, function(v)
            Settings.AutoTraceHealth = v
        end)
    end

    ASTER.Tabs.Combat:AddLabel("Auto Bolt")
    ASTER.Tabs.Combat:AddToggle("Auto Bolt", false, function(v)
        Settings.AutoBoltEnabled = v
        if v then
            task.spawn(function()
                while Settings.AutoBoltEnabled do
                    local myHrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
                    if myHrp then
                        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                            if p ~= plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character:FindFirstChild("Humanoid") then
                                local isTargetable = true
                                -- Check Teams
                                local myTeam = plr.Team
                                local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                                if myTeam ~= noTribe and p.Team == myTeam then isTargetable = false end
                                if isTargetable and isAlly(p) then isTargetable = false end
                                
                                if isTargetable then
                                    local dist = (p.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                                    local boltRange = Settings.AutoBoltRange or 50
                                    local boltThreshold = Settings.AutoBoltThreshold or 30
                                    
                                    if dist <= boltRange then
                                        local healthPct = (p.Character.Humanoid.Health / p.Character.Humanoid.MaxHealth) * 100
                                        if healthPct <= boltThreshold then
                                            -- Check Voodoo Level
                                            local voodoo = 0
                                            local gui = game:GetService("Players").LocalPlayer.PlayerGui
                                            if gui and gui:FindFirstChild("MainGui") and gui.MainGui:FindFirstChild("Panels") and gui.MainGui.Panels:FindFirstChild("Stats") then
                                                local bars = gui.MainGui.Panels.Stats:FindFirstChild("Bars")
                                                local voodooFrame = bars and bars:FindFirstChild("Voodoo")
                                                local label = voodooFrame and voodooFrame:FindFirstChild("ValueLabel")
                                                if label then
                                                    voodoo = tonumber(label.Text) or 0
                                                end
                                            end
                                            
                                            if voodoo >= 91 then
                                                -- Fire 3 Bolts Rapidly
                                                for i=1, 3 do
                                                    local targetHrp = getBoogaPlayerHRP(p)
                                                    local myHrp = getBoogaPlayerHRP(plr)
                                                    if targetHrp and myHrp then
                                                        sendVoodooPacket(targetHrp.CFrame, myHrp.CFrame)
                                                    end
                                                    task.wait(0.02) -- Very fast burst
                                                end
                                                task.wait(0.5) -- Cooldown after burst
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    task.wait(0.1) -- Fast Scan interval
                end
            end)
        end
    end)
    ASTER.Tabs.Combat:AddSlider("Bolt Range", 10, 200, 50, 5, function(v)
        Settings.AutoBoltRange = v
    end)
    ASTER.Tabs.Combat:AddSlider("Bolt Health %", 1, 100, 26, 1, function(v)
        Settings.AutoBoltThreshold = v
    end)
end -- AsterTabUI

do -- AsterBowSilentAim
getSilentAimChar = function(player)
    if not player then return nil end
    local playersFolder = workspace:FindFirstChild("Players")
    if playersFolder then
        local customChar = playersFolder:FindFirstChild(player.Name)
        if customChar then return customChar end
    end
    return player.Character
end

_silentAimTarget = nil
_silentAimTargetChar = nil
_saVelHistory = {}

    ASTER.Tabs.Combat:AddLabel("Bow Utilities")
    ASTER.Tabs.Combat:AddToggle("Expand Hitboxes", false, function(v)
        Settings.HitboxEnabled = v
    end)
    ASTER.Tabs.Combat:AddToggle("Bow Only (Auto Toggle)", false, function(v)
        Settings.HitboxBowOnly = v
    end)
    ASTER.Tabs.Combat:AddSlider("Hitbox Size", 2, 15, 7, 1, function(v)
        Settings.HitboxSize = v
    end)
    ASTER.Tabs.Combat:AddToggle("Show Hitbox", false, function(v)
        Settings.HitboxVisuals = v
    end)
    -- ScreenGui FOV ring: Drawing.new is unsupported/broken on mobile & Android (and some executors).
    local fovGui = Instance.new("ScreenGui")
    fovGui.ResetOnSpawn = false
    fovGui.IgnoreGuiInset = true
    fovGui.DisplayOrder = 10000
    fovGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function()
        asterParentGui(fovGui, "ASTER_FOV_Overlay")
    end)

    local fovCircle = Instance.new("Frame")
    fovCircle.Name = "FOVRing"
    fovCircle.AnchorPoint = Vector2.new(0.5, 0.5)
    fovCircle.BackgroundTransparency = 1
    fovCircle.BorderSizePixel = 0
    fovCircle.Visible = false
    fovCircle.Parent = fovGui
    local fovStroke = Instance.new("UIStroke")
    fovStroke.Thickness = 1.5
    fovStroke.Color = Color3.fromRGB(255, 255, 255)
    fovStroke.Transparency = 0.3
    fovStroke.Parent = fovCircle
    local fovCorner = Instance.new("UICorner")
    fovCorner.CornerRadius = UDim.new(1, 0)
    fovCorner.Parent = fovCircle

    local fovRadiusPx = 120
    local function setFovRadius(r)
        fovRadiusPx = r
        local d = math.max(8, r * 2)
        fovCircle.Size = UDim2.fromOffset(d, d)
    end
    setFovRadius(fovRadiusPx)

    ASTER.Tabs.Combat:AddToggle("Silent Aimbot", false, function(v)
        Settings.SilentAimbot = v
        if not v and not Settings.AutoShoot and not Settings.AutoShootCritter then
            pcall(restoreEventShotPassthrough)
        end
    end)
    ASTER.Tabs.Combat:AddDropdown("SilentAimbot Part", {
        "HumanoidRootPart", "Head", "UpperTorso", "LowerTorso",
        "LeftUpperArm", "RightUpperArm", "LeftUpperLeg", "RightUpperLeg"
    }, "HumanoidRootPart", function(v)
        Settings.SilentAimTargetPart = v
    end)

    local _aimToolNames = { "Bow", "Iron Bow", "God Sling", "Sling", "Magnetite Crossbow", "Crossbow", "Cannon", "Ballista" }
    local _aimToolList = { "All" }
    for _, name in ipairs(_aimToolNames) do
        table.insert(_aimToolList, name)
    end
    Settings.SelectedBowTool = "All"

    ASTER.Tabs.Combat:AddDropdown("Select Tool", _aimToolList, "All", function(v)
        Settings.SelectedBowTool = v
    end)

    ASTER.Tabs.Combat:AddToggle("Auto Shoot", false, function(v)
        Settings.AutoShoot = v
    end)
    ASTER.Tabs.Combat:AddToggle("Show FOV Circle", false, function(v)
        Settings.ShowFOVCircle = v
    end)
    ASTER.Tabs.Combat:AddSlider("FOV Circle Radius", 30, 800, 120, 5, function(v)
        Settings.HitboxFOVSize = v
        setFovRadius(v)
    end)
    ASTER.Tabs.Combat:AddToggle("Move Circle FOV", false, function(v)
        Settings.MoveFOV = v
    end)
    ASTER.Tabs.Combat:AddMultiDropdown(
        "Select Critters",
        getCritterNames(),
        Settings.SelectedBowCritters or {},
        function(v)
            Settings.SelectedBowCritters = v
        end
    )
    ASTER.Tabs.Combat:AddToggle("Auto Shoot Critter", false, function(v)
        Settings.AutoShootCritter = v == true
        if not v and not Settings.SilentAimbot and not Settings.AutoShoot then
            pcall(restoreEventShotPassthrough)
        end
    end)

    local fovDot = Instance.new("Frame")
    fovDot.Name = "FOVCenter"
    fovDot.AnchorPoint = Vector2.new(0.5, 0.5)
    fovDot.Size = UDim2.fromOffset(8, 8)
    fovDot.BackgroundColor3 = Color3.fromRGB(255, 50, 50)
    fovDot.BorderSizePixel = 0
    fovDot.Visible = false
    fovDot.Parent = fovGui
    local fovDotCorner = Instance.new("UICorner")
    fovDotCorner.CornerRadius = UDim.new(1, 0)
    fovDotCorner.Parent = fovDot

    local function setFovPosition(pos)
        local px = UDim2.fromOffset(pos.X, pos.Y)
        fovCircle.Position = px
        fovDot.Position = px
    end

    local function setFovVisible(show)
        local v = show == true
        fovCircle.Visible = v
        fovDot.Visible = v
    end

    local _fovLastTouchPos = nil
    local _fovIsTouchDevice = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    UserInputService.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.Touch then
            _fovLastTouchPos = Vector2.new(input.Position.X, input.Position.Y)
        end
    end)

    local function getFovScreenCenter(cam)
        if Settings.MoveFOV then
            if _fovIsTouchDevice and _fovLastTouchPos then
                return _fovLastTouchPos
            end
            local m = UserInputService:GetMouseLocation()
            if m and (m.X > 1 or m.Y > 1) then
                return m
            end
        end
        local vs = cam.ViewportSize
        return Vector2.new(vs.X * 0.5, vs.Y * 0.5)
    end

    local function isHoldingBow()
        local playersFolder = workspace:FindFirstChild("Players")
        if not playersFolder then return false end
        local plrFolder = playersFolder:FindFirstChild(plr.Name)
        if not plrFolder then return false end
        local toolsFolder = plrFolder:FindFirstChild("Tools")
        if not toolsFolder then return false end

        local sel = Settings.SelectedBowTool
        if sel and sel ~= "All" then
            return toolsFolder:FindFirstChild(sel) ~= nil
        end

        for _, tool in ipairs(toolsFolder:GetChildren()) do
            local n = tool.Name:lower()
            if n:find("bow") or n:find("sling") or n:find("crossbow") or n:find("cannon") or n:find("ballista") then
                return true
            end
        end
        return false
    end

    local function isSilentAimActive()
        return Settings.SilentAimbot
            or Settings.AutoShoot
            or Settings.AutoShootCritter
    end

    local function bowCritterSelectionWants(name)
        local selected = Settings.SelectedBowCritters
        if type(selected) ~= "table" or not name or name == "" then
            return false
        end
        if selected.All == true or selected.AllOptions == true then
            return true
        end
        if selected[name] == true then
            return true
        end
        if #selected > 0 then
            for _, entry in ipairs(selected) do
                if entry == "All" or entry == "AllOptions" or entry == name then
                    return true
                end
            end
        end
        return false
    end

    local function hasBowCritterSelection()
        local selected = Settings.SelectedBowCritters
        if type(selected) ~= "table" then
            return false
        end
        if selected.All == true or selected.AllOptions == true then
            return true
        end
        for k, v in pairs(selected) do
            if v == true and type(k) == "string" and k ~= "" then
                return true
            end
            if type(k) == "number" and type(v) == "string" and v ~= "" then
                return true
            end
        end
        return false
    end

    task.defer(function()
        if __ASTER_RUNTIME.silentAimEngineReady then return end
        __ASTER_RUNTIME.silentAimEngineReady = true
        pcall(function()
        do -- saEngine: keep silent aim locals out of parent scope
        local RunService = game:GetService("RunService")
        local Players = game:GetService("Players")
        local ReplicatedStorage = game:GetService("ReplicatedStorage")
        local UIS = game:GetService("UserInputService")

        local ProjectileClass, ItemData, ItemIDs
        pcall(function()
            ProjectileClass = require(ReplicatedStorage.Game.classes.projectile)
            ItemData = require(ReplicatedStorage.Modules.ItemData)
            ItemIDs = require(ReplicatedStorage.Modules.ItemIDS)
        end)
        if not ProjectileClass then return end

        local SPEED_CURVE = {
            {0, 430.16}, {494, 430.16}, {532, 424.46},
            {595, 424.00}, {990, 329.71}, {10000, 329.71},
        }

        local function saIsTargetable(player)
            if not player or player == plr then return false end
            if isAlly(player) then return false end
            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
            local myTeam = plr.Team
            if myTeam and myTeam ~= noTribe and player.Team == myTeam then
                return false
            end
            local char = getSilentAimChar(player)
            if not char then return false end
            local hum = char:FindFirstChildOfClass("Humanoid")
            return hum and hum.Health > 0
        end

        local function saGetAimPart(char)
            local partName = Settings.SilentAimTargetPart or "HumanoidRootPart"
            local part = char:FindFirstChild(partName)
            if part and part:IsA("BasePart") then return part end
            for _, name in ipairs({"HumanoidRootPart", "UpperTorso", "Head"}) do
                part = char:FindFirstChild(name)
                if part and part:IsA("BasePart") then return part end
            end
            return nil
        end

        saGetBestTarget = function(cam)
            if not cam then cam = workspace.CurrentCamera end
            if not cam then return nil, nil end

            -- Auto Shoot Critter: nearest selected critter to local player (Silent Aim pipeline).
            if Settings.AutoShootCritter then
                if hasBowCritterSelection() then
                    local myChar = getSilentAimChar(plr) or plr.Character
                    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    if myHrp then
                        local bestModel, bestPart, bestDist = nil, nil, math.huge
                        for _, critter in ipairs(collectWorkspaceCritters()) do
                            if isWorkspaceCritterAlive(critter) then
                                local cName = getWorkspaceCritterName(critter)
                                if bowCritterSelectionWants(cName) then
                                    local part = getWorkspaceCritterPart(critter)
                                    local model = getWorkspaceCritterModel(critter) or critter
                                    if part and model then
                                        local d = (part.Position - myHrp.Position).Magnitude
                                        if d < bestDist then
                                            bestDist = d
                                            bestModel = model
                                            bestPart = part
                                        end
                                    end
                                end
                            end
                        end
                        if bestModel and bestPart then
                            return bestModel, bestPart
                        end
                    end
                end
                -- Critter mode only: do not fall through to players.
                if not Settings.SilentAimbot and not Settings.AutoShoot then
                    return nil, nil
                end
            end

            local fovCenter = getFovScreenCenter(cam)
            local fovRadius = Settings.HitboxFOVSize or 120
            local camPos = cam.CFrame.Position

            local bestPart, bestChar, bestScore = nil, nil, math.huge
            local worldWeight = 0.00025

            for _, player in ipairs(Players:GetPlayers()) do
                if saIsTargetable(player) then
                    local char = getSilentAimChar(player)
                    local part = char and saGetAimPart(char)
                    if part then
                        local sp = cam:WorldToViewportPoint(part.Position)
                        if sp.Z > 0.01 then
                            local sd = (Vector2.new(sp.X, sp.Y) - fovCenter).Magnitude
                            if sd <= fovRadius then
                                local wd = (part.Position - camPos).Magnitude
                                local score = sd + wd * worldWeight
                                if score < bestScore then
                                    bestScore = score
                                    bestPart = part
                                    bestChar = char
                                end
                            end
                        end
                    end
                end
            end

            return bestChar, bestPart
        end

        local function saSpeedFromCurve(dist)
            local d = math.max(0, dist)
            for i = 1, #SPEED_CURVE - 1 do
                local a, b = SPEED_CURVE[i], SPEED_CURVE[i + 1]
                if d >= a[1] and d <= b[1] then
                    local t = (d - a[1]) / math.max(b[1] - a[1], 1e-6)
                    return a[2] + (b[2] - a[2]) * t
                end
            end
            return SPEED_CURVE[#SPEED_CURVE][2]
        end

        local function saGetItemRow(toolID, projectileName)
            if type(ItemData) ~= "table" then return nil end
            local id = tonumber(toolID)
            if id and ItemData[id] then return ItemData[id] end
            if type(ItemIDs) == "table" then
                local name = ItemIDs[id] or ItemIDs[tostring(id)]
                if name and ItemData[name] then return ItemData[name] end
            end
            if projectileName and ItemData[projectileName] then
                return ItemData[projectileName]
            end
            return nil
        end

        local function saSolveTrajectory(origin, vm, targetPos, gravityVec)
            local G = -gravityVec.Y
            local direct = (targetPos - origin).Unit
            if G <= 0 or vm <= 0 then
                return direct, 0, 0, false, false
            end
            local d = targetPos - origin
            local Dxz = Vector2.new(d.X, d.Z).Magnitude
            if Dxz < 8 then
                return direct, 0, d.Magnitude / vm, true, false
            end
            local v2 = vm * vm
            local disc = v2 * v2 - G * (G * Dxz * Dxz + 2 * d.Y * v2)
            if disc < 0 then
                return direct, 0, d.Magnitude / vm, false, false
            end
            local sq = math.sqrt(disc)
            local highAngle = math.atan((v2 + sq) / (G * Dxz))
            local lowAngle = math.atan((v2 - sq) / (G * Dxz))
            local angle = lowAngle
            local isHighArc = false
            if targetPos.Y - origin.Y > 100 then
                angle = highAngle
                isHighArc = true
            elseif angle ~= angle or math.abs(angle) > math.abs(highAngle) then
                angle = highAngle
                isHighArc = true
            end
            angle = math.clamp(angle, -1.5, 1.55)
            local flatDir = Vector3.new(d.X, 0, d.Z)
            if flatDir.Magnitude < 1e-6 then
                return direct, angle, d.Magnitude / vm, true, isHighArc
            end
            flatDir = flatDir.Unit
            local dir = (flatDir * math.cos(angle) + Vector3.new(0, math.sin(angle), 0)).Unit
            local horizontalSpeed = vm * math.cos(angle)
            local flightTime = (math.abs(horizontalSpeed) < 1e-6) and (d.Magnitude / vm) or math.min(Dxz / horizontalSpeed, 10)
            return dir, angle, flightTime, true, isHighArc
        end

        local function saPredictPosition(origin, targetPos, targetChar, targetPart, vm, gravityVec)
            local leadMult = Settings.SilentAimLeadMult or 1
            local vel = Vector3.zero
            local hist = _saVelHistory[targetChar]
            if hist then
                vel = Vector3.new(hist.vel.X, 0, hist.vel.Z) * leadMult
            else
                local rv = targetPart.AssemblyLinearVelocity
                vel = Vector3.new(rv.X, 0, rv.Z) * leadMult
            end
            local dist = (targetPos - origin).Magnitude
            local iterations = (dist > 150 and 8) or (dist > 75 and 6) or 4
            local flatCap = Settings.SilentAimFlatCap or 4
            local highCap = Settings.SilentAimHighArcCap or 1.5
            local predicted = targetPos
            for _ = 1, iterations do
                local _, _, flightTime, _, isHighArc = saSolveTrajectory(origin, vm, predicted, gravityVec)
                flightTime = math.min(flightTime, isHighArc and highCap or flatCap)
                predicted = targetPos + vel * flightTime
            end
            return predicted
        end

        local function saComputeAim(origin, targetPart, targetChar, projectileObject)
            local toolID = projectileObject.toolID
            local projectileName = projectileObject.projectileName
            local drawStrength = 1.0
            local item = saGetItemRow(toolID, projectileName)
            local projItem = (type(ItemData) == "table" and projectileName and ItemData[projectileName]) or nil
            local baseSpeed = (item and tonumber(item.velocityMagnitude)) or saSpeedFromCurve((targetPart.Position - origin).Magnitude)
            local addVel = (projItem and tonumber(projItem.additionalVelocity)) or 0
            local velocityMag = (baseSpeed + addVel) * drawStrength
            local addGrav = (projItem and tonumber(projItem.additionalGravity)) or 0
            local gravity = Vector3.new(0, -122.2 + addGrav, 0)
            local targetPos = targetPart.Position + Vector3.new(0, 0.1, 0)
            local predicted = saPredictPosition(origin, targetPos, targetChar, targetPart, velocityMag, gravity)
            return select(1, saSolveTrajectory(origin, velocityMag, predicted, gravity))
        end

        local function saApplyAim(self)
            if not isSilentAimActive() then return end
            if not isHoldingBow() then return end
            local targetChar, targetPart = saGetBestTarget(workspace.CurrentCamera)
            if not (targetPart and targetChar) then return end
            self.drawStrength = 1.0
            local origin = self.originCF and self.originCF.Position
            if not origin then return end
            local dir = saComputeAim(origin, targetPart, targetChar, self)
            if dir and dir.Magnitude > 0 then
                self.originCF = CFrame.lookAt(origin, origin + dir)
            end
        end

        registerHeartbeatUpdate("silentAimVelocity", function(dt)
            if not isSilentAimActive() then return end
            local cam = workspace.CurrentCamera
            for _, player in ipairs(Players:GetPlayers()) do
                if player ~= plr then
                    local char = getSilentAimChar(player)
                    if char then
                        local hrp = char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            if not _saVelHistory[char] then
                                _saVelHistory[char] = { prev = hrp.Position, vel = Vector3.zero }
                            else
                                local entry = _saVelHistory[char]
                                local frameVel = (dt > 0) and ((hrp.Position - entry.prev) / dt) or Vector3.zero
                                local dist = cam and (hrp.Position - cam.CFrame.Position).Magnitude or 100
                                local alpha = math.clamp(0.5 - (dist / 1000), 0.2, 0.5)
                                entry.vel = entry.vel:Lerp(frameVel, alpha)
                                entry.prev = hrp.Position
                            end
                        end
                    end
                end
            end
            -- Critter lead support for Auto Shoot Critter (same prediction path as players).
            if Settings.AutoShootCritter and hasBowCritterSelection() then
                for _, critter in ipairs(collectWorkspaceCritters()) do
                    if isWorkspaceCritterAlive(critter) then
                        local cName = getWorkspaceCritterName(critter)
                        if bowCritterSelectionWants(cName) then
                            local model = getWorkspaceCritterModel(critter) or critter
                            local part = getWorkspaceCritterPart(critter)
                            if model and part then
                                if not _saVelHistory[model] then
                                    _saVelHistory[model] = { prev = part.Position, vel = Vector3.zero }
                                else
                                    local entry = _saVelHistory[model]
                                    local frameVel = (dt > 0) and ((part.Position - entry.prev) / dt) or Vector3.zero
                                    local dist = cam and (part.Position - cam.CFrame.Position).Magnitude or 100
                                    local alpha = math.clamp(0.5 - (dist / 1000), 0.2, 0.5)
                                    entry.vel = entry.vel:Lerp(frameVel, alpha)
                                    entry.prev = part.Position
                                end
                            end
                        end
                    end
                end
            end
        end)
        ensureMasterHeartbeatLoop()

        trackConnection("silentAimPlayerRemoving", Players.PlayerRemoving:Connect(function(player)
            local char = getSilentAimChar(player)
            if char then _saVelHistory[char] = nil end
            if _silentAimTargetChar and (player.Character == _silentAimTargetChar or char == _silentAimTargetChar) then
                _silentAimTarget, _silentAimTargetChar = nil, nil
            end
        end))

        registerFrameUpdate("silentAimRender", function()
            local aimActive = isSilentAimActive()
            local showFov = Settings.ShowFOVCircle == true
            if not aimActive and not showFov then
                _silentAimTarget, _silentAimTargetChar = nil, nil
                setFovVisible(false)
                return
            end
            setFovVisible(aimActive and showFov)
            local cam = workspace.CurrentCamera
            if showFov and cam then
                setFovPosition(getFovScreenCenter(cam))
            end
            if not aimActive then
                _silentAimTarget, _silentAimTargetChar = nil, nil
                return
            end
            if not cam then return end
            local targetChar, targetPart = saGetBestTarget(cam)
            _silentAimTarget = targetPart
            _silentAimTargetChar = targetChar
        end)
        ensureMasterFrameLoop()

        local function saHasShootTarget()
            if not isHoldingBow() then return false, nil, nil end
            local cam = workspace.CurrentCamera
            if not cam then return false, nil, nil end
            local targetChar, targetPart = saGetBestTarget(cam)
            if targetPart and targetChar then
                _silentAimTarget = targetPart
                _silentAimTargetChar = targetChar
                return true, targetChar, targetPart
            end
            return false, nil, nil
        end

        if not __ASTER_RUNTIME.autoShootLoopStarted then
            __ASTER_RUNTIME.autoShootLoopStarted = true
            local session = CURRENT_SESSION
            task.spawn(function()
            local vim = game:GetService("VirtualInputManager")
            local FULL_CHARGE = 0.58
            local POLL = 0.02
            local COOLDOWN = 0.13
            local lastShot = 0

            -- Combat tab Auto Shoot / Auto Shoot Critter: hold draw (player mouse input)
            while isRuntimeSessionActive(session) do
                if not Settings.AutoShoot and not Settings.AutoShootCritter then
                    task.wait(0.25)
                    continue
                end
                task.wait(0.025)
                if (tick() - lastShot >= COOLDOWN) and saHasShootTarget() then
                    local m = UIS:GetMouseLocation()
                    local mx, my = math.floor(m.X), math.floor(m.Y)
                    pcall(function() vim:SendMouseButtonEvent(mx, my, 0, true, game, 1) end)
                    local t0 = tick()
                    while tick() - t0 < FULL_CHARGE do
                        task.wait(POLL)
                        if (not Settings.AutoShoot and not Settings.AutoShootCritter) or not saHasShootTarget() then break end
                    end
                    pcall(function() vim:SendMouseButtonEvent(mx, my, 0, false, game, 1) end)
                    lastShot = tick()
                    task.wait(COOLDOWN)
                end
            end
            end)
        end


        local oldNew = ProjectileClass.new
        local function hookedNew(self, ...)
            pcall(function() saApplyAim(self) end)
            return oldNew(self, ...)
        end
        if hookfunction and type(hookfunction) == "function" then
            oldNew = hookfunction(ProjectileClass.new, hookedNew)
        else
            ProjectileClass.new = function(self, ...)
                return hookedNew(self, ...)
            end
        end

        if typeof(hookmetamethod) == "function" and typeof(getnamecallmethod) == "function" then
            pcall(function()
                local oldNc
                oldNc = hookmetamethod(game, "__namecall", function(self, ...)
                    if isSilentAimActive()
                        and getnamecallmethod() == "FireServer"
                        and typeof(self) == "Instance"
                        and self.Name == "CreateProjectile"
                    then
                        local shot = select(1, ...)
                        if shot then pcall(function() saApplyAim(shot) end) end
                    end
                    return oldNc(self, ...)
                end)
            end)
        end
        end -- saEngine
        end)
    end)

        local _hitboxAccum = 0
        registerFrameUpdate("hitboxVisuals", function(dt)
            if not Settings.HitboxEnabled and not Settings.HitboxVisuals then return end
            _hitboxAccum = _hitboxAccum + dt
            if _hitboxAccum < 0.1 then return end
            _hitboxAccum = 0
            pcall(function()
                 local enabled = Settings.HitboxEnabled
                 local visuals = Settings.HitboxVisuals
                 if not enabled and not visuals then return end

                 if Settings.HitboxBowOnly and not isHoldingBow() then
                     enabled = false
                 end

                 local myChar = getSilentAimChar(plr) or plr.Character
                 local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                 if not myHrp then return end
                 local baseSize = Settings.HitboxSize or 7
                 
                 for _, player in pairs(Players:GetPlayers()) do
                    local char = getSilentAimChar(player)
                    if player ~= plr and char then
                        local hrp = char:FindFirstChild("HumanoidRootPart")
                        if hrp then
                            local shouldExpand = enabled and not isAlly(player)

                            if shouldExpand then
                                local head = char:FindFirstChild("Head")
                                if head then
                                    for _, v in ipairs(hrp:GetChildren()) do
                                        if v:IsA("BillboardGui") and v.Adornee ~= head
                                            and v.Name ~= "ESPHitboxVisual" and v.Name ~= "GodESPHitboxVisual"
                                            and not string.find(v.Name, "ESPHitboxVisual_", 1, true)
                                            and not string.find(v.Name, "GodESPHitboxVisual_", 1, true) then
                                            v.Adornee = head
                                        end
                                    end
                                end

                                local dist = (hrp.Position - myHrp.Position).Magnitude
                                local finalSize = baseSize
                                if dist < 40 then
                                    local alpha = math.clamp(dist / 40, 0.3, 1)
                                    finalSize = math.max(3, baseSize * alpha)
                                end

                                if math.abs(hrp.Size.X - finalSize) > 0.2 then
                                    hrp.Size = Vector3.new(finalSize, finalSize, finalSize)
                                    hrp.CanCollide = false
                                    hrp.Transparency = 1
                                end
                                
                                if visuals then
                                    local box = hrp:FindFirstChild("HitboxVisual")
                                    if not box then
                                        box = Instance.new("SelectionBox")
                                        box.Name = "HitboxVisual"
                                        box.Adornee = hrp
                                        box.LineThickness = 0
                                        box.Transparency = 1
                                        box.SurfaceTransparency = 0.75
                                        box.SurfaceColor3 = Color3.fromRGB(255, 50, 50)
                                        box.Parent = hrp
                                    end
                                    box.Visible = true
                                else
                                    local box = hrp:FindFirstChild("HitboxVisual")
                                    if box then box.Visible = false end
                                end
                            else
                                if hrp.Size.X > 2.5 then
                                    hrp.Size = Vector3.new(2, 2, 1)
                                    hrp.Transparency = 1
                                    hrp.CanCollide = true
                                end
                                local box = hrp:FindFirstChild("HitboxVisual")
                                if box then box:Destroy() end
                            end
                        end
                    end
                 end
            end)
        end)
        ensureMasterFrameLoop()

        -- Selected bow critters only: force aim part hitbox to 15^3 (no targeting changes).
        local _bowCritterHitboxAccum = 0
        local BOW_CRITTER_HITBOX = Vector3.new(15, 15, 15)
        registerFrameUpdate("bowCritterHitbox", function(dt)
            if not hasBowCritterSelection() then return end
            _bowCritterHitboxAccum = _bowCritterHitboxAccum + dt
            if _bowCritterHitboxAccum < 0.1 then return end
            _bowCritterHitboxAccum = 0
            pcall(function()
                for _, critter in ipairs(collectWorkspaceCritters()) do
                    if isWorkspaceCritterAlive(critter) then
                        local cName = getWorkspaceCritterName(critter)
                        if bowCritterSelectionWants(cName) then
                            local part = getWorkspaceCritterPart(critter)
                            if part and (math.abs(part.Size.X - 15) > 0.2 or math.abs(part.Size.Y - 15) > 0.2 or math.abs(part.Size.Z - 15) > 0.2) then
                                part.Size = BOW_CRITTER_HITBOX
                                part.CanCollide = false
                            end
                        end
                    end
                end
            end)
        end)
        ensureMasterFrameLoop()
end -- AsterBowSilentAim


do -- AsterKeybindOverlay
    ASTER.Options.VoodooSpell = ASTER.Options.VoodooSpell or {}
    ASTER.Options.VoodooSpell.Keybind = nil

    ASTER.KeybindsOverlayUI = ASTER.KeybindsOverlayUI or {}
    local KO = ASTER.KeybindsOverlayUI

    local function copyOverlaySelection(sel)
        local out = {}
        for k, v in pairs(sel or {}) do
            if v then out[k] = true end
        end
        return out
    end

    local function isKeybindOverlayItemVisible(name)
        local sel = Settings.KeybindOverlaySelection
        if type(sel) ~= "table" or not next(sel) then
            return true
        end
        return sel[name] == true
    end

    local function shouldShowInKeybindOverlay(name, key)
        if not isKeybindOverlayItemVisible(name) then return false end
        return type(key) == "string" and key ~= ""
    end

    local function getKeybindOverlayOptionList()
        ToggleBind.ensureBuiltinBinds()
        local opts, seen = {}, {}
        for _, bind in ipairs(ToggleBind.BUILTIN_BINDS or {}) do
            local key = bind.get and bind.get()
            if shouldShowInKeybindOverlay(bind.id, key) and not seen[bind.id] then
                seen[bind.id] = true
                table.insert(opts, bind.id)
            end
        end
        for toggleName, bindKey in pairs(Settings.ToggleKeybinds or {}) do
            if bindKey and bindKey ~= "" and Window.ElementRegistry[toggleName]
                and shouldShowInKeybindOverlay(toggleName, bindKey) and not seen[toggleName] then
                seen[toggleName] = true
                table.insert(opts, toggleName)
            end
        end
        table.sort(opts, function(a, b) return tostring(a) < tostring(b) end)
        return opts
    end

    local function getKeybindOverlayDefaultSelection()
        return copyOverlaySelection(Settings.KeybindOverlaySelection)
    end

    local function hideKeybindOverlayItem(name)
        ToggleBind.clearKeybindByName(name)
    end

    function ASTER.RefreshKeybindOverlayDropdown()
        ASTER.RefreshKeybindsOverlayRows()
    end

    function ASTER.SyncKeybindsOverlayWithMainUI(mainUiVisible)
        if not Settings.ShowKeybindsOverlay then
            if KO.gui then KO.gui.Enabled = false end
            return
        end
        if mainUiVisible then
            if not KO.gui or not KO.gui.Parent then
                ASTER.CreateKeybindsOverlay()
            else
                KO.gui.Enabled = true
            end
        elseif KO.gui then
            KO.gui.Enabled = false
        end
    end

    function ASTER.ApplyKeybindsOverlaySize()
        if not KO.container then return end
        local sizeVal = math.clamp(tonumber(Settings.OverlayMenuSize or Settings.OverlayMenuSide) or 5, 0, 10)
        local scale = 0.5 + (sizeVal / 10) * 1.0
        if not KO.uiScale then
            KO.uiScale = Instance.new("UIScale")
            KO.uiScale.Parent = KO.container
        end
        KO.uiScale.Scale = scale
    end

    local function getKeybindOverlayEntries()
        local entries = {}
        local function push(name, key, isOn, isTrigger)
            if not shouldShowInKeybindOverlay(name, key) then return end
            table.insert(entries, { name = name, key = key, isOn = isOn, isTrigger = isTrigger })
        end
        push("AutoHit", Settings.AutoHitKey, Settings.AutoHitStartEnabled)
        push("Auto Heal", Settings.QuickHealKey, healRunning)
        push("Chest", Settings.AutoChestKey, Settings.AutoChestEnabled)
        push("Pinch", ConfigPinch.Keybind, ConfigPinch.Enabled)
        push("Quick Hut", Settings.QuickHutKey, Settings.QuickHut)
        push("Follow", Settings.FollowKey, Settings.FollowEnabled)
        push("Voodoo", ASTER.Options.VoodooSpell.Keybind, false, true)
        for toggleName, bindKey in pairs(Settings.ToggleKeybinds or {}) do
            if bindKey and bindKey ~= "" and Window.ElementRegistry[toggleName] then
                local reg = Window.ElementRegistry[toggleName]
                local isOn = reg.GetValue and reg.GetValue() or false
                push(toggleName, bindKey, isOn)
            end
        end
        return entries
    end

    function ASTER.ApplyKeybindsOverlayTheme()
        if not KO.gui or not KO.container then return end
        local frame = KO.container
        local themeMain = (CurrentTheme and CurrentTheme.Main) or UI.Surface.Text

        frame.BackgroundColor3 = UI.Surface.Card
        frame.BackgroundTransparency = GlobalTransparency

        if KO.frameStroke then
            KO.frameStroke.Color = UI.Surface.Stroke
            ApplyGradient(KO.frameStroke)
        end

        if KO.header then
            KO.header.BackgroundColor3 = UI.Surface.Control
            KO.header.BackgroundTransparency = GlobalTransparency
        end

        if KO.headerLine then
            KO.headerLine.BackgroundColor3 = themeMain
            ApplyGradient(KO.headerLine)
        end

        if KO.titleLabel then
            KO.titleLabel.TextColor3 = UI.Surface.Text
            ApplyGradient(KO.titleLabel)
        end

        if KO.subtitleLabel then
            KO.subtitleLabel.TextColor3 = UI.Surface.Muted
        end

        if KO.body then
            for _, row in ipairs(KO.body:GetChildren()) do
                if row:IsA("Frame") and row.Name == "BindRow" then
                    row.BackgroundColor3 = UI.Surface.Control
                    row.BackgroundTransparency = math.clamp(GlobalTransparency + 0.15, 0, 0.85)
                    local keyBadge = row:FindFirstChild("KeyBadge")
                    if keyBadge then
                        keyBadge.BackgroundColor3 = UI.Surface.ControlHover
                        keyBadge.TextColor3 = themeMain
                        ApplyGradient(keyBadge)
                    end
                    local nameLabel = row:FindFirstChild("NameLabel")
                    if nameLabel then nameLabel.TextColor3 = UI.Surface.Text end
                    local statusLabel = row:FindFirstChild("StatusLabel")
                    if statusLabel then
                        local on = statusLabel:GetAttribute("IsOn") == true
                        local trigger = statusLabel:GetAttribute("IsTrigger") == true
                        if trigger then
                            statusLabel.Text = "KEY"
                            statusLabel.TextColor3 = themeMain
                        elseif on then
                            statusLabel.Text = "ON"
                            statusLabel.TextColor3 = Color3.fromRGB(90, 255, 150)
                        else
                            statusLabel.Text = "OFF"
                            statusLabel.TextColor3 = UI.Surface.Danger
                        end
                    end
                end
            end
        end
    end

    local function createKeybindOverlayRow(entry)
        local themeMain = (CurrentTheme and CurrentTheme.Main) or UI.Surface.Text
        local row = Instance.new("Frame")
        row.Name = "BindRow"
        row.Size = UDim2.new(1, 0, 0, 22)
        row.BackgroundColor3 = UI.Surface.Control
        row.BackgroundTransparency = math.clamp(GlobalTransparency + 0.15, 0, 0.85)
        row.BorderSizePixel = 0
        uiCorner(row, UI.Radius.sm)

        local keyBadge = Instance.new("TextLabel", row)
        keyBadge.Name = "KeyBadge"
        keyBadge.Size = UDim2.fromOffset(26, 16)
        keyBadge.Position = UDim2.fromOffset(4, 3)
        keyBadge.BackgroundColor3 = UI.Surface.ControlHover
        keyBadge.BorderSizePixel = 0
        keyBadge.Font = UI.FontTitle
        keyBadge.TextSize = 9
        keyBadge.Text = tostring(entry.key or "?")
        keyBadge.TextColor3 = themeMain
        keyBadge.TextTruncate = Enum.TextTruncate.AtEnd
        uiCorner(keyBadge, UI.Radius.sm)
        ApplyGradient(keyBadge)

        local nameLabel = Instance.new("TextLabel", row)
        nameLabel.Name = "NameLabel"
        nameLabel.Size = UDim2.new(1, -78, 1, 0)
        nameLabel.Position = UDim2.fromOffset(34, 0)
        nameLabel.BackgroundTransparency = 1
        nameLabel.Font = UI.FontBody
        nameLabel.TextSize = 11
        nameLabel.TextXAlignment = Enum.TextXAlignment.Left
        nameLabel.Text = entry.name
        nameLabel.TextColor3 = UI.Surface.Text
        nameLabel.TextTruncate = Enum.TextTruncate.AtEnd

        local statusLabel = Instance.new("TextLabel", row)
        statusLabel.Name = "StatusLabel"
        statusLabel.Size = UDim2.fromOffset(28, 16)
        statusLabel.AnchorPoint = Vector2.new(1, 0.5)
        statusLabel.Position = UDim2.new(1, -18, 0.5, 0)
        statusLabel.BackgroundTransparency = 1
        statusLabel.Font = UI.FontTitle
        statusLabel.TextSize = 9
        statusLabel.TextXAlignment = Enum.TextXAlignment.Right
        statusLabel:SetAttribute("IsOn", entry.isOn == true)
        statusLabel:SetAttribute("IsTrigger", entry.isTrigger == true)

        if entry.isTrigger then
            statusLabel.Text = "KEY"
            statusLabel.TextColor3 = themeMain
        elseif entry.isOn then
            statusLabel.Text = "ON"
            statusLabel.TextColor3 = Color3.fromRGB(90, 255, 150)
        else
            statusLabel.Text = "OFF"
            statusLabel.TextColor3 = UI.Surface.Danger
        end

        local hideBtn = Instance.new("TextButton", row)
        hideBtn.Name = "HideBtn"
        hideBtn.Size = UDim2.fromOffset(14, 14)
        hideBtn.AnchorPoint = Vector2.new(1, 0.5)
        hideBtn.Position = UDim2.new(1, -2, 0.5, 0)
        hideBtn.BackgroundTransparency = 1
        hideBtn.BorderSizePixel = 0
        hideBtn.AutoButtonColor = false
        hideBtn.Font = UI.FontTitle
        hideBtn.TextSize = 11
        hideBtn.Text = "x"
        hideBtn.TextColor3 = UI.Surface.Muted
        hideBtn.MouseButton1Click:Connect(function()
            hideKeybindOverlayItem(entry.name)
        end)

        return row
    end

    function ASTER.RefreshKeybindsOverlayRows()
        if not KO.body then return end
        KO.body:ClearAllChildren()
        local layout = Instance.new("UIListLayout", KO.body)
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 2)
        for i, entry in ipairs(getKeybindOverlayEntries()) do
            local row = createKeybindOverlayRow(entry)
            row.LayoutOrder = i
            row.Parent = KO.body
        end
    end

    function ASTER.CreateKeybindsOverlay()
        if KO.gui and KO.gui.Parent then return end

        local gui = Instance.new("ScreenGui")
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        if game:GetService("RunService"):IsStudio() then
            gui.Name = asterGuiCoverName("AsterKeybindsOverlay")
            gui.Parent = plr:WaitForChild("PlayerGui")
        else
            asterParentGui(gui, "AsterKeybindsOverlay")
        end

        local frame = Instance.new("Frame")
        frame.Name = "Container"
        frame.AnchorPoint = Vector2.new(0.5, 0)
        frame.Position = UDim2.new(0.5, 0, 0, 8)
        frame.Size = UDim2.fromOffset(162, 0)
        frame.AutomaticSize = Enum.AutomaticSize.Y
        frame.BackgroundColor3 = UI.Surface.Card
        frame.BackgroundTransparency = GlobalTransparency
        frame.BorderSizePixel = 0
        frame.Active = true
        frame.Parent = gui
        uiCorner(frame, UI.Radius.lg)

        local frameStroke = uiStroke(frame, 1, 0.45)
        ApplyGradient(frameStroke)

        uiPadding(frame, UI.Space.xs, UI.Space.xs, UI.Space.xs, UI.Space.xs)

        local header = Instance.new("Frame", frame)
        header.Name = "Header"
        header.Size = UDim2.new(1, 0, 0, 24)
        header.BackgroundColor3 = UI.Surface.Control
        header.BackgroundTransparency = GlobalTransparency
        header.BorderSizePixel = 0
        uiCorner(header, UI.Radius.sm)

        local titleLabel = Instance.new("TextLabel", header)
        titleLabel.Name = "Title"
        titleLabel.Size = UDim2.new(1, -10, 0, 14)
        titleLabel.Position = UDim2.fromOffset(8, 3)
        titleLabel.BackgroundTransparency = 1
        titleLabel.Font = UI.FontTitle
        titleLabel.TextSize = 12
        titleLabel.TextXAlignment = Enum.TextXAlignment.Left
        titleLabel.Text = "Keybinds"
        titleLabel.TextColor3 = UI.Surface.Text
        ApplyGradient(titleLabel)

        local subtitleLabel = Instance.new("TextLabel", header)
        subtitleLabel.Name = "Subtitle"
        subtitleLabel.Size = UDim2.new(1, -10, 0, 10)
        subtitleLabel.Position = UDim2.fromOffset(8, 14)
        subtitleLabel.BackgroundTransparency = 1
        subtitleLabel.Font = UI.FontLabel
        subtitleLabel.TextSize = 8
        subtitleLabel.TextXAlignment = Enum.TextXAlignment.Left
        subtitleLabel.Text = "Drag header Ãƒâ€šÃ‚Â· x hides row"
        subtitleLabel.TextColor3 = UI.Surface.Muted

        local headerLine = Instance.new("Frame", frame)
        headerLine.Name = "HeaderLine"
        headerLine.Size = UDim2.new(1, -12, 0, 1)
        headerLine.Position = UDim2.new(0, 6, 0, 28)
        headerLine.BorderSizePixel = 0
        headerLine.BackgroundColor3 = (CurrentTheme and CurrentTheme.Main) or UI.Surface.Stroke
        ApplyGradient(headerLine)

        local body = Instance.new("Frame", frame)
        body.Name = "Body"
        body.Size = UDim2.new(1, 0, 0, 0)
        body.AutomaticSize = Enum.AutomaticSize.Y
        body.Position = UDim2.fromOffset(0, 32)
        body.BackgroundTransparency = 1
        body.Parent = frame

        KO.gui = gui
        KO.container = frame
        KO.frameStroke = frameStroke
        KO.header = header
        KO.headerLine = headerLine
        KO.titleLabel = titleLabel
        KO.subtitleLabel = subtitleLabel
        KO.body = body
        KO.uiScale = nil
        ASTER.KeybindsOverlay = gui

        if mainFrame and not mainFrame.Visible then
            gui.Enabled = false
        end

        makeDraggable(frame, header)

        ASTER.ApplyKeybindsOverlayTheme()
        ASTER.ApplyKeybindsOverlaySize()
        ASTER.RefreshKeybindsOverlayRows()

        if KO.updateRunning then return end
        KO.updateRunning = true
        task.spawn(function()
            while Settings.ShowKeybindsOverlay and KO.gui and KO.gui.Parent do
                ASTER.RefreshKeybindsOverlayRows()
                task.wait(0.2)
            end
            KO.updateRunning = false
            if not Settings.ShowKeybindsOverlay then
                ASTER.DestroyKeybindsOverlay()
            end
        end)
    end

    function ASTER.DestroyKeybindsOverlay()
        KO.updateRunning = false
        if KO.gui then
            KO.gui:Destroy()
        end
        KO.gui = nil
        KO.container = nil
        KO.frameStroke = nil
        KO.header = nil
        KO.headerLine = nil
        KO.titleLabel = nil
        KO.subtitleLabel = nil
        KO.body = nil
        KO.uiScale = nil
        ASTER.KeybindsOverlay = nil
    end

    ASTER.Tabs.Combat:AddLabel("Keybind Manager")

    ASTER.Tabs.Combat:AddToggleInSection("Keybind Manager", "Show Keybinds Overlay", Settings.ShowKeybindsOverlay or false, function(v)
        Settings.ShowKeybindsOverlay = v
        if v then
            ASTER.SyncKeybindsOverlayWithMainUI(mainFrame and mainFrame.Visible)
        else
            ASTER.DestroyKeybindsOverlay()
        end
    end)

    ASTER.Tabs.Combat:AddSliderInSection("Keybind Manager", "OverlayMenuSize", 0, 10, Settings.OverlayMenuSize or Settings.OverlayMenuSide or 5, 0.01, function(v)
        Settings.OverlayMenuSize = v
        ASTER.ApplyKeybindsOverlaySize()
    end)

    ASTER.Tabs.Combat:AddDropdownInSection("Keybind Manager", "Add Toggle Keybind", ToggleBind.getAvailableToggleKeybindOptions(), "None", function(v)
        if v and v ~= "None" then
            ToggleBind.addToggleKeybind(v)
            local reg = Window.ElementRegistry["Add Toggle Keybind"]
            if reg and reg.SetValue then reg.SetValue("None") end
        end
    end)

    ToggleBind.initKeybindManager()
    
    -- AutoHit & Heal Keybind Listener
    game:GetService("UserInputService").InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.UserInputType == Enum.UserInputType.Keyboard then
            local autoHitKey = Settings.AutoHitKey
            local healKey = Settings.QuickHealKey
            local chestKey = Settings.AutoChestKey

            if autoHitKey and autoHitKey ~= "" and input.KeyCode.Name == tostring(autoHitKey):upper() then
                if Window.ElementRegistry["AutoHitStart"] then
                    local current = Window.ElementRegistry["AutoHitStart"].GetValue()
                    Window.ElementRegistry["AutoHitStart"].SetValue(not current)
                end
            elseif healKey and healKey ~= "" and input.KeyCode.Name == tostring(healKey):upper() then
                -- Toggle via Registry
                if Window.ElementRegistry["Auto Heal"] then
                    local current = Window.ElementRegistry["Auto Heal"].GetValue()
                    Window.ElementRegistry["Auto Heal"].SetValue(not current)
                end
            elseif chestKey and chestKey ~= "" and input.KeyCode.Name == tostring(chestKey):upper() then
                if Window.ElementRegistry["Enable AutoChest"] then
                    local current = Window.ElementRegistry["Enable AutoChest"].GetValue()
                    Window.ElementRegistry["Enable AutoChest"].SetValue(not current)
                else
                    Settings.AutoChestEnabled = not Settings.AutoChestEnabled
                end
            end
        end
    end)
    
    -- Update label function for safety - Stored in Options to avoid register limit
    ASTER.Options.updatePinchLabel = function(name)
         local label = ASTER.Options.TargetingLabel
         if label then
             label.Text = "Targeting: " .. tostring(name)
         end
    end

