    -- Auto Target Nearest "God" Player Loop (Replaces Click Targeting)
    if not __ASTER_RUNTIME.combatTargetLoopStarted then
        __ASTER_RUNTIME.combatTargetLoopStarted = true
        local session = CURRENT_SESSION
        task.spawn(function()
            while isRuntimeSessionActive(session) do
                local needsTargeting = ConfigPinch.Enabled
                    or Settings.AutoBoltEnabled
                    or Settings.TargetMode == "Auto Target Mode"
                    or Settings.TargetMode == "Target GodOnly"
                if not needsTargeting then
                    task.wait(1)
                    continue
                end

            -- Only run auto-targeting logic when in Auto Target Mode
            if Settings.TargetMode == "Auto Target Mode" then
                local closestPlayer, closestDistance = nil, math.huge
                if plr and plr.Character and plr.Character:FindFirstChild("HumanoidRootPart") then
                    local myPos = plr.Character.HumanoidRootPart.Position
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") and p.Character:FindFirstChild("Humanoid") and p.Character.Humanoid.Health > 0 and not p:GetAttribute("God") then
                            local isTargetable = true
                            
                            -- Check Teams
                            local myTeam = plr.Team
                            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                            
                            if myTeam and myTeam ~= noTribe and p.Team == myTeam then
                                isTargetable = false
                            end

                            if isTargetable and isAlly(p) then
                                isTargetable = false
                            end
                            
                            if isTargetable then
                                local theirPos = p.Character.HumanoidRootPart.Position
                                local distance = (myPos - theirPos).Magnitude
                                if distance < closestDistance then
                                    closestDistance = distance
                                    closestPlayer = p
                                end
                            end
                        end
                    end
                end
                
                if closestPlayer then
                    ConfigPinch.TargetPlayer = closestPlayer
                    ConfigPinch.TargetName = closestPlayer.Name
                    if ASTER.Options.TargetingLabel then ASTER.Options.TargetingLabel.Text = "Targeting: " .. closestPlayer.Name end
                elseif (ConfigPinch.PendingWallSend or 0) == 0 then
                    ConfigPinch.TargetPlayer = nil
                    ConfigPinch.TargetName = ""
                    if ASTER.Options.TargetingLabel then ASTER.Options.TargetingLabel.Text = "Targeting: None" end
                end
            end

            if Settings.TargetMode == "Target GodOnly" then

                local godTarget = nil
                local godDist = math.huge
                
                local myChar = plr.Character
                local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                
                if myHrp then
                    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                        if p ~= plr and p.Character and p.Character:FindFirstChild("HumanoidRootPart") then
                             local isTargetable = true
                             
                             -- Check Teams
                             local myTeam = plr.Team
                             local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                             
                             if myTeam and myTeam ~= noTribe and p.Team == myTeam then
                                 isTargetable = false
                             end

                             if isTargetable and isAlly(p) then
                                 isTargetable = false
                             end

                             if isTargetable then
                                 -- "God" Armor Check
                                 local armorCount = 0
                                 if p.Character:FindFirstChild("God Halo") then
                                     armorCount = armorCount + 1
                                 end
                                 if p.Character:FindFirstChild("God Chestplate") then
                                     armorCount = armorCount + 1
                                 end
                                 if p.Character:FindFirstChild("God Legs") then
                                     armorCount = armorCount + 1
                                 end

                                 if armorCount > 0 then
                                     local dist = (p.Character.HumanoidRootPart.Position - myHrp.Position).Magnitude
                                     if dist < godDist then
                                         godDist = dist
                                         godTarget = p
                                     end
                                 end
                             end
                        end
                    end
                    
                    -- Only use the god target
                    if godTarget ~= ConfigPinch.TargetPlayer then
                        ConfigPinch.TargetPlayer = godTarget
                        if ASTER.Options.updatePinchLabel and godTarget then 
                            ASTER.Options.updatePinchLabel(godTarget.Name) 
                        elseif ASTER.Options.updatePinchLabel then
                            ASTER.Options.updatePinchLabel("None")
                        end
                    end
                end
            end
            task.wait(1)
        end
        end)
    end
    
    -- Target Highlight Loop
    -- Ensures whatever player is currently targeted by ConfigPinch is highlighted
    if not __ASTER_RUNTIME.targetHighlightLoopStarted then
        __ASTER_RUNTIME.targetHighlightLoopStarted = true
        local session = CURRENT_SESSION
        task.spawn(function()
            local lastHighlighted = nil
            while isRuntimeSessionActive(session) do
                if not Settings.TargetHighlightEnabled then
                    if lastHighlighted then
                        for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                             if p.Character then
                                 local old = p.Character:FindFirstChild("TargetHighlightBox")
                                 if old then old:Destroy() end
                                 local legacy = p.Character:FindFirstChild("TargetHighlight")
                                 if legacy then legacy:Destroy() end
                             end
                        end
                        lastHighlighted = nil
                    end
                    task.wait(1)
                    continue
                end

            local currentTarget = ConfigPinch.TargetPlayer
            
            -- If feature is enabled and we have a valid target
            if Settings.TargetHighlightEnabled and currentTarget and currentTarget.Parent and currentTarget.Character then
                 local hrp = currentTarget.Character:FindFirstChild("HumanoidRootPart")
                 if hrp then
                     -- Check if existing highlight matches current target
                     local existing = currentTarget.Character:FindFirstChild("TargetHighlightBox")
                     
                     if lastHighlighted ~= currentTarget or not existing then
                         -- Cleanup all old highlights
                         for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                             if p.Character then
                                 local old = p.Character:FindFirstChild("TargetHighlightBox")
                                 if old then old:Destroy() end
                                 local oldGui = p.Character:FindFirstChild("TargetLabelGui")
                                 if oldGui then oldGui:Destroy() end
                                 -- Also cleanup legacy highlight if present
                                 local legacy = p.Character:FindFirstChild("TargetHighlight")
                                 if legacy then legacy:Destroy() end
                             end
                         end
                         
                         -- Create static hitbox part for fixed size
                         local hitbox = Instance.new("Part")
                         hitbox.Name = "TargetHighlightBox"
                         hitbox.Size = Vector3.new(4, 6, 4) -- Fixed size box (Character roughly fits in 4x6x4)
                         hitbox.Transparency = 1
                         hitbox.CanCollide = false
                         hitbox.Massless = true
                         hitbox.Anchored = false
                         hitbox.Parent = currentTarget.Character
                         hitbox.CFrame = hrp.CFrame
                         
                         local weld = Instance.new("WeldConstraint")

                         -- Create BillboardGui for the text
                         local billboardGui = Instance.new("BillboardGui")
                         billboardGui.Name = "TargetLabelGui"
                         billboardGui.Adornee = hitbox
                         billboardGui.Size = UDim2.new(0, 100, 0, 50)
                         billboardGui.StudsOffset = Vector3.new(0, 4, 0)
                         billboardGui.AlwaysOnTop = true
                         billboardGui.Parent = hitbox

                         local textLabel = Instance.new("TextLabel")
                         textLabel.Parent = billboardGui
                         textLabel.BackgroundTransparency = 1
                         textLabel.Size = UDim2.new(1, 0, 1, 0)
                         textLabel.Text = "Target"
                         textLabel.TextColor3 = Color3.new(1, 0, 0) -- Red text
                         textLabel.TextSize = 24
                         textLabel.Font = Enum.Font.SourceSansBold
                         textLabel.TextStrokeTransparency = 0
                         weld.Part0 = hitbox
                         weld.Part1 = hrp
                         weld.Parent = hitbox
                         
                         local hl = Instance.new("SelectionBox")
                         hl.Name = "Outline"
                         hl.Adornee = hitbox
                         hl.Color3 = Color3.fromRGB(255, 0, 0)
                         hl.LineThickness = 0.05
                         hl.SurfaceTransparency = 1
                         hl.Transparency = 0
                         hl.Parent = hitbox
                         
                         lastHighlighted = currentTarget
                     end
                 end
            else
                -- Feature disabled or no target: Cleanup everything
                if lastHighlighted then
                    for _, p in ipairs(game:GetService("Players"):GetPlayers()) do
                         if p.Character then
                             local old = p.Character:FindFirstChild("TargetHighlightBox")
                             if old then old:Destroy() end
                             local legacy = p.Character:FindFirstChild("TargetHighlight")
                             if legacy then legacy:Destroy() end
                         end
                    end
                    lastHighlighted = nil
                end
            end
            
            task.wait(0.5)
        end
        end)
    end
    
    -- Pinch keybind is configured in Keybind Manager
    
    trackConnection("pinchKeybind", game:GetService("UserInputService").InputBegan:Connect(function(input, gpe) 
        if gpe then return end 
        local key = ConfigPinch.Keybind
        if not key or key == "" then return end
        
        -- Support Number Keys for Keybinds
        local inputKeyName = input.KeyCode.Name
        if input.KeyCode.Value >= 48 and input.KeyCode.Value <= 57 then
             inputKeyName = string.char(input.KeyCode.Value) -- Converts Enum.KeyCode.One -> "1"
        end
        -- Fallback for standard KeyCode.Name which is "One", "Two", etc.
        if inputKeyName:match("One") then inputKeyName = "1" end
        if inputKeyName:match("Two") then inputKeyName = "2" end
        if inputKeyName:match("Three") then inputKeyName = "3" end
        if inputKeyName:match("Four") then inputKeyName = "4" end
        if inputKeyName:match("Five") then inputKeyName = "5" end
        if inputKeyName:match("Six") then inputKeyName = "6" end
        if inputKeyName:match("Seven") then inputKeyName = "7" end
        if inputKeyName:match("Eight") then inputKeyName = "8" end
        if inputKeyName:match("Nine") then inputKeyName = "9" end
        if inputKeyName:match("Zero") then inputKeyName = "0" end
        
        if inputKeyName == key then 
            ConfigPinch.Enabled = not ConfigPinch.Enabled 
            local resetPinch = ASTER.Options.resetPinchPlacement
            if resetPinch then
                resetPinch()
            end
            
            -- Update Targeting Label
            local label = ASTER.Options.TargetingLabel
            if label then
                local text = "Targeting: None"
                if ConfigPinch.Enabled then
                     if ConfigPinch.TargetPlayer then
                         text = "Targeting: " .. ConfigPinch.TargetPlayer.Name
                     else
                         text = "Targeting: Scanning..."
                     end
                end
                
                if label then label.Text = text end
            end

            -- Update UI toggle if it exists
            local tgl = Window.ElementRegistry["Pinch"]
            
            -- FIX: Check if tgl exists and has SetValue, but avoid triggering tween errors if UI is hidden/destroyed
            if tgl and tgl.SetValue then 
                 pcall(function() tgl.SetValue(ConfigPinch.Enabled) end)
            end
        end 
    end))

    -- Voodoo keybind is configured in Keybind Manager
        -- Auto Hut Feature
    -- Helpers from AutoHut.lua
    local function GetGroundPosition(pos, ignoreChar)
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        params.FilterDescendantsInstances = {plr.Character, ignoreChar}
        
        local result = game:GetService("Workspace"):Raycast(pos + Vector3.new(0, 5, 0), Vector3.new(0, -100, 0), params)
        if result then
            return result.Position
        end
        return pos -- Fallback
    end

    local function GetNearestPlayer()
        local closestPlayer = nil
        local minDistance = 100 -- Max range
        local myChar = plr.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        
        if myHrp then
            for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                if player ~= plr then
                     local isTargetable = true
                     
                     -- Check Teams
                     local myTeam = plr.Team
                     local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                     
                     if myTeam ~= noTribe and player.Team == myTeam then
                         isTargetable = false
                     end
                     
                     if isTargetable and isAlly(player) then
                         isTargetable = false
                     end
                     
                     if isTargetable and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                        local hrp = player.Character.HumanoidRootPart
                    local dist = (hrp.Position - myHrp.Position).Magnitude
                    if dist < minDistance then
                        minDistance = dist
                        closestPlayer = player
                    end
                end
            end
        end
        end
        return closestPlayer
    end

    local function placeHutAt(cframe)
        if not ByteNetReliable then return end
        
        local id = getPacketId("PlaceStructure")
        
        local name = Settings.QuickHutHutOption or "Big Ol' Hut"
        local len = #name
        
        local b = buffer.create(4 + len + 18)
        
        buffer.writeu8(b, 0, 0)
        buffer.writeu8(b, 1, id)
        buffer.writeu16(b, 2, len)
        buffer.writestring(b, 4, name)
        
        local offset = 4 + len
        write18ByteCFrame(b, offset, cframe)
        
        ByteNetReliable:FireServer(b)
    end

    -- Shared Targeting Helpers
    local godItems = {}
    local function initGodItems()
        if next(godItems) then return end
        local success, ItemIDS = pcall(function() return require(game:GetService("ReplicatedStorage").Modules.ItemIDS) end)
        if success and ItemIDS then
             local targetNames = {
                 ["God Halo"] = true,
                 ["God Chestplate"] = true,
                 ["God Legs"] = true
             }
             for id, name in pairs(ItemIDS) do
                 if targetNames[name] then
                     godItems[id] = name
                 end
             end
        end
        if not next(godItems) then
            godItems = { 
                 [16] = "God Halo", 
                 [26] = "God Chestplate", 
                 [288] = "God Legs" 
            }
        end
    end

    local function hasGodItem(player)
        initGodItems()
        if not player then return false end
        
        -- Check Character
        if player.Character then
            for _, name in pairs(godItems) do
                if player.Character:FindFirstChild(name) then return true end
            end
        end
        
        -- Check Workspace Players Folder (Custom Game Structure)
        local playersFolder = workspace:FindFirstChild("Players")
        if playersFolder then
            local plrFolder = playersFolder:FindFirstChild(player.Name)
            if plrFolder then
                -- Check Tools folder
                local tools = plrFolder:FindFirstChild("Tools")
                if tools then
                    for _, name in pairs(godItems) do
                        if tools:FindFirstChild(name) then return true end
                    end
                end
                -- Check direct children (Armor might be here)
                for _, name in pairs(godItems) do
                    if plrFolder:FindFirstChild(name) then return true end
                end
            end
        end
        
        return false
    end

    AttemptHutNearest = function()
        local target = nil
        local minDistance = 100 -- Max range
        local myChar = plr.Character
        local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
        
        local godTarget = nil
        local godDist = 100
        
        local normalTarget = nil
        local normalDist = 100
        
        if myHrp then
            for _, player in pairs(game:GetService("Players"):GetPlayers()) do
                if player ~= plr then
                     local isTargetable = true
                     
                     -- Check Teams
                     local myTeam = plr.Team
                     local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
                     
                     if myTeam ~= noTribe and player.Team == myTeam then
                         isTargetable = false
                     end

                     if isTargetable and isAlly(player) then
                         isTargetable = false
                     end
                     
                     if isTargetable and player.Character and player.Character:FindFirstChild("HumanoidRootPart") then
                        local hrp = player.Character.HumanoidRootPart
                    local dist = (hrp.Position - myHrp.Position).Magnitude
                    
                    if dist < 100 then
                        -- Check for God Item
                        if hasGodItem(player) then
                            if dist < godDist then
                                godDist = dist
                                godTarget = player
                            end
                        end
                        
                        -- Check for Normal (Backup)
                        if dist < normalDist then
                            normalDist = dist
                            normalTarget = player
                        end
                    end
                end
            end
        end
        end
        
        target = godTarget or normalTarget

        if not target then return end
        
        local targetChar = target.Character
        local targetHrp = targetChar and targetChar:FindFirstChild("HumanoidRootPart")
        if not targetHrp then return end

        -- Calculate position based on movement (Velocity) or facing direction (LookVector)
        local velocity = targetHrp.AssemblyLinearVelocity
        local moveVec = Vector3.new(velocity.X, 0, velocity.Z)
        
        local targetPos
        
        if moveVec.Magnitude > 2 then
            -- Moving: Place ahead of movement (prediction)
            targetPos = targetHrp.Position + (moveVec.Unit * 10) 
        else
            -- Stationary: Place in front of face
            local lookVec = targetHrp.CFrame.LookVector
            lookVec = Vector3.new(lookVec.X, 0, lookVec.Z)
            
            if lookVec.Magnitude > 0.01 then
                lookVec = lookVec.Unit
            else
                lookVec = Vector3.new(1, 0, 0)
            end
            targetPos = targetHrp.Position + (lookVec * 8)
        end
        local groundPos = GetGroundPosition(targetPos, targetChar)
        
        if groundPos then
            -- Use strict Identity rotation (No rotation) to prevent tipping/tilting
            -- User requested: "always be up right" and "not change rotation like sideways"
            local placeCFrame = CFrame.new(groundPos) 
            placeHutAt(placeCFrame)
        end
    end

    AttemptVoodooNearest = function()
        local myHrp = getBoogaPlayerHRP(plr)
        if not myHrp then return end

        local function isTargetablePlayer(player)
            if not player or player == plr then return false end
            local myTeam = plr.Team
            local noTribe = game:GetService("Teams"):FindFirstChild("NoTribe")
            if myTeam ~= noTribe and player.Team == myTeam then return false end
            if isAlly(player) then return false end
            local hrp = getBoogaPlayerHRP(player)
            if not hrp then return false end
            return (hrp.Position - myHrp.Position).Magnitude < 100
        end

        local godTarget = nil
        local godDist = 100
        local normalTarget = nil
        local normalDist = 100

        for _, player in pairs(game:GetService("Players"):GetPlayers()) do
            if isTargetablePlayer(player) then
                local hrp = getBoogaPlayerHRP(player)
                local dist = (hrp.Position - myHrp.Position).Magnitude
                local char = getBoogaPlayerCharacter(player)

                local isGod = false
                if hasGodItem then
                    if hasGodItem(player) then isGod = true end
                elseif char then
                    for _, part in ipairs(char:GetChildren()) do
                        if part.Name:find("God") then isGod = true break end
                    end
                end

                if isGod and dist < godDist then
                    godDist = dist
                    godTarget = player
                end

                if dist < normalDist then
                    normalDist = dist
                    normalTarget = player
                end
            end
        end

        local target = godTarget or normalTarget
        if not target then return end

        local targetHrp = getBoogaPlayerHRP(target)
        if not targetHrp then return end

        sendVoodooPacket(targetHrp.CFrame, myHrp.CFrame)
    end

    -- Voodoo Spell Feature (Uses Pinch Target)
    -- Stored in ASTER.Options to avoid local register limit
    trackConnection("voodooKeybind", game:GetService("UserInputService").InputBegan:Connect(function(input, gpe)
        if gpe then return end
        local key = ASTER.Options.VoodooSpell and ASTER.Options.VoodooSpell.Keybind
        if not key or key == "" then return end
        
        -- Support Number Keys for Keybinds
        local inputKeyName = input.KeyCode.Name
        if input.KeyCode.Value >= 48 and input.KeyCode.Value <= 57 then
             inputKeyName = string.char(input.KeyCode.Value) -- Converts Enum.KeyCode.One -> "1"
        end
        if inputKeyName:match("One") then inputKeyName = "1" end
        if inputKeyName:match("Two") then inputKeyName = "2" end
        if inputKeyName:match("Three") then inputKeyName = "3" end
        if inputKeyName:match("Four") then inputKeyName = "4" end
        if inputKeyName:match("Five") then inputKeyName = "5" end
        if inputKeyName:match("Six") then inputKeyName = "6" end
        if inputKeyName:match("Seven") then inputKeyName = "7" end
        if inputKeyName:match("Eight") then inputKeyName = "8" end
        if inputKeyName:match("Nine") then inputKeyName = "9" end
        if inputKeyName:match("Zero") then inputKeyName = "0" end

        if inputKeyName == key then
            -- Use the SAME target as Pinch
            local target = ConfigPinch.TargetPlayer
            if target then
                task.spawn(function()
                    for i = 1, 2 do
                        local targetHrp = getBoogaPlayerHRP(target)
                        local myHrp = getBoogaPlayerHRP(plr)
                        if targetHrp and myHrp then
                            sendVoodooPacket(targetHrp.CFrame, myHrp.CFrame)
                        end
                        task.wait(0.05) 
                    end
                end)
            end
        end
    end))
    
    -- Quick Hut / Follow keybinds are configured in Keybind Manager
    
    -- Follow Keybind Listener
    game:GetService("UserInputService").InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if Settings.FollowKey and Settings.FollowKey ~= "" then
             local key = tostring(Settings.FollowKey):upper()
             local inputKey = input.KeyCode.Name
             if input.KeyCode.Value >= 48 and input.KeyCode.Value <= 57 then
                inputKey = string.char(input.KeyCode.Value)
             end
             
             if inputKey == key then
                  local newState = not Settings.FollowEnabled
                  if Window.ElementRegistry["Follow Nearest Player"] then
                      Window.ElementRegistry["Follow Nearest Player"].SetValue(newState)
                  else
                      Settings.FollowEnabled = newState
                  end
             end
        end
    end)

    -- Keybind Listener for Quick Hut
    -- Stored in a global connection to avoid GC if inside a scope (though here it's main scope)
    local asterEnv = getAsterEnv()
    if asterEnv.QuickHutConnection then asterEnv.QuickHutConnection:Disconnect() end
    asterEnv.QuickHutConnection = game:GetService("UserInputService").InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if Settings.QuickHutKey and Settings.QuickHutKey ~= "" then
            local key = tostring(Settings.QuickHutKey):upper()
            local inputKey = input.KeyCode.Name
            
            -- Handle Number Keys
            if input.KeyCode.Value >= 48 and input.KeyCode.Value <= 57 then
                inputKey = string.char(input.KeyCode.Value)
            end
            
            if inputKey == key then
                 local newState = not Settings.QuickHut
                 
                 -- Try to update via UI Library (which triggers callback and loop)
                 local toggledViaUI = false
                 if Window and Window.ElementRegistry and Window.ElementRegistry["Quick Hut"] then
                     pcall(function()
                         Window.ElementRegistry["Quick Hut"].SetValue(newState)
                         toggledViaUI = true
                     end)
                 end
                 
                 -- Fallback if UI failed or didn't exist
                 if not toggledViaUI then
                     Settings.QuickHut = newState
                     local env = getAsterEnv()
                     if type(env.SetAsterHutGuiState) == "function" then
                         pcall(function() env.SetAsterHutGuiState(newState) end)
                     end
                     if newState then
                         task.spawn(function()
                             while Settings.QuickHut do
                                 if AttemptHutNearest then
                                     AttemptHutNearest()
                                 else
                                     executeQuickHutScan()
                                 end
                                 task.wait(0.1) 
                             end
                         end)
                     end
                 end

                
            end
        end
    end)

