do
    ASTER.Tabs.Automation:AddLabel("Tribe")
    ASTER.Tabs.Automation:AddButton("Auto Tribe Sniper", function()
         local ReplicatedStorage = game:GetService("ReplicatedStorage")
         local Players = game:GetService("Players")
         local LocalPlayer = Players.LocalPlayer
     
         -- Attempt to load real modules from the game
         local Modules = ReplicatedStorage:WaitForChild("Modules", 5)
         if not Modules then
             warn("Could not find Modules folder in ReplicatedStorage. Is the game loaded?")
             return
         end
     
         -- Safely require modules
         local success, result = pcall(function()
             return {
                 Packets = require(Modules:WaitForChild("Packets")),
                 ColorData = require(Modules:WaitForChild("ColorData")),
                 GameUtil = require(Modules:WaitForChild("GameUtil"))
             }
         end)
     
         if not success then

             return
         end
     
         local GameModules = result
         local Packets = GameModules.Packets
         local ColorData = GameModules.ColorData
         local GameUtil = GameModules.GameUtil
     
         task.spawn(function()
             while true do
                 -- 1. Check if we are already in a tribe
                 local inTribe = GameUtil.isInATribe(LocalPlayer.UserId)
                 if inTribe then

                     
                     -- Play success sound
                     local LocalSounds = ReplicatedStorage:FindFirstChild("LocalSounds")
                     if LocalSounds and LocalSounds:FindFirstChild("Quicks") and LocalSounds.Quicks:FindFirstChild("TribeSound") then
                         LocalSounds.Quicks.TribeSound:Play()
                     end
                     break -- Exit the loop
                 end
     
                 -- Get all available colors
                 local possibleColors = {}
                 for colorName, _ in pairs(ColorData.TribeColors) do
                     table.insert(possibleColors, colorName)
                 end
     
                 for _, colorName in ipairs(possibleColors) do
                     -- Check again inside the inner loop
                     if GameUtil.isInATribe(LocalPlayer.UserId) then
                          break
                     end
     
                     
                     -- Send manual packet
                     if ByteNetReliable then
                         local tribeID = getPacketId("CreateTribe")
                         if tribeID then
                             local len = #colorName
                             local b = buffer.create(4 + len)
                             buffer.writeu8(b, 0, 0)
                             buffer.writeu8(b, 1, tribeID)
                             buffer.writeu16(b, 2, len)
                             buffer.writestring(b, 4, colorName)
                             ByteNetReliable:FireServer(b)
                             
                             task.wait(0.05)
                         end
                     end
                 end
                 
                 task.wait(0.02) -- Wait before retrying the whole list if still not in a tribe
             end
         end)
    end)
end

do
    local function getShopBuyAmount()
        local amount = tonumber(Settings.FarmingAmount)
        local reg = Window and Window.ElementRegistry and Window.ElementRegistry["Amount to Buy"]
        if reg and reg.GetValue then
            local uiVal = tonumber(reg.GetValue())
            if uiVal then amount = uiVal end
        end
        amount = math.floor(amount or 1)
        if amount < 1 then return 1 end
        return amount
    end

    local function getShopSelectedItem()
        local itemName = Settings.FarmingSelectedItem or "Adurite"
        local reg = Window and Window.ElementRegistry and Window.ElementRegistry["Select Item to Buy"]
        if reg and reg.GetValue then
            local uiVal = reg.GetValue()
            if uiVal and uiVal ~= "" then itemName = uiVal end
        end
        return itemName
    end

    local function getShopItemId(itemName)
        local itemID = craftNameToID and craftNameToID[itemName]
        if not itemID and autoDiscoverItemID then
            itemID = autoDiscoverItemID(itemName)
        end
        return itemID
    end

    ASTER.Tabs.Automation:AddLabel("Shop (Quick Buy)")
    ASTER.Tabs.Automation:AddDropdown("Select Item to Buy", {"Adurite", "Bloodfruit", "Crystal Chunk", "Gold", "Iron", "Steel", "Wood", "Leaves", "Bluefruit", "Jelly", "Log", "Ice Cube", "Berry", "Fire Hide", "Hide", "Stone", "Obsidian", "Cooked Meat", "Lemon"}, "Adurite", function(v)
        Settings.FarmingSelectedItem = v
    end)

    ASTER.Tabs.Automation:AddInput("Amount to Buy", "1", function(v)
        Settings.FarmingAmount = tonumber(v) or 1
    end)

    ASTER.Tabs.Automation:AddToggle("Quick Shop & Stop", false, function(v)
        Settings.AutoBuyItem = v
        if v then
            local itemName = getShopSelectedItem()
            local itemID = getShopItemId(itemName)
            local amt = getShopBuyAmount()
            Settings.FarmingAmount = amt
            Settings.FarmingSelectedItem = itemName

            if itemID and ByteNetReliable then
                task.spawn(function()
                    for i = 1, amt do
                        if not Settings.AutoBuyItem then break end
                        local b = buffer.create(8)
                        buffer.writeu8(b, 0, 0)
                        buffer.writeu8(b, 1, getPacketId("PurchaseFromShop"))
                        buffer.writeu32(b, 2, itemID)
                        buffer.writeu16(b, 6, 1)
                        ByteNetReliable:FireServer(b)
                        task.wait(0.05)
                    end
                    Settings.AutoBuyItem = false
                    if Window.ElementRegistry["Quick Shop & Stop"] and Window.ElementRegistry["Quick Shop & Stop"].SetValue then
                        Window.ElementRegistry["Quick Shop & Stop"].SetValue(false)
                    end
                end)
            end
        end
    end)
end

