do
    ASTER.Tabs.Automation:AddLabel("Server / Rejoin")
    
    local autoRejoinConnections = {}
    ASTER.Tabs.Automation:AddToggle("Auto Rejoin", false, function(v)
        Settings.AutoRejoinEnabled = v
        local CoreGui = game:GetService("CoreGui")
        local Players = game:GetService("Players")
        
        if v then
            local TARGET_PLACE_ID = 11729688377
            local function onKicked()
                task.wait(0.5)
                local ts = game:GetService("TeleportService")
                local p = Players.LocalPlayer
                if type(teleport) == "function" then
                    pcall(function() teleport(TARGET_PLACE_ID) end)
                else
                    pcall(function() ts:Teleport(TARGET_PLACE_ID, p) end)
                end
            end
            
            local promptOverlay = CoreGui:FindFirstChild("RobloxPromptGui") and CoreGui.RobloxPromptGui:FindFirstChild("promptOverlay")
            if promptOverlay then
                local conn = promptOverlay.ChildAdded:Connect(function(child)
                    if child.Name == "ErrorPrompt" then onKicked() end
                end)
                table.insert(autoRejoinConnections, conn)
            end
            
            local conn2 = game:GetService("GuiService").ErrorMessageChanged:Connect(function()
                onKicked()
            end)
            table.insert(autoRejoinConnections, conn2)
        else
            for _, conn in ipairs(autoRejoinConnections) do
                conn:Disconnect()
            end
            autoRejoinConnections = {}
        end
    end)
    
    ASTER.Tabs.Automation:AddButton("Kick (Requires Auto Rejoin)", function()
        local privateServerId = workspace:GetAttribute("privateServerId") or ""
        local Players = game:GetService("Players")
        if privateServerId ~= "" then
            Players.LocalPlayer:Kick("\n\nYou have been kicked from the server.\nVIP ID: " .. privateServerId)
        else
            Players.LocalPlayer:Kick("\n\nYou have been safely kicked from the server.")
        end
    end)

    local manualToolIDs = {
        ["God Axe"] = 454,
        ["God Pick"] = 132,
        ["Emerald Pick"] = 134,
        ["Pink Diamond Pick"] = 125,
        ["Void Pick"] = 496
    }

    ASTER.Tabs.Automation:AddDropdown("SelectFarmChoice", {"Ancient Tree", "Ancient God", "Furious God", "Hateful God", "Lonely God", "Miserable God", "Old God", "Sleeping God", "Wealthy God", "CrystalGuardianFarm"}, "Ancient Tree", function(v)
        Settings.FarmChoice = v
    end)

    ASTER.Tabs.Automation:AddDropdown("Tool Selections", {"Emerald Axe", "Void Axe", "Pink Diamond Axe", "God Axe", "Emerald Pick", "Void Pick", "Pink Diamond Pick", "God Pick"}, "Void Axe", function(v)
        Settings.FarmTool = v
    end)

    ASTER.Tabs.Automation:AddDropdown("ToolSaveOption", {"BuyFromShop (GodOnly)", "Reset&Loot"}, "BuyFromShop (GodOnly)", function(v)
        Settings.ToolSaveOption = v
    end)

    ASTER.Tabs.Automation:AddToggle("GodLootPickUp", false, function(v)
        Settings.GodLootPickUpEnabled = v
    end)

    ASTER.Tabs.Automation:AddToggle("GodAutoRebirth", false, function(v)
        Settings.GodAutoRebirthEnabled = v
    end)

    ASTER.Tabs.Automation:AddSlider("CrystalGuardian Speed", 1, 21, Settings.CrystalGuardianSpeed or 17, 1, function(v)
        Settings.CrystalGuardianSpeed = v
    end)

    ASTER.Tabs.Automation:AddToggle("StartFarmChoice", false, function(v)
        Settings.StartFarmChoiceEnabled = v
        if v then
            if Window.ElementRegistry["Auto Bed Respawn"] and Window.ElementRegistry["Auto Bed Respawn"].SetValue then
                Window.ElementRegistry["Auto Bed Respawn"].SetValue(true)
            end
            
            task.spawn(function()
                local Players = game:GetService("Players")
                local ByteNetReliable = game:GetService("ReplicatedStorage"):WaitForChild("ByteNetReliable", 10)

                local function hasFarmTool(name)
                    if not name then return false end
                    if getToolSlot and getToolSlot(name) then return true end
                    local success, hasL = pcall(function() return getlayout and getlayout(name) ~= nil end)
                    if success and hasL then return true end
                    local lp = Players.LocalPlayer
                    local char = lp and lp.Character
                    if char and char:FindFirstChild(name) then return true end
                    local bp = lp and lp:FindFirstChildOfClass("Backpack")
                    if bp and bp:FindFirstChild(name) then return true end
                    return false
                end

                local function resolveGodToolCraftId(toolName)
                    if not toolName or toolName == "" then return nil end
                    local id = craftNameToID and craftNameToID[toolName]
                    id = tonumber(id)
                    if id and id > 0 then return id end
                    id = tonumber(manualToolIDs[toolName])
                    if id and id > 0 then return id end
                    if autoDiscoverItemID then
                        id = tonumber(autoDiscoverItemID(toolName))
                        if id and id > 0 then return id end
                    end
                    return nil
                end

                local function fireGodToolCraftFor(toolName)
                    local recipeId = resolveGodToolCraftId(toolName)
                    local craftPkt = getPacketId("CraftItem")
                    if not recipeId or not craftPkt or not ByteNetReliable then return false end
                    local b = buffer.create(4)
                    buffer.writeu8(b, 0, 0)
                    buffer.writeu8(b, 1, craftPkt)
                    buffer.writeu16(b, 2, recipeId)
                    ByteNetReliable:FireServer(b)
                    return true
                end

                -- Ancient Tree: if the selected axe is not on the player, craft it.
                local lastAncientAxeCraftAt = 0
                local function ensureAncientTreeAxe(toolName)
                    if not toolName or toolName == "" then return false end
                    if hasFarmTool(toolName) then return true end
                    if (tick() - lastAncientAxeCraftAt) < 0.75 then return false end
                    lastAncientAxeCraftAt = tick()
                    fireGodToolCraftFor(toolName)
                    local waitStart = tick()
                    while Settings.StartFarmChoiceEnabled and not hasFarmTool(toolName) and (tick() - waitStart) < 0.7 do
                        task.wait(0.1)
                    end
                    if not hasFarmTool(toolName) then
                        lastAncientAxeCraftAt = tick()
                        fireGodToolCraftFor(toolName)
                    end
                    return hasFarmTool(toolName)
                end

                local function tryStockAndCraftGodTool(toolName)
                    local purchasePkt = getPacketId("PurchaseFromShop")
                    if not purchasePkt or not ByteNetReliable then return false end

                    local GOLD_BUY_COUNT = 12
                    local CRYSTAL_BUY_COUNT = 3

                    local function getItemIdFast(itemName)
                        local id = craftNameToID and craftNameToID[itemName]
                        if type(id) == "number" and id > 0 then return id end
                        if type(id) == "string" then
                            local n = tonumber(id)
                            if n and n > 0 then return n end
                        end
                        if autoDiscoverItemID then
                            id = autoDiscoverItemID(itemName)
                            if type(id) == "number" and id > 0 then return id end
                        end
                        return nil
                    end

                    local rebirthPkt = getPacketId("Rebirth")
                    if rebirthPkt then
                        local b = buffer.create(2)
                        buffer.writeu8(b, 0, 0)
                        buffer.writeu8(b, 1, rebirthPkt)
                        ByteNetReliable:FireServer(b)
                    end
                    task.wait(2.5)

                    local goldID = getItemIdFast("Gold")
                    if goldID then
                        for i = 1, GOLD_BUY_COUNT do
                            local b = buffer.create(8)
                            buffer.writeu8(b, 0, 0)
                            buffer.writeu8(b, 1, purchasePkt)
                            buffer.writeu32(b, 2, goldID)
                            buffer.writeu16(b, 6, 1)
                            ByteNetReliable:FireServer(b)
                            task.wait(0.05)
                        end
                    end
                    task.wait(0.5)

                    local crystalID = getItemIdFast("Crystal Chunk")
                    if crystalID then
                        for i = 1, CRYSTAL_BUY_COUNT do
                            local b = buffer.create(8)
                            buffer.writeu8(b, 0, 0)
                            buffer.writeu8(b, 1, purchasePkt)
                            buffer.writeu32(b, 2, crystalID)
                            buffer.writeu16(b, 6, 1)
                            ByteNetReliable:FireServer(b)
                            task.wait(0.05)
                        end
                    end

                    task.wait(0.85)
                    fireGodToolCraftFor(toolName)
                    return hasFarmTool(toolName)
                end

                local function tryPickupItemInRangeForCraftMats(itemsFolder, range)
                    local pl = Players.LocalPlayer
                    local hrp = pl.Character and pl.Character:FindFirstChild("HumanoidRootPart")
                    if not hrp or not itemsFolder or not ByteNetReliable then return 0 end
                    local pickupPid = getPacketId("Pickup")
                    if not pickupPid then return 0 end
                    local hrpPos = hrp.Position
                    local sent = 0
                    for _, item in ipairs(itemsFolder:GetDescendants()) do
                        if item:IsA("Model") or item:IsA("BasePart") then
                            local okPos, itemPos = pcall(function() return item:GetPivot().Position end)
                            if okPos and itemPos and (hrpPos - itemPos).Magnitude <= range then
                                local eid = item:GetAttribute("ID") or item:GetAttribute("NetworkID") or item:GetAttribute("EntityID")
                                if type(eid) == "string" then eid = tonumber(eid) end
                                if not eid then
                                    local val = item:FindFirstChildWhichIsA("IntValue", true) or item:FindFirstChildWhichIsA("NumberValue", true)
                                    if val and type(val.Value) == "number" and val.Value ~= 0 then eid = val.Value end
                                end
                                if not eid then
                                    for attrName, val in pairs(item:GetAttributes()) do
                                        if typeof(val) == "number" and val ~= 0 and (attrName == "ID" or attrName == "NetworkID" or attrName == "EntityID" or attrName == "Eid" or attrName == "EntityId") then
                                            eid = val
                                            break
                                        end
                                    end
                                end
                                if not eid and item.Parent and item.Parent ~= workspace and item.Parent ~= itemsFolder then
                                    local p = item.Parent
                                    eid = p:GetAttribute("ID") or p:GetAttribute("NetworkID") or p:GetAttribute("EntityID")
                                    if type(eid) == "string" then eid = tonumber(eid) end
                                end
                                if type(eid) == "number" and eid ~= 0 then
                                    local itemID = 0
                                    if craftNameToID and craftNameToID[item.Name] then
                                        itemID = craftNameToID[item.Name]
                                    end
                                    if (itemID == 0 or not itemID) and autoDiscoverItemID then
                                        itemID = autoDiscoverItemID(item.Name) or 0
                                    end
                                    if type(itemID) ~= "number" then itemID = 0 end
                                    local b = buffer.create(8)
                                    buffer.writeu8(b, 0, 0)
                                    buffer.writeu8(b, 1, pickupPid)
                                    buffer.writeu32(b, 2, eid)
                                    buffer.writeu16(b, 6, itemID)
                                    ByteNetReliable:FireServer(b)
                                    sent = sent + 1
                                    if sent >= 220 then break end
                                end
                            end
                        end
                    end
                    return sent
                end

                local farmGodToolObtainAttempted = false

                while Settings.StartFarmChoiceEnabled do
                    local treeFound = false
                    local essenceFound = false
                    local treeObj = nil
                    
                    local player = Players.LocalPlayer
                    local function getChar()
                        return player.Character
                    end
                    local function getHRP()
                        local c = getChar()
                        return c and c:FindFirstChild("HumanoidRootPart")
                    end
                    local function getHum()
                        local c = getChar()
                        return c and (c:FindFirstChildOfClass("Humanoid") or c:FindFirstChild("Humanoid"))
                    end
                    local hrp = getHRP()
                    local hum = getHum()
                    
                    local targetName = Settings.FarmChoice or "Ancient Tree"
                    local axeName = Settings.FarmTool or "Void Axe"
                    if targetName ~= "Ancient Tree" and targetName ~= "CrystalGuardianFarm" then
                        axeName = "God Pick"
                    end

                    if targetName == "CrystalGuardianFarm" then
                        local function setToggleByName(toggleName, state)
                            local el = Window and Window.ElementRegistry and Window.ElementRegistry[toggleName]
                            if el and el.SetValue then
                                pcall(function() el.SetValue(state) end)
                                return true
                            end
                            return false
                        end

                        local function stopCrystalMove()
                            local cHrp = getHRP()
                            if cHrp then
                                pcall(function()
                                    removeBodyVelocity(cHrp)
                                    cHrp.Velocity = Vector3.zero
                                    cHrp.RotVelocity = Vector3.zero
                                end)
                            end
                        end

                        local function getCrystalGuardian()
                            -- Prefer the live orb part: Resources["Crystal Guardian"] ... ["Crystal Guardian"] (Part).
                            local res = getWorkspaceResources()
                            if not res then return nil end
                            local outer = res:FindFirstChild("Crystal Guardian")
                            if not outer then return nil end

                            if outer:IsA("BasePart") then
                                return outer
                            end

                            for _, d in ipairs(outer:GetDescendants()) do
                                if d:IsA("BasePart") and d.Name == "Crystal Guardian" then
                                    return d
                                end
                            end

                            local inner = outer:FindFirstChild("Crystal Guardian")
                            if inner then return inner end

                            if outer:IsA("Model") then
                                return outer
                            end

                            for _, d in ipairs(outer:GetDescendants()) do
                                if d:IsA("Model") then
                                    return d
                                end
                            end

                            return outer:FindFirstChildWhichIsA("BasePart", true)
                        end

                        local function getGuardianCFrame(inst)
                            if not inst then return nil end
                            local ok, cf = pcall(function()
                                if inst:IsA("BasePart") then
                                    return inst.CFrame
                                end
                                local named = inst:FindFirstChild("Crystal Guardian", true)
                                if named and named:IsA("BasePart") then
                                    return named.CFrame
                                end
                                if inst:IsA("Model") then
                                    return inst:GetPivot()
                                end
                                local part = inst:FindFirstChildWhichIsA("BasePart", true)
                                return part and part.CFrame or nil
                            end)
                            return ok and cf or nil
                        end

                        local function getPos(inst)
                            local cf = getGuardianCFrame(inst)
                            if cf then return cf.Position end
                            local ok, pos = pcall(function()
                                if inst:IsA("Model") then return inst:GetPivot().Position end
                                if inst:IsA("BasePart") then return inst.Position end
                                local part = inst:FindFirstChildWhichIsA("BasePart", true)
                                return part and part.Position or nil
                            end)
                            return ok and pos or nil
                        end

                        local function stillAlive(inst)
                            return inst and inst.Parent ~= nil
                        end

                        local guardian = getCrystalGuardian()

                        -- Wait for character parts (prevents "doesn't walk" when spawning/respawning).
                        if not hrp or not hum then
                            local t0 = tick()
                            while Settings.StartFarmChoiceEnabled and (not hrp or not hum) and (tick() - t0) < 6 do
                                hrp = getHRP()
                                hum = getHum()
                                task.wait(0.1)
                            end
                        end

                        if hrp and hum then
                            -- Keep the selected tool equipped without equip/unequip spam.
                            -- Use a stable check (Humanoid's currently equipped Tool) and rate-limit equip attempts.
                            local lastEquipAttempt = 0
                            local function ensureToolEquipped()
                                local toolName = Settings.FarmTool or axeName
                                if not toolName or toolName == "" then return end

                                local equippedTool = (player.Character and player.Character:FindFirstChildOfClass("Tool")) or nil
                                if equippedTool and equippedTool.Name == toolName then
                                    return
                                end

                                if (tick() - lastEquipAttempt) < 1.5 then return end
                                lastEquipAttempt = tick()

                                pcall(function() equipItemPacket(toolName) end)
                            end
                            pcall(ensureToolEquipped)

                            -- Ensure Resource Aura is enabled to break it.
                            if not Settings.ResourceAuraEnabled then
                                setSelectAuraTypeEnabled("Resource Aura", true)
                            end

                            -- If it isn't spawned yet, wait a bit and keep trying.
                            local waitSpawnStart = tick()
                            while Settings.StartFarmChoiceEnabled and (not guardian) and (tick() - waitSpawnStart) < 20 do
                                guardian = getCrystalGuardian()
                                task.wait(0.25)
                            end

                            if not guardian then
                                stopCrystalMove()
                                task.wait(0.2)
                                continue
                            end

                            -- Live-follow the Crystal Guardian CFrame while farming.
                            -- When the CFrame stops changing, park 5 studs away and hold.
                            local desiredRange = 5
                            local followStart = tick()
                            local lastCF = nil
                            local stillSince = nil
                            local holdDir = nil
                            local lastImprove = tick()
                            local lastDist = math.huge
                            local STILL_EPS = 0.12
                            local STILL_HOLD = 0.2
                            local reachedGuardian = false
                            while Settings.StartFarmChoiceEnabled and (tick() - followStart) < 270 do
                                hrp = getHRP()
                                hum = getHum()
                                if not hrp or not hum then
                                    stopCrystalMove()
                                    task.wait(0.1)
                                    continue
                                end
                                guardian = getCrystalGuardian() or guardian
                                if not stillAlive(guardian) then
                                    stopCrystalMove()
                                    break
                                end

                                local cf = getGuardianCFrame(guardian)
                                local pos = cf and cf.Position or getPos(guardian)
                                if not pos then
                                    stopCrystalMove()
                                    break
                                end

                                local moving = true
                                if lastCF then
                                    local delta = (pos - lastCF.Position).Magnitude
                                    if delta < STILL_EPS then
                                        stillSince = stillSince or tick()
                                        if (tick() - stillSince) >= STILL_HOLD then
                                            moving = false
                                        end
                                    else
                                        stillSince = nil
                                    end
                                end
                                lastCF = cf or CFrame.new(pos)

                                local away = Vector3.new(hrp.Position.X - pos.X, 0, hrp.Position.Z - pos.Z)
                                if away.Magnitude > 0.15 then
                                    holdDir = away.Unit
                                elseif not holdDir then
                                    local look = Vector3.new(hrp.CFrame.LookVector.X, 0, hrp.CFrame.LookVector.Z)
                                    if look.Magnitude > 0.15 then
                                        holdDir = -look.Unit
                                    else
                                        holdDir = Vector3.new(1, 0, 0)
                                    end
                                end

                                local holdPos = Vector3.new(pos.X, hrp.Position.Y, pos.Z) + (holdDir * desiredRange)
                                local distToGuardian = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
                                local distToHold = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(holdPos.X, 0, holdPos.Z)).Magnitude

                                if distToGuardian <= (desiredRange + 1.25) then
                                    reachedGuardian = true
                                    pcall(ensureToolEquipped)
                                end

                                if distToGuardian < (lastDist - 0.35) then
                                    lastDist = distToGuardian
                                    lastImprove = tick()
                                end

                                local speed = tonumber(Settings.CrystalGuardianSpeed) or tonumber(Settings.FarmingTweenSpeed) or tonumber(Settings.GoldSpeed) or 20
                                local stuck = (tick() - lastImprove) > 2.0
                                if stuck then
                                    pcall(function() removeBodyVelocity(hrp) end)
                                    lastImprove = tick()
                                end

                                if (not moving) and distToHold <= 0.55 then
                                    stopCrystalMove()
                                else
                                    if walkToWaypoint then
                                        pcall(function() walkToWaypoint(hrp, hum, holdPos, speed) end)
                                    end
                                    pcall(function() hum:MoveTo(holdPos) end)
                                end

                                task.wait(0.05)
                            end

                            -- Cleanup movement helpers to avoid drifting after break.
                            pcall(function()
                                if hrp then removeBodyVelocity(hrp) end
                                if removeAlignPosition then removeAlignPosition() end
                                isTweening = false
                            end)

                            -- Turn on auto pickup for drops.
                            Settings.AutoPickupEnabled = true
                            if not setToggleByName("Auto Pickup Items", true) then
                                if startAutoPickup then pcall(function() startAutoPickup() end) end
                            end

                            -- Prioritize Spirit Key pickup before rejoining.
                            task.wait(0.35)
                            pcall(function()
                                local hrp2 = getHRP()
                                if not hrp2 or not ByteNetReliable then return end
                                local pickupPid = getPacketId("Pickup")
                                if not pickupPid then return end

                                local itemsFolder = workspace:FindFirstChild("Items") or workspace:FindFirstChild("DroppedItems")
                                if not itemsFolder then return end

                                local SPIRIT_KEY_ID = 387
                                local function spiritKeyOwned()
                                    local ok, cnt = pcall(function()
                                        if getInventoryCount then return getInventoryCount("Spirit Key") end
                                        return 0
                                    end)
                                    if ok and type(cnt) == "number" and cnt > 0 then return true end
                                    local c = player.Character
                                    if c and c:FindFirstChild("Spirit Key") then return true end
                                    local bp = player:FindFirstChildOfClass("Backpack")
                                    if bp and bp:FindFirstChild("Spirit Key") then return true end
                                    return false
                                end

                                local ownedBefore = spiritKeyOwned()
                                while Settings.StartFarmChoiceEnabled do
                                    hrp2 = getHRP()
                                    if not hrp2 then break end
                                    -- Stop waiting once we actually have the key.
                                    if spiritKeyOwned() and not ownedBefore then break end
                                    if ownedBefore and spiritKeyOwned() then break end
                                    local foundAny = false
                                    for _, item in ipairs(itemsFolder:GetDescendants()) do
                                        if item.Name == "Spirit Key" and (item:IsA("Model") or item:IsA("BasePart")) then
                                            local okPos, ipos = pcall(function() return item:GetPivot().Position end)
                                            if okPos and ipos and (hrp2.Position - ipos).Magnitude <= 45 then
                                                local eid = item:GetAttribute("NetworkID") or item:GetAttribute("EntityID") or item:GetAttribute("ID")
                                                if type(eid) == "string" then eid = tonumber(eid) end
                                                if not eid then
                                                    local val = item:FindFirstChildWhichIsA("IntValue", true) or item:FindFirstChildWhichIsA("NumberValue", true)
                                                    if val and type(val.Value) == "number" and val.Value > 0 then eid = val.Value end
                                                end
                                                if type(eid) == "number" and eid ~= 0 then
                                                    local b = buffer.create(8)
                                                    buffer.writeu8(b, 0, 0)
                                                    buffer.writeu8(b, 1, pickupPid)
                                                    buffer.writeu32(b, 2, eid)
                                                    buffer.writeu16(b, 6, SPIRIT_KEY_ID)
                                                    ByteNetReliable:FireServer(b)
                                                    foundAny = true
                                                end
                                            end
                                        end
                                    end
                                    if foundAny then
                                        task.wait(0.12)
                                    else
                                        task.wait(0.22)
                                    end
                                end
                            end)

                            task.wait(0.4)

                            -- Rejoin and repeat (via auto-exec).
                            pcall(function()
                                -- Use the Auto Rejoin system (toggle + kick) when available.
                                if not Settings.AutoRejoinEnabled then
                                    setToggleByName("Auto Rejoin", true)
                                    Settings.AutoRejoinEnabled = true
                                end

                                local privateServerId = workspace:GetAttribute("privateServerId") or ""
                                if privateServerId ~= "" then
                                    Players.LocalPlayer:Kick("\n\nYou have been kicked from the server.\nVIP ID: " .. privateServerId)
                                else
                                    Players.LocalPlayer:Kick("\n\nYou have been safely kicked from the server.")
                                end
                            end)
                            break
                        end

                        task.wait(0.2)
                        continue
                    end

                    if (axeName == "God Axe" or axeName == "God Pick") and not hasFarmTool(axeName) and not farmGodToolObtainAttempted then
                        farmGodToolObtainAttempted = true
                        local obtainOpt = Settings.ToolSaveOption or "BuyFromShop (GodOnly)"
                        if obtainOpt == "Reset&Loot" then
                            local char = Players.LocalPlayer.Character
                            if char and char:FindFirstChild("Humanoid") then
                                char.Humanoid.Health = 0
                            end
                            task.wait(0.8)
                            local rebirthPkt = getPacketId("Rebirth")
                            if ByteNetReliable and rebirthPkt then
                                local b = buffer.create(2)
                                buffer.writeu8(b, 0, 0)
                                buffer.writeu8(b, 1, rebirthPkt)
                                ByteNetReliable:FireServer(b)
                            end
                            -- Reset&Loot: do not run any heavy item scanning on start.
                            task.wait(4)
                        else
                            tryStockAndCraftGodTool(axeName)
                        end
                    end

                    -- Ancient Tree: craft the selected axe as soon as it is missing.
                    if targetName == "Ancient Tree" and not hasFarmTool(axeName) then
                        ensureAncientTreeAxe(axeName)
                    end
                    
                    -- Mobile/Android Optimization: Find the boss instantly without looping the whole game
                    treeObj = workspace:FindFirstChild(targetName, true)
                    if treeObj then
                        treeFound = true
                    end
                    
                    -- Essence sits as a direct child of workspace.Items (e.g. Items:GetChildren()[n]); also allow renames / nested parts.
                    if targetName == "Ancient Tree" then
                        local itemsFolder = workspace:FindFirstChild("Items") or workspace:FindFirstChild("DroppedItems") or workspace
                        local function worldNameIsEssenceDrop(name)
                            if not name or name == "" then return false end
                            local n = string.lower(name)
                            return n == "essence" or n == "essence stack" or string.find(n, "essence", 1, true) ~= nil
                        end
                        local seenPickupEid = {}
                        local function coerceEntityId(v)
                            if type(v) == "number" and v == v and v ~= 0 then return v end
                            if type(v) == "string" then
                                local n = tonumber(v)
                                if type(n) == "number" and n ~= 0 then return n end
                            end
                            return nil
                        end
                        local function readEntityIdOnInstance(inst)
                            if not inst then return nil end
                            return coerceEntityId(inst:GetAttribute("ID"))
                                or coerceEntityId(inst:GetAttribute("NetworkID"))
                                or coerceEntityId(inst:GetAttribute("EntityID"))
                                or coerceEntityId(inst:GetAttribute("Eid"))
                                or coerceEntityId(inst:GetAttribute("EntityId"))
                        end
                        local function readEntityIdFromSubtree(root)
                            local eid = readEntityIdOnInstance(root)
                            if eid then return eid end
                            for _, childName in ipairs({ "ID", "NetworkID", "EntityID", "Eid", "EntityId" }) do
                                local ch = root:FindFirstChild(childName, true)
                                if ch and (ch:IsA("IntValue") or ch:IsA("NumberValue")) then
                                    eid = coerceEntityId(ch.Value)
                                    if eid then return eid end
                                end
                            end
                            for _, d in ipairs(root:GetDescendants()) do
                                eid = readEntityIdOnInstance(d)
                                if eid then return eid end
                            end
                            return nil
                        end
                        local function tryPickupEssenceObj(obj)
                            if not worldNameIsEssenceDrop(obj.Name) then return end
                            if hrp then
                                local ok, pos = pcall(function()
                                    return obj:GetPivot().Position
                                end)
                                if ok and pos and (pos - hrp.Position).Magnitude > 150 then return end
                            end
                            essenceFound = true
                            local eid = readEntityIdFromSubtree(obj)
                            if not eid and obj.Parent and obj.Parent ~= itemsFolder and obj.Parent ~= workspace then
                                eid = readEntityIdFromSubtree(obj.Parent)
                            end
                            if not eid or seenPickupEid[eid] then return end
                            seenPickupEid[eid] = true
                            local itemID = 0
                            if autoDiscoverItemID then
                                itemID = autoDiscoverItemID(obj.Name) or autoDiscoverItemID("Essence") or autoDiscoverItemID("Essence Stack") or 0
                            end
                            if type(itemID) ~= "number" then itemID = 0 end
                            if ByteNetReliable and getPacketId("Pickup") and type(eid) == "number" then
                                local b = buffer.create(8)
                                buffer.writeu8(b, 0, 0)
                                buffer.writeu8(b, 1, getPacketId("Pickup"))
                                buffer.writeu32(b, 2, eid)
                                buffer.writeu16(b, 6, itemID)
                                ByteNetReliable:FireServer(b)
                            end
                        end
                        if itemsFolder.Name == "Items" or itemsFolder.Name == "DroppedItems" then
                            for _, obj in ipairs(itemsFolder:GetChildren()) do
                                tryPickupEssenceObj(obj)
                            end
                            for _, obj in ipairs(itemsFolder:GetDescendants()) do
                                tryPickupEssenceObj(obj)
                            end
                        else
                            for _, obj in ipairs(itemsFolder:GetDescendants()) do
                                tryPickupEssenceObj(obj)
                            end
                        end
                    end

                    if treeObj then
                        if targetName == "Ancient Tree" and not hasFarmTool(axeName) then
                            ensureAncientTreeAxe(axeName)
                        end
                        if not isToolEquipped(axeName) then
                            equipItemPacket(axeName)
                            task.wait(0.2)
                        end
                        
                        if hrp and ByteNetReliable and getPacketId("SwingTool") then
                            
                            local eid = treeObj:GetAttribute("NetworkID") or treeObj:GetAttribute("EntityID") or treeObj:GetAttribute("ID")
                            if not eid then
                                local valObj = treeObj:FindFirstChildWhichIsA("IntValue", true) or treeObj:FindFirstChildWhichIsA("NumberValue", true)
                                if valObj and valObj.Value > 1000 then eid = valObj.Value end
                            end
                            if not eid then
                                for name, val in pairs(treeObj:GetAttributes()) do
                                    if typeof(val) == "number" and val > 1000 then eid = val break end
                                end
                            end
                            
                            if eid then
                                local treePos = nil
                                pcall(function() treePos = treeObj:GetPivot().Position end)
                                fireByteNetSwingTool({
                                    { eid = eid, pos = treePos or hrp.Position }
                                }, hrp, { maxPerPacket = 1 })

                                local swingBuf = buffer.create(2)
                                buffer.writeu8(swingBuf, 0, 0)
                                buffer.writeu8(swingBuf, 1, getPacketId("ClientSwing"))
                                ByteNetReliable:FireServer(swingBuf)
                            end
                        end
                    end
                    
                    if not treeFound and not essenceFound then
                        local player = Players.LocalPlayer
                        local topbarGui = player:WaitForChild("PlayerGui", 5) and player.PlayerGui:FindFirstChild("Topbar")
                        local levelLabel = topbarGui and topbarGui:FindFirstChild("Topbar") and topbarGui.Topbar:FindFirstChild("Right") and topbarGui.Topbar.Right:FindFirstChild("Level") and topbarGui.Topbar.Right.Level:FindFirstChild("Level")
                        local rawText = levelLabel and levelLabel.Text or "0"
                        local levelNumber = tonumber(rawText:match("%d+")) or 0
                        
                        if targetName ~= "Ancient Tree" and Settings.GodLootPickUpEnabled then
                            -- God Loot Pickup Sequence
                            local pickupStart = tick()
                            while tick() - pickupStart < 4 do
                                local hrp = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
                                if hrp and ByteNetReliable and getPacketId("Pickup") then
                                    local itemsFolder = workspace:FindFirstChild("Items") or workspace:FindFirstChild("DroppedItems") or workspace
                                    for _, item in ipairs(itemsFolder:GetDescendants()) do
                                        if item:IsA("Model") or item:IsA("BasePart") then
                                            local itemPos = item:GetPivot().Position
                                            if (hrp.Position - itemPos).Magnitude < 40 then
                                                local eid = item:GetAttribute("NetworkID") or item:GetAttribute("EntityID") or item:GetAttribute("ID")
                                                if not eid then
                                                    local val = item:FindFirstChildWhichIsA("IntValue", true) or item:FindFirstChildWhichIsA("NumberValue", true)
                                                    if val and val.Value > 1000 then eid = val.Value end
                                                end
                                                if not eid then
                                                    for name, val in pairs(item:GetAttributes()) do
                                                        if typeof(val) == "number" and val > 1000 then eid = val break end
                                                    end
                                                end
                                                
                                                local itemID = autoDiscoverItemID and autoDiscoverItemID(item.Name)
                                                if itemID and eid then
                                                    local b = buffer.create(8)
                                                    buffer.writeu8(b, 0, 0)
                                                    buffer.writeu8(b, 1, getPacketId("Pickup"))
                                                    buffer.writeu32(b, 2, eid)
                                                    buffer.writeu16(b, 6, itemID)
                                                    ByteNetReliable:FireServer(b)
                                                end
                                            end
                                        end
                                    end
                                end
                                task.wait(0.05)
                            end
                        end
                        
                        if levelNumber >= 100 and (targetName == "Ancient Tree" or Settings.GodAutoRebirthEnabled) then
                            if axeName ~= "God Axe" and axeName ~= "God Pick" then
                                local slot = getToolSlot(axeName)
                                if slot then
                                    local b = buffer.create(3)
                                    buffer.writeu8(b, 0, 0)
                                    local retoolId = getPacketId("Retool")
                                    if retoolId then
                                        buffer.writeu8(b, 1, retoolId)
                                        buffer.writeu8(b, 2, slot)

                                        if ByteNetReliable then
                                            ByteNetReliable:FireServer(b)
                                        end

                                        task.wait(0.3) -- Give the server time to process the Retool before dropping
                                        if drop then drop(axeName) end
                                        task.wait(0.5)
                                    end
                                end
                                
                                -- Rebirth
                                if ByteNetReliable and getPacketId("Rebirth") then
                                    local b = buffer.create(2)
                                    buffer.writeu8(b, 0, 0)
                                    buffer.writeu8(b, 1, getPacketId("Rebirth"))
                                    ByteNetReliable:FireServer(b)
                                end
                                task.wait(2.5) -- Wait for bed respawn
                                
                                -- Pick up the dropped axe repeatedly until we have it
                                local itemsFolder = workspace:FindFirstChild("Items") or workspace:FindFirstChild("DroppedItems") or workspace
                                while not hasFarmTool(axeName) do
                                    local axeItem = nil
                                    for _, item in ipairs(itemsFolder:GetDescendants()) do
                                        if item.Name == axeName then
                                            axeItem = item
                                            break
                                        end
                                    end
                                    
                                    if axeItem then
                                        local eid = axeItem:GetAttribute("NetworkID") or axeItem:GetAttribute("EntityID") or axeItem:GetAttribute("ID")
                                        if not eid then
                                            local val = axeItem:FindFirstChildWhichIsA("IntValue", true) or axeItem:FindFirstChildWhichIsA("NumberValue", true)
                                            if val and val.Value > 1000 then eid = val.Value end
                                        end
                                        if not eid then
                                            for name, val in pairs(axeItem:GetAttributes()) do
                                                if typeof(val) == "number" and val > 1000 then eid = val break end
                                            end
                                        end
                                        
                                        local itemID = (autoDiscoverItemID and autoDiscoverItemID(axeName)) or manualToolIDs[axeName]
                                        
                                        if itemID and eid and ByteNetReliable and getPacketId("Pickup") then
                                            local b = buffer.create(8)
                                            buffer.writeu8(b, 0, 0)
                                            buffer.writeu8(b, 1, getPacketId("Pickup"))
                                            buffer.writeu32(b, 2, eid)
                                            buffer.writeu16(b, 6, itemID)
                                            ByteNetReliable:FireServer(b)
                                        end
                                    end
                                    task.wait(0.2)
                                end
                            else
                                -- God Axe / God Pick Logic
                                local godAxeOption = Settings.ToolSaveOption or "BuyFromShop (GodOnly)"
                                
                                if godAxeOption == "Reset&Loot" then
                                    -- Reset character
                                    local char = Players.LocalPlayer.Character
                                    if char and char:FindFirstChild("Humanoid") then
                                        char.Humanoid.Health = 0
                                    end
                                    task.wait(0.8) -- Wait for character to die and drop bag
                                    
                                    -- Rebirth
                                    if ByteNetReliable and getPacketId("Rebirth") then
                                        local b = buffer.create(2)
                                        buffer.writeu8(b, 0, 0)
                                        buffer.writeu8(b, 1, getPacketId("Rebirth"))
                                        ByteNetReliable:FireServer(b)
                                    end
                                    
                                    task.wait(4) -- Wait longer for spawn menu and Auto Bed Respawn to teleport
                                    -- Reset&Loot: do not scan items/craft on toggle enable. The "loot" path
                                    -- is intentionally lightweight here; farming loop will continue normally.
                                else
                                    -- BuyFromShop (GodOnly): one rebirth, one shop stock-up, one craft
                                    tryStockAndCraftGodTool(axeName)
                                    task.wait(0.9)
                                end
                            end
                            
                            task.wait(2.5)
                        end
                        
                        Settings.StartFarmChoiceEnabled = false
                        local privateServerId = workspace:GetAttribute("privateServerId") or ""
                        if privateServerId ~= "" then
                            Players.LocalPlayer:Kick("\n\nYou have been kicked from the server.\nVIP ID: " .. privateServerId)
                        else
                            Players.LocalPlayer:Kick("\n\nYou have been safely kicked from the server.")
                        end
                        
                        break
                    end
                    
                    task.wait(0.2)
                end
            end)
        end
    end)

    -- [[ POTIONS & SAND FARM ]] --
    do -- AsterPotionSandFarmUI
        -- Game cauldron UI crafts via Packets.CraftPotion.send({ itemID, entityID })
        -- Wire: [0]=0 [1]=CraftPotion [2..5]=entityID u32 [6..7]=itemID u16
        local CollectionService = game:GetService("CollectionService")
        local PotionSelectList = {
            "Fire Resistance Potion",
            "Harming Potion",
            "Haste Potion",
            "Healing Potion",
            "Ice Potion",
            "Poison Potion",
            "Splash Fire Resistance Potion",
            "Splash Harming Potion",
            "Splash Haste Potion",
            "Splash Healing Potion",
            "Splash Ice Potion",
            "Splash Poison Potion",
            "Splash Strength Potion",
            "Splash Swiftness Potion",
            "Splash Weakness Potion",
            "Strength Potion",
            "Swiftness Potion",
            "Weakness Potion",
        }

        local function resolvePotionCraftID(potionName)
            if not potionName or potionName == "" then return nil end
            local itemID = craftNameToID and craftNameToID[potionName]
            if not itemID then
                pcall(function()
                    local ItemIDS = require(ReplicatedStorage.Modules.ItemIDS)
                    if type(ItemIDS) == "table" then
                        local v = ItemIDS[potionName]
                        if type(v) == "number" then
                            itemID = v
                        end
                    end
                end)
            end
            if not itemID then
                itemID = autoDiscoverItemID(potionName)
            end
            if itemID then
                Settings.PotionCraftItemID = itemID
                if type(craftNameToID) == "table" then
                    craftNameToID[potionName] = itemID
                end
                pcall(function()
                    local discoveredPath = "ASTER/Booga/discovered_items.json"
                    local discovered = {}
                    if isfile(discoveredPath) then
                        discovered = game:GetService("HttpService"):JSONDecode(readfile(discoveredPath)) or {}
                    end
                    discovered[potionName] = itemID
                    writefile(discoveredPath, game:GetService("HttpService"):JSONEncode(discovered))
                end)
            end
            return itemID
        end

        local function getCraftPotionPacketId()
            local id = getPacketId("CraftPotion")
            if id then return id end
            pcall(function()
                local Packets = require(ReplicatedStorage.Modules.Packets)
                local pkt = Packets and Packets.CraftPotion
                if type(pkt) == "table" then
                    for _, key in ipairs({ "id", "Id", "_id", "packetId", "packetID", "ID" }) do
                        local v = pkt[key]
                        if type(v) == "number" and v > 0 then
                            PACKET_IDS.CraftPotion = v
                            return
                        end
                    end
                end
            end)
            return getPacketId("CraftPotion")
        end

        local function getNearestCraftCauldron(range)
            range = tonumber(range) or tonumber(Settings.PotionRange) or 15
            local char = plr.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if not hrp then return nil end
            local origin = hrp.Position
            local bestFilled, bestFilledDist = nil, range
            local bestAny, bestAnyDist = nil, range

            local function consider(model)
                if not model or not model:IsA("Model") then return end
                local eid = model:GetAttribute("EntityID")
                if typeof(eid) ~= "number" or eid <= 0 then return end
                local pivot = model:GetPivot()
                if not pivot then return end
                local dist = (pivot.Position - origin).Magnitude
                if dist > range then return end
                local entry = { model = model, entityID = eid, dist = dist, filled = model:GetAttribute("filled") == true }
                if entry.filled and dist <= bestFilledDist then
                    bestFilled, bestFilledDist = entry, dist
                end
                if dist <= bestAnyDist then
                    bestAny, bestAnyDist = entry, dist
                end
            end

            for _, model in ipairs(CollectionService:GetTagged("Cauldron")) do
                consider(model)
            end
            if not bestFilled and not bestAny then
                local deployables = workspace:FindFirstChild("Deployables")
                local folder = deployables or workspace
                for _, v in ipairs(folder:GetChildren()) do
                    if v:IsA("Model") and (v.Name == "Cauldron" or v.Name:find("Cauldron")) then
                        consider(v)
                    end
                end
            end
            return bestFilled or bestAny
        end

        local function fireCraftPotion(itemID, entityID)
            if not itemID or not entityID or not ByteNetReliable then return false end
            local craftId = getCraftPotionPacketId()
            if not craftId then return false end
            local b = buffer.create(8)
            buffer.writeu8(b, 0, 0)
            buffer.writeu8(b, 1, craftId)
            buffer.writeu32(b, 2, entityID)
            buffer.writeu16(b, 6, itemID)
            ByteNetReliable:FireServer(b)
            return true
        end

        local autoCraftPotionActive = false
        local function startAutoCraftPotion()
            if autoCraftPotionActive then return end
            autoCraftPotionActive = true
            task.spawn(function()
                while Settings.AutoCraftPotionEnabled do
                    pcall(function()
                        local potionName = Settings.SelectedPotion
                        local itemID = Settings.PotionCraftItemID
                        if not itemID and potionName then
                            itemID = resolvePotionCraftID(potionName)
                        end
                        local cauldron = getNearestCraftCauldron(Settings.PotionRange)
                        if itemID and cauldron and cauldron.entityID then
                            fireCraftPotion(itemID, cauldron.entityID)
                        end
                    end)
                    task.wait(tonumber(Settings.PotionCraftDelay) or 0.5)
                end
                autoCraftPotionActive = false
            end)
        end

        ASTER.Tabs.Automation:AddLabel("Potions & SandFarm")
        ASTER.Tabs.Automation:AddDropdown("Select Potions", PotionSelectList, Settings.SelectedPotion or "Swiftness Potion", function(v)
            Settings.SelectedPotion = v
            Settings.PotionCraftItemID = nil
            resolvePotionCraftID(v)
        end)
        ASTER.Tabs.Automation:AddToggle("AutoCraft Potion", false, function(v)
            Settings.AutoCraftPotionEnabled = v
            if v then
                if not Settings.PotionCraftItemID and Settings.SelectedPotion then
                    resolvePotionCraftID(Settings.SelectedPotion)
                end
                startAutoCraftPotion()
            end
        end)
        ASTER.Tabs.Automation:AddSlider("Potion Craft Delay", 0.01, 2, 0.5, 0.01, function(v)
            Settings.PotionCraftDelay = v
        end)
        ASTER.Tabs.Automation:AddSlider("Potion Range", 5, 40, 15, 1, function(v)
            Settings.PotionRange = v
        end)

        local autoBarleyActive = false
        local barleyPacket = buffer.create(8)
        buffer.writeu8(barleyPacket, 0, 0x75)
        buffer.writeu8(barleyPacket, 1, 0xe9)
        buffer.writeu8(barleyPacket, 2, 0xfd)
        buffer.writeu8(barleyPacket, 3, 0x32)
        buffer.writeu8(barleyPacket, 4, 0xcc)
        buffer.writeu8(barleyPacket, 5, 0x43)
        buffer.writeu8(barleyPacket, 6, 0x80)
        buffer.writeu8(barleyPacket, 7, 0xa7)

        local function fireBarleyPacket()
            if not ByteNetReliable then return false end
            return pcall(function()
                ByteNetReliable:FireServer(barleyPacket)
            end)
        end

        local function startAutoBarley()
            if autoBarleyActive then return end
            autoBarleyActive = true
            task.spawn(function()
                while Settings.AutoBarleyEnabled and not ScriptKilled do
                    fireBarleyPacket()
                    local cps = math.clamp(tonumber(Settings.BarleyCPS) or 20, 1, 200)
                    task.wait(1 / cps)
                end
                autoBarleyActive = false
            end)
        end

        ASTER.Tabs.Automation:AddToggle("Auto Barley", false, function(v)
            Settings.AutoBarleyEnabled = v
            if v then startAutoBarley() end
        end)
        ASTER.Tabs.Automation:AddSlider("Auto Barley CPS", 1, 200, Settings.BarleyCPS or 20, 1, function(v)
            Settings.BarleyCPS = math.clamp(math.floor(tonumber(v) or 20), 1, 200)
        end)

        ASTER.Tabs.Automation:AddToggle("Auto Sand Farm (Turn on resource aura)", false, function(v)
            Settings.AutoSandEnabled = v
            if v then startAutoSand() end
        end)
        ASTER.Tabs.Automation:AddSlider("Farm Speed", 0.2, 1, 0.4, 0.1, function(v)
            Settings.SandFarmSpeed = v
        end)
        ASTER.Tabs.Automation:AddSlider("Sand Amount", 1, 40, Settings.SandAmount or 1, 1, function(v)
            Settings.SandAmount = math.floor(tonumber(v) or 1)
        end)

        task.defer(function()
            if Settings.SelectedPotion then
                resolvePotionCraftID(Settings.SelectedPotion)
            end
            pcall(syncPacketIDs)
        end)
    end -- AsterPotionSandFarmUI

    ASTER.Tabs.Automation:AddLabel("PathFinder/AutoStuff")
    refreshPathFinderItemIds()
    local pathItemOptions = getPathFinderItemOptions()
    local pathItemDefault = Settings.PathFinderItem or PATHFINDER_ORE_NAMES[1] or "Iron Node"
    local pathItemListed = false
    for _, name in ipairs(pathItemOptions) do
        if name == pathItemDefault then pathItemListed = true break end
    end
    if not pathItemListed then pathItemDefault = pathItemOptions[1] or PATHFINDER_ORE_NAMES[1] or "Iron Node" end
    ASTER.Tabs.Automation:AddToggle("StartPathFinder", false, function(v)
        Settings.PathFinderEnabled = v
        if v then
            resetPathFinderSelection(Settings.PathFinderItem)
            if __ASTER_RUNTIME.pathFinderState and __ASTER_RUNTIME.pathFinderState.active then
                stopPathFinder()
                Settings.PathFinderEnabled = true
            end
            startPathFinder()
        else
            stopPathFinder()
        end
    end)
    ASTER.Options.PathItemDropdown = ASTER.Tabs.Automation:AddDropdown("SelectPathItem", pathItemOptions, pathItemDefault, function(v)
        resetPathFinderSelection(v)
    end)
    if not __ASTER_RUNTIME.pathFinderRefreshStarted then
        __ASTER_RUNTIME.pathFinderRefreshStarted = true
        local session = CURRENT_SESSION
        task.spawn(function()
            local lastSerialized = table.concat(pathItemOptions, "\0")
            while not ScriptKilled and isRuntimeSessionActive(session) do
                if Settings.PathFinderEnabled then
                    refreshPathFinderItemIds()
                    task.wait(8)
                else
                    refreshPathFinderItemIds()
                    task.wait(45)
                end
                local newOpts = getPathFinderItemOptions()
                local serialized = table.concat(newOpts, "\0")
                if serialized ~= lastSerialized and ASTER.Options.PathItemDropdown then
                    lastSerialized = serialized
                    ASTER.Options.PathItemDropdown:SetValues(newOpts)
                    local current = Settings.PathFinderItem
                    local stillListed = false
                    for _, name in ipairs(newOpts) do
                        if name == current then stillListed = true break end
                    end
                    if not stillListed and newOpts[1] then
                        ASTER.Options.PathItemDropdown:SetValue(newOpts[1])
                    end
                end
            end
        end)
    end
    ASTER.Tabs.Automation:AddSlider("PathFinderSpeed", 1, 21, Settings.PathFinderSpeed or 18, 1, function(v)
        Settings.PathFinderSpeed = math.floor(v + 0.5)
    end)

end -- AsterAutomationTabUI

-- [[ PLANTING TAB ]] --
do -- AsterPlantingTabUI
    -- The movement/tween farming modes all drive the character with the same
    -- primitives, so only ONE may be active at a time. Enabling one disables the
    -- others (and updates their toggle UI) to stop them fighting over movement.
    local MOVEMENT_MODES = {
        { key = "TweenToPlantBox",  reg = "Tween to Plant Box" },
        { key = "TweenToBush",      reg = "Tween to Bush" },
        { key = "TweenToBushAndBox", reg = "Tween to Bush & Box" },
        { key = "CacheWalk",        reg = "CacheWalk" },
    }
    local function setExclusiveMovement(keepReg)
        if ASTER.ConfigSystem and ASTER.ConfigSystem.Loading then return end
        for _, m in ipairs(MOVEMENT_MODES) do
            if m.reg ~= keepReg and Settings[m.key] then
                Settings[m.key] = false
                local el = Window.ElementRegistry[m.reg]
                if el and el.SetValue then el.SetValue(false) end
            end
        end
    end

    ASTER.Tabs.Planting:AddLabel("Farming")
    ASTER.Tabs.Planting:AddToggle("Auto Plant", false, function(v)
        Settings.PlantEnabled = v
        if v then startPlant() end
    end)
    ASTER.Tabs.Planting:AddMultiDropdown("Plant Fruit", PLANT_FRUIT_LIST, {"Bloodfruit"}, function(v)
        Settings.PlantFruit = v
    end)

    ASTER.Tabs.Planting:AddToggle("Auto Harvest", false, function(v)
        Settings.HarvestEnabled = v
        if v then startHarvest() end
    end)

        ASTER.Tabs.Planting:AddToggle("Tween to Plant Box", false, function(v)
        Settings.TweenToPlantBox = v
        if v then
            setExclusiveMovement("Tween to Plant Box")
            startTweenPlantBox()
        end
    end)
        ASTER.Tabs.Planting:AddToggle("Tween to Bush", false, function(v)
        Settings.TweenToBush = v
        if v then
            setExclusiveMovement("Tween to Bush")
            startTweenToBush()
        end
    end)
    ASTER.Tabs.Planting:AddToggle("Tween to Bush & Box", false, function(v)
        Settings.TweenToBushAndBox = v
        if v then
            setExclusiveMovement("Tween to Bush & Box")
            startTweenBushAndBox()
        end
    end)

    ASTER.Tabs.Planting:AddLabel("CacheFarming")
    ASTER.Tabs.Planting:AddSlider("CacheAmount", 1, 50, 20, 1, function(v)
        Settings.CacheAmount = math.clamp(math.floor(tonumber(v) or 20), 1, 50)
    end)
    ASTER.Tabs.Planting:AddSlider("CacheTimer", 1, 10, 3, 1, function(v)
        Settings.CacheTimer = math.clamp(tonumber(v) or 3, 1, 10)
    end)
    ASTER.Tabs.Planting:AddToggle("CachePlantBoxes", false, function(v)
        Settings.CachePlantBoxes = v
        if not v and Settings.CacheWalk and not ASTER.ConfigSystem.Loading then
            Settings.CacheWalk = false
            if Window.ElementRegistry["CacheWalk"] and Window.ElementRegistry["CacheWalk"].SetValue then
                Window.ElementRegistry["CacheWalk"].SetValue(false)
            end
        end
        if v or Settings.CacheWalk == true then
            startPlant()
        elseif not (Settings.TweenToPlantBox or Settings.TweenToBush or Settings.TweenToBushAndBox) then
            plantStopMovement()
        end
    end)
    ASTER.Tabs.Planting:AddToggle("CacheWalk", false, function(v)
        Settings.CacheWalk = v
        if v then
            setExclusiveMovement("CacheWalk")
            startPlant()
        elseif Settings.CachePlantBoxes == true then
            startPlant()
        elseif not (Settings.TweenToPlantBox or Settings.TweenToBush or Settings.TweenToBushAndBox) then
            plantStopMovement()
        end
    end)


ASTER.Tabs.Planting:AddLabel("Performance")

    ASTER.Tabs.Planting:AddSlider("Harvest Range", 5, 150, Settings.HarvestRange or 30, 5, function(v)
        Settings.HarvestRange = math.clamp(math.floor(tonumber(v) or 30), 5, 150)
    end)
    ASTER.Tabs.Planting:AddSlider("Harvest Batch Size", 10, 200, 50, 10, function(v)
        Settings.HarvestBatchSize = v
    end)

     ASTER.Tabs.Planting:AddSlider("Planting Range", 5, 25, 18, 1, function(v)
        Settings.PlantRange = v
    end)
    ASTER.Tabs.Planting:AddSlider("Bush Search", 250, 1000, Settings.TweenRange or 500, 10, function(v)
        Settings.TweenRange = math.clamp(tonumber(v) or 500, 250, 1000)
    end)

    ASTER.Tabs.Planting:AddDropdown("Tween Select", {"Tween", "Walk", "SmoothWalk"}, Settings.PlantingTweenMode or "SmoothWalk", function(v)
        Settings.PlantingTweenMode = v
    end)
    ASTER.Tabs.Planting:AddSlider("Tween Speed", 1, 21, 18, 1, function(v)
        Settings.PlantingTweenSpeed = v
    end)

end -- AsterPlantingTabUI

do -- AsterPlantPlacementUI
    ASTER.Tabs.Planting:AddLabel("Placement")

    ASTER.Options.updatePlantPlacementState = function()
        Settings.MultiplyPlantBox = false
        Settings.SoloPatternPlantBoxes = false
        if Settings.AutoPlaceMaster then
            if Settings.PlantMode == "MultiPlantBoxPlacement" then Settings.MultiplyPlantBox = true startMultiplyPlantBox()
            elseif Settings.PlantMode == "SinglePlantBoxPlacement" then Settings.SoloPatternPlantBoxes = true startSoloPatternPlantBoxes() end
        end
    end
    ASTER.Tabs.Planting:AddToggle("Auto Place Master", false, function(v)
        Settings.AutoPlaceMaster = v
        if ASTER.Options.updatePlantPlacementState then ASTER.Options.updatePlantPlacementState() end
    end)
    ASTER.Tabs.Planting:AddDropdown("Mode", {"MultiPlantBoxPlacement", "SinglePlantBoxPlacement"}, "MultiPlantBoxPlacement", function(v)
        Settings.PlantMode = v
        if ASTER.Options.updatePlantPlacementState then ASTER.Options.updatePlantPlacementState() end
    end)
    
    ASTER.Tabs.Planting:AddToggle("Preview Placement", false, function(v)
        Settings.ShowPlantBoxPreview = v
        if not v and clearPlantBoxPreviewVisuals then
            clearPlantBoxPreviewVisuals()
        end
    end)
    ASTER.Tabs.Planting:AddSlider("Plant Box Rotation", 0, 360, 0, 1, function(v)
        Settings.PlantBoxRotation = v
    end)
    
end -- AsterPlantPlacementUI

-- [[ VISUALS TAB ]] --
do -- AsterVisualsTabUI
    ASTER.Tabs.Visuals:AddLabel("ESP Color")
    local ESP_COLOR_TARGETS = {"PlayerESP", "GodESP", "Wandering Trader ESP", "Big Chests", "Meteor Core ESP", "God Boss ESP", "Critter ESP"}
    local ESP_COLOR_PRESETS = {
        ["Purple"] = Color3.fromRGB(170, 85, 255),
        ["Pink"] = Color3.fromRGB(255, 0, 255),
        ["Red"] = Color3.fromRGB(255, 0, 0),
        ["Orange"] = Color3.fromRGB(255, 150, 50),
        ["Yellow"] = Color3.fromRGB(255, 255, 0),
        ["Green"] = Color3.fromRGB(0, 255, 0),
        ["Cyan"] = Color3.fromRGB(0, 255, 255),
        ["Blue"] = Color3.fromRGB(0, 120, 255),
        ["White"] = Color3.fromRGB(255, 255, 255),
    }

    local function colorToHex(c)
        return string.format("#%02X%02X%02X", math.floor(c.R * 255 + 0.5), math.floor(c.G * 255 + 0.5), math.floor(c.B * 255 + 0.5))
    end

    local function colorFromHex(text)
        local hex = tostring(text or ""):gsub("#", ""):gsub("%s+", "")
        if #hex == 3 then
            hex = hex:sub(1,1)..hex:sub(1,1)..hex:sub(2,2)..hex:sub(2,2)..hex:sub(3,3)..hex:sub(3,3)
        end
        if #hex ~= 6 or hex:find("[^%x]") then return nil end
        return Color3.fromRGB(tonumber(hex:sub(1, 2), 16), tonumber(hex:sub(3, 4), 16), tonumber(hex:sub(5, 6), 16))
    end

    local function selectedEspColorTarget()
        return Window.ElementRegistry["Target ESP Color"] and Window.ElementRegistry["Target ESP Color"].GetValue() or "PlayerESP"
    end

    local suppressEspHexUpdate = false
    local function setEspColorControls(c)
        if Window.ElementRegistry["ESP Red"] then Window.ElementRegistry["ESP Red"].SetValue(c.R * 255) end
        if Window.ElementRegistry["ESP Green"] then Window.ElementRegistry["ESP Green"].SetValue(c.G * 255) end
        if Window.ElementRegistry["ESP Blue"] then Window.ElementRegistry["ESP Blue"].SetValue(c.B * 255) end
        if Window.ElementRegistry["ESP Hex"] then
            suppressEspHexUpdate = true
            Window.ElementRegistry["ESP Hex"].SetValue(colorToHex(c))
            suppressEspHexUpdate = false
        end
    end

    ASTER.Options.updateColor = function()
        local target = selectedEspColorTarget()
        if target and Settings.ESPColors[target] then
            local r = Window.ElementRegistry["ESP Red"] and Window.ElementRegistry["ESP Red"].GetValue() or 255
            local g = Window.ElementRegistry["ESP Green"] and Window.ElementRegistry["ESP Green"].GetValue() or 255
            local b = Window.ElementRegistry["ESP Blue"] and Window.ElementRegistry["ESP Blue"].GetValue() or 255
            Settings.ESPColors[target] = Color3.fromRGB(r, g, b)
        end
    end

    ASTER.Tabs.Visuals:AddDropdown("Target ESP Color", ESP_COLOR_TARGETS, "PlayerESP", function(v)
        local c = Settings.ESPColors[v]
        if c then
            setEspColorControls(c)
        end
    end)
    ASTER.Tabs.Visuals:AddInput("ESP Hex", "#FF00FF", function(v)
        if suppressEspHexUpdate then return end
        local c = colorFromHex(v)
        local target = selectedEspColorTarget()
        if c and target and Settings.ESPColors[target] then
            Settings.ESPColors[target] = c
            setEspColorControls(c)
        end
    end)
    ASTER.Tabs.Visuals:AddDropdown("ESP Color Preset", {"Purple", "Pink", "Red", "Orange", "Yellow", "Green", "Cyan", "Blue", "White"}, "Pink", function(v)
        local c = ESP_COLOR_PRESETS[v]
        local target = selectedEspColorTarget()
        if c and target and Settings.ESPColors[target] then
            Settings.ESPColors[target] = c
            setEspColorControls(c)
        end
    end)
    -- Remove local variable 'initialColor' and use ASTER.Options.initialColor to save register
    ASTER.Options.initialColor = Settings.ESPColors["PlayerESP"]
    ASTER.Tabs.Visuals:AddSlider("ESP Red", 0, 255, math.floor(ASTER.Options.initialColor.R * 255), 1, ASTER.Options.updateColor)
    ASTER.Tabs.Visuals:AddSlider("ESP Green", 0, 255, math.floor(ASTER.Options.initialColor.G * 255), 1, ASTER.Options.updateColor)
    ASTER.Tabs.Visuals:AddSlider("ESP Blue", 0, 255, math.floor(ASTER.Options.initialColor.B * 255), 1, ASTER.Options.updateColor)
end -- AsterVisualsTabUI

do -- AsterVisualsPlayersUI
    ASTER.Tabs.Visuals:AddLabel("Players")
    ASTER.Tabs.Visuals:AddToggle("Player ESP", false, function(v)
