        Settings.AutoRespawnEnabled = v
        if v then startAutoRespawn() end
    end)

        ASTER.Tabs.Automation:AddToggle("Auto Rebirth", false, function(v)
        Settings.AutoRebirthEnabled = v
        if v then startAutoRebirth() end
    end)
    ASTER.Tabs.Automation:AddInput("Rebirth Level", "101", function(v)
        Settings.RebirthLevel = tonumber(v) or 100
    end)
    
    ASTER.Tabs.Automation:AddLabel("Auto buy Storate (USES MOJOS)")

    ASTER.Tabs.Automation:AddInput("Storage Amount", "1", function(v)
        Settings.StorageBuyAmount = tonumber(v) or 1
    end)

    ASTER.Tabs.Automation:AddButton("Buy Storage (Mojo)", function()
        local amt = Settings.StorageBuyAmount or 1
        local ByteNetReliable = game:GetService("ReplicatedStorage"):WaitForChild("ByteNetReliable")
        
        task.spawn(function()
            local pkt = resolvePacketId("PurchaseMojoItem", "PurchaseChest", "PurchaseFromShop")
            if not pkt then
                warn("Could not find a purchase packet id (PurchaseMojoItem/PurchaseChest/PurchaseFromShop) in PACKET_IDS.")
                return
            end

            local storageId
            if autoDiscoverItemID then
                -- Always prefer the exact name first.
                storageId = autoDiscoverItemID("Increase Storage")
                if not storageId then
                    for _, name in ipairs({ "Storage Upgrade", "Extra Storage", "Storage" }) do
                        storageId = autoDiscoverItemID(name)
                        if storageId then break end
                    end
                end
            end

            if not storageId then
                -- Fallback mojoItemId for "Increase Storage" (0x039D / 925).
                -- Packet id is resolved by name via getPacketId / PACKET_IDS.
                storageId = 0x039D
            end

            for i = 1, amt do
                -- Mojo purchase layout: [u8 0][u8 packetId][u16 mojoItemId]
                if storageId > 65535 then
                    warn(("Storage item id too large for mojo purchase u16: %s"):format(tostring(storageId)))
                    return
                end
                local b = buffer.create(4)
                buffer.writeu8(b, 0, 0)
                buffer.writeu8(b, 1, pkt)
                buffer.writeu16(b, 2, storageId)
                ByteNetReliable:FireServer(b)

                if i % 5 == 0 then task.wait(0.05) end
            end
        end)
    end)
    


    
end -- AsterRebirthTabUI


