        end
    end)

    -- Paste a config's JSON directly instead of picking a saved file. It gets saved
    -- (under Config Name if provided, else "Imported"), applied immediately, and
    -- added to the Select Config list so it persists.
    ASTER.Tabs.Config:AddInput("InputConfig", "", function(v)
        if not v or v == "" then return end
        local ok, decoded = pcall(function() return httpservice:JSONDecode(v) end)
        if not ok or type(decoded) ~= "table" then return end
        local name = Settings.ConfigName
        if not name or name == "" then name = "Imported" end
        if not isfolder(ASTER.ConfigFolder) then makefolder(ASTER.ConfigFolder) end
        writefile(ASTER.ConfigFolder .. "/" .. name .. ".json", v)
        ASTER.ConfigSystem.LoadConfig(name)
        Settings.SelectedConfig = name
        if ASTER.Options.ConfigDropdown then
            ASTER.Options.ConfigDropdown:SetValues(ASTER.ConfigSystem.GetConfigs())
