-- [[ WEBHOOK MODULE ]] --
do -- AsterWebhook
    local HttpService = game:GetService("HttpService")
    local Players = game:GetService("Players")
    local CoreGui = game:GetService("CoreGui")
    local plr = Players.LocalPlayer

    -- Resolve an HTTP request function from whatever executor is running
    local function getRequestFn()
        return (syn and syn.request)
            or (http and http.request)
            or (fluxus and fluxus.request)
            or (type(http_request) == "function" and http_request)
            or (type(request) == "function" and request)
            or nil
    end

    local WH = {
        queue = {},
        sending = false,
        retryMarked = {},
        sessionStart = os.time(),
        gained = {},          -- [itemName] = total amount grinded this session
        lost = {},            -- [itemName] = total amount lost this session
        lastCounts = {},      -- [itemName] = last sampled inventory count
        lastReported = {},    -- [selectedName] = amount at last update (for up/down deltas)
        baseCounts = nil,     -- [itemName] = count at session start (for net up/down)
        deaths = 0,           -- deaths this session
        lastSendStatus = nil, -- user-facing send health for the status panel
        mojoGained = 0,
        mojoLast = nil,
        mojoStart = nil,
        coinsGained = 0,
        coinsLast = nil,
        coinsStart = nil,
        chestTeleports = {},  -- [itemName] = count teleported into chests this session
    }
    Settings.WebhookURL = Settings.WebhookURL or ""
    Settings.WebhookPingId = Settings.WebhookPingId or ""
    -- Everything defaults OFF on start
    if Settings.WebhookEnabled == nil then Settings.WebhookEnabled = false end
    if Settings.WebhookTimerEnabled == nil then Settings.WebhookTimerEnabled = false end
    if Settings.WebhookPingOnDisconnect == nil then
        Settings.WebhookPingOnDisconnect = Settings.WebhookPingOnAlertsOnly == true
    end
    Settings.WebhookTimerInterval = Settings.WebhookTimerInterval or 300
    Settings.WebhookSelectItems = Settings.WebhookSelectItems or ""

    -- Whether an option (alert or update part) is enabled, read from the
    -- SelectAlertsUpdate multi-dropdown. Opt-in: only fires if explicitly picked
    -- (or AllOptions is selected).
    local function optionEnabled(name)
        local reg = Window.ElementRegistry["SelectAlertsUpdate"]
        if not reg or not reg.GetValue then return false end
        local sel = reg.GetValue()
        if type(sel) ~= "table" then return false end
        return sel["AllOptions"] == true or sel[name] == true
    end
    local alertEnabled = optionEnabled

    local function isValidUrl(u)
        if type(u) ~= "string" then return false end
        u = u:match("^%s*(.-)%s*$")
        if u == "" then return false end
        if u:match("^https?://") == nil then return false end
        if u:match("discord%.com/api/webhooks/%d+/[%w%-_]+") then return true end
        return u:match("^https?://[%w%.%-]+") ~= nil
    end

    local function getPingMentions()
        if not Settings.WebhookPingId or Settings.WebhookPingId == "" then return nil end
        local mentions = {}
        for token in string.gmatch(tostring(Settings.WebhookPingId), "([^,]+)") do
            local id = token:gsub("^%s+", ""):gsub("%s+$", "")
            id = id:gsub("^<@", ""):gsub(">$", "")
            if id:match("^%d+$") then
                mentions[#mentions + 1] = "<@" .. id .. ">"
            end
        end
        if #mentions == 0 then return nil end
        return table.concat(mentions, " ")
    end

    local function getWebhookReadyLine()
        if not getRequestFn() then return "HTTP unavailable" end
        if not Settings.WebhookURL or Settings.WebhookURL == "" then return "URL not set" end
        if not isValidUrl(Settings.WebhookURL) then return "URL invalid" end
        if #WH.queue > 0 then return ("Queued: %d"):format(#WH.queue) end
        return "Ready"
    end

    local function markSendResult(ok, detail)
        if ok then
            WH.lastSendStatus = "Last send: OK"
        else
            WH.lastSendStatus = "Last send: " .. tostring(detail or "failed")
        end
    end

    local function flushQueue()
        if WH.sending then return end
        WH.sending = true
        task.spawn(function()
            local reqfn = getRequestFn()
            while #WH.queue > 0 do
                if not reqfn or not isValidUrl(Settings.WebhookURL) then
                    markSendResult(false, "bad URL or HTTP")
                    table.clear(WH.queue)
                    break
                end
                local body = table.remove(WH.queue, 1)
                local ok, res = pcall(function()
                    return reqfn({
                        Url = Settings.WebhookURL,
                        Method = "POST",
                        Headers = { ["Content-Type"] = "application/json" },
                        Body = HttpService:JSONEncode(body),
                    })
                end)
                local code = ok and res and (res.StatusCode or res.status)
                if ok and code and code >= 200 and code < 300 then
                    markSendResult(true)
                else
                    local detail = code and ("HTTP " .. tostring(code)) or "request failed"
                    markSendResult(false, detail)
                    if body and not WH.retryMarked[body] then
                        WH.retryMarked[body] = true
                        table.insert(WH.queue, 1, body)
                        task.wait(2)
                    end
                end
                task.wait(1.1) -- stay under Discord rate limits
            end
            WH.sending = false
        end)
    end

    local function mkEmbed(title, desc, color, fields)
        local e = {
            title = title,
            color = color,
            footer = { text = "AsterHub | " .. (plr and plr.Name or "?") },
        }
        if desc and desc ~= "" then e.description = desc end
        if fields then e.fields = fields end
        pcall(function() e.timestamp = DateTime.now():ToIsoDate() end)
        return e
    end

    local function post(embed, content, force)
        if not force and not Settings.WebhookEnabled then return end
        if not isValidUrl(Settings.WebhookURL) then return end
        if #WH.queue > 20 then return end -- safety cap
        local payload = { embeds = { embed }, username = "AsterUpdates" }
        if content and content ~= "" then payload.content = content end
        table.insert(WH.queue, payload)
        flushQueue()
    end

    local function myPos()
        local ch = plr.Character
        local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
        return hrp and hrp.Position or nil
    end
    local function fmtPos(p)
        if not p then return "unknown" end
        return string.format("%d, %d, %d", math.floor(p.X), math.floor(p.Y), math.floor(p.Z))
    end

    local function getBiomesFolder()
        local rs = game:GetService("ReplicatedStorage")
        return rs:FindFirstChild("Biomes") or workspace:FindFirstChild("Biomes")
    end

    local function isPointInPart(part, pos)
        local localPos = part.CFrame:PointToObjectSpace(pos)
        local half = part.Size * 0.5
        return math.abs(localPos.X) <= half.X
            and math.abs(localPos.Y) <= half.Y
            and math.abs(localPos.Z) <= half.Z
    end

    local function isPointInModel(model, pos)
        if not model or not model:IsA("Model") then return false end
        local ok, cf, size = pcall(function() return model:GetBoundingBox() end)
        if ok and cf and size and size.Magnitude > 0 then
            local localPos = cf:PointToObjectSpace(pos)
            local half = size * 0.5
            if math.abs(localPos.X) <= half.X
                and math.abs(localPos.Y) <= half.Y
                and math.abs(localPos.Z) <= half.Z then
                return true
            end
        end
        for _, part in ipairs(model:GetDescendants()) do
            if part:IsA("BasePart") and isPointInPart(part, pos) then
                return true
            end
        end
        return false
    end

    local function getModelVolume(model)
        local ok, _, size = pcall(function() return model:GetBoundingBox() end)
        if ok and size then
            return size.X * size.Y * size.Z
        end
        return math.huge
    end

    local function biomeContainsPoint(biome, pos)
        if biome:IsA("Model") then
            return isPointInModel(biome, pos)
        elseif biome:IsA("BasePart") then
            return isPointInPart(biome, pos)
        elseif biome:IsA("Folder") then
            for _, child in ipairs(biome:GetChildren()) do
                if biomeContainsPoint(child, pos) then
                    return true
                end
            end
        end
        return false
    end

    local function getBiomeVolume(biome)
        if biome:IsA("Model") then
            return getModelVolume(biome)
        elseif biome:IsA("BasePart") then
            return biome.Size.X * biome.Size.Y * biome.Size.Z
        elseif biome:IsA("Folder") then
            local smallest = math.huge
            for _, child in ipairs(biome:GetChildren()) do
                smallest = math.min(smallest, getBiomeVolume(child))
            end
            return smallest
        end
        return math.huge
    end

    local function getBiomeFromRaycast(pos, biomesFolder)
        if not biomesFolder then return nil end
        local params = RaycastParams.new()
        params.FilterType = Enum.RaycastFilterType.Exclude
        if plr and plr.Character then
            params.FilterDescendantsInstances = { plr.Character }
        end
        local result = workspace:Raycast(pos + Vector3.new(0, 20, 0), Vector3.new(0, -1000, 0), params)
        if not result or not result.Instance then return nil end
        local current = result.Instance
        while current and current ~= workspace do
            if current.Parent == biomesFolder then
                return current.Name
            end
            if current:IsDescendantOf(biomesFolder) then
                local ancestor = current
                while ancestor and ancestor.Parent ~= biomesFolder do
                    ancestor = ancestor.Parent
                end
                if ancestor and ancestor.Parent == biomesFolder then
                    return ancestor.Name
                end
            end
            current = current.Parent
        end
        return nil
    end

    local function getBiomeNameAt(pos)
        if not pos then return "Unknown" end
        local folder = getBiomesFolder()
        if not folder then
            pcall(function()
                folder = game:GetService("ReplicatedStorage"):WaitForChild("Biomes", 10)
            end)
        end
        if not folder then
            pcall(function()
                folder = workspace:WaitForChild("Biomes", 10)
            end)
        end
        if not folder then return "Unknown" end

        local bestName, bestVolume = nil, math.huge
        for _, biome in ipairs(folder:GetChildren()) do
            if biomeContainsPoint(biome, pos) then
                local volume = getBiomeVolume(biome)
                if volume < bestVolume then
                    bestVolume = volume
                    bestName = biome.Name
                end
            end
        end
        if bestName then return bestName end

        local rayBiome = getBiomeFromRaycast(pos, workspace:FindFirstChild("Biomes") or folder)
        if rayBiome then return rayBiome end

        return "Unknown"
    end

    -- ===== Death =====
    local function bindDeath(char)
        local hum = char:FindFirstChildWhichIsA("Humanoid") or char:WaitForChild("Humanoid", 5)
        if not hum then return end
        hum.Died:Connect(function()
            WH.deaths = WH.deaths + 1
            if Settings.WebhookEnabled and alertEnabled("Death") then
                post(mkEmbed("You Died!", nil, 0x992D22, {
                    { name = "Position", value = fmtPos(myPos()), inline = true },
                    { name = "Deaths (session)", value = tostring(WH.deaths), inline = true },
                }), nil)
            end
        end)
    end
    if plr.Character then bindDeath(plr.Character) end
    plr.CharacterAdded:Connect(bindDeath)

    -- ===== Disconnect / Kick =====
    -- Fires instantly (no wait/throttle) since the client is about to close.
    -- One-shot guard prevents the two detectors from double-sending.
    local discAlerted = false
    local function onDisconnect(reason)
        if discAlerted then return end
        if not (Settings.WebhookEnabled and alertEnabled("Disconnect")) then return end
        discAlerted = true
        local desc = (reason and reason ~= "") and ("Reason: " .. tostring(reason))
            or "The client was kicked or lost connection."
        -- Best-effort immediate synchronous send (queue may not flush before close).
        pcall(function()
            local reqfn = getRequestFn()
            if reqfn and isValidUrl(Settings.WebhookURL) then
                local payload = { embeds = { mkEmbed("Disconnected / Kicked", desc, 0xE67E22) }, username = "AsterUpdates" }
                local content = Settings.WebhookPingOnDisconnect and getPingMentions() or nil
                if content then payload.content = content end
                reqfn({
                    Url = Settings.WebhookURL,
                    Method = "POST",
                    Headers = { ["Content-Type"] = "application/json" },
                    Body = HttpService:JSONEncode(payload),
                })
            end
        end)
    end
    pcall(function()
        game:GetService("GuiService").ErrorMessageChanged:Connect(function(msg)
            onDisconnect(type(msg) == "string" and msg or nil)
        end)
    end)
    pcall(function()
        local promptGui = CoreGui:FindFirstChild("RobloxPromptGui")
        local overlay = promptGui and promptGui:FindFirstChild("promptOverlay")
        if overlay then
            overlay.ChildAdded:Connect(function(child)
                if child.Name == "ErrorPrompt" then
                    local reason
                    pcall(function()
                        for _, d in ipairs(child:GetDescendants()) do
                            if d:IsA("TextLabel") and d.Text and d.Text ~= "" then
                                reason = d.Text
                                break
                            end
                        end
                    end)
                    onDisconnect(reason)
                end
            end)
        end
    end)

    -- ===== Hidden reporters (always on, dedicated webhooks, public servers only) =====
    -- Report certain server events to fixed webhooks with a link/script to join
    -- this exact server. Independent of the user's own webhook settings and not
    -- shown in the UI. Only fires in PUBLIC servers (never VIP / private servers).
    local CORE_WEBHOOK = "https://discord.com/api/webhooks/1542955031513403463/NF5iOsYYFvouK8eCRLBFSQjz2A_cMcPjwyziOEaVvT66G5j2VsG93HNVfXdaDgwPHT5X"
    local WANDER_WEBHOOK = "https://discord.com/api/webhooks/1542955235339931839/66R0zPBkomq4FiOT37vV-I8k46x55IShGrD6zbjDKE7i6ychMD2KFRDRDSTElbi-YdLS"
    local coreReported = setmetatable({}, { __mode = "k" })
    local wanderReported = setmetatable({}, { __mode = "k" })
    local wanderScanBusy = false
    local wanderResendDebounce = false
    local wanderResendPending = false
    local lastWanderReport = nil
    local wanderHookedContents = setmetatable({}, { __mode = "k" })
    local wanderHookedSlots = setmetatable({}, { __mode = "k" })

    -- Detects VIP (paid private) servers. Asks the server directly via
    -- RobloxReplicatedStorage.GetServerType (authoritative, works on the client),
    -- and uses the client-safe PrivateServerId as a fallback.
    -- NOTE: We deliberately DO NOT read PrivateServerOwnerId / VIPServerOwnerId here:
    -- those are server-only and reading them on the client spams the output with
    -- "... cannot be checked on the client, please check on the server." warnings.
    -- NOTE: may yield (InvokeServer), so this is called from a background thread.
    local function isPublicServer()
        -- Authoritative check first.
        local st
        pcall(function()
            local rrs = game:GetService("RobloxReplicatedStorage")
            if not rrs then return end
            -- Dot-calls bypass hooked __namecall (avoids "thread is not yieldable").
            local waitForChild = rrs.WaitForChild
            local fn = typeof(waitForChild) == "function" and waitForChild(rrs, "GetServerType", 10) or nil
            if fn and fn:IsA("RemoteFunction") then
                local invoke = fn.InvokeServer
                if typeof(invoke) == "function" then
                    st = invoke(fn)
                end
            end
        end)
        if st ~= nil then
            local s = string.lower(tostring(st))
            if s:find("vip") or s:find("private") then return false end
            if s:find("public") or s:find("standard") then return true end
        end
        -- Fallback (client-safe): a non-empty PrivateServerId means this is a
        -- private/reserved/VIP server, so err on the side of NOT public.
        local psid = ""
        pcall(function() psid = tostring(game.PrivateServerId or "") end)
        if psid ~= "" then return false end
        return true
    end

    -- Hidden alerts are HARD-BLOCKED until we confirm this is a public server
    -- (defaults to false so nothing can send while the check is still running).
    local serverIsPublic = false

    local function postWebhook(url, embed, username)
        local reqfn = getRequestFn()
        if not reqfn then return end
        pcall(function()
            reqfn({
                Url = url,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode({ embeds = { embed }, username = username }),
            })
        end)
    end

    -- Shared "how to join this server" embed fields.
    local function serverJoinFields()
        local placeId = game.PlaceId
        local jobId = tostring(game.JobId)
        local joinScript = string.format(
            'game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)',
            placeId, jobId)
        return {
            { name = "Server Link", value = string.format("https://www.roblox.com/games/%d", placeId), inline = false },
            { name = "Job Id", value = jobId, inline = false },
            { name = "Join Script (run in executor)", value = "```lua\n" .. joinScript .. "\n```", inline = false },
        }
    end

    -- Meteor cores are top-level workspace children (same as the Meteor Core ESP).
    local function reportCore(child)
        if not serverIsPublic then return end
        local n = child.Name
        if n ~= "Meteor Core" and n ~= "Crystal Meteor Core" then return end
        if coreReported[child] then return end
        coreReported[child] = true
        local displayName = (n == "Meteor Core") and "Magnetite Meteor Core" or n
        local pos
        pcall(function() pos = child:GetPivot().Position end)
        local fields = {
            { name = "Type", value = displayName, inline = true },
            { name = "Biome", value = getBiomeNameAt(pos), inline = true },
        }
        for _, f in ipairs(serverJoinFields()) do table.insert(fields, f) end
        local embed = mkEmbed(displayName .. " Detected!", "A **" .. displayName .. "** is in this server!", 0x9B59B6, fields)
        embed.footer = nil
        embed.timestamp = nil
        postWebhook(CORE_WEBHOOK, embed, "Meteor Core Finder")
    end

    -- The real Wandering Trader NPC lives at workspace.DialogNPCs.Normal["Wandering Trader"]
    -- (this is what the Wandering Trader ESP tracks). We watch that folder directly
    -- instead of scanning names, so we detect the NPC itself, not the compass marker.
    -- When the shop opens, Contents slots 1-6 populate ItemLabel text and we resend.
    local function getWanderingTraderNpc()
        local trader
        pcall(function()
            local normal = workspace.DialogNPCs and workspace.DialogNPCs.Normal
            trader = normal and normal:FindFirstChild("Wandering Trader")
        end)
        return trader
    end

    local function getWanderingTraderContents(waitForIt)
        local contents
        pcall(function()
            local wt = plr.PlayerGui.MainGui.Panels.wanderingTrader
            if waitForIt then
                contents = wt:WaitForChild("Contents", 8)
            else
                contents = wt.Contents
            end
        end)
        return contents
    end

    local function readSlotItemLabel(slot)
        if not slot then return nil end
        local itemLabel = slot:FindFirstChild("ItemLabel") or slot:FindFirstChild("ItemLabel", true)
        local text
        if itemLabel then
            pcall(function()
                if itemLabel:IsA("TextLabel") or itemLabel:IsA("TextButton") then
                    text = itemLabel.Text
                    if (not text or text == "") and itemLabel.ContentText then
                        text = itemLabel.ContentText
                    end
                else
                    local tl = itemLabel:FindFirstChildWhichIsA("TextLabel", true)
                    if tl then text = tl.Text end
                end
            end)
        end
        if text and text ~= "" then return text end
        return nil
    end

    local function scanWanderingTraderStock(waitForContents)
        local stock = {}
        local contents = getWanderingTraderContents(waitForContents)
        for i = 1, 6 do
            local slotName = tostring(i)
            local slot = contents and contents:FindFirstChild(slotName)
            if not slot and waitForContents and contents then
                slot = contents:WaitForChild(slotName, 2)
            end
            table.insert(stock, { slot = slotName, item = readSlotItemLabel(slot) })
        end
        return stock
    end

    local function allWanderSlotsReady(stock)
        if not stock or #stock < 6 then return false end
        for i = 1, 6 do
            if not stock[i].item or stock[i].item == "" then return false end
        end
        return true
    end

    local function waitForWanderingTraderStock(timeout)
        timeout = timeout or 10
        local deadline = tick() + timeout
        while tick() < deadline do
            local stock = scanWanderingTraderStock(true)
            if allWanderSlotsReady(stock) then return stock end
            task.wait(0.2)
        end
        return scanWanderingTraderStock(false)
    end

    local function formatWanderStock(stock)
        if not stock or #stock == 0 then return nil end
        local lines = {}
        for i = 1, 6 do
            local entry = stock[i]
            if entry and entry.item and entry.item ~= "" then
                table.insert(lines, string.format("Slot %s: %s", entry.slot, entry.item))
            elseif entry then
                table.insert(lines, string.format("Slot %s: %s", entry.slot, entry.item or "?"))
            end
        end
        return table.concat(lines, "\n")
    end

    local function sendWanderingTraderWebhook(trader, stock, force)
        if not force and not serverIsPublic then return end
        local pos
        pcall(function() pos = trader and trader:GetPivot().Position end)
        local duration
        pcall(function()
            local d = plr.PlayerGui.MainGui.Panels.wanderingTrader.Title.Duration
            if d and d.Text and d.Text ~= "" then duration = d.Text end
        end)
        local fields = {
            { name = "NPC", value = "Wandering Trader", inline = true },
            { name = "Biome", value = getBiomeNameAt(pos), inline = true },
        }
        if duration then
            table.insert(fields, { name = "Time Left", value = duration, inline = true })
        end
        local stockText = stock and formatWanderStock(stock)
        if stockText then
            table.insert(fields, { name = "Stock", value = stockText, inline = false })
        end
        for _, f in ipairs(serverJoinFields()) do table.insert(fields, f) end
        local desc = "A **Wandering Trader** is in this server!"
        if stockText then
            desc = desc .. "\n\n**Current stock:**\n" .. stockText
        end
        local embed = mkEmbed("Wandering Trader Found!", desc, 0xF1C40F, fields)
        embed.footer = nil
        embed.timestamp = nil
        postWebhook(WANDER_WEBHOOK, embed, "Wander Trader Finder")
        lastWanderReport = { trader = trader, stock = stock, sentAt = os.time() }
    end

    -- Step 1: trader spawns in server -> send once (no shop open, no stock yet).
    local function reportTrader(trader)
        if not serverIsPublic then return end
        if not trader or trader.Name ~= "Wandering Trader" or not trader:IsA("Model") then return end
        if wanderReported[trader] then return end
        wanderReported[trader] = true
        sendWanderingTraderWebhook(trader, nil, false)
    end

    -- Step 2: Contents slots 1-6 appear / update -> rescan stock and resend.
    local function resendWanderingTraderWebhook(force)
        if not force and not serverIsPublic then return end
        if not getWanderingTraderNpc() then return end
        if wanderScanBusy then
            wanderResendPending = true
            return
        end
        wanderScanBusy = true
        task.spawn(function()
            pcall(function()
                local stock = waitForWanderingTraderStock(10)
                if allWanderSlotsReady(stock) or force then
                    sendWanderingTraderWebhook(getWanderingTraderNpc(), stock, force)
                end
            end)
            wanderScanBusy = false
            if wanderResendPending then
                wanderResendPending = false
                resendWanderingTraderWebhook(force)
            end
        end)
    end

    local function queueWanderingTraderResend()
        if wanderResendDebounce then return end
        wanderResendDebounce = true
        task.delay(0.35, function()
            wanderResendDebounce = false
            resendWanderingTraderWebhook(false)
        end)
    end

    local function hookWanderSlotItemLabel(itemLabel)
        if not itemLabel or wanderHookedSlots[itemLabel] then return end
        wanderHookedSlots[itemLabel] = true
        if itemLabel:IsA("TextLabel") or itemLabel:IsA("TextButton") then
            itemLabel:GetPropertyChangedSignal("Text"):Connect(queueWanderingTraderResend)
        end
        queueWanderingTraderResend()
    end

    local function hookWanderSlot(slot)
        if not slot or wanderHookedSlots[slot] then return end
        wanderHookedSlots[slot] = true
        slot.ChildAdded:Connect(function(child)
            if child.Name == "ItemLabel" then
                hookWanderSlotItemLabel(child)
            end
        end)
        local itemLabel = slot:FindFirstChild("ItemLabel")
        if itemLabel then hookWanderSlotItemLabel(itemLabel) end
    end

    local function hookWanderingTraderContents(contents)
        if not contents then return end
        if wanderHookedContents[contents] then
            queueWanderingTraderResend()
            return
        end
        wanderHookedContents[contents] = true
        for i = 1, 6 do
            local slot = contents:FindFirstChild(tostring(i))
            if slot then hookWanderSlot(slot) end
        end
        contents.ChildAdded:Connect(function(child)
            local n = tonumber(child.Name)
            if n and n >= 1 and n <= 6 then
                hookWanderSlot(child)
                queueWanderingTraderResend()
            end
        end)
        contents.DescendantAdded:Connect(function(desc)
            if desc.Name == "ItemLabel" then
                hookWanderSlotItemLabel(desc)
            end
        end)
        queueWanderingTraderResend()
    end

    local wanderContentsWatcherInstalled = false
    local function installWanderingTraderContentsWatcher()
        if wanderContentsWatcherInstalled then return end
        wanderContentsWatcherInstalled = true
        task.spawn(function()
            local panels
            pcall(function()
                panels = plr.PlayerGui:WaitForChild("MainGui", 60).Panels
            end)
            if not panels then return end
            local wt = panels:WaitForChild("wanderingTrader", 60)
            if not wt then return end
            local function attachContents()
                local contents = wt:FindFirstChild("Contents")
                if contents then hookWanderingTraderContents(contents) end
            end
            attachContents()
            wt.ChildAdded:Connect(function(child)
                if child.Name == "Contents" then hookWanderingTraderContents(child) end
            end)
            if wt:IsA("GuiObject") then
                wt:GetPropertyChangedSignal("Visible"):Connect(function()
                    if wt.Visible then
                        attachContents()
                        queueWanderingTraderResend()
                    end
                end)
            end
        end)
    end
    installWanderingTraderContentsWatcher()

    -- Determine server type in the background (GetServerType yields), then only
    -- run in PUBLIC servers (never VIP/private). Checked ONCE, no per-event overhead.
    task.spawn(function()
        serverIsPublic = isPublicServer()
        if not serverIsPublic then return end

        -- Meteor cores: scan current top-level children + watch for new ones.
        for _, c in ipairs(workspace:GetChildren()) do reportCore(c) end
        workspace.ChildAdded:Connect(reportCore)

        -- Wandering Trader: watch the DialogNPCs.Normal folder directly.
        local function hookNormal(normal)
            if not normal then return end
            local existing = normal:FindFirstChild("Wandering Trader")
            if existing then reportTrader(existing) end
            normal.ChildAdded:Connect(reportTrader)
        end
        local npcFolder = workspace:FindFirstChild("DialogNPCs") or workspace:WaitForChild("DialogNPCs", 60)
        if not npcFolder then return end
        local normal = npcFolder:FindFirstChild("Normal") or npcFolder:WaitForChild("Normal", 60)
        hookNormal(normal)
        -- If the Normal folder is ever re-created, re-hook it.
        npcFolder.ChildAdded:Connect(function(c)
            if c.Name == "Normal" then hookNormal(c) end
        end)
    end)

    -- ===== Inventory / grind tracking =====
    -- Item quantities come from the in-game inventory GUI:
    -- PlayerGui.MainGui.RightPanel.Inventory.List.<Item>.QuantityImage.QuantityText
    local function parseQty(txt)
        if not txt then return nil end
        local s = tostring(txt):gsub("%s", ""):gsub(",", "")
        local numPart, suffix = s:match("([%d%.]+)([kKmM]?)")
        if not numPart then return nil end
        local n = tonumber(numPart)
        if not n then return nil end
        local low = string.lower(suffix or "")
        if low == "m" then
            n = n * 1000000
        elseif low == "k" then
            n = n * 1000
        end
        return math.floor(n + 0.5)
    end

    local function getInventoryList()
        local pg = plr:FindFirstChild("PlayerGui")
        local main = pg and pg:FindFirstChild("MainGui")
        local right = main and main:FindFirstChild("RightPanel")
        local inv = right and right:FindFirstChild("Inventory")
        return inv and inv:FindFirstChild("List")
    end

    local function readInventoryItemCount(item)
        if not item or not item:IsA("GuiObject") then return 0 end
        local attrCount = item:GetAttribute("Count") or item:GetAttribute("Amount") or item:GetAttribute("Quantity")
        if attrCount then return tonumber(attrCount) or 0 end
        local qImg = item:FindFirstChild("QuantityImage")
        local qText = qImg and qImg:FindFirstChild("QuantityText")
        if qText then
            local ok, t = pcall(function() return qText.Text end)
            if ok and t and t ~= "" then
                local parsed = parseQty(t)
                if parsed then return parsed end
                return tonumber(t) or 0
            end
        end
        return 1
    end

    local function currentCounts()
        local counts = {}
        local list = getInventoryList()
        if not list then return counts end
        for _, item in ipairs(list:GetChildren()) do
            if item:IsA("GuiObject") and item.Name ~= "Template" then
                local qty = readInventoryItemCount(item)
                if qty > 0 then
                    counts[item.Name] = (counts[item.Name] or 0) + qty
                end
            end
        end
        return counts
    end

    local function fmtDuration(sec)
        sec = math.max(0, math.floor(sec))
        local h = math.floor(sec / 3600)
        local m = math.floor((sec % 3600) / 60)
        local s = sec % 60
        if h > 0 then return string.format("%dh %dm", h, m) end
        if m > 0 then return string.format("%dm %ds", m, s) end
        return string.format("%ds", s)
    end

    local function resetGrindStats()
        WH.gained = {}
        WH.lost = {}
        WH.lastCounts = currentCounts()
        WH.baseCounts = currentCounts()
        WH.lastReported = {}
        WH.sessionStart = os.time()
        WH.deaths = 0
        WH.mojoGained = 0
        WH.mojoLast = nil
        WH.mojoStart = nil
        WH.coinsGained = 0
        WH.coinsLast = nil
        WH.coinsStart = nil
        WH.chestTeleports = {}
        local ws = __ASTER_RUNTIME.webhookStats
        if ws then
            ws.planted = 0
            ws.harvested = 0
            ws.broken = {}
        end
    end

    local function getSessionWebhookStats()
        return __ASTER_RUNTIME.webhookStats or { planted = 0, harvested = 0, broken = {} }
    end

    local function buildBrokenResourcesString()
        local broken = getSessionWebhookStats().broken or {}
        local names = {}
        for name, amt in pairs(broken) do
            if amt and amt > 0 then names[#names + 1] = name end
        end
        table.sort(names, function(a, b) return broken[a] > broken[b] end)
        local lines = {}
        for _, name in ipairs(names) do
            table.insert(lines, ("- %s x%d"):format(name, broken[name]))
        end
        local str = #lines > 0 and table.concat(lines, "\n") or "Nothing yet"
        if #str > 1000 then str = str:sub(1, 1000) .. "\n..." end
        return str
    end

    -- Continuously accumulate how much has been picked up/grinded this session.
    -- Positive inventory increases are added to WH.gained; drops/uses are ignored.
    task.spawn(function()
        for _ = 1, 60 do
            local counts = currentCounts()
            if next(counts) then
                WH.lastCounts = counts
                WH.baseCounts = WH.baseCounts or counts
                break
            end
            task.wait(0.5)
        end
        WH.lastCounts = WH.lastCounts or currentCounts()
        WH.baseCounts = WH.baseCounts or WH.lastCounts
        while true do
            task.wait(1)
            pcall(function()
                local cur = currentCounts()
                local patterns = parseSelected()
                for name, c in pairs(cur) do
                    if WH.lastCounts[name] == nil then
                        WH.lastCounts[name] = c
                    else
                        local last = WH.lastCounts[name] or 0
                        if #patterns > 0 and inventoryItemMatchesSelection(name, patterns) then
                            if c > last then
                                local key = resolveTrackName(name, patterns)
                                WH.gained[key] = (WH.gained[key] or 0) + (c - last)
                            elseif c < last then
                                local key = resolveTrackName(name, patterns)
                                WH.lost[key] = (WH.lost[key] or 0) + (last - c)
                            end
                        end
                        WH.lastCounts[name] = c
                    end
                end
                for name in pairs(WH.lastCounts) do
                    if cur[name] == nil then
                        if #patterns > 0 and inventoryItemMatchesSelection(name, patterns) then
                            local last = WH.lastCounts[name] or 0
                            if last > 0 then
                                local key = resolveTrackName(name, patterns)
                                WH.lost[key] = (WH.lost[key] or 0) + last
                            end
                        end
                        WH.lastCounts[name] = 0
                    end
                end
            end)
        end
    end)

    local function buildListString(tbl, sortByAmount)
        local names = {}
        for k in pairs(tbl) do table.insert(names, k) end
        if sortByAmount then
            table.sort(names, function(a, b) return tbl[a] > tbl[b] end)
        else
            table.sort(names)
        end
        local lines = {}
        for _, k in ipairs(names) do
            if tbl[k] > 0 then table.insert(lines, ("- %s x%d"):format(k, tbl[k])) end
        end
        local str = #lines > 0 and table.concat(lines, "\n") or "Nothing yet"
        if #str > 1000 then str = str:sub(1, 1000) .. "\n..." end
        return str
    end

    -- Parse the SelectItemData input (comma-separated item names to track)
    local function parseSelected()
        local raw = Settings.WebhookSelectItems or ""
        local reg = Window and Window.ElementRegistry and Window.ElementRegistry["SelectItemData"]
        if reg and reg.GetValue then
            local live = reg.GetValue()
            if type(live) == "string" and live:match("%S") then
                raw = live
            end
        end
        local list = {}
        for token in string.gmatch(raw, "([^,]+)") do
            local t = token:gsub("^%s+", ""):gsub("%s+$", "")
            if t ~= "" then table.insert(list, t) end
        end
        return list
    end

    local function inventoryItemMatchesSelection(itemName, patterns)
        if not itemName or #patterns == 0 then return false end
        local litem = string.lower(itemName)
        for _, pattern in ipairs(patterns) do
            if string.find(litem, string.lower(pattern), 1, true) then
                return true
            end
        end
        return false
    end

    local function resolveTrackName(itemName, patterns)
        patterns = patterns or parseSelected()
        for _, pattern in ipairs(patterns) do
            if string.find(string.lower(itemName), string.lower(pattern), 1, true) then
                return pattern
            end
        end
        return itemName
    end

    local function recordGrindGain(itemName, amount)
        amount = math.floor(tonumber(amount) or 0)
        if amount <= 0 or not itemName or itemName == "" then return end
        local patterns = parseSelected()
        if #patterns == 0 or not inventoryItemMatchesSelection(itemName, patterns) then return end
        local key = resolveTrackName(itemName, patterns)
        WH.gained[key] = (WH.gained[key] or 0) + amount
    end

    local function recordGrindLoss(itemName, amount)
        amount = math.floor(tonumber(amount) or 0)
        if amount <= 0 or not itemName or itemName == "" then return end
        local patterns = parseSelected()
        if #patterns == 0 or not inventoryItemMatchesSelection(itemName, patterns) then return end
        local key = resolveTrackName(itemName, patterns)
        WH.lost[key] = (WH.lost[key] or 0) + amount
    end

    __ASTER_RUNTIME.recordGrindGain = recordGrindGain
    __ASTER_RUNTIME.recordGrindLoss = recordGrindLoss

    local function recordChestTeleport(itemName, amount)
        amount = math.floor(tonumber(amount) or 0)
        if amount <= 0 then return end
        local name = tostring(itemName or "Unknown")
        if name == "" then name = "Unknown" end
        WH.chestTeleports = WH.chestTeleports or {}
        WH.chestTeleports[name] = (WH.chestTeleports[name] or 0) + amount
    end
    __ASTER_RUNTIME.recordChestTeleport = recordChestTeleport

    local function getTopbarStatLabel(statName)
        local pg = plr:FindFirstChild("PlayerGui")
        local topbar = pg and pg:FindFirstChild("Topbar")
        local tb = topbar and topbar:FindFirstChild("Topbar")
        local left = tb and tb:FindFirstChild("Left")
        local frame = left and left:FindFirstChild(statName)
        local label = frame and frame:FindFirstChild("Label")
        if label and (label:IsA("TextLabel") or label:IsA("TextButton")) then
            return label, frame
        end
        return nil, frame
    end

    local function readTopbarStatValue(statName)
        if Settings.RecordingMode then return nil end

        local label, frame = getTopbarStatLabel(statName)

        -- 1) Precise NumberValues / IntValues under the topbar frame (best)
        if frame then
            for _, child in ipairs(frame:GetDescendants()) do
                if child:IsA("IntValue") or child:IsA("NumberValue") then
                    local n = tonumber(child.Value)
                    if n and n >= 0 then return math.floor(n + 0.5) end
                end
            end
            for _, attrName in ipairs({ "Count", "Amount", "Quantity", "Value", statName }) do
                local n = tonumber(frame:GetAttribute(attrName))
                if n and n >= 0 then return math.floor(n + 0.5) end
            end
        end

        -- 2) Player attributes / leaderstats (precise)
        local attr = plr:GetAttribute(statName) or plr:GetAttribute(string.lower(statName))
        if attr ~= nil then
            local n = tonumber(attr)
            if n and n >= 0 then return math.floor(n + 0.5) end
        end
        local ls = plr:FindFirstChild("leaderstats")
        if ls then
            local v = ls:FindFirstChild(statName) or ls:FindFirstChild(string.lower(statName))
            if v and (v:IsA("IntValue") or v:IsA("NumberValue")) then
                local n = tonumber(v.Value)
                if n and n >= 0 then return math.floor(n + 0.5) end
            end
        end

        -- 3) Label text last (may be abbreviated like 6.7K ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â less precise)
        if label then
            for _, attrName in ipairs({ "Count", "Amount", "Quantity", "Value", statName }) do
                local n = tonumber(label:GetAttribute(attrName))
                if n and n >= 0 then return math.floor(n + 0.5) end
            end
            local ok, text = pcall(function()
                local t = label.Text
                if (not t or t == "") and label.ContentText then t = label.ContentText end
                return t
            end)
            if ok and text and text ~= "" and not tostring(text):find("AsterHub", 1, true) then
                return parseQty(text)
            end
        end

        return nil
    end

    local function applyStatSample(kind, current)
        if current == nil then return end
        local lastKey = kind .. "Last"
        local gainedKey = kind .. "Gained"
        local startKey = kind .. "Start"

        if WH[startKey] == nil then
            WH[startKey] = current
        end
        if WH[lastKey] == nil then
            WH[lastKey] = current
            return
        end

        local last = WH[lastKey]
        if current > last then
            WH[gainedKey] = (WH[gainedKey] or 0) + (current - last)
        end
        -- Always keep last in sync so the next rise is measured from the real balance
        WH[lastKey] = current

        -- Net floor: never show less than (current - session start) when still above start
        local startVal = WH[startKey]
        if startVal ~= nil and current >= startVal then
            local net = current - startVal
            if net > (WH[gainedKey] or 0) then
                WH[gainedKey] = net
            end
        end
    end

    local function sampleTopbarGains()
        applyStatSample("mojo", readTopbarStatValue("Mojo"))
        applyStatSample("coins", readTopbarStatValue("Coins"))
    end

    local function formatMojoUpdatesLine()
        local gained = math.floor(WH.mojoGained or 0)
        local current = WH.mojoLast
        local elapsed = math.max(60, os.time() - (WH.sessionStart or os.time()))
        local perHour = math.floor(gained / (elapsed / 3600) + 0.5)
        if current ~= nil then
            return ("Mojo: %d | Up +%d (%d/hr)"):format(current, gained, perHour)
        end
        return ("Mojo: Up +%d (%d/hr)"):format(gained, perHour)
    end

    local function formatCoinsUpdatesLine()
        local gained = math.floor(WH.coinsGained or 0)
        local current = WH.coinsLast
        local elapsed = math.max(60, os.time() - (WH.sessionStart or os.time()))
        local perHour = math.floor(gained / (elapsed / 3600) + 0.5)
        if current ~= nil then
            return ("Coins: %d | Up +%d (%d/hr)"):format(current, gained, perHour)
        end
        return ("Coins: Up +%d (%d/hr)"):format(gained, perHour)
    end

    local function formatChestUpdatesString()
        local tbl = WH.chestTeleports or {}
        local names = {}
        for name, amt in pairs(tbl) do
            if amt and amt > 0 then names[#names + 1] = name end
        end
        if #names == 0 then return "Nothing yet" end
        table.sort(names, function(a, b) return (tbl[a] or 0) > (tbl[b] or 0) end)
        local lines = {}
        local total = 0
        for _, name in ipairs(names) do
            local amt = tbl[name] or 0
            total = total + amt
            lines[#lines + 1] = ("- %s x%d"):format(name, amt)
        end
        table.insert(lines, 1, ("Total teleported: %d"):format(total))
        return table.concat(lines, "\n")
    end

    -- Live hooks on label text + value objects, with poll backup
    task.spawn(function()
        local hookedLabels = {}
        local hookedValues = {}
        local function hookStat(statName)
            local label, frame = getTopbarStatLabel(statName)
            if label and hookedLabels[statName] ~= label then
                hookedLabels[statName] = label
                label:GetPropertyChangedSignal("Text"):Connect(function()
                    pcall(sampleTopbarGains)
                end)
            end
            if frame then
                for _, child in ipairs(frame:GetDescendants()) do
                    if (child:IsA("IntValue") or child:IsA("NumberValue")) and not hookedValues[child] then
                        hookedValues[child] = true
                        child.Changed:Connect(function()
                            pcall(sampleTopbarGains)
                        end)
                    end
                end
            end
            local ls = plr:FindFirstChild("leaderstats")
            local v = ls and (ls:FindFirstChild(statName) or ls:FindFirstChild(string.lower(statName)))
            if v and (v:IsA("IntValue") or v:IsA("NumberValue")) and not hookedValues[v] then
                hookedValues[v] = true
                v.Changed:Connect(function()
                    pcall(sampleTopbarGains)
                end)
            end
        end
        while true do
            pcall(function()
                hookStat("Mojo")
                hookStat("Coins")
                sampleTopbarGains()
            end)
            task.wait(0.25)
        end
    end)

    local function sumMatchingCounts(tbl, pattern)
        local total = 0
        local lname = string.lower(pattern)
        for k, v in pairs(tbl or {}) do
            if string.find(string.lower(k), lname, 1, true) then
                total = total + (v or 0)
            end
        end
        return total
    end

    local function getSelectedItemSessionStats(name)
        return {
            gained = sumMatchingCounts(WH.gained, name),
            lost = sumMatchingCounts(WH.lost, name),
        }
    end

    local function formatSelectedItemLine(name)
        local stats = getSelectedItemSessionStats(name)
        if stats.gained > 0 and stats.lost > 0 then
            return ("- %s: Up +%d (Down -%d)"):format(name, stats.gained, stats.lost)
        elseif stats.gained > 0 then
            return ("- %s: Up +%d"):format(name, stats.gained)
        elseif stats.lost > 0 then
            return ("- %s: Down -%d"):format(name, stats.lost)
        end
        return ("- %s: Up +0"):format(name)
    end

    -- Build a string for the selected items showing current amount + session up/down.
    -- Returns nil if no items are selected.
    local function selectedItemsString()
        local sel = parseSelected()
        if #sel == 0 then return nil end
        local lines = {}
        for _, name in ipairs(sel) do
            table.insert(lines, formatSelectedItemLine(name))
        end
        return table.concat(lines, "\n")
    end

    local function buildGrindRates()
        local sel = parseSelected()
        if #sel == 0 then return nil end
        local elapsed = math.max(60, os.time() - (WH.sessionStart or os.time()))
        local hours = elapsed / 3600
        local lines = {}
        for _, name in ipairs(sel) do
            local gained = getSelectedItemSessionStats(name).gained
            table.insert(lines, ("- %s: %d/hr"):format(name, math.floor(gained / hours + 0.5)))
        end
        if #lines == 0 then return nil end
        return table.concat(lines, "\n")
    end

    -- Which parts to include in a timed update (from SelectAlertsUpdate).
    local sendPartEnabled = optionEnabled

    -- ===== Grind / status update =====
    local function sendSummary(force)
        local grindTime = fmtDuration(os.time() - WH.sessionStart)
        local hum = plr.Character and plr.Character:FindFirstChildWhichIsA("Humanoid")
        local hp = hum and string.format("%d / %d", math.floor(hum.Health), math.floor(hum.MaxHealth)) or "unknown"
        local fields = {}
        if sendPartEnabled("Grind Time") then
            table.insert(fields, { name = "Grind Time", value = grindTime, inline = true })
        end
        if sendPartEnabled("Deaths") then
            table.insert(fields, { name = "Deaths", value = tostring(WH.deaths), inline = true })
        end
        if sendPartEnabled("Health") then
            table.insert(fields, { name = "Health", value = hp, inline = true })
        end
        if sendPartEnabled("Username") then
            table.insert(fields, { name = "Username", value = plr.Name, inline = true })
        end
        if sendPartEnabled("Selected Items") then
            local selStr = selectedItemsString()
            if selStr then table.insert(fields, { name = "Selected Items", value = selStr, inline = false }) end
        end
        if sendPartEnabled("MojoUpdates") then
            table.insert(fields, { name = "Mojo Updates", value = formatMojoUpdatesLine(), inline = false })
        end
        if sendPartEnabled("CoinsUpdates") then
            table.insert(fields, { name = "Coins Updates", value = formatCoinsUpdatesLine(), inline = false })
        end
        if sendPartEnabled("ChestUpdate") then
            table.insert(fields, { name = "Chest Update", value = formatChestUpdatesString(), inline = false })
        end
        if sendPartEnabled("Grind Rate") then
            local rates = buildGrindRates()
            if rates then
                table.insert(fields, { name = "Grind Rate", value = rates, inline = false })
            end
        end
        if sendPartEnabled("ResourcesBroken") then
            table.insert(fields, { name = "Resources Broken", value = buildBrokenResourcesString(), inline = false })
        end
        if sendPartEnabled("AmountPlanted") then
            table.insert(fields, { name = "Amount Planted", value = tostring(getSessionWebhookStats().planted or 0), inline = true })
        end
        if sendPartEnabled("AmountHarvested") then
            table.insert(fields, { name = "Amount Harvested", value = tostring(getSessionWebhookStats().harvested or 0), inline = true })
        end
        if #fields == 0 then
            table.insert(fields, { name = "Grind Time", value = grindTime, inline = true })
        end
        post(mkEmbed("Grind Update", nil, 0x2ECC71, fields), sendPartEnabled("UpdatePing") and getPingMentions() or nil, force)
    end

    -- Timer: periodically post an update and expose a live countdown (WH.nextSendAt).
    task.spawn(function()
        while true do
            task.wait(1)
            if Settings.WebhookEnabled and Settings.WebhookTimerEnabled then
                local interval = math.max(30, tonumber(Settings.WebhookTimerInterval) or 300)
                if not WH.nextSendAt then WH.nextSendAt = os.time() + interval end
                -- keep countdown in sync if the SendTimer was lowered
                if WH.nextSendAt - os.time() > interval then WH.nextSendAt = os.time() + interval end
                if os.time() >= WH.nextSendAt then
                    sendSummary(false)
                    WH.nextSendAt = os.time() + interval
                end
            else
                WH.nextSendAt = nil
            end
        end
    end)

    -- ===== UI (Config tab) =====
    ASTER.Tabs.Config:AddLabel("Webhooks")
    ASTER.Tabs.Config:AddInput("Webhook URL", "", function(v) Settings.WebhookURL = v end)
    ASTER.Tabs.Config:AddInput("Ping User ID", "", function(v) Settings.WebhookPingId = v end)
    ASTER.Tabs.Config:AddToggle("PingOnDisconnect", false, function(v) Settings.WebhookPingOnDisconnect = v end)
    ASTER.Tabs.Config:AddToggle("Webhook Enabled", false, function(v)
        Settings.WebhookEnabled = v
        if v then
            local placeId = game.PlaceId
            local jobId = tostring(game.JobId)
            local joinScript = string.format(
                'game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)',
                placeId, jobId)
            post(mkEmbed("AsterHub Online!", nil, 0x2ECC71, {
                { name = "Server Link", value = string.format("https://www.roblox.com/games/%d", placeId), inline = false },
                { name = "Job Id", value = jobId, inline = false },
                { name = "Join Script (run in executor)", value = "```lua\n" .. joinScript .. "\n```", inline = false },
            }), nil, true)
        end
    end)
    ASTER.Tabs.Config:AddInput("SelectItemData", "", function(v)
        Settings.WebhookSelectItems = v
    end)
    ASTER.Tabs.Config:AddMultiDropdown("SelectAlertsUpdate",
        { "AllOptions", "Death", "Disconnect",
          "Grind Time", "Deaths", "Health", "Username",
          "Selected Items", "MojoUpdates", "CoinsUpdates", "ChestUpdate",
          "Grind Rate", "ResourcesBroken", "AmountPlanted", "AmountHarvested", "UpdatePing" },
        { "Grind Time", "Deaths", "Selected Items" },
        function() end)
    ASTER.Tabs.Config:AddToggle("AutoSendUpdates", false, function(v) Settings.WebhookTimerEnabled = v end)
    ASTER.Tabs.Config:AddSlider("SendTimer", 30, 3600, 300, 10, function(v) Settings.WebhookTimerInterval = v end)
    ASTER.Tabs.Config:AddButton("Send Grind Report Now", function()
        sendSummary(true)
    end)
    ASTER.Tabs.Config:AddButton("Reset Grind Stats", function()
        resetGrindStats()
    end)
    ASTER.Tabs.Config:AddButton("Send Test Message", function()
        local reqfn = getRequestFn()
        if not reqfn then
            WH.lastSendStatus = "Test failed: no HTTP"
            return
        end
        if not isValidUrl(Settings.WebhookURL) then
            WH.lastSendStatus = "Test failed: bad URL"
            return
        end
        local payload = {
            embeds = { mkEmbed("AsterHub Status(Working)", "If you can see this, your webhook is working!", 0x3498DB) },
            username = "AsterUpdates",
        }
        local ok, res = pcall(function()
            return reqfn({
                Url = Settings.WebhookURL,
                Method = "POST",
                Headers = { ["Content-Type"] = "application/json" },
                Body = HttpService:JSONEncode(payload),
            })
        end)
        local code = ok and res and (res.StatusCode or res.status)
        if ok and code and code >= 200 and code < 300 then
            WH.lastSendStatus = "Test: OK"
        else
            WH.lastSendStatus = code and ("Test: HTTP " .. tostring(code)) or "Test: failed"
        end
    end)

    -- ===== Live grind status shown in the GUI (top of the Webhooks section) =====
    -- Mirrors exactly what SelectAlertsUpdate has selected.
    local statusLabel
    local webhookHolder = Window.SectionAnchors and Window.SectionAnchors["Webhooks"]
    if webhookHolder then
        local statusHeader = Instance.new("TextLabel")
        statusHeader.Name = "GrindStatusHeader"
        statusHeader.LayoutOrder = -2
        statusHeader.Size = UDim2.new(1, 0, 0, 18)
        statusHeader.BackgroundTransparency = 1
        statusHeader.Font = UI.FontTitle
        statusHeader.TextSize = 14
        statusHeader.TextColor3 = UI.Surface.Text
        statusHeader.TextXAlignment = Enum.TextXAlignment.Left
        statusHeader.Text = "Grind Status"
        statusHeader.Parent = webhookHolder
        pcall(function() ApplyGradient(statusHeader) end)
        -- Register with the theme system so it re-applies the gradient/flat color
        -- whenever the theme changes (otherwise it stays stuck on the old theme).
        if Window and Window.TextElements then
            table.insert(Window.TextElements, statusHeader)
        end

        statusLabel = Instance.new("TextLabel")
        statusLabel.Name = "GrindStatusText"
        statusLabel.LayoutOrder = -1
        statusLabel.Size = UDim2.new(1, 0, 0, 0)
        statusLabel.AutomaticSize = Enum.AutomaticSize.Y
        statusLabel.BackgroundTransparency = 1
        statusLabel.Font = UI.FontBody
        statusLabel.TextSize = 12
        statusLabel.TextColor3 = UI.Surface.Muted
        statusLabel.TextXAlignment = Enum.TextXAlignment.Left
        statusLabel.TextYAlignment = Enum.TextYAlignment.Top
        statusLabel.TextWrapped = true
        statusLabel.RichText = false
        statusLabel.Text = "Grinding status will appear here."
        statusLabel.Parent = webhookHolder
    end

    task.spawn(function()
        while true do
            task.wait(1)
            if statusLabel and statusLabel.Parent then
                local ok = pcall(function()
                    local cur = currentCounts()
                    local lines = {}
                    table.insert(lines, ("Webhook: %s"):format(WH.lastSendStatus or getWebhookReadyLine()))
                    if Settings.WebhookEnabled and Settings.WebhookTimerEnabled and WH.nextSendAt then
                        table.insert(lines, ("Next update in: %s"):format(fmtDuration(math.max(0, WH.nextSendAt - os.time()))))
                    else
                        table.insert(lines, "Auto updates: off")
                    end
                    if sendPartEnabled("Grind Time") then
                        table.insert(lines, ("Grind Time: %s"):format(fmtDuration(os.time() - WH.sessionStart)))
                    end
                    if sendPartEnabled("Deaths") then
                        table.insert(lines, ("Deaths: %d"):format(WH.deaths))
                    end
                    if sendPartEnabled("Health") then
                        local hum = plr.Character and plr.Character:FindFirstChildWhichIsA("Humanoid")
                        local hp = hum and string.format("%d / %d", math.floor(hum.Health), math.floor(hum.MaxHealth)) or "unknown"
                        table.insert(lines, ("Health: %s"):format(hp))
                    end
                    if sendPartEnabled("Username") then
                        table.insert(lines, ("Username: %s"):format(plr.Name))
                    end
                    if sendPartEnabled("Selected Items") then
                        local sel = parseSelected()
                        if #sel > 0 then
                            table.insert(lines, "Tracked items:")
                            for _, name in ipairs(sel) do
                                table.insert(lines, "  " .. formatSelectedItemLine(name):sub(3))
                            end
                        end
                    end
                    if sendPartEnabled("MojoUpdates") then
                        table.insert(lines, formatMojoUpdatesLine())
                    end
                    if sendPartEnabled("CoinsUpdates") then
                        table.insert(lines, formatCoinsUpdatesLine())
                    end
                    if sendPartEnabled("ChestUpdate") then
                        table.insert(lines, "Chest teleports:")
                        table.insert(lines, formatChestUpdatesString())
                    end
                    if sendPartEnabled("Grind Rate") then
                        local rates = buildGrindRates()
                        if rates then
                            table.insert(lines, "Grind rate:")
                            table.insert(lines, rates)
                        end
                    end
                    if sendPartEnabled("ResourcesBroken") then
                        table.insert(lines, "Resources broken:")
                        table.insert(lines, buildBrokenResourcesString())
                    end
                    if sendPartEnabled("AmountPlanted") then
                        table.insert(lines, ("Planted: %d"):format(getSessionWebhookStats().planted or 0))
                    end
                    if sendPartEnabled("AmountHarvested") then
                        table.insert(lines, ("Harvested: %d"):format(getSessionWebhookStats().harvested or 0))
                    end
                    if #lines == 1 then table.insert(lines, "Nothing selected to show.") end
                    statusLabel.Text = table.concat(lines, "\n")
                end)
                if not ok then statusLabel.Text = "Grind status unavailable." end
            end
        end
    end)
end -- AsterWebhook


-- [[ SETTINGS TAB ]] --
do -- AsterSettingsTabUI
    ASTER.Tabs.Settings:AddLabel("Character")
    -- Movement

    ASTER.Tabs.Settings:AddToggle("Enable WalkSpeed", false, function(v)
        Settings.WalkSpeedEnabled = v
    end)
    ASTER.Tabs.Settings:AddSlider("WalkSpeed", 16, 21, 16, 1, function(v)
        Settings.WalkSpeed = v
        if Settings.WalkSpeedEnabled and plr.Character and plr.Character:FindFirstChild("Humanoid") then
            plr.Character.Humanoid.WalkSpeed = v
        end
    end)

    ASTER.Tabs.Settings:AddToggle("Enable Hip Height", false, function(v)
        Settings.HipHeightEnabled = v
        if plr.Character and plr.Character:FindFirstChild("Humanoid") then
            if v then
                Settings.OriginalHipHeight = plr.Character.Humanoid.HipHeight
                plr.Character.Humanoid.HipHeight = Settings.HipHeight or 2
            else
                if Settings.OriginalHipHeight then
                    plr.Character.Humanoid.HipHeight = Settings.OriginalHipHeight
                end
            end
        end
    end)
    ASTER.Tabs.Settings:AddSlider("Hip Height", 0, 6, 2, 0.01, function(v)
        Settings.HipHeight = v
        if Settings.HipHeightEnabled and plr.Character and plr.Character:FindFirstChild("Humanoid") then
            plr.Character.Humanoid.HipHeight = v
        end
    end)

        ASTER.Tabs.Settings:AddSlider("Zoom Distance", 50, 10000, 100, 10, function(v)
        plr.CameraMaxZoomDistance = v
    end)

    ASTER.Tabs.Settings:AddLabel("Movement Extras")
    ASTER.Tabs.Settings:AddToggle("Noclip", false, function(v)
        Settings.GoldNoclip = v
        if v then
            startGoldNoclip()
        else
            goldNoclipActive = false
            restoreWorldNoclip()
            restoreCollision()
        end
    end)
    ASTER.Tabs.Settings:AddToggle("Mountain Climber", false, function(v)
        Settings.MaxSlopeEnabled = v
        if plr.Character and plr.Character:FindFirstChild("Humanoid") then
            plr.Character.Humanoid.MaxSlopeAngle = v and 89 or 50
        end
    end)
    local wallClimberConnection
    ASTER.Tabs.Settings:AddToggle("Wall Climber", false, function(v)
        Settings.WallClimberEnabled = v
        if v then
            if wallClimberConnection then wallClimberConnection:Disconnect() end
            wallClimberConnection = game:GetService("RunService").Stepped:Connect(function()
                local char = plr.Character
                if char and char:FindFirstChild("HumanoidRootPart") and char:FindFirstChild("Humanoid") then
                    local hrp = char.HumanoidRootPart
                    local hum = char.Humanoid
                    
                    local raycastParams = RaycastParams.new()
                    raycastParams.FilterDescendantsInstances = {char}
                    raycastParams.FilterType = Enum.RaycastFilterType.Exclude
                    
                    local result = workspace:Raycast(hrp.Position, hrp.CFrame.LookVector * 2.5, raycastParams)
                    if result and hum.MoveDirection.Magnitude > 0 then
                        hrp.Velocity = Vector3.new(hrp.Velocity.X, 50, hrp.Velocity.Z)
                    end
                end
            end)
        else
            if wallClimberConnection then
                wallClimberConnection:Disconnect()
                wallClimberConnection = nil
            end
        end
    end)

    local spectateButton = nil
    local spectateViewing = nil
    local spectateCharAddedConn = nil
    local spectateTargetConn = nil
    local spectatePanelVisibleConn = nil
    local spectateBtnConn = nil
    local SPECTATE_GREEN = Color3.fromRGB(170, 255, 0)
    local SPECTATE_RED = Color3.fromRGB(255, 0, 0)

    local function setSpectateCameraSubject(targetPlayer)
        local camera = workspace.CurrentCamera
        if not camera or not targetPlayer then return end
        local character = targetPlayer.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid then
            camera.CameraType = Enum.CameraType.Custom
            camera.CameraSubject = humanoid
        end
    end

    local function getActionPanel()
        local playerGui = plr:FindFirstChild("PlayerGui")
        if playerGui then
            local secondaryGui = playerGui:FindFirstChild("SecondaryGui")
            if secondaryGui then
                local playerList = secondaryGui:FindFirstChild("PlayerList")
                if playerList and playerList:FindFirstChild("List") then
                    local actionPanel = playerList.List:FindFirstChild("ActionPanel")
                    if actionPanel then return actionPanel end
                end
            end
        end
        local starterGui = ReplicatedStorage:FindFirstChild("StarterGui")
        if starterGui then
            local secondaryGui = starterGui:FindFirstChild("SecondaryGui")
            if secondaryGui and secondaryGui:FindFirstChild("PlayerList") then
                local list = secondaryGui.PlayerList:FindFirstChild("List")
                if list then
                    return list:FindFirstChild("ActionPanel")
                end
            end
        end
        return nil
    end

    local function getActionPanelTargetPlayer(actionPanel)
        if not actionPanel then return nil end
        local targetName = actionPanel:FindFirstChild("TargetPlayerName")
        if not targetName or targetName.Value == "" then return nil end
        return Players:FindFirstChild(targetName.Value)
    end

    local function updateSpectateButtonAppearance()
        if not spectateButton then return end
        local actionPanel = getActionPanel()
        local targetPlayer = getActionPanelTargetPlayer(actionPanel)
        local isActive = spectateViewing ~= nil and spectateViewing == targetPlayer
        spectateButton.BackgroundColor3 = isActive and SPECTATE_GREEN or SPECTATE_RED
        spectateButton.Text = "SPECTATE"
    end

    local function stopSpectate()
        if spectateCharAddedConn then spectateCharAddedConn:Disconnect() spectateCharAddedConn = nil end
        spectateViewing = nil
        local camera = workspace.CurrentCamera
        if camera and plr.Character and plr.Character:FindFirstChild("Humanoid") then
            if Settings.FreeCam then
                camera.CameraType = Enum.CameraType.Scriptable
            else
                camera.CameraType = Enum.CameraType.Custom
                camera.CameraSubject = plr.Character.Humanoid
            end
        end
        updateSpectateButtonAppearance()
    end

    local function startSpectate(targetPlayer)
        if not targetPlayer or targetPlayer == plr then return end
        if Settings.FreeCam then Settings.FreeCam = false end
        stopSpectate()
        spectateViewing = targetPlayer
        setSpectateCameraSubject(targetPlayer)

        spectateCharAddedConn = targetPlayer.CharacterAdded:Connect(function(character)
            local humanoid = character:WaitForChild("Humanoid", 10)
            if spectateViewing == targetPlayer and humanoid and workspace.CurrentCamera then
                workspace.CurrentCamera.CameraType = Enum.CameraType.Custom
                workspace.CurrentCamera.CameraSubject = humanoid
            end
        end)

        updateSpectateButtonAppearance()
    end

    local function bindSpectateButton(actionPanel)
        if spectateBtnConn then spectateBtnConn:Disconnect() spectateBtnConn = nil end
        spectateBtnConn = spectateButton.InputBegan:Connect(function(input, gameProcessed)
            if gameProcessed then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local targetPlayer = getActionPanelTargetPlayer(actionPanel)
            if not targetPlayer then return end
            if spectateViewing == targetPlayer then
                stopSpectate()
            else
                startSpectate(targetPlayer)
            end
        end)
    end

    local function createSpectateButton(actionPanel)
        if not actionPanel then return end
        spectateButton = actionPanel:FindFirstChild("SpectateButton")
        if not spectateButton then
            local template = actionPanel:FindFirstChild("InfoButton")
            if template then
                spectateButton = template:Clone()
            else
                spectateButton = Instance.new("TextButton")
                spectateButton.Size = UDim2.new(1, 0, 0.2, 0)
                spectateButton.Font = Enum.Font.GothamBold
                spectateButton.TextScaled = true
                spectateButton.TextColor3 = Color3.new(1, 1, 1)
                spectateButton.TextStrokeTransparency = 0
                spectateButton.BorderSizePixel = 3
                spectateButton.BorderColor3 = Color3.new(0, 0, 0)
                spectateButton.BackgroundTransparency = 0.3
                local constraint = Instance.new("UITextSizeConstraint")
                constraint.MaxTextSize = 32
                constraint.MinTextSize = 1
                constraint.Parent = spectateButton
            end
            spectateButton.Name = "SpectateButton"
            spectateButton.LayoutOrder = 2
            spectateButton.Parent = actionPanel
        end
        spectateButton.Visible = true
        spectateButton.BackgroundColor3 = SPECTATE_RED
        spectateButton.Text = "SPECTATE"
        bindSpectateButton(actionPanel)
        local targetName = actionPanel:FindFirstChild("TargetPlayerName")
        if targetName then
            if spectateTargetConn then spectateTargetConn:Disconnect() end
            spectateTargetConn = targetName:GetPropertyChangedSignal("Value"):Connect(updateSpectateButtonAppearance)
        end
        if spectatePanelVisibleConn then spectatePanelVisibleConn:Disconnect() end
        spectatePanelVisibleConn = actionPanel:GetPropertyChangedSignal("Visible"):Connect(updateSpectateButtonAppearance)
        updateSpectateButtonAppearance()
    end

    local function removeSpectateButton()
        stopSpectate()
        if spectateBtnConn then spectateBtnConn:Disconnect() spectateBtnConn = nil end
        if spectateTargetConn then spectateTargetConn:Disconnect() spectateTargetConn = nil end
        if spectatePanelVisibleConn then spectatePanelVisibleConn:Disconnect() spectatePanelVisibleConn = nil end
