    local freecamSpeedSlider = nil
    local freecamScrollConnection = nil
    local dynamicThumbstickGui = nil
    local thumbstickBeganConn = nil
    local thumbstickChangedConn = nil
    local thumbstickEndedConn = nil
    local thumbstickRenderConn = nil
    local phoneInputBeganConn = nil
    local phoneInputChangedConn = nil
    local phoneInputEndedConn = nil

    local function isFreeCamMobile()
        return UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    end

    local function createDynamicThumbstick()
        if dynamicThumbstickGui then return end

        dynamicThumbstickGui = Instance.new("ScreenGui")
        dynamicThumbstickGui.Name = "FreeCamDynamicThumbstick"
        dynamicThumbstickGui.Parent = game:GetService("CoreGui")

        local thumbstickFrame, thumbstick
        local touchInput, touchStart
        local moveVector = Vector3.new()
        local verticalMove = 0



        thumbstickBeganConn = UserInputService.InputBegan:Connect(function(input, gameProcessedEvent)
            if gameProcessedEvent or input.UserInputType ~= Enum.UserInputType.Touch or touchInput then return end
            if input.Position.X > workspace.CurrentCamera.ViewportSize.X / 2 then return end

            touchInput = input
            touchStart = input.Position

            thumbstickFrame = Instance.new("Frame")
            thumbstickFrame.Size = UDim2.new(0, 150, 0, 150)
            thumbstickFrame.Position = UDim2.new(0, touchStart.X, 0, touchStart.Y)
            thumbstickFrame.AnchorPoint = Vector2.new(0.5, 0.5)
            thumbstickFrame.BackgroundTransparency = 0.5
            thumbstickFrame.BackgroundColor3 = Color3.new(0, 0, 0)
            thumbstickFrame.Parent = dynamicThumbstickGui

            local corner = Instance.new("UICorner")
            corner.CornerRadius = UDim.new(0.5, 0)
            corner.Parent = thumbstickFrame

            thumbstick = Instance.new("Frame")
            thumbstick.Size = UDim2.new(0, 50, 0, 50)
            thumbstick.Position = UDim2.new(0.5, 0, 0.5, 0)
            thumbstick.AnchorPoint = Vector2.new(0.5, 0.5)
            thumbstick.BackgroundColor3 = Color3.new(1, 1, 1)
            thumbstick.Parent = thumbstickFrame

            local thumbstickCorner = Instance.new("UICorner")
            thumbstickCorner.CornerRadius = UDim.new(0.5, 0)
            thumbstickCorner.Parent = thumbstick
        end)

        thumbstickChangedConn = UserInputService.InputChanged:Connect(function(input)
            if input == touchInput then
                local delta = input.Position - touchStart
                local radius = thumbstickFrame.AbsoluteSize.X / 2

                if delta.Magnitude > radius then
                    delta = delta.Unit * radius
                end

                thumbstick.Position = UDim2.new(0.5, delta.X, 0.5, delta.Y)
                moveVector = Vector3.new(delta.X / radius, 0, delta.Y / radius)
            end
        end)

        thumbstickEndedConn = UserInputService.InputEnded:Connect(function(input)
            if input == touchInput then
                touchInput = nil
                thumbstickFrame:Destroy()
                moveVector = Vector3.new()
            end
        end)

        local camera = workspace.CurrentCamera
        thumbstickRenderConn = game:GetService("RunService").RenderStepped:Connect(function(dt)
            if not Settings.FreeCam or not isFreeCamMobile() then return end
            local moveSpeed = (Settings.FreeCamSpeed or 3)
            local finalMove = (camera.CFrame.RightVector * moveVector.X + camera.CFrame.LookVector * -moveVector.Z) * moveSpeed * dt
            camera.CFrame = CFrame.new(camera.CFrame.Position + finalMove) * camera.CFrame.Rotation
        end)
    end



    ASTER.Tabs.Settings:AddToggle("FreeCam", false, function(v)
        Settings.FreeCam = v
        Settings.FreeCamPhone = false
        local camera = workspace.CurrentCamera
        local char = plr.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local mobile = isFreeCamMobile()

        if v then
            if hrp then
                Settings.OriginalHRPAnchored = hrp.Anchored
                hrp.Anchored = true
            end
            Settings.OriginalCameraType = camera.CameraType
            camera.CameraType = Enum.CameraType.Scriptable

            if mobile then
                createDynamicThumbstick()

                local rotationInput, lastRotationPos, cameraYaw, cameraPitch
                local _, y, _ = camera.CFrame:ToOrientation()
                cameraYaw = y
                local lookVector = camera.CFrame.LookVector
                cameraPitch = math.asin(-lookVector.Y)

                phoneInputBeganConn = UserInputService.InputBegan:Connect(function(input, gameProcessedEvent)
                    if gameProcessedEvent or input.UserInputType ~= Enum.UserInputType.Touch then return end
                    if input.Position.X < workspace.CurrentCamera.ViewportSize.X / 2 then return end
                    rotationInput = input
                    lastRotationPos = input.Position
                end)

                phoneInputChangedConn = UserInputService.InputChanged:Connect(function(input)
                    if input == rotationInput then
                        local delta = input.Position - lastRotationPos
                        local rotationSpeed = (Settings.FreeCamSpeed or 3) / 200

                        cameraYaw = cameraYaw - math.rad(delta.X * rotationSpeed * 3)
                        cameraPitch = cameraPitch - math.rad(delta.Y * rotationSpeed * 3)
                        cameraPitch = math.clamp(cameraPitch, -math.pi/2 + 0.01, math.pi/2 - 0.01)

                        camera.CFrame = CFrame.new(camera.CFrame.Position) * CFrame.fromEulerAnglesYXZ(cameraPitch, cameraYaw, 0)
                        lastRotationPos = input.Position
                    end
                end)

                phoneInputEndedConn = UserInputService.InputEnded:Connect(function(input)
                    if input == rotationInput then
                        rotationInput = nil
                    end
                end)
            else
                local rx, ry, rz = camera.CFrame:toEulerAnglesYXZ()
                Settings.FreeCamYaw = math.deg(ry)
                Settings.FreeCamPitch = math.deg(rx)

                freecamScrollConnection = UserInputService.InputChanged:Connect(function(input)
                    if Settings.FreeCam and input.UserInputType == Enum.UserInputType.MouseWheel then
                        local currentSpeed = Settings.FreeCamSpeed or 3
                        local multiplier = 1.1
                        local newSpeed
                        if input.Position.Z > 0 then
                            newSpeed = currentSpeed / multiplier
                        else
                            newSpeed = currentSpeed * multiplier
                        end

                        newSpeed = math.clamp(newSpeed, 0.01, 50)
                        Settings.FreeCamSpeed = newSpeed

                        if freecamSpeedSlider and freecamSpeedSlider.SetValue then
                            freecamSpeedSlider:SetValue(newSpeed)
                        end
                    end
                end)
            end
        else
            if hrp then
                hrp.Anchored = Settings.OriginalHRPAnchored or false
            end
            camera.CameraType = Settings.OriginalCameraType or Enum.CameraType.Custom
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default

            if freecamScrollConnection then
                freecamScrollConnection:Disconnect()
                freecamScrollConnection = nil
            end

            if touchPanConnection then touchPanConnection:Disconnect() end
            if touchPinchConnection then touchPinchConnection:Disconnect() end
            if touchRotateConnection then touchRotateConnection:Disconnect() end

            if dynamicThumbstickGui then
                dynamicThumbstickGui:Destroy()
                dynamicThumbstickGui = nil
            end

            if thumbstickBeganConn then thumbstickBeganConn:Disconnect(); thumbstickBeganConn = nil end
            if thumbstickChangedConn then thumbstickChangedConn:Disconnect(); thumbstickChangedConn = nil end
            if thumbstickEndedConn then thumbstickEndedConn:Disconnect(); thumbstickEndedConn = nil end
            if thumbstickRenderConn then thumbstickRenderConn:Disconnect(); thumbstickRenderConn = nil end

            if phoneInputBeganConn then phoneInputBeganConn:Disconnect(); phoneInputBeganConn = nil end
            if phoneInputChangedConn then phoneInputChangedConn:Disconnect(); phoneInputChangedConn = nil end
            if phoneInputEndedConn then phoneInputEndedConn:Disconnect(); phoneInputEndedConn = nil end

            if joystickGui then
                joystickGui:Destroy()
                joystickGui = nil
            end

            if char and char:FindFirstChild("Humanoid") then
                camera.CameraSubject = char.Humanoid
            end

            if char and char:FindFirstChild("Head") then
                camera.CFrame = char.Head.CFrame * CFrame.new(0, 2, 10)
            end
        end
    end)

    freecamSpeedSlider = ASTER.Tabs.Settings:AddSlider("FreeCam Speed", 0.01, 50, 3, 0.01, function(v)
        Settings.FreeCamSpeed = v
    end)

